window.__D("text/zohar-hebrew-translation/c003",{"p":[[9522011155,"<p>וַאֲנִי הִנְנִי מֵבִיא אֶת הַמַּבּוּל מַיִם עַל הָאָרֶץ. רַבִּי יְהוּדָה פָּתַח, (במדבר כ) הֵמָּה מֵי מְרִיבָה אֲשֶׁר רָבוּ בְנֵי יִשְׂרָאֵל אֶת ה' וַיִּקָּדֵשׁ בָּם. וְכִי בְמָקוֹם אַחֵר לֹא רָבוּ בְנֵי יִשְׂרָאֵל אֶת ה'? מַה שּׁוֹנֶה כָּאן שֶׁאָמַר הֵמָּה מֵי מְרִיבָה, וְלֹא אֲחֵרִים? אֶלָּא מֵי הַמְּרִיבָה הַלָּלוּ הָיוּ וַדַּאי שֶׁנָּתְנוּ כֹּחַ וְחֹזֶק לְבַעֲלֵי הַדִּין לְהִתְחַזֵּק. מִשּׁוּם שֶׁיֵּשׁ מַיִם מְתוּקִים וּמַיִם מְרִירִים. יֵשׁ מַיִם צְלוּלִים וְיֵשׁ מַיִם עֲכוּרִים. יֵשׁ מֵי שָׁלוֹם וּמֵי קְטָטָה. וְעַל זֶה, הֵמָּה מֵי מְרִיבָה אֲשֶׁר רָבוּ בְנֵי יִשְׂרָאֵל אֶת ה', שֶׁהִמְשִׁיכוּ עֲלֵיהֶם אֶת מִי שֶׁלֹּא צָרִיךְ וְנִטְמְאוּ בוֹ. זֶהוּ שֶׁכָּתוּב וַיִּקָּדֵשׁ בָּם.</p>\n<p>אָמַר לוֹ רַבִּי חִזְקִיָּה, אִם כָּךְ, מַה זֶּה וַיִּקָּדֵשׁ? הָיָה צָרִיךְ לִהְיוֹת וַיִּקָּדְשׁוּ! אֶלָּא הַדָּבָר עָלָה. וַיִּקָּדֵשׁ - נִפְגַּם מִי שֶׁלֹּא צָרִיךְ. כִּבְיָכוֹל שֶׁנִּפְגְּמָה הַלְּבָנָה. וַיִּקָּדֵשׁ אֵינוֹ לְשֶׁבַח כָּאן. וַאֲנִי הִנְנִי מֵבִיא אֶת הַמַּבּוּל, כְּמוֹ שֶׁבֵּאַרְנוּ, לְהָבִיא מַשְׁחִית עֲלֵיהֶם כְּמוֹ שֶׁהֵם נִטְמְאוּ בוֹ.</p>\n<p>אָמַר רַבִּי יוֹסֵי, אוֹי לָרְשָׁעִים שֶׁלֹּא רוֹצִים לָשׁוּב לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא עַל חֲטָאֵיהֶם בְּעוֹד שֶׁהֵם בָּעוֹלָם הַזֶּה. שֶׁכְּשֶׁאָדָם שָׁב וּמִתְנַחֵם עַל חֶטְאוֹ, הַקָּדוֹשׁ בָּרוּךְ הוּא מוֹחֵל לוֹ, וְכָל אוֹתָם שֶׁמַּחֲזִיקִים בַּחֲטָאֵיהֶם וְלֹא רָצוּ לָשׁוּב לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא עַל (חטאים) חֲטָאֵיהֶם, אַחַר כָּךְ (יפל) יִפְּלוּ לַגֵּיהִנֹּם וְלֹא יַעֲלוּ מִשָּׁם לְעוֹלָמִים.</p>\n<p>בֹּא רְאֵה, מִשּׁוּם שֶׁחִזְּקוּ אֶת לִבָּם כָּל אוֹתָם דּוֹרוֹ שֶׁל נֹחַ וְרָצוּ לְהַרְאוֹת חֶטְאָם בְּגָלוּי, הֵבִיא הַקָּדוֹשׁ בָּרוּךְ הוּא עֲלֵיהֶם הַדִּין בְּאוֹתוֹ הַגָּוֶן. אָמַר רַבִּי יִצְחָק, אֲפִלּוּ כְּשֶׁחוֹטֵא אָדָם בְּנִסְתָּר, הַקָּדוֹשׁ בָּרוּךְ הוּא רַחֲמָן. וְאִם שָׁב בֶּן הָאָדָם אֵלָיו, מְכַסֶּה עָלָיו וּמוֹחֵל לוֹ וּמְוַתֵּר לוֹ. וְאִם לֹא, הוּא מְגַלֶּה אוֹתוֹ לְעֵינֵי כֹל. מִנַּיִן לָנוּ? מִסּוֹטָה.</p>\n<p>וְכָךָ גַּם נִמְחוּ הָרְשָׁעִים הַלָּלוּ מֵהָאָרֶץ בְּגָלוּי. וְאֵיךְ נִמְחוּ? אֶלָּא שֶׁהָיוּ יוֹצְאִים מַיִם, וְהָיוּ רוֹתְחִים מֵהַתְּהוֹם, וְעוֹלִים וּמַעֲבִירִים מֵהֶם אֶת עוֹרָם. וְכֵיוָן שֶׁהָעֳבַר מֵהֶם הָעוֹר - כָּךְ גַּם הַבָּשָׂר, וְלֹא נִשְׁאֲרוּ אֶלָּא בָּעֲצָמוֹת שֶׁלָּהֶם בִּלְבַד, לְקַיֵּם אֶת מַה שֶּׁכָּתוּב וַיִּמָּחוּ מִן הָאָרֶץ. וְכָל אוֹתָם הָעֲצָמוֹת נִפְרְדוּ זוֹ מִזּוֹ וְלֹא נִשְׁאֲרוּ כְּאֶחָד, וּמֵהַכֹּל הָעָבְרוּ מֵהָעוֹלָם. רַבִּי יִצְחָק אָמַר, וַיִּמָּחוּ מִן הָאָרֶץ, מַה זֶּה וַיִּמָּחוּ? כְּמוֹ שֶׁנֶּאֱמַר יִמָּחוּ מֵאֶרֶץ חַיִּים. מִכָּאן לָמַדְנוּ, שֶׁאֵין לָהֶם תְּחִיָּה לְעוֹלָמִים וְלֹא יָקוּמוּ בְּדִין.</p>"],[9522011156,"<p>וַהֲקִמֹתִי אֶת בְּרִיתִי אִתָּךְ. אָמַר רַבִּי אֶלְעָזָר, מִכָּאן קִיּוּם הַבְּרִית לְמַעְלָה כְּקִיּוּם הַבְּרִית לְמַטָּה, מַשְׁמָע שֶׁכָּתוּב אִתָּךְ. וְאָמַר רַבִּי אֶלְעָזָר, מִכָּאן לָמַדְנוּ, שֶׁכְּשֶׁהַצַּדִּיקִים בָּעוֹלָם, מִתְקַיֵּם הָעוֹלָם לְמַעְלָה וּלְמַטָּה. אָמַר רַבִּי שִׁמְעוֹן, דָּבָר נִסְתָּר הוּא, כְּשֶׁהִתְעוֹרְרוּת הַזָּכָר לַנְּקֵבָה כְּשֶׁהוּא מְקַנֵּא לָהּ</p>\n<p>בֹּא רְאֵה סוֹד הַדָּבָר, כְּשֶׁצַּדִּיק יֵשׁ בָּעוֹלָם, מִיָּד הַשְּׁכִינָה לֹא זָזָה מִמֶּנּוּ וְהִשְׁתּוֹקְקוּתָהּ בּוֹ. וְאָז הִשְׁתּוֹקְקוּת שֶׁלְּמַעְלָה אֵלֶיהָ בְּאַהֲבָה כְּהִשְׁתּוֹקְקוּת הַזָּכָר לִנְקֵבָתוֹ כְּשֶׁהוּא מְקַנֵּא לָהּ. וְעַל זֶה, וַהֲקִמֹתִי אֶת בְּרִיתִי אִתָּךְ. הַהִשְׁתּוֹקְקוּת מִתְעוֹרֶרֶת בִּגְלָלְךְ. כְּמוֹ זֶה (בראשית יז) וְאֶת בְּרִיתִי אָקִים אֶת יִצְחָק.</p>\n<p>וַהֲקִמֹתִי אֶת בְּרִיךְ אִתָּךְ, לִהְיוֹת אוֹת בְּרִיתִי בָּעוֹלָם, וְאַחַר כָּךְ וּבָאתָ אֶל הַתֵּבָה. שֶׁאִלְמָלֵא אֵינוֹ צַדִּיק (ברית), לֹא יִכָּנֵס לַתֵּבָה. שֶׁהֲרֵי לֹא מִתְחַבֵּר לַתֵּבָה, רַק צַדִּיק. וְלָכֵן וּבָאתָ אֶל הַתֵּבָה, וַהֲרֵי זֶה נִתְבָּאֵר.</p>\n<p>אָמַר רַבִּי אֶלְעָזָר, בְּכָל זְמַן שֶׁבְּנֵי אָדָם יֶאֶחְזוּ בִּבְרִית זוֹ וְלֹא יַעַזְבוּ אוֹתָהּ, אֵין עַם וְלָשׁוֹן בָּעוֹלָם שֶׁיּוּכְלוּ לְהָרַע לָהֶם. וְנֹחַ הֶחֱזִיק בִּבְרִית זוֹ וְשָׁמַר אוֹתָהּ, וְלָכֵן שָׁמַר אוֹתוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא (וכל אשר לו). וְכָל בְּנֵי דוֹרוֹ לֹא שָׁמְרוּ אוֹתָהּ, וְלָכֵן הֶעֱבִיר אוֹתָם הַקָּדוֹשׁ בָּרוּךְ הוּא מֵהָעוֹלָם. וַהֲרֵי נֶאֱמַר, בְּאוֹתוֹ חֵטְא מַמָּשׁ שֶׁהֵם חָטְאוּ - בְּאוֹתוֹ גָוֶן נִמְחוּ מֵהָעוֹלָם.</p>"],[9522011157,"<p>רַבִּי יְהוּדָה הָיָה מָצוּי לִפְנֵי רַבִּי שִׁמְעוֹן, וְהָיוּ עוֹסְקִים בַּפָּסוּק הַזֶּה שֶׁכָּתוּב (מלכים א יח) וַיְרַפֵּא אֶת מִזְבַּח ה' הֶהָרוּס. מַה זֶּה וַיְרַפֵּא.? בֹּא רְאֵה, בִּימֵי אֵלִיָּהוּ כָּל יִשְׂרָאֵל עָזְבוּ אֶת הַקָּדוֹשׁ בָּרוּךְ הוּא וְעָזְבוּ אֶת בְּרִית הַמִּילָה שֶׁלָּהֶם. כְּשֶׁבָּא אֵלִיָּהוּ וּרְאֵה שֶׁעָזְבוּ בְּנֵי יִשְׂרָאֵל בְּרִית מִילָה הַזּוֹ וְהֶעֱבִירוּ מֵהֶם אֶת הַבְּרִית הַזּוֹ.</p>\n<p>כֵּיוָן שֶׁרָאָה כָּךְ אֵלִיָּהוּ, בָּא לְתַקֵּן דָּבָר בִּמְקוֹמוֹ. כֵּיוָן שֶׁהִקְרִיב דָּבָר לִמְקוֹמוֹ - הַכֹּל הִתְרַפֵּא. זֶהוּ שֶׁכָּתוּב וַיְרַפֵּא אֶת מִזְבַּח ה' הֶהָרוּס. זוֹ בְּרִית הַמִּילָה (שבא לתקן מזבח ה' ההרוס ברית המילה) שֶׁנֶּעֶזְבָה בָּעוֹלָם. וְכָתוּב (שם) וַיִּקַּח אֵלִיָּהוּ שְׁתֵּים עֶשְׂרֵה אֲבָנִים כְּמִסְפַּר שִׁבְטֵי בְנֵי יַעֲקֹב. זֶהוּ תִקּוּן שֶׁל מִזְבַּח ה'.</p>\n<p>אֲשֶׁר הָיָה דְבַר ה' אֵלָיו לֵאמֹר יִשְׂרָאֵל יִהְיֶה שְׁמֶךְ. מָה הַטַּעַם נִזְכַּר כָּאן יִשְׂרָאֵל? אֶלָּא וַדַּאי יִשְׂרָאֵל יִהְיֶה שְׁמֶךְ וַדַּאי לְהִתְעַלּוֹת לְמַעְלָה וּלְהָשִׁיב אֶת בְּרִית הַמִּילָה לִמְקוֹמָהּ. וְהַיְנוּ שֶׁכָּתוּב (שם יט) כִּי עָזְבוּ בְרִיתְךְ בְּנֵי יִשְׂרָאֵל, וּמִשּׁוּם כָּךְ אֶת מִזְבְּחֹתֶיךְ הָרָסוּ.</p>\n<p>בֹּא רְאֵה, כָּל זְמַן שֶׁיִּשְׂרָאֵל שָׁמְרוּ בְּרִית הַקָּדוֹשׁ, אָז עָשׂוּ קִיּוּם לְמַעְלָה וּלְמַטָּה. וּכְשֶׁעָזְבוּ אֶת הַבְּרִית הַזֹּאת, אָז לֹא נִמְצָא קִיּוּם לְמַעְלָה וּלְמַטָּה, שֶׁכָּתוּב (ירמיה לג) אִם לֹא בְרִיתִי יוֹמָם וָלָיְלָה חֻקּוֹת שָׁמַיִם וָאָרֶץ לֹא שָׂמְתִּי. וְלָכֵן וַיְרַפֵּא אֶת מִזְבַּח ה' הֶהָרוּס. וְכִי זוֹ רְפוּאָה? כָּךְ זֶה וַדַּאי, שֶׁהֲרֵי מְקַיֵּם אֶת אוֹתוֹ מָקוֹם שֶׁהָאֱמוּנָה תְּלוּיָה בּוֹ.</p>\n<p>בֹּא רְאֵה, גַּם כָּךְ פִּנְחָס, בְּשָׁעה שֶׁקִּנֵּא לְמַעֲשֵׂה זִמְרִי, הִתְקִין אֶת הַבְּרִית הַזּוֹ בִּמְקוֹמָהּ, וְלָכֵן כָּתוּב (במדבר כה) הִנְנִי נֹתֵן לוֹ אֶת בְּרִיתִי שָׁלוֹם. וְכִי יַעֲלֶה עַל דַּעְתְּךְ שֶׁמִּשּׁוּם פִּנְחָס הָיָה? אֵיזוֹ קְטָטָה הָיְתָה לוֹ לְפִנְחָס בַּבְּרִית הַזּוֹ? אֶלָּא כָּאן נִקְשָׁר הַדָּבָר בִּמְקוֹמוֹ. הִנְנִי נֹתֵן לוֹ אֶת בְּרִיתִי. וּמָה אֶתֵּן לוֹ? שָׁלוֹם (להתחבר כל אחד במקומו) לְהִתְחַבֵּר הַבְּרִית בִּמְקוֹמָהּ, וְעַל זֶה הִנְנִי נֹתֵן לוֹ אֶת בְּרִיתִי שָׁלוֹם. וּמַהוּ? שָׁלוֹם, שֶׁהוּא מָקוֹם לְהִתְחַבֵּר עִמּוֹ. מַה שֶּׁנִּפְרַד מִמֶּנּוּ בְּחֶטְאָם - בִּגְלָלוֹ הִתְחַבֵּר בּוֹ. וְעַל זֶה, הוֹאִיל וְהוּא הִתְקִין הַדָּבָר בִּמְקוֹמוֹ, מִכָּאן וָהָלְאָה - וְהָיְתָה לוֹ וּלְזַרְעוֹ אַחֲרָיו בְּרִית כְּהֻנַּת עוֹלָם תַּחַת אֲשֶׁר קִנֵּא לֵאלֹהָיו.</p>\n<p>אָמַר רַבִּי שִׁמְעוֹן, אֵין לְךְ דָּבָר בָּעוֹלָם שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא מְקַנֵּא לוֹ כְּמוֹ חֵטְא הַבְּרִית, כְּמוֹ שֶׁנֶּאֱמַר (ויקרא כו) חֶרֶב נֹקֶמֶת נְקַם בְּרִית. וּבא וּרְאֵה, לֹא הֻשְׁלַם חֵטְא דּוֹר הַמַּבּוּל אֶלָּא מִשּׁוּם שֶׁחָטְאוּ בְּהַשְׁחָתַת דַּרְכָּם עַל הָאָרֶץ, וְאַף עַל גַּב שֶׁהָיוּ חוֹמְסִים זֶה אֶת זֶה, כַּכָּתוּב וַתִּמָּלֵא הָאָרֶץ חָמָס (וחמס מהכל היה, ולכן), וְכָתוּב כִּי מָלְאָה הָאָרֶץ חָמָס מִפְּנֵיהֶם. מִכָּל מָקוֹם וַתִּשָּׁחֵת הָאָרֶץ לִפְנֵי הָאֱלֹהִים. וְהִנְנִי מַשְׁחִיתָם - מִדָּה כְּנֶגֶד מִדָּה. הִנְנִי מַשְׁחִיתָם בְּחֵטְא הַהַשְׁחָתָה.</p>\n<p>וְיִשִׁ אוֹמְרִים שֶׁלֹּא הִתְמַלְּאָה סְאָתָם אֶלָּא בְּחֵטְא הֶחָמָס שֶׁהָיוּ חוֹמְסִים זֶה אֶת זֶה, שֶׁהָיוּ רָעִים לַשָּׁמַיִם וְלַבְּרִיּוֹת בֹּא רְאֵה כַּמָּה מְמֻנִּים מִלְמַעְלָה שֶׁמֻּפְקָדִים עַל קוֹלוֹת אֵלּוּ שֶׁמּוֹסְרִים הַדִּין עַל חַבְרֵיהֶם עַל מַה שֶּׁעָשׂוּ לָהֶם, וְעַל זֶה כָּתוּב כִּי מָלְאָה הָאָרֶץ חָמָס מִפְּנֵיהֶם. וְלָכֵן כָּתוּב וְהִנְנִי מַשְׁחִיתָם אֶת הָאָרֶץ.</p>"],[9522011158,"<p>וַיֹּאמֶר ה' לְנֹחַ בֹּא אַתָּה וְכָל בֵּיתְךְ. אָמַר רַבִּי שִׁמְעוֹן, לָמָּה בְּכֻלָּם (אמר) אֱלֹהִים וְכָאן יְיָ? מַה שּׁוֹנֶה כָּאן שֶׁנֶּאֱמַר ה', הַשֵּׁם הָעֶלְיוֹן שֶׁל הָרַחֲמִים? אֶלָּא סוֹד הוּא שֶׁלָּמַדְנוּ - אֵין דֶּרֶךְ אֶרֶץ שֶׁתְּקַבֵּל אִשָּׁה אוֹרֵחַ עִמָּהּ אֶלָּא בִּרְשׁוּת בַּעְלָהּ.</p>\n<p>אַף כָּךְ (גם נח,) נֹחַ רָצָה לְהִכָּנֵס לַתֵּבָה לְהִתְחַבֵּר עִמָּהּ, וְלֹא הָיָה (לו) רָאוּי עַד שֶׁבַּעַל הַתֵּבָה יִתֵּן לוֹ רְשׁוּת לְהִכָּנֵס (עמה), שֶׁכָּתוּב בֹּא אַתָּה וְכֹל בֵּיתְךְ אֶל הַתֵּבָה. וְלָכֵן נִקְרָא כָּאן ה', הַבַּעַל שֶׁל הַתֵּבָה, וְאָז נִכְנַס נֹחַ וְהִתְחַבֵּר עִמָּהּ. וְכֵן לָמַדְנוּ שֶׁאֵין רְשׁוּת לְאוֹרֵחַ לְהִכָּנֵס לְבַיִת אֶלָּא בִּרְשׁוּת בַּעְלָהּ, בַּעַל הַבַּיִת. זֶהוּ שֶׁכָּתוּב אַחַר כָּךְ וַיָּבֹא נֹחַ וְגוֹ'</p>\n<p>בֹּא רְאֵה מַה כָּתוּב, כִּי אֹתְךְ רָאִיתִי צַדִּיק לְפָנַי בַּדּוֹר הַזֶּה. מִכָּאן לָמַדְנוּ שֶׁלֹּא יְקַבֵּל אָדָם אוֹרֵחַ בְּבֵיתוֹ אִם הוּא חוֹשֵׁד בּוֹ שֶׁהוּא רָשָׁע, אֶלָּא אִם עוֹמֵד בְּעֵינָיו לְצַדִּיק שֶׁלֹּא חָשׁוּד בְּעֵינָיו כְּלָל. זֶהוּ שֶׁכָּתוּב בּא אַתָּה וְכֹל בֵּיתְךְ אֶל הַתֵּבָה. מָה הַטַּעַם? מִשּׁוּם כִּי אֹתְךְ רָאִיתִי צַדִּיק לְפָנַי בַּדּוֹר הַזֶּה.</p>\n<p>וְלָמַדְנוּ, שֶׁאִם נָתַן לוֹ רְשׁוּת לְבַדּוֹ וְלֹא נָתַן רְשׁוּת לְכָל אוֹתָם שֶׁבָּאִים עִמּוֹ, לֹא יַכְנִיס אוֹתָם לַבַּיִת. זֶהוּ שֶׁכָּתוּב בֹּא אַתָּה וְכָל בֵּיתְךְ אֶל הַתֵּבָה. לְכֻלָּם נָתַן רְשׁוּת לְהִכָּנֵס. וּמִפָּסוּק הַזֶּה לָמַדְנוּ סוֹד דֶּרֶךְ אֶרֶץ. (ד\"א בא אתה וכל ביתך אל התבה וגו').</p>"],[9522011159,"<p>רַבִּי יְהוּדָה פָּתַח, (תהלים כד) לְדָוִד מִזְמוֹר לַה' הָאָרֶץ וּמְלוֹאָהּ תֵּבֵל וְיֹשְׁבֵי בָהּ. הֲרֵי שָׁנִינוּ, לְדָוִד מִזְמוֹר - שֶׁאָמַר שִׁירָה וְאַחַר כָּךְ שָׁרְתָה עָלָיו רוּחַ הַקֹּדֶשׁ. מִזְמוֹר לְדָוִד - שֶׁשָּׁרְתָה עָלָיו רוּחַ הַקֹּדֶשׁ וְאַחַר כָּךְ אָמַר שִׁירָה.</p>\n<p>לַה' הָאָרֶץ וּמְלוֹאָהּ - פָּסוּק זֶה נֶאֱמַר עַל אֶרֶץ יִשְׂרָאֵל שֶׁהִיא אֶרֶץ הַקְּדוֹשָׁה. וּמְלוֹאָהּ זוֹ הַשְּׁכִינָה, כְּמוֹ שֶׁנֶּאֱמַר (דברי הימים ב ה) כִּי מָלֵא כְבוֹד ה' אֶת בֵּית ה', וְכָתוּב (שמות מ) וּכְבוֹד ה' מָלֵא אֶת הַמִּשְׁכָּן. לָמָּה מָלֵא וְלֹא מִלֵּא? אֶלָּא מָלֵא וַדַּאי, שֶׁהִתְמַלֵּא מֵהַכֹּל, שֶׁהִתְמַלֵּא מֵהַשֶּׁמֶשׁ. הַלְּבָנָה שְׁלֵמָה בְּכָל הַצְּדָדִים. מָלֵא מִכָּל טוּב שֶׁלְּמַעְלָה, כְּמוֹ הָאוֹצָר הַזֶּה שֶׁהִתְמַלֵּא מִכָּל טוּב שֶׁל הָעוֹלָם, וְעַל זֶה כָּתוּב לַה' הָאָרֶץ וּמְלוֹאָהּ. תֵּבֵל וְיֹשְׁבֵי בָהּ - אֵלּוּ שְׁאָר הָאֲרָצוֹת.</p>\n<p>דָּבָר אַחֵר, לַה' הָאָרֶץ וּמְלוֹאָהּ - זוֹ אֶרֶץ הַקְּדוֹשָׁה הָעֶלְיוֹנָה שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא רוֹצֶה בָּהּ. וּמְלוֹאָהּ - אֵלּוּ נִשְׁמוֹת הַצַּדִּיקִים (ד\"א שכלם ממלאים אותה) מִתְמַלֵּאת (ד\"א שמתמלאת) מֵהֶם מִכֹּחַ עַמּוּד אֶחָד שֶׁהָעוֹלָם עוֹמֵד עָלָיו.</p>\n<p>וְאִם תֹּאמַר עַל אֶחָד עוֹמֵד. בֹּא רְאֵה מַה כָּתוּב, (תהלים כד) כִּי הוּא עַל יַמִּים יְסָדָהּ. כִּי הוּא, מִי הוּא זֶה הַקָּדוֹשׁ בָּרוּךְ הוּא, כְּמוֹ שֶׁנֶּאֱמַר הוּא עָשָׂנוּ, וְכָתוּב (איוב כח) כִּי הוּא לִקְצוֹת הָאָרֶץ יַבִּיט.</p>\n<p>עֵל יַמִּים יְסָדָהּ וְעַל נְהָרוֹת יְכוֹנְנֶהָ - אֵלּוּ שִׁבְעָה עַמּוּדִים שֶׁעוֹמֶדֶת הָאָרֶץ עֲלֵיהֶם וּמְמַלְּאִים אוֹתָהּ, וְהִיא מִתְמַלֵּאת מֵהֶם. אֵיךְ מִתְמַלֵּאת מֵהֶם? בְּשָׁעָה שֶׁמִּתְרַבִּים הַצַּדִּיקִים בָּעוֹלָם, אָז הָאָרֶץ הַזּוֹ עוֹשָׂה פֵּרוֹת וּמִתְמַלֵּאת מֵהַכֹּל.</p>\n<p>וּבְשָׁעָה שֶׁמִּתְרַבִּים הָרְשָׁעִים בָּעוֹלָם, אָז כָּתוּב (שם יד) אָזְלוּ מַיִם מִנִּי יָם וְנָהָר יֶחֱרַב וְיָבֵשׁ. אָזְלוּ מַיִם מִנִּי יָם - זוֹ הָאָרֶץ הַקְּדוֹשָׁה שֶׁאָמַרְנוּ שֶׁנִּשְׁקֵית מֵהַשְׁקָאָה עֶלְיוֹנָה. וְנָהָר יֶחֱרַב וְיָבֵשׁ - אוֹתוֹ הָעַמּוּד הָאֶחָד שֶׁעוֹמֵד עָלֶיהָ לִהְיוֹת מוּאָר מִמֶּנּוּ. וְנָהָר יֶחֱרַב וְיָבֵשׁ - כְּמוֹ שֶׁנֶּאֱמַר (ישעיה נז) הַצַּדִּיק אָבָד.</p>"],[9522011160,"<p>וְאָמַר רַבִּי יְהוּדָה, בְּאוֹתוֹ זְמַן שֶׁנֶּאֱבָדִים אוֹתָם רְשָׁעִים מֵהָעוֹלָם, הַקָּדוֹשׁ בָּרוּךְ הוּא (עצוב) (מסתכל) מִשְׁתַּדֵּל עַל הָעוֹלָם וְלֹא רוֹאֶה מִי שֶׁמֵּגֵן (שעומד) עָלָיו. וְאִם תֹּאמַר הֲרֵי נֹחַ, שֶׁהָיָה לוֹ לְהָגֵן עַל (דורו) עַצְמוֹ וּלְהוֹצִיא מִמֶּנּוּ תוֹלָדוֹת לָעוֹלָם - זֶהוּ שֶׁכָּתוּב כִּי אֹתְךְ רָאִיתִי צַדִּיק לְפָנַי בַּדּוֹר הַזֶּה. דַּוְקָא בַּדּוֹר הַזֶּה.</p>\n<p>רַבִּי יוֹסֵי אָמַר, בַּדּוֹר הַזֶּה זֶה שֶׁבַח שֶׁלּוֹ, שֶׁהָיָה בְּאוֹתוֹ דוֹר רָשָׁע, וְנִמְצָא כָּל כָּךְ אִישׁ צַדִּיק תָּמִים (ודאי ולא בדורו, אלא) (ס\"א וזה שלו) וַאֲפִלּוּ בְּדוֹרוֹ שֶׁל מֹשֶׁה, אֲבָל לֹא הָיָה יָכוֹל לְהָגֵן עַל הָעוֹלָם, מִשּׁוּם שֶׁלֹּא נִמְצְאוּ עֲשָׂרָה בָּעוֹלָם, כְּמוֹ שֶׁנֶּאֱמַר (בראשית יח) אוּלַי יִמָּצְאוּן שָׁם עֲשָׂרָה, וְלֹא נִמְצְאוּ שָׁם. גַּם כָּאן לֹא נִמְצְאוּ עֲשָׂרָה, אֶלָּא הוּא וּשְׁלֹשֶׁת בָּנָיו וּנְקֵבוֹתֵיהֶם, וְלֹא הָיוּ עֲשָׂרָה.</p>\n<p>רַבִּי אֶלְעָזָר שָׁאַל אֶת רַבִּי שִׁמְעוֹן אָבִיו, הֲרֵי שָׁנִינוּ, בְּשָׁעָה שֶׁהָעוֹלָם מִתְמַלֵּא בַּחֲטָאֵי בְּנֵי אָדָם וְהַדִּין יוֹצֵא - אוֹי לְאוֹתוֹ צַדִּיק שֶׁנִּמְצָא בָּעוֹלָם, שֶׁהוּא נִתְפָּס בַּחֲטָאֵי הָרְשָׁעִים בַּתְּחִלָּה. אֵיךְ נִצַּל נֹחַ שֶׁלֹּא נִתְפַּס בַּחֲטָאֵיהֶם? אָמַר לוֹ, הֲרֵי נֶאֱמַר שֶׁרָצָה הַקָּדוֹשׁ בָּרוּךְ הוּא לְהוֹצִיא מִמֶּנּוּ תּוֹלָדוֹת לָעוֹלָם מִתּוֹךְ הַתֵּבָה. וְעוֹד, שֶׁהֲרֵי הַדִּין לֹא יָכֹל לִשְׁלֹט עָלָיו, מִשּׁוּם שֶׁהָיָה טָמִיר וְנִסְתָּר בַּתֵּבָה וְהִתְכַּסָּה מֵהָעַיִן.</p>\n<p>וּבֹא וּרְאֵה, כָּתוּב (צפניה ב) בַּקְּשׁוּ צֶדֶק בַּקְּשׁוּ עֲנָוָה אוּלַי תִּסָּתְרוּ בְּיוֹם אַף ה'. וְנֹחַ בִּקֵּשׁ צֶדֶק, וְנִכְנַס לְתוֹךְ הַתֵּבָה וְנִסְתַּר בְּיוֹם אַף ה', וְעַל זֶה הַדִּין לֹא יָכֹל לִשְׁלֹט וּלְקַטְרֵג עָלָיו.</p>\n<p>כָּאן נִרְמָז לְאוֹתָם קְדוֹשִׁים עֶלְיוֹנִים לָדַעַת בְּסוֹד הָאוֹתִיּוֹת הַקְּדוֹשׁוֹת הָעֶלְיוֹנוֹת הַהִפּוּךְ שֶׁל הָאוֹתִיּוֹת כ\"ב לְהַכּוֹת אֶת אוֹתָם הָרְשָׁעִים, וְעַל זֶה וַיִּמָּחוּ מִן הָאָרֶץ כָּתוּב. בּא אַתָּה וְכֹל בֵּיתְךְ.</p>"],[9522011161,"<p>רַבִּי יִצְחָק פָּתַח, (ישעיה סג) מוֹלִיךְ לִימִין מֹשֶׁה זְרוֹעַ תִּפְאַרְתּוֹ בּוֹקֵעַ מַיִם מִפְּנֵיהֶם לַעֲשׂוֹת לוֹ שֵׁם עוֹלָם (זרוע תפארתו) - זוֹ זְכוּת שֶׁל אַבְרָהָם, שֶׁהוּא הַיָּמִין מִמֹּשֶׁה, תִּפְאֶרֶת שֶׁל מֹשֶׁה, וּמִשּׁוּם כָּךְ בּוֹקֵעַ מַיִם מִפְּנֵיהֶם, שֶׁהֲרֵי הַזְּכוּת שֶׁל אַבְרָהָם הִיא בּוֹקַעַת מַיִם. וְכָל זֶה לָמָּה? לַעֲשׂוֹת לוֹ שֵׁם עוֹלָם</p>\n<p>בֹּא רְאֵה מַה בֵּין מֹשֶׁה לִשְׁאָר בְּנֵי הָעוֹלָם. בְּשָׁעָה שֶׁאָמַר הַקָּדוֹשׁ בָּרוּךְ הוּא לְמֹשֶׁה (שמות לב) וְעַתָּה הַנִּיחָה לִּי וְגוֹ', וְאֶעֱשֶׂה אוֹתְךְ לְגוֹי גָּדוֹל וְגוֹ' - מִיָּד אָמַר מֹשֶׁה, וְכִי אֶעֱזֹב דִּינָם שֶׁל יִשְׂרָאֵל בִּשְׁבִילִי? כָּעֵת יֹאמְרוּ כָּל אוֹתָם בְּנֵי הָעוֹלָם שֶׁאֲנִי הָרַגְתִּי אֶת יִשְׂרָאֵל כְּמוֹ שֶׁעָשָׂה נֹחַ.</p>\n<p>שֶׁכֵּיוָן שֶׁאָמַר לוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא שֶׁיַּצִּיל אוֹתוֹ בַּתֵּבָה, (כמו שנאמר) שֶׁכָּתוּב וַאֲנִי הִנְנִי מֵבִיא אֶת הַמַּבּוּל מַיִם וְגוֹ', וְכָתוּב וּמָחִיתִי אֶת כָּל הַיְקוּם אֲשֶׁר עָשִׂיתִי מֵעַל פְּנֵי הָאֲדָמָה וַאֲנִי הִנְנִי מֵקִים אֶת בְּרִיתִי וְגוֹ' וּבָאתָ אֶל הַתֵּבָה - כֵּיוָן שֶׁאָמַר לוֹ שֶׁיִּנָּצֵל הוּא וּבָנָיו, לֹא בִקֵּשׁ רַחֲמִים עַל הָעוֹלָם וְנֶאֶבְדוּ. וּמִשּׁוּם כָּךְ נִקְרָאִים מֵי הַמַּבּוּל עַל שְׁמוֹ, כְּמוֹ שֶׁנֶּאֱמַר (ישעיה נד) כִּי מֵי נֹחַ זֹאת לִי אֲשֶׁר נִשְׁבַּעְתִּי מֵעֲבֹר מֵי נֹחַ.</p>\n<p>אָמַר מֹשֶׁה, כָּעֵת יֹאמְרוּ בְּנֵי הָעוֹלָם שֶׁאֲנִי הָרַגְתִּי אוֹתָם מִשּׁוּם שֶׁאָמַר לִי וְאֶעֱשֶׂה אוֹתְךְ לְגוֹי גָּדוֹל. כָּעֵת טוֹב לִי שֶׁאָמוּת וְלֹא יֻשְׁמְדוּ יִשְׂרָאֵל. מִיָּד - וַיְחַל מֹשֶׁה אֶת פְּנֵי ה' אֱלֹהָיו. בִּקֵּשׁ רַחֲמִים עֲלֵיהֶם וְעוֹרֵר רַחֲמִים עַל הָעוֹלָם.</p>\n<p>וְאָמַר רַבִּי יִצְחָק, בַּתְּחִלָּה כְּשֶׁבִּקֵּשׁ רַחֲמִים עֲלֵיהֶם מָה אָמַר? לָמָה ה' יֶחֱרֶה אַפְּךְ בְּעַמֶּךְ. וְכִי הַדָּבָר הַזֶּה אֵיךְ אָמַר אוֹתוֹ מֹשֶׁה לָמָּה, וַהֲרֵי עָבְדוּ כּוֹכָבִים וּמַזָּלוֹת, כְּמוֹ שֶׁנֶּאֱמַר עָשׂוּ לָהֶם עֵגֶל מַסֵּכָה וַיִּשְׁתַּחֲווּ לוֹ וַיֹּאמְרוּ אֵלֶּה וְגוֹ', וּמֹשֶׁה אָמַר לָמָּה? אֶלָּא כָּךְ לָמַדְנוּ, מִי שֶׁמְּרַצֶּה אֶת הָאַחֵר, לֹא צָרִיךְ לַעֲשׂוֹת אֶת אוֹתוֹ חֵטְא (שהוא) לְגָדוֹל, אֶלָּא יַקְטִין אוֹתוֹ לְפָנָיו, וְאַחַר כָּךְ יַגְדִּיל אוֹתוֹ לִפְנֵי הָאַחֵר (הרשע), שֶׁכָּתוּב אַתֶּם חֲטָאתֶם חֲטָאָה גְדֹלָה.</p>\n<p>וְלֹא עָזַב אֶת הַקָּדוֹשׁ בָּרוּךְ הוּא עַד שֶׁמָּסַר עַצְמוֹ לְמִיתָה, שֶׁכָּתוּב וְעַתָּה אִם תִּשָּׂא חַטָּאתָם וְאִם אַיִן מְחֵנִי נָא מִסִּפְרְךְ אֲשֶׁר כָּתָבְתָּ. וְהַקָּדוֹשׁ בָּרוּךְ הוּא מָחַל לָהֶם, שֶׁכָּתוּב וַיִּנָּחֵם ה' עַל הָרָעָה וְגוֹ'. וְנֹחַ לֹא עָשָׂה כֵּן, אֶלָּא רָצָה לְהִנָּצֵל, וְעָזַב אֶת כָּל הָעוֹלָם.</p>\n<p>וּבְכָל פַּעַם שֶׁהַדִּין שׁוֹרֶה עַל הָעוֹלָם, רוּחַ הַקֹּדֶשׁ אוֹמֶרֶת: אוֹי שֶׁלֹּא נִמְצָא כְּמוֹ מֹשֶׁה, שֶׁכָּתוּב (ישעיה סג) וַיִּזְכֹּר יְמֵי עוֹלָם מֹשֶׁה עַמּוֹ אַיֵּה הַמַּעֲלֵם מִיָּם וְגוֹ', שֶׁכָּתוּב (שמות יד) וַיֹּאמֶר ה' אֶל מֹשֶׁה מַה תִּצְעַק אֵלָי. שֶׁהֲרֵי בַּתְּפִלָּה הוּא הֶעֱלָה אוֹתָם מֵהַיָּם, וּמִשּׁוּם שֶׁשָּׂם עַצְמוֹ בִּתְפִלָּה עַל יִשְׂרָאֵל בַּיָּם, נִקְרָא (על שמו) הַמַּעֲלֵם מִיָּם, שֶׁהוּא הֶעֱלָה אוֹתָם מֵהַיָּם.</p>\n<p>אַיֵּה הַשָּׂם בְּקִרְבּוֹ אֶת רוּחַ קָדְשׁוֹ - זֶהוּ מֹשֶׁה, שֶׁהִשְׁרָה שְׁכִינָה בֵּין יִשְׂרָאֵל. מוֹלִיכָם בַּתְּהֹמוֹת - כְּשֶׁנִּבְקְעוּ הַמַּיִם וְהָלְכוּ בְּתוֹךְ הַתְּהוֹם בַּיַּבָּשָׁה שֶׁקָּפְאוּ הַמַּיִם (והכל נאמר על משה) (נ\"א: ועל זה נקרא משה עמו), מִשּׁוּם שֶׁמָּסַר עַצְמוֹ עַל יִשְׂרָאֵל.</p>\n<p>אָמַר רַבִּי יְהוּדָה, אַף עַל גַּב שֶׁצַּדִּיק הָיָה נֹחַ, אֵינוֹ כְּדַאי (כדי) שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא יָגֵן עַל הָעוֹלָם בִּשְׁבִילוֹ. בֹּא רְאֵה, מֹשֶׁה לֹא תָלָה הַדָּבָר בִּזְכוּתוֹ, אֶלָּא בִּזְכוּת הָאָבוֹת הָרִאשׁוֹנִים, אֲבָל לְנֹחַ לֹא הָיָה לוֹ בְּמַה שֶּׁיִּתְלֶה בִּזְכוּת כְּמוֹ מֹשֶׁה.</p>\n<p>אָמַר רַבִּי יִצְחָק, וְעִם כָּל זֶה, כֵּיוָן שֶׁאָמַר לוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא וַהֲקִמֹתִי אֶת בְּרִיתִי אִתָּךְ, הָיָה לוֹ לְבַקֵּשׁ עֲלֵיהֶם רַחֲמִים. וְהַקָּרְבָּן שֶׁהִקְרִיב אַחַר כָּךְ - שֶׁיַּקְרִיב אוֹתוֹ מִקֹּדֶם לָזֶה, אוּלַי יִשְׁכַּךְ הַכַּעַס מֵהָעוֹלָם.</p>\n<p>אָמַר רַבִּי יְהוּדָה, מֶה הָיָה לוֹ לַעֲשׂוֹת, שֶׁהֲרֵי רִשְׁעֵי הָעוֹלָם הָיוּ מַכְעִיסִים לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא, וְהוּא יַקְרִיב קָרְבָּן!? אֶלָּא וַדַּאי נֹחַ פּוֹחֵד עַל עַצְמוֹ הָיָה בִּשְׁבִיל שֶׁלֹּא יִפְגֹּשׁ בּוֹ הַמָּוֶת בְּתוֹךְ רִשְׁעֵי הָעוֹלָם, שֶׁהָיָה רוֹאֶה מַעֲשֵׂיהֶם הָרָעִים בְּכָל יוֹם וְאֵיךְ מַכְעִיסִים לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא כָּל יוֹם.</p>\n<p>רַבִּי (אלעזר פתח) יִצְחָק אָמַר, כָּל פַּעַם שֶׁמִּתְרַבִּים רִשְׁעֵי הָעוֹלָם, הַצַּדִּיק שֶׁנִּמְצָא בֵינֵיהֶם נִתְפָּס בָּרִאשׁוֹנָה, שֶׁכָּתוּב (יחזקאל ט) וּמִמִּקְדָּשִׁי תָּחֵלּוּ. וְשָׁנִינוּ, אַל תִּקְרֵי מִמִּקְדָּשִׁי אֶלָּא מִמְקֻדָּשִׁי. וְאֵיךְ הִשְׁאִיר הַקָּדוֹשׁ בָּרוּךְ הוּא אֶת נֹחַ בֵּין כָּל אוֹתָם הָרְשָׁעִים? אֶלָּא כְּדֵי שֶׁיֵּצְאוּ מִמֶּנּוּ תוֹלָדוֹת לָעוֹלָם, שֶׁהָיָה צַדִּיק כָּרָאוּי.</p>\n<p>וְעוֹד, שֶׁהוּא הִתְרָה בָהֶם כָּל יוֹם וָיוֹם וְלֹא קִבְּלוּ מִמֶּנּוּ, וְקִיֵּם בְּנַפְשׁוֹ אֶת הַפָּסוּק שֶׁכָּתוּב (שם ג) וְאַתָּה כִּי הִזְהַרְתָּ רָשָׁע וְגוֹ', וְכָתוּב וְאַתָּה אֶת נַפְשְׁךְ הִצַּלְתָּ. מִכָּאן שֶׁכָּל מִי שֶׁמַּזְהִיר אֶת הָרָשָׁע - אַף עַל גַּב שֶׁלֹּא קִבֵּל מִמֶּנּוּ, הוּא מַצִּיל אֶת עַצְמוֹ, וְאוֹתוֹ רָשָׁע נִתְפָּס בְּחֶטְאוֹ. וְעַד כַּמָּה יַזְהִיר אוֹתוֹ? עַד שֶׁיַּכֶּה אוֹתוֹ, וַהֲרֵי פֵּרְשׁוּהָ הַחֲבֵרִים.</p>\n<p>רַבִּי יוֹסֵי הָיָה מָצוּי לִפְנֵי רַבִּי שִׁמְעוֹן יוֹם אֶחָד. אָמַר לוֹ, מָה רָאָה הַקָּדוֹשׁ בָּרוּךְ הוּא לְהַשְׁמִיד אֶת כָּל חַיּוֹת הַבָּר וְעוֹף הַשָּׁמַיִם עִם הָרְשָׁעִים? אִם בְּנֵי הָאָדָם חָטְאוּ, בְּהֵמוֹת וְעוֹפוֹת הַשָּׁמַיִם וּשְׁאָר הַבְּרִיּוֹת מֶה חָטְאוּ? אָמַר לוֹ, מִשּׁוּם שֶׁכָּתוּב כִּי הִשְׁחִית כָּל בָּשָׂר אֶת דַּרְכּוֹ עַל הָאָרֶץ. כֻּלָּם הָיוּ מַשְׁחִיתִים דַּרְכֵיהֶם. עָזְבוּ אֶת מִינָם וְנִדְבְּקוּ בְּמִין אַחֵר.</p>\n<p>בֹּא רְאֵה, אוֹתָם רִשְׁעֵי הָעוֹלָם גָּרְמוּ כָּךְ לְכָל הַבְּרִיּוֹת, וְרָצוּ (להשכיח) לְהַכְחִישׁ מַעֲשֵׂה בְרֵאשִׁית, וְהֵם גָּרְמוּ לְכָל הַבְּרִיּוֹת לְהַשְׁחִית דַּרְכָּם כְּמוֹ שֶׁהֵם הִשְׁחִיתוּ. אָמַר הַקָּדוֹשׁ בָּרוּךְ הוּא, אַתֶּם רְצִיתֶם (להשכיח) לְהַכְחִישׁ מַעֲשֵׂי יָדַי? אֲנִי אַשְׁלִים רְצוֹנְכֶם, וּמָחִיתִי אֶת כָּל הַיְקוּם אֲשֶׁר עָשִׂיתִי מֵעַל פְּנֵי הָאֲדָמָה. אַחֲזִיר הָעוֹלָם לְמַיִם כְּמוֹ שֶׁהָיָה בַּהַתְחָלָה, מַיִם בְּמַיִם, וַהֲרֵי נִתְבָּאֵר. מִכָּאן וָהָלְאָה אֶעֱשֶׂה בְּרִיּוֹת אֲחֵרוֹת בָּעוֹלָם כָּרָאוּי.</p>"],[9522011162,"<p>וַיָּבֹא נֹחַ וּבָנָיו וְאִשְׁתּוֹ וּנְשֵׁי בָנָיו אִתּוֹ. רַבִּי חִיָּיא פָּתַח וְאָמַר, (ירמיה כג) אִם יִסָּתֵר אִישׁ בַּמִּסְתָּרִים וַאֲנִי לֹא אֶרְאֶנּוּ נְאֻם ה'. כַּמָּה הֵם בְּנֵי אָדָם אֲטוּמֵי לֵב וּסְתוּמֵי עֵינַיִם שֶׁלֹּא מַשְׁגִּיחִים וְלֹא יוֹדְעִים בִּכְבוֹד רִבּוֹנָם, שֶׁכָּתוּב בּוֹ הֲלוֹא אֶת הַשָּׁמַיִם וְאֶת הָאָרֶץ אֲנִי מָלֵא. אֵיךְ רוֹצִים בְּנֵי אָדָם לְהִסְתַּתֵּר מֵחֲטָאֵיהֶם וְאוֹמְרִים מִי רוֹאֵנוּ וּמִי יוֹדְעֵנוּ, וְכָתוּב (ישעיה כט) וְהָיָה בְמַחְשָׁךְ מַעֲשֵׂיהֶם. לְאָן יֵחָבְאוּ מִפָּנָיו?</p>\n<p>לְמֶלֶךָ שֶׁבָּנָה פַּלְטֵרִין וְעָשָׂה תַּחַת הָאָרֶץ מְחִלּוֹת נִסְתָּרוֹת. לְיָמִים מָרְדוּ בְּנֵי הָאַרְמוֹן בַּמֶּלֶךְ. הִקִּיף (צער) עֲלֵיהֶם הַמֶּלֶךְ בִּגְיָסוֹת. מֶה עָשׂוּ? נִכְנְסוּ וְהֶחְבִּיאוּ עַצְמָם תַּחַת נִקְבֵי הַמְּחִלּוֹת. אָמַר הַמֶּלֶךְ, אֲנִי עָשִׂיתִי אוֹתָם, וּמִלְּפָנַי אַתֶּם רוֹצִים לְהִתְחַבֵּא? זֶהוּ שֶׁכָּתוּב אִם יִסָּתֵר אִישׁ בַּמִּסְתָּרִים וַאֲנִי לֹא אֶרְאֶנּוּ נְאֻם ה'? אֲנִי הוּא שֶׁעָשִׂיתִי מְחִלּוֹת וְעָשִׂיתִי חֹשֶׁךְ וְאוֹר, וְאַתֶּם אֵיךְ תּוּכְלוּ לְהִתְחַבֵּא מִלְּפָנַי?!</p>\n<p>בֹּא רְאֵה, כְּשֶׁאָדָם חוֹטֵא לִפְנֵי רִבּוֹנוֹ וּמַמְשִׁיךְ עַצְמוֹ לְהִסְתַּתֵּר, הַקָּדוֹשׁ בָּרוּךְ הוּא עוֹשֶׂה בּוֹ דִּין בְּגָלוּי. וּכְשֶׁהָאָדָם מְטַהֵר עַצְמוֹ, הַקָּדוֹשׁ בָּרוּךְ הוּא רוֹצֶה לְהַסְתִּירוֹ שֶׁלֹּא יִרְאֶה בְּיוֹם אַף ה'. שֶׁוַּדַּאי שֶׁצָּרִיךְ לוֹ לָאָדָם שֶׁלֹּא לְהֵרָאוֹת לִפְנֵי הַמַּשְׁחִית כְּשֶׁשּׁוֹרֶה עַל הָעוֹלָם שֶׁלֹּא יִסְתַּכֵּל בּוֹ, שֶׁהֲרֵי כָּל אֵלּוּ שֶׁנִּרְאִים לְפָנָיו, יֵשׁ לוֹ רְשׁוּת לְהַשְׁחִית.</p>\n<p>וְזְהִוּ מַה שֶּׁאָמַר רַבִּי שִׁמְעוֹן, כָּל אָדָם שֶׁעֵינוֹ רָעָה - עֵין הַמַּשְׁחִית שׁוֹרָה עָלָיו. וְהוּא נִקְרָא מַשְׁחִית הָעוֹלָם. וְצָרִיךְ הָאָדָם לְהִשָּׁמֵר מִמֶּנּוּ וְלֹא לְהִתְקָרֵב אֵלָיו כְּדֵי שֶׁלֹּא יִנָּזֵק (לפניו), וְאָסוּר לִקְרַב אֵלָיו בְּהִתְגַּלּוּת. וּמִשּׁוּם כָּךְ צָרִיךְ לְהִשָּׁמֵר מֵאִישׁ רַע עַיִן, וּמִלִּפְנֵי מַלְאַךְ הַמָּוֶת עַל אַחַת כַּמָּה וְכַמָּה.</p>\n<p>(ועל זה) מַה כָּתוּב בְּבִלְעָם? (במדבר כד) וּנְאֻם הַגֶּבֶר שְׁתֻם הָעָיִן. שֶׁעַיִן רָעָה הָיְתָה לוֹ, וּבְכָל מָקוֹם שֶׁהָיָה מִסְתַּכֵּל בּוֹ, הָיָה מַמְשִׁיךְ עָלָיו אֶת רוּחַ הַמַּשְׁחִית. וְלָכֵן רָצָה לְהִסְתַּכֵּל בְּיִשְׂרָאֵל, כְּדֵי לְהַשְׁמִיד בְּכָל מָקוֹם שֶׁעֵינָיו הָיוּ מִסְתַּכְּלוֹת. מַה כָּתוּב? וַיִּשָּׂא בִלְעָם אֶת עֵינָיו. שֶׁזָּקַף עַיִן אַחַת וְהִנְמִיךְ עַיִן אַחַת כְּדֵי לְהִסְתַּכֵּל עַל יִשְׂרָאֵל בְּעַיִן רָעָה.</p>\n<p>בֹּא רְאֵה מַה כָּתוּב, וַיַּרְא אֶת יִשְׂרָאֵל שֹׁכֵן לִשְׁבָטָיו. וְרָאָה שֶׁהַשְּׁכִינָה מְכַסָּה עֲלֵיהֶם וְרוֹבֶצֶת עֲלֵיהֶם מְתֻקֶּנֶת בִּשְׁנֵים עָשָׂר שְׁבָטִים תַּחְתֶּיהָ, וְאֵין יְכוֹלוֹת עֵינָיו לִשְׁלֹט עֲלֵיהֶם. אָמַר, אֵיךְ אוּכַל לָהֶם, שֶׁהֲרֵי רוּחַ קְדוֹשָׁה עֶלְיוֹנָה רוֹבֶצֶת עֲלֵיהֶם וּמְכַסָּה אוֹתָם בִּכְנָפֶיהָ? זֶהוּ שֶׁכָּתוּב כָּרַע שָׁכַב כַּאֲרִי וּכְלָבִיא מִי יְקִימֶנּוּ. מִי יְקִימֶנּוּ מֵעֲלֵיהֶם כְּדֵי שֶׁיִּתְגַּלּוּ וְתִשְׁלֹט עֲלֵיהֶם הָעַיִן.</p>\n<p>וְעַל זֶה רָצָה הַקָּדוֹשׁ בָּרוּךְ הוּא לְכַסּוֹת אֶת נֹחַ, לְהִסְתַּתֵּר מֵהָעַיִן, שֶׁלֹּא תוּכַל רוּחַ הַטֻּמְאָה לִשְׁלֹט עָלָיו כְּדֵי שֶׁלֹּא יֻשְׁחַת, וַהֲרֵי נִתְבָּאֵר. וַיָּבֹא נֹחַ, כְּמוֹ שֶׁנִּתְבָּאֵר לְהִסְתַּתֵּר מֵהָעַיִן. מִפְּנֵי מֵי הַמַּבּוּל, (שהרי) הַמַּיִם דָּחֲקוּ אוֹתוֹ. אָמַר רַבִּי יוֹסֵי, רָאָה מַלְאַךְ הַמָּוֶת שֶׁהָיָה בָּא (אליו) וְלָכֵן נִכְנַס לַתֵּבָה וְנִשְׁמַר בָּהּ שְׁנֵים עָשָׂר חֳדָשִׁים (של השנה).</p>\n<p>וְלָמָּה שְׁנֵים עָשָׂר חֳדָשִׁים? נֶחְלְקוּ בָהּ רַבִּי יִצְחָק וְרַבִּי יְהוּדָה. הָאֶחָד אָמַר שְׁנֵים עָשָׂר חֹדֶשׁ שֶׁכָּךְ הוּא דִין הָרְשָׁעִים. וְאֶחָד אָמַר לְהַשְׁלִים צַדִּיק (נ\"א צריך) שְׁתֵּים עֶשְׂרֵה דְרָגוֹת וּשְׁאָר הַדְּרָגוֹת שֶׁהָיוּ רְאוּיִים לָצֵאת מֵהַתֵּבָה.</p>\n<p>רַבִּי יְהוּדָה אָמַר, שִׁשָּׁה חֳדָשִׁים הֵם בְּמַיִם וְשִׁשָּׁה חֳדָשִׁים בְּאֵשׁ, וַהֲרֵי כָּאן הָיוּ מַיִם, וְלָמָּה שְׁנֵים עָשָׂר חֳדָשִׁים? אָמַר (לו) רַבִּי יוֹסֵי, בִּשְׁנֵי דִינֵי הַגֵּיהִנֹּם נִדּוֹנוּ - בְּמַיִם וְאֵשׁ. בְּמַיִם - שֶׁהַמַּיִם שֶׁיָּרְדוּ עֲלֵיהֶם מִלְמַעְלָה הָיוּ צוֹנְנִים כַּשֶּׁלֶג. וּבְאֵשׁ - שֶׁהַמַּיִם שֶׁיָּצְאוּ מִלְּמַטָּה הָיוּ רוֹתְחִים כָּאֵשׁ. וְעַל זֶה בְּדִין הַגֵּיהִנֹּם נִדּוֹנוּ - בְּאֵשׁ וּמַיִם (ולכן שנים עשר חדש היו, שאמר רבי אלעזר, דין הרשעים בגיהנם הם שנים עשר חדשים, והרי פרשוה, ועל זה כל אותם רשעי העולם נדונים בשני דינים הללו במים ואש) עַד שֶׁהֻשְׁמְדוּ מִן הָעוֹלָם. וְנֹחַ הָיָה מִסְתַּתֵּר בַּתֵּבָה וְהִתְכַּסָּה מִן הָעַיִן וְהַמַּשְׁחִית וְלֹא קָרַב אֵלָיו, וְהַתֵּבָה הָיְתָה שָׁטָה עַל פְּנֵי הַמַּיִם, כְּמוֹ שֶׁנֶּאֱמַר וַיִּשְׂאוּ אֶת הַתֵּבָה וַתָּרָם מֵעַל הָאָרֶץ.</p>\n<p>אַרְבָּעִים יוֹם לָקוּ, שֶׁכָּתוּב וַיְהִי הַמַּבּוּל אַרְבָּעִים יוֹם עַל הָאָרֶץ וְגוֹ'. וְכָל שְׁאָר הַזְּמַן נִמְחוּ מֵהָעוֹלָם. זֶהוּ שֶׁכָּתוּב וַיִּמָּחוּ מִן הָאָרֶץ. אוֹי לָהֶם לְאוֹתָם רְשָׁעִים, שֶׁהֲרֵי לֹא יָקוּמוּ לִחְיוֹת בָּעוֹלָם לַעֲמֹד בְּדִין. זֶהוּ שֶׁכָּתוּב וַיִּמָּחוּ, כְּמוֹ שֶׁנֶּאֱמַר (תהלים ט) שְׁמָם מָחִיתָ לְעוֹלָם וָעֶד. שֶׁאֲפִלּוּ לַעֲמֹד בְּדִין לֹא יָקוּמוּ.</p>"],[9522011163,"<p>וַיִּשְׂאוּ אֶת הַתֵּבָה וַתָּרָם מֵעַל הָאָרֶץ. רַבִּי אַבָּא פָּתַח, (שם נז) רוּמָה עַל הַשָּׁמַיִם אֱלֹהִים עַל כָּל הָאָרֶץ כְּבוֹדֶךְ. אוֹי לָהֶם לָרְשָׁעִים שֶׁחוֹטְאִים וּמַרְגִּיזִים אֶת רִבּוֹנָם בְּכָל יוֹם, וּבַחֲטָאֵיהֶם דּוֹחִים אֶת הַשְּׁכִינָה מִן הָאָרֶץ, וְגוֹרְמִים שֶׁתִּסְתַּלֵּק מִן הָעוֹלָם. וְהַשְּׁכִינָה נִקְרֵאת אֱלֹהִים, וְעָלֶיהָ כָּתוּב רוּמָה עַל הַשָּׁמַיִם אֱלֹהִים.</p>\n<p>בֹּא רְאֵה מַה כָּתוּב, וַיִּשְׂאוּ אֶת הַתֵּבָה, שֶׁדָּחוּ אוֹתָהּ הַחוּצָה. וַתָּרָם מֵעַל הָאָרֶץ, שֶׁלֹּא שׁוֹרָה בָּעוֹלָם וְהִסְתַּלְּקָה מִמֶּנּוּ. וּכְשֶׁהִיא מִסְתַּלֶּקֶת מֵהָעוֹלָם, הֲרֵי אֵין מִי שֶׁיַּשְׁגִּיחַ בָּעוֹלָם, וְאָז הַדִּין שׁוֹלֵט (הדין) עָלָיו. וּכְשֶׁיִּמָּחוּ רִשְׁעֵי הָעוֹלָם וְיִסְתַּלְּקוּ מִמֶּנּוּ (מהעולם), הַשְּׁכִינָה מַחֲזִירָה אֶת מְדוֹרָהּ לָעוֹלָם.</p>\n<p>אָמַר לוֹ רַבִּי יֵיסָא, אִם כָּךְ, הֲרֵי אֶרֶץ יִשְׂרָאֵל שֶׁנִּמְחוּ הָרְשָׁעִים שֶׁהָיוּ בְּאוֹתוֹ זְמַן, אָז לָמָּה לֹא חָזְרָה הַשְּׁכִינָה לִמְקוֹמָהּ כְּבַתְּחִלָּה? אָמַר לוֹ, מִשּׁוּם שֶׁלֹּא נִשְׁאֲרוּ בָהּ שְׁאָר צַדִּיקֵי הָעוֹלָם, אֶלָּא (אבל) בְּכָל מָקוֹם שֶׁהָלְכוּ, יָרְדָה וְשָׂמָה אֶת מְדוֹרָהּ עִמָּהֶם. וּמָה בְּאֶרֶץ נָכְרִיָּה אַחֶרֶת לֹא נִפְרְדָה מֵהֶם - כָּל שֶׁכֵּן אִם נִשְׁאֲרוּ בָּאָרֶץ הַקְּדוֹשָׁה.</p>\n<p>וַהֲרֵי אָמַרְנוּ. בְּכָל הַחֲטָאִים שֶׁל רִשְׁעֵי הָעוֹלָם, דּוֹחִים אֶת הַשְּׁכִינָה. אֶחָד מֵהֶם מִי שֶׁמַּשְׁחִית דַּרְכּוֹ עַל הָאָרֶץ, כְּמוֹ שֶׁאָמַרְנוּ, וְלָכֵן לֹא רוֹאֶה פְּנֵי שְׁכִינָה וְלֹא נִכְנָס לַפַּלְטֵרִין. וְעַל זֶה כָּתוּב עַל אֵלֶּה וַיִּמָּחוּ מִן הָאָרֶץ, שֶׁנִּמְחוּ מֵהַכֹּל.</p>\n<p>בֹּא רְאֵה, בְּאוֹתוֹ הַזְּמַן שֶׁעָתִיד הַקָּדוֹשׁ בָּרוּךְ הוּא לְהַחֲיוֹת הַמֵּתִים, כָּל אוֹתָם מֵתִים שֶׁיִּמָּצְאוּ בַחוּץ בִּשְׁאָר אֲרָצוֹת נָכְרִיּוֹת, הַקָּדוֹשׁ בָּרוּךְ הוּא יִבְרָא לָהֶם גּוּפֵיהֶם (נ\"א: יעמידם בגופם) כָּרָאוּי. שֶׁהֲרֵי עֶצֶם אַחַת שֶׁנִּשְׁאֶרֶת בָּאָדָם תַּחַת הָאָרֶץ, אוֹתָהּ עֶצֶם תֵּעָשֶׂה כַּשְּׂאוֹר שֶׁבָּעִסָּה, וְעָלֶיהָ יִבְנֶה הַקָּדוֹשׁ בָּרוּךְ הוּא אֶת כָּל הַגּוּף.</p>\n<p>וְלֹא יִתֵּן הַקָּדוֹשׁ בָּרוּךְ הוּא לָהֶם נְשָׁמוֹת אֶלָּא בְּאֶרֶץ יִשְׂרָאֵל, שֶׁכָּתוּב (יחזקאל לז) הִנֵּה אֲנִי פֹתֵחַ אֶת קִבְרוֹתֵיכֶם וְהַעֲלֵיתִי אֶתְכֶם מִקִּבְרוֹתֵיכֶם עַמִּי וְהֵבֵאתִי אֶתְכֶם אֶל אַדְמַת יִשְׂרָאֵל. שֶׁיִּתְגַּלְגְּלוּ תַּחַת הָאָרֶץ. וְאַחַר כָּךְ מַה כָּתוּב? וְנָתַתִּי רוּחִי בָכֶם וִחְיִיתֶם וְגוֹ', שֶׁהֲרֵי בְּאֶרֶץ יִשְׂרָאֵל יְקַבְּלוּ נְשָׁמוֹת כָּל אוֹתָם בְּנֵי הָעוֹלָם, פְּרָט לְאֵלּוּ (דור המבול) שֶׁנִּטְמְאוּ וְטִמְּאוּ אֶת הָאָרֶץ. בְּאֵלֶּה כָּתוּב וַיִּמָּחוּ מִן הָאָרֶץ, דַּוְקָא מִן הָאָרֶץ. וְאַף עַל גַּב שֶׁהִקְשׁוּ וְנֶחְלְקוּ הָרִאשׁוֹנִים עַל זֶה. וַיִּמָּחוּ, כְּמוֹ שֶׁנֶּאֱמַר (תהלים סט) יִמָּחוּ מִסֵּפֶר חַיִּים.</p>\n<p>אָמַר לוֹ רַבִּי שִׁמְעוֹן, וַדַּאי שֶׁאֵין לָהֶם חֵלֶק בָּעוֹלָם הַבָּא, שֶׁכָּתוּב וַיִּמָּחוּ מִן הָאָרֶץ, וְכָתוּב לְעוֹלָם יִירְשׁוּ אָרֶץ. אֲבָל יָקוּמוּ בְדִין. וַעֲלֵיהֶם כָּתוּב (דניאל יב) וְרַבִּים מִיְּשֵׁנֵי עָפָר יָקִיצוּ אֵלֶּה לְחַיֵּי עוֹלָם וְאֵלֶּה לַחֲרָפוֹת לְדִרְאוֹן עוֹלָם. וְהַמַּחֲלֹקֶת בָּזֶה. אֲבָל הַכֹּל כְּפִי שֶׁבֵּאֲרוּהָ הַחֲבֵרִים.</p>"],[9522011164,"<p>וַיִּמַח אֶת כָּל הַיְקוּם אֲשֶׁר עַל פְּנֵי הָאֲדָמָה. רַבִּי אַבָּא אָמַר, (את כל) - לִכְלֹל כָּל אוֹתָם שַׁלִּיטִים שֶׁשּׁוֹלְטִים הַמְמֻנִּים עַל הָאָרֶץ, וְזֶהוּ הַיְקוּם אֲשֶׁר עַל פְּנֵי הָאֲדָמָה. שֶׁכַּאֲשֶׁר עוֹשֶׂה הַקָּדוֹשׁ בָּרוּךְ הוּא דִּין בִּבְנֵי הָעוֹלָם, מַעֲבִיר אֶת אוֹתָם הַשַּׁלִּיטִים הַמְמֻנִּים עֲלֵיהֶם בַּהַתְחָלָה, וְאַחַר כָּךְ אֶת אוֹתָם שֶׁיּוֹשְׁבִים תַּחַת כַּנְפֵיהֶם, שֶׁכָּתוּב (ישעיה כד) יִפְקֹד ה' עַל צְבָא הַמָּרוֹם בַּמָּרוֹם, וְאַחַר כָּךְ - עַל מַלְכֵי הָאֲדָמָה עַל הָאֲדָמָה.</p>\n<p>וְאֵיךָ מָעֳבָרִים מִלְּפָנָיו? אֶלָּא מַעֲבִיר אוֹתָם בְּאֵשׁ שֶׁדּוֹלֶקֶת. זֶהוּ שֶׁכָּתוּב (דברים ד) כִּי ה' אֱלֹהֶיךְ אֵשׁ אֹכְלָה הוּא אֵל קַנָּא. אֵשׁ (הוא) שֶׁאוֹכֶלֶת אֵשׁ. אוֹתוֹ שֶׁעוֹמֵד מֵעֲלֵיהֶם (נ\"א: עובר) בְּאֵשׁ. וְאוֹתָם שֶׁיּוֹשְׁבִים תַּחְתֵּיהֶם בְּמַיִם. וּמִשּׁוּם כָּךְ וַיִּמַח אֶת כָּל הַיְקוּם אֲשֶׁר עַל פְּנֵי הָאֲדָמָה, וְאַחַר כָּךְ מֵאָדָם וְעַד בְּהֵמָה עַד רֶמֶשׂ וְעַד עוֹף הַשָּׁמַיִם וַיִּמָּחוּ מִן הָאָרֶץ, כָּל אֵלּוּ שֶׁלְּמַטָּה. וַיִּשָּׁאֵר אַךְ נֹחַ - אַךְ לְמַעֵט. שֶׁלֹּא נִשְׁאֲרוּ בָּעוֹלָם רַק נֹחַ וּמִי שֶׁעִמּוֹ בַּתֵּבָה. רַבִּי יוֹסֵי אָמַר, שֶׁהָיָה חִגֵּר, שֶׁהִכִּישׁוֹ אַרְיֵה, וַהֲרֵי פֵּרְשׁוּהָ.</p>"],[9522011165,"<p>וַיִּזְכֹּר אֱלֹהִים אֶת נֹחַ וְאֶת כָּל הַחַיָּה וְאֶת כָּל הַבְּהֵמָה אֲשֶׁר אִתּוֹ בַּתֵּבָה. רַבִּי חִיָּיא פָּתַח, (משלי כב) עָרוּם רָעָה רָעָה וְנִסְתָּר. פָּסוּק זֶה נֶאֱמַר עַל נֹחַ שֶׁנִּכְנַס לַתֵּבָה וְהִסְתַּתֵּר בָּהּ, וְנִכְנַס לְתוֹךְ הַתֵּבָה בִּזְמַן שֶׁהַמַּיִם דָּחֲקוּ אוֹתוֹ. וַהֲרֵי נֶאֱמַר שֶׁעַד שֶׁלֹּא נִכְנַס לַתֵּבָה, רָאָה אֶת מַלְאַךְ הַמָּוֶת שֶׁהוֹלֵךְ בֵּינֵיהֶם וּמַקִּיף אוֹתָם. כֵּיוָן שֶׁרָאָה אוֹתוֹ, נִכְנַס לַתֵּבָה וְהִסְתַּתֵּר בְּתוֹכָהּ. זֶהוּ שֶׁכָּתוּב עָרוּם רָאָה רָעָה וְנִסְתָּר. רָאָה רָעָה - זֶהוּ מַלְאַךְ הַמָּוֶת, וְנִסְתַּר מִלְּפָנָיו. זֶהוּ שֶׁכָּתוּב מִפְּנֵי מֵי הַמַּבּוּל.</p>\n<p>רַבִּי יוֹסֵי אָמַר, עָרוּם רָאָה רָעָה וְנִסְתָּר, (לא כתוב ויסתר) חָזַר עַל מַה שֶּׁנֶּאֱמַר, בִּזְמַן שֶׁהַמָּוֶת שָׁרוּי בָּעוֹלָם, בֶּן אָדָם חָכָם יִסְתַּתֵּר וְלֹא יַעֲמֹד בַּחוּץ וְלֹא יִתְרָאֶה לִפְנֵי הַמַּשְׁחִית, מִשּׁוּם שֶׁכֵּיוָן שֶׁנִּתְּנָה לוֹ הָרְשׁוּת, הוּא יַשְׁחִית אֶת כָּל אוֹתָם שֶׁנִּמְצָאִים לְפָנָיו וְעוֹבְרִים לְפָנָיו גָּלוּי. וְסוֹף הַפָּסוּק - וּפְתָאִים עָבְרוּ וְנֶעֱנָשׁוּ. עָבְרוּ לְפָנָיו וְהִתְרָאוּ לְפָנָיו, וְנֶעֱנָשׁוּ. דָּבָר אַחֵר עָבְרוּ - עָבְרוּ עַל מִצְוָה זוֹ (נ\"א: של רבונם) וְנֶעֱנָשׁוּ. דָּבָר אַחֵר עָרוּם רָאָה רָעָה וְנִסְתָּר - זֶה נֹחַ. וּפְתָאִים עָבְרוּ וְנֶעֱנָשׁוּ - אֵלּוּ בְּנֵי דוֹרוֹ (ונענשו).</p>\n<p>כֵּיוָן שֶׁהִסְתַּתֵּר וְהִשְׁתַּהָה שָׁם כָּל אוֹתוֹ זְמַן, אַחַר כָּךְ וַיִּזְכֹּר אֱלֹהִים אֶת נֹחַ. אָמַר רַבִּי שִׁמְעוֹן, (ויזכר אלהים את נח) בּא רְאֵה, בְּשָׁעָה שֶׁהַדִּין נַעֲשָׂה, לֹא כָתוּב בּוֹ זְכִירָה. כֵּיוָן שֶׁנַּעֲשָׂה (בו) הַדִּין וְנֶאֶבְדוּ רִשְׁעֵי הָעוֹלָם, אָז כָּתוּב בּוֹ זְכִירָה. שֶׁהֲרֵי כַּאֲשֶׁר הַדִּין שָׁרוּי בָּעוֹלָם, לֹא נִמְצֵאת הִתְחַבְּרוּת, וְהַמַּשְׁחִית שָׁרוּי עַל הָעוֹלָם.</p>\n<p>כֵּיוָן שֶׁעָבַר הַדִּין וְשָׁכַךְ הָרֹגֶז, שָׁב הַכֹּל לִמְקוֹמוֹ, וְלָכֵן כָּתוּב כָּאן וַיִּזְכֹּר אֱלֹהִים אֶת נֹחַ, שֶׁבּוֹ שׁוֹרֶה זָכוֹר, שֶׁנֹּחַ אִישׁ צַדִּיק כָּתוּב בּוֹ.</p>\n<p>כָּתוּב (תהלים פט) אַתָּה מוֹשֵׁל בְּגֵאוּת הַיָּם בְּשׂוֹא גַלָּיו אַתָּה תְשַׁבְּחֵם. בְּשָׁעָה שֶׁהַיָּם קוֹפֵץ בְּגַלָּיו וְהַתְּהוֹמוֹת עוֹלִים וְיוֹרְדִים, הַקָּדוֹשׁ בָּרוּךְ הוּא שׁוֹלֵחַ חוּט אֶחָד מִצַּד הַיָּמִין וּמוֹשֵׁךְ אֶת גַּלָּיו וְשׁוֹכֵךְ זַעְפּוֹ, וְאֵין מִי שֶׁיּוֹדֵעַ אוֹתוֹ.</p>\n<p>יוֹנָה יָרַד לַיָּם וְהִזְדַּמֵּן לוֹ אוֹתוֹ הַדָּג וּבָלַע אוֹתוֹ, אֵיךְ לֹא יָצְאָה נִשְׁמָתוֹ מִמֶּנּוּ וְלֹא פָרְחָה מִיָּד? אֶלָּא מִשּׁוּם שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא שׁוֹלֵט בְּאוֹתָהּ גֵּאוּת שֶׁל הַיָּם,</p>\n<p>וְאוֹתָהּ גֵּאוּת הַיָּם הִיא חוּט אֶחָד שֶׁל הַשְּׂמֹאל שֶׁמַּעֲלֶה אֶת הַיָּם לְמַעְלָה, וּבוֹ הוּא מִתְעַלָּה. וְאִם לֹא אוֹתוֹ הַחוּט שֶׁמַּגִּיעַ אֵלָיו מִצַּד הַיָּמִין, לֹא יַעֲלֶה לְעוֹלָמִים. שֶׁכַּאֲשֶׁר (שכיון) שֶׁאוֹתוֹ הַחוּט יוֹרֵד לַיָּם, וְהַיָּם אוֹחֵז בּוֹ, אָז מִתְעוֹרְרִים הַגַּלִּים וְשׁוֹאֲגִים לִטְרֹף טֶרֶף, עַד שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא מֵשִׁיב אוֹתוֹ (אותם) לְאָחוֹר וְשָׁבִים לִמְקוֹמָם.</p>\n<p>זְהִוּ שֶׁכָּתוּב בְּשׂוֹא גַלָּיו אַתָּה תְשַׁבְּחֵם. תְּשַׁבְּחֵם אֶת אוֹתָם גַּלֵּי הַיָּם. תְּשַׁבְּחֵם - תְּשַׁבֵּר אוֹתָם לַחֲזֹר לִמְקוֹמָם. דָּבָר אַחֵר, תְּשַׁבְּחֵם מַמָּשׁ. שֶׁבַח הוּא לָהֶם מִשּׁוּם שֶׁעוֹלִים לִרְאוֹת בְּהִשְׁתּוֹקְקוּת. מִכָּאן, כָּל מִי שֶׁנִּכְסָף לְהִסְתַּכֵּל וְלָדַעַת, אַף עַל גַּב שֶׁלֹּא יָכוֹל (נ\"א: ולא נותנים לו רשות) - הַשֶּׁבַח הוּא שֶׁלּוֹ, וְכֻלָּם מְשַׁבְּחִים אוֹתוֹ.</p>\n<p>אָמַר רַבִּי יְהוּדָה, נֹחַ, כְּשֶׁהָיָה בַּתֵּבָה, הָיָה פּוֹחֵד שֶׁלֹּא יִזְכֹּר אוֹתוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא לְעוֹלָמִים. וְכֵיוָן שֶׁנַּעֲשֶׂה הַדִּין וְנֶעֶבְרוּ רִשְׁעֵי הָעוֹלָם, אָז מַה כָּתוּב? וַיִּזְכֹּר אֱלֹהִים אֶת נֹחַ.</p>\n<p>רַבִּי אֶלְעָזָר אָמַר, בּא רְאֵה, בְּשָׁעָה שֶׁהַדִּין שָׁרוּי בָּעוֹלָם, לֹא צָרִיךְ לָאָדָם שֶׁיִּזָּכֵר שְׁמוֹ לְמַעְלָה (לפני הקדוש ברוך הוא בעולם). שֶׁהֲרֵי אִם נִזְכָּר שְׁמוֹ, נִזְכָּרִים (כל) חֲטָאָיו וְיָבוֹאוּ לְהַשְׁגִּיחַ בּוֹ.</p>\n<p>מִנַּיִן לָנוּ? מִשּׁוּנַמִּית. שֶׁאוֹתוֹ הַיּוֹם הָיָה יוֹם טוֹב שֶׁל רֹאשׁ הַשָּׁנָה, וְהַקָּדוֹשׁ בָּרוּךְ הוּא דָּן אֶת הָעוֹלָם, וְאָז אָמַר לָהּ אֱלִישָׁע (מלכים ב ד) הֲיֵשׁ לְדַבֵּר לָךְ אֶל הַמֶּלֶךְ? זֶה הַקָּדוֹשׁ בָּרוּךְ הוּא, שֶׁאָז נִקְרָא מֶלֶךְ. מֶלֶךְ הַקָּדוֹשׁ. מֶלֶךְ הַמִּשְׁפָּט. וַתֹּאמֶר בְּתוֹךְ עַמִּי אָנֹכִי יוֹשָׁבֶת. אֵינִי רוֹצָה שֶׁיִּזְכְּרוּ אוֹתִי וְיַשְׁגִּיחוּ בִי, אֶלָּא בְּתוֹךְ עַמִּי. מִי שֶׁמַּכְנִיס רֹאשׁוֹ בֵּין הָעָם (כלו), לֹא יַשְׁגִּיחוּ עָלָיו לָדוּן אוֹתוֹ לְרַע. מִשּׁוּם כָּךְ אָמְרָה בְּתוֹךְ עַמִּי.</p>\n<p>בֹּא רְאֵה, נֹחַ, בְּשָׁעָה שֶׁהָרֹגֶז הָיָה שָׁרוּי בָּעוֹלָם, לֹא נִזְכַּר. כֵּיוָן שֶׁעָבַר הַדִּין, מַה כָּתוּב? וַיִּזְכֹּר אֱלֹהִים אֶת נֹחַ. עַכְשָׁו נִזְכַּר שְׁמוֹ. דָּבָר אַחֵר וַיִּזְכֹּר אֱלֹהִים אֶת נֹחַ, כְּמוֹ שֶׁנֶּאֱמַר וָאֶזְכֹּר אֶת בְּרִיתִי.</p>"],[9522011166,"<p>רַבִּי חִזְקִיָּה הָיָה הוֹלֵךְ מִקַּפּוֹטְקִיָּא לְלוֹד. פָּגַע בּוֹ רַבִּי יֵיסָא. אָמַר לוֹ, תְּמֵהַנִי עָלֶיךְ שֶׁאַתָּה לְבַד, שֶׁהֲרֵי שָׁנִינוּ שֶׁלֹּא יֵצֵא אָדָם יְחִידִי לַדֶּרֶךְ. אָמַר לוֹ, תִּינוֹק אֶחָד הָלַךְ עִמִּי, וְהוּא בָא אַחֲרַי. אָמַר לוֹ, וְעַל זֶה אֲנִי תָּמֵהַּ, אֵיךְ הוֹלֵךְ עִמְּךְ מִי שֶׁלֹּא תְדַבֵּר עִמּוֹ דִּבְרֵי תוֹרָה? שֶׁהֲרֵי שָׁנִינוּ, כָּל מִי שֶׁהוֹלֵךְ בַּדֶּרֶךְ וְאֵין עִמּוֹ דִּבְרֵי תוֹרָה, מִסְתַּכֵּן בְּנַפְשׁוֹ. אָמַר לוֹ, כָּךְ זֶה בְּוַדַּאי.</p>\n<p>בֵּינְתַיִם הִגִּיעַ אוֹתוֹ תִינוֹק. אָמַר לוֹ רַבִּי יֵיסָא, בְּנִי, מֵאֵיזֶה מָקוֹם אַתָּה? אָמַר לוֹ, מֵעִיר לוֹד, וְשָׁמַעְתִּי שֶׁהָאִישׁ הַזֶּה הֶחָכָם הוֹלֵךְ לְשָׁם, וְזִמַּנְתִּי עַצְמִי לַעֲבוֹדָתוֹ וְלָלֶכֶת עִמּוֹ. אָמַר לוֹ, בְּנִי, אַתָּה יוֹדֵעַ דִּבְרֵי תוֹרָה?</p>\n<p>אָמַר לוֹ, אֲנִי יוֹדֵעַ, שֶׁהֲרֵי אָבִי לִמֵּד אוֹתִי בְּפָרָשַׁת קָרְבָּנוֹת, וְהִרְכַּנְתִּי אָזְנַי לְמַה שֶּׁהָיָה אוֹמֵר עִם אָחִי, שֶׁהוּא גָּדוֹל מִמֶּנִּי. אָמַר לוֹ רַבִּי יֵיסָא, בְּנִי, אֱמֹר לִי.</p>\n<p>פָּתַח וְאָמַר: וַיִּבֶן נֹחַ מִזְבֵּחַ לַה' וַיִּקַּח מִכֹּל הַבְּהֵמָה הַטְּהֹרָה וּמִכֹּל הָעוֹף הַטָּהוֹר וַיַּעַל עֹלֹת בַּמִּזְבֵּחַ. וַיִּבֶן נֹחַ מִזְבֵּחַ - זֶהוּ הַמִּזְבֵּחַ שֶׁהִקְרִיב בּוֹ אָדָם הָרִאשׁוֹן. לָמָּה נֹחַ הִקְרִיב עוֹלָה, שֶׁהֲרֵי עוֹלָה לֹא עוֹלָה אֶלָּא בִּשְׁבִיל הִרְהוּר וּרְצוֹן הַלֵּב, וְנֹחַ בַּמָּה חָטָא? אֶלָּא נֹחַ הִרְהֵר וְאָמַר: הֲרֵי הַקָּדוֹשׁ בָּרוּךְ הוּא גָּזַר דִּין עַל הָעוֹלָם שֶׁיֵּחָרֵב, אוּלַי מִשּׁוּם שֶׁמַּצִּיל אוֹתִי פָּקְעָה כָּל זְכוּתִי וְלֹא תִשָּׁאֵר לִי זְכוּת בָּעוֹלָם? מִיָּד - וַיִּבֶן נֹחַ מִזְבֵּחַ לַה'.</p>\n<p>אוֹתוֹ מִזְבֵּחַ שֶׁבּוֹ הִקְרִיב אָדָם הָרִאשׁוֹן הָיָה. אִם כָּךְ, אָז לָמָּה וַיִּבֶן? אֶלָּא מִשּׁוּם שֶׁרִשְׁעֵי הָעוֹלָם גָּרְמוּ שֶׁלֹּא עָמַד בִּמְקוֹמוֹ. כֵּיוָן שֶׁבָּא נֹחַ, כָּתוּב בּוֹ וַיִּבֶן.</p>\n<p>וַיַּעַל עֹלֹת, כָּתוּב עֹלַת, אֶחָד. כָּתוּב (ויקרא א) עֹלָה הִוא אִשֵּׁה רֵיחַ נִיחֹחַ לַה' (לעולם עלה עולה זכר, אם) עוֹלָה - עוֹלֶה זָכָר וְלֹא עוֹלָה נְקֵבָה, שֶׁכָּתוּב זָכָר תָּמִים יַקְרִיבֶנּוּ. לָמָּה כָּתוּב אִשֶּׁה, שֶׁהֲרֵי אֵשׁ צְרִיכָה לְהִמָּצֵא שָׁם?</p>\n<p>אֶלָּא אַף עַל גַּב שֶׁעוֹלָה נִקְרֶבֶת זָכָר וְלִמְקוֹמָהּ נִקְרֶבֶת, הַנְּקֵבָה לֹא צְרִיכָה לְהִפָּרֵד מִמֶּנּוּ, אֶלָּא עִמָּהּ נִקְרָב, בִּשְׁבִיל לְחַבֵּר זֶה עִם זֶה. שֶׁעוֹלָה הַנְּקֵבָה אֶל הַזָּכָר לְהִתְחַבֵּר כְּאֶחָד, וְאַף עַל גַּב שֶׁאִשֶּׁה לְשׁוּם אִישִׁים.</p>\n<p>נֹחַ הָיָה צָרִיךְ לְהַקְרִיב עוֹלָה, שֶׁהוּא בַּמָּקוֹם שֶׁל הַזָּכָר, עָשָׂה אוֹתוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא לְהִתְחַבֵּר וּלְהִכָּנֵס לַתֵּבָה, וְעַל זֶה הִקְרִיב עוֹלָה. עוֹלָה הוּא אִשֶּׁה. אֵשׁ ה'. שֶׁהִתְחַבֵּר (עמה) הַשְּׂמֹאל בַּנְּקֵבָה. שֶׁהֲרֵי (כל) נְקֵבָה מִצַּד הַשְּׂמֹאל בָּאָה, וְזָכָר מִצַּד הַיָּמִין בְּהִתְדַּבְּקוּת זֶה בָּזֶה, וְלָכֵן נִקְרֵאת (עולה) נְקֵבָה אִשֶּׁה. אִשֶּׁה - קֶשֶׁר שֶׁל הָאַהֲבָה שֶׁאוֹחֵז בָּהּ הַשְּׂמֹאל לְהַעֲלוֹתָהּ לְמַעְלָה וּלְהִתְקַשֵּׁר כְּאֶחָד, וְלָכֵן כָּתוּב עֹלָה הִוא אִשֵּׁה, הַקֶּשֶׁר שֶׁל זָכָר וּנְקֵבָה זֶה עִם זֶה.</p>"],[9522011167,"<p>וַיָּרַח ה' אֶת רֵיחַ הַנִּיחֹחַ. וְכָתוּב אִשֵּׁה רֵיחַ נִיחֹחַ. אִשֶּׁה, כָּךְ שָׁמַעְנוּ - עָשָׁן וְאֵשׁ מְחֻבָּרִים כְּאֶחָד, שֶׁהֲרֵי אֵין עָשָׁן בְּלֹא אֵשׁ, כְּמוֹ שֶׁכָּתוּב (שמות יט) וְהַר סִינַי עָשַׁן כֻּלּוֹ מִפְּנֵי אֲשֶׁר יָרַד עָלָיו ה' בָּאֵשׁ.</p>\n<p>בֹּא רְאֵה, אֵשׁ יוֹצֵאת מִבִּפְנִים וְהוּא דַק, וְאוֹחֵז בְּדָבָר אֶחָד בַּחוּץ שֶׁאֵינוֹ דַק כָּךְ, וְנֶאֱחָזִים זֶה בָּזֶה, וְאָז עוֹלֶה הֶעָשָׁן. מָה הַטַּעַם? מִשּׁוּם שֶׁהָאֵשׁ אוֹחֶזֶת בְּדָבָר הַמִּתְפַּעֵל, וְסִימָן לַדָּבָר - הַחֹטֶם שֶׁיּוֹצֵא בּוֹ עָשָׁן מִתּוֹךְ אֵשׁ.</p>\n<p>וְעַל זֶה כָּתוּב (דברים לג) יָשִׂימוּ קְטוֹרָה בְּאַפֶּךְ. מִשּׁוּם שֶׁחוֹזֶרֶת הָאֵשׁ לִמְקוֹמָהּ. וְהַחֹטֶם (מתפעל) נֶאֱסָף בְּאוֹתוֹ רֵיחַ לִפְנַי וְלִפְנִים, עַד שֶׁנֶּאֱחָז הַכֹּל וְחוֹזֵר לִמְקוֹמוֹ, וְנִקְרָב הַכֹּל לְתוֹךְ הַמַּחֲשָׁבָה וְנַעֲשֶׂה רָצוֹן אֶחָד. וְאָז רֵיחַ נִיחֹחַ, שֶׁנָּח הָרֹגֶז וְנַעֲשֶׂה נַחַת.</p>\n<p>שֶׁהֲרֵי הֶעָשָׁן נֶאֱסָף וְנִכְנָס וּמִתְקַמֵּט בָּאֵשׁ, וְהָאֵשׁ אוֹחֶזֶת בֶּעָשָׁן, וְנִכְנָסִים שְׁנֵיהֶם לִפְנַי וְלִפְנִים עַד שֶׁנָּח הָרֹגֶז. וּכְשֶׁהַכֹּל נֶאֱחָזִים (אוחז) זֶה בָּזֶה וְנָח הָרֹגֶז, אָז הוּא מְנוּחָה וְקֶשֶׁר אֶחָד וְנִקְרֵאת נַחַת. נַחַת הָרוּחַ חֶדְוַת הַכֹּל כְּאֶחָד. הֶאָרַת הַנֵּרוֹת הֶאָרַת הַפָּנִים. וְלָכֵן כָּתוּב וַיָּרַח ה' אֶת רֵיחַ הַנִּיחֹחַ, כְּמוֹ מִי שֶׁמֵּרִיחַ וְכוֹנֵס הַכֹּל לְתוֹךְ מְקוֹמוֹ.</p>\n<p>בָּא רַבִּי יֵיסָא וּנְשָׁקוֹ. אָמַר, וּמַה כָּל הַטּוּב הַזֶּה תַּחַת יָדְךְ וְלֹא יָדַעְתִּי בוֹ? אָמַר, אֶחֱזֹר מֵהַדֶּרֶךְ וְנִתְחַבֵּר עִמְּךְ. הָלְכוּ. אָמַר רַבִּי חִזְקִיָּה, בְּדֶרֶךְ זוֹ עִם הַשְּׁכִינָה נֵלֵךְ, שֶׁהֲרֵי מְתֻקֶּנֶת לְפָנֵינוּ. אָחַז בִּידֵי אוֹתוֹ תִינוֹק וְהָלְכוּ. אָמַר לוֹ, אֱמֹר לָנוּ פָּסוּק אֶחָד מֵאוֹתָם שֶׁאָבִיךְ אָמַר לְךְ.</p>\n<p>פָּתַח אוֹתוֹ הַתִּינוֹק וְאָמַר, (שיר א) יִשָּׁקֵנִי מִנְּשִׁיקוֹת פִּיהוּ. זוֹהִי הִשְׁתּוֹקְקוּת הָעֶלְיוֹנָה שֶׁיּוֹצֵא (שיצא) רָצוֹן מֵהַפֶּה לְנַשֵּׁק, וְלֹא יוֹצֵא מֵהַחֹטֶם כַּאֲשֶׁר יוֹצֵאת אֵשׁ. שֶׁהֲרֵי כְּשֶׁמִּתְחַבֵּר הַפֶּה לְנַשֵּׁק, יוֹצֵאת אֵשׁ בְּרָצוֹן בְּפָנִים מְאִירוֹת, בְּחֶדְוַת הַכֹּל, בְּהִתְדַּבְּקוּת שֶׁל מְנוּחָה.</p>\n<p>וּמִשּׁוּם כָּךְ כִּי טוֹבִים דֹּדֶיךְ מִיָּיִן, מֵאוֹתוֹ יַיִן (יין) הַמְשַׂמֵּחַ וּמֵאִיר פָּנִים וְהָעֵינַיִם מְחַיְּכוֹת, וְנַעֲשֶׂה הָרָצוֹן. וְלֹא מֵהַיַּיִן הַמְשַׁכֵּר (שמשכיר) וְעוֹשֶׂה רֹגֶז וּמַחְשִׁיךְ פָּנִים, וְהָעֵינַיִם לוֹהֲטוֹת יַיִן שֶׁל רֹגֶז.</p>\n<p>וְעַל זֶה, מִשּׁוּם שֶׁיַּיִן זֶה טוֹב מֵאִיר הַפָּנִים וּמְשַׂמֵּחַ הָעֵינַיִם וְעוֹשֶׂה הִשְׁתּוֹקְקוּת שֶׁל אַהֲבָה, מַקְרִיבִים אוֹתוֹ כָּל יוֹם עַל גַּבֵּי הַמִּזְבֵּחַ בְּשִׁעוּר שֶׁמִּי שֶׁשּׁוֹתֶה אוֹתוֹ, מְשַׂמֵּחַ אוֹתוֹ וְעוֹשֶׂה לוֹ נַחַת, שֶׁכָּתוּב (במדבר כח) וְנִסְכּוֹ רְבִיעִית הַהִין. וּמִשּׁוּם כָּךְ כִּי טוֹבִים דֹּדֶיךְ מִיָּיִן, מֵאוֹתוֹ הַיַּיִן שֶׁמִּעוֹרֵר אַהֲבָה וְהִשְׁתּוֹקְקוּת.</p>\n<p>וְהַסֹלֹ כְּמוֹ שֶׁלְּמַטָּה מְעוֹרֵר אַהֲבָה שֶׁלְּמַעְלָה. שְׁנֵי נֵרוֹת, כְּשֶׁדּוֹעֵךְ הָאוֹר שֶׁלְּמַעְלָה בֶּעָשָׁן שֶׁעוֹלֶה מֵאוֹתוֹ שֶׁלְּמַטָּה, נִדְלָק אוֹתוֹ שֶׁלְּמַעְלָה. אָמַר רַבִּי חִזְקִיָּה, כָּךְ הוּא בְּוַדַּאי, שֶׁהָעוֹלָם הָעֶלְיוֹן תָּלוּי בַּתַּחְתּוֹן וְהַתַּחְתּוֹן בָּעֶלְיוֹן. וּמִזְּמַן שֶׁנֶּחֱרַב בֵּית הַמִּקְדָּשׁ, לֹא נִמְצְאוּ בְרָכוֹת לְמַעְלָה וּלְמַטָּה, כְּדֵי לְהַרְאוֹת שֶׁזֶּה תָּלוּי בָּזֶה.</p>\n<p>וְאָמַר רַבִּי יוֹסֵי, בְּרָכוֹת אֵין נִמְצָאוֹת, וּקְלָלוֹת נִמְצָאוֹת, שֶׁהֲרֵי יְנִיקַת הַכֹּל מֵאוֹתוֹ צַד יוֹצְאִים (ד\"א וברכות לא יוצאות). מָה הַטַּעַם? מִשּׁוּם שֶׁיִּשְׂרָאֵל לֹא שְׁרוּיִים בָּאָרֶץ וְלֹא עוֹבְדִים עֲבוֹדָה שֶׁצָּרִיךְ לְהַדְלִיק מְאוֹרוֹת וּלְהִמָּצֵא בְרָכוֹת, וְלָכֵן לֹא נִמְצָאִים לְמַעְלָה וּלְמַטָּה, וְהָעוֹלָם לֹא יוֹשֵׁב בְּקִיּוּמוֹ כָּרָאוּי.</p>\n<p>וְאָמַר רַבִּי חִזְקִיָּה, לֹא אֹסִף לְקַלֵּל עוֹד אֶת הָאֲדָמָה בַּעֲבוּר הָאָדָם. מַהוּ זֶה? אָמַר רַבֵּי יֵיסָא, כָּךְ שָׁמַעְתִּי מֵרַבִּי שִׁמְעוֹן שֶׁאָמַר, כָּל פַּעַם שֶׁאֵשׁ שֶׁלְּמַעְלָה מוֹסִיפָה לְהִתְחַזֵּק - הֶעָשָׁן, שֶׁהוּא דִין שֶׁלְּמַטָּה, מְחַזֵּק הָרֹגֶז וּמַשְׁמִיד הַכֹּל. מִשּׁוּם שֶׁכְּשֶׁיּוֹצֵאת אֵשׁ, אֵין לָהּ הַפְסָקָה (לפניו) עַד שֶׁנִּשְׁלָם הַדִּין, וּכְשֶׁדִּין שֶׁלְּמַטָּה לֹא מוֹסִיף לְהִתְחַזֵּק עִם הַדִּין שֶׁלְּמַעְלָה, עוֹשֶׂה דִין וּפוֹסֵק, וְלֹא יֻשְׁלַם הַדִּין לְהַשְׁמִיד. וְלָכֵן כָּתוּב לֹא אֹסִף, לָתֵת תּוֹסֶפֶת שֶׁיִּתְחַזֵּק הַדִּין שֶׁלְּמַטָּה.</p>\n<p>אָמַר אוֹתוֹ תִינוֹק, שָׁמַעְתִּי מִשּׁוּם שֶׁכָּתוּב אֲרוּרָה הָאֲדָמָה בַּעֲבוּרֶךְ, שֶׁהֲרֵי בְּאוֹתָהּ שָׁעָה שֶׁהִתְקַלְלָה הָאָרֶץ בְּחֶטְאוֹ שֶׁל אָדָם, נִתְּנָה רְשׁוּת שֶׁיִּשְׁלֹט עָלֶיהָ אוֹתוֹ הַנָּחָשׁ הָרָע, שֶׁהוּא מַשְׁחִית אֶת הָעוֹלָם וּמַשְׁמִיד אֶת בְּנֵי הָעוֹלָם. מֵאוֹתוֹ יוֹם שֶׁהִקְרִיב נֹחַ קָרְבָּן וְהֵרִיחַ הַקָּדוֹשׁ בָּרוּךְ הוּא אוֹתוֹ, נִתְּנָה רְשׁוּת לָאָרֶץ לָצֵאת מִתַּחַת אוֹתוֹ הַנָּחָשׁ וְיָצְאָה מִטֻּמְאָתָהּ. וְלָכֵן מַקְרִיבִים יִשְׂרָאֵל קָרְבָּן לַקָּדוֹשׁ- בָּרוּךְ-הוּא, כְּדֵי לְהָאִיר פְּנֵי הָאָרֶץ. אָמַר רַבִּי חִזְקִיָּה, יָפֶה הוּא, (והוא) וזֶה הָיָה תָלוּי עַד שֶׁעָמְדוּ יִשְׂרָאֵל עַל הַר סִינַי. אָמַר רַבִּי יֵיסָא, הַקָּדוֹשׁ בָּרוּךְ הוּא הִקְטִין אֶת הַלְּבָנָה וְשָׁלַט אוֹתוֹ הַנָּחָשׁ, אֲבָל מִשּׁוּם חֶטְאוֹ שֶׁל אָדָם הִתְקַלְלָה כְּדֵי לְקַלֵּל אֶת הָעוֹלָם. בְּאוֹתוֹ יוֹם (שנתנה התורה) יָצְאָה הָאָרֶץ מֵאוֹתָהּ קְלָלָה וְעָמְדָה הַלְּבָנָה בְּאוֹתָהּ גְּרִיעוּת, פְּרָט לַשָּׁעָה שֶׁקָּרְבָּנוֹת נִמְצְאוּ בָעוֹלָם וְיִשְׂרָאֵל יוֹשְׁבִים עַל אַרְצָם.</p>\n<p>אָמַר רַבִּי יֵיסָא לְאוֹתוֹ תִינוֹק, מַה שִּׁמְךְ? אָמַר לוֹ, אַבָּא. אָמַר לוֹ, אַבָּא תִּהְיֶה בַּכֹּל, בְּחָכְמָה וּבְשָׁנִים. קָרָא עָלָיו (משלי כג) יִשְׂמַח אָבִיךְ וְאִמֶּךְ וְתָגֵל יוֹלַדְתֶּךְ.</p>\n<p>אָמַר רַבִּי חִזְקִיָּה, עָתִיד הַקָּדוֹשׁ בָּרוּךְ הוּא לְהַעֲבִיר רוּחַ הַטֻּמְאָה מֵהָעוֹלָם, כְּמוֹ (שנאמר) שֶׁכָּתוּב (זכריה ג) וְאֶת רוּחַ הַטֻּמְאָה אַעֲבִיר מִן הָאָרֶץ, וְכָתוּב (ישעיה כה) בִּלַּע הַמָּוֶת לָנֶצַח וּמָחָה ה' אֱלֹהִים דִּמְעָה מֵעַל כָּל פָּנִים וְחֶרְפַּת עַמּוֹ יָסִיר מֵעַל כָּל הָאָרֶץ כִּי ה' דִּבֵּר.</p>\n<p>ועָתִיד הַקָּדוֹשׁ בָּרוּךְ הוּא לְהָאִיר אֶת הַלְּבָנָה וּלְהוֹצִיאָהּ מֵהַחֹשֶׁךְ מִשּׁוּם אוֹתוֹ נָחָשׁ הָרָע, כְּמוֹ שֶׁכָּתוּב (שם ל) והיה אור הלבנה כאור החמה ואור החמה יהיה שבעתים כאור שבעת הימים. איזה אור? אותו האור שגנזו הקדוש ברוך הוא במעשה בראשית.</p>"],[9522011168,"<p>ויְבָרֶךָ אֱלֹהִים אֶת נֹחַ וְאֶת בָּנָיו וַיֹּאמֶר לָהֶם פְּרוּ וּרְבוּ וְגוֹ'. רַבִּי אַבָּא פָּתַח וְאָמַר, (משלי י) בִּרְכַּת ה' הִיא תַעֲשִׁיר וְלֹא יוֹסִף עֶצֶב עִמָּהּ. בִּרְכַּת ה' - זוֹ הַשְּׁכִינָה, שֶׁהִיא מְמֻנָּה עַל בִּרְכוֹת הָעוֹלָם, וּמִמֶּנָּה יוֹצְאוֹת בְּרָכוֹת לַכֹּל.</p>\n<p>בֹּא רְאֵה מַה כָּתוּב בַּהַתְחָלָה, וַיֹּאמֶר ה' לְנֹחַ בּא אַתָּה וְכֹל בֵּיתְךְ אֶל הַתֵּבָה וְגוֹ'. כְּמוֹ שֶׁנִּתְבָּאֵר, שֶׁבַּעַל הַבַּיִת נָתַן לוֹ רְשׁוּת לְהִכָּנֵס. אַחַר כָּךְ הָאִשָּׁה אָמְרָה לוֹ לָצֵאת. בַּהַתְחָלָה נִכְנַס בִּרְשׁוּת בַּעְלָהּ, וּבַסּוֹף יָצָא בִּרְשׁוּת הָאִשָּׁה. מִכָּאן לָמַדְנוּ שֶׁבַּעַל הַבַּיִת יַכְנִיס, וְהָאִשָּׁה תּוֹצִיא. זֶהוּ שֶׁכָּתוּב וַיְדַבֵּר אֱלֹהִים אֶל נֹחַ לֵאמֹר צֵא מִן הַתֵּבָה. שֶׁרְשׁוּת הָיְתָה בְיָדֶיהָ לְהוֹצִיא אֶת הָאוֹרֵחַ, וְלֹא לְהַכְנִיסוֹ.</p>\n<p>כֵּיוָן שֶׁיָּצָא, נָתַן לָהּ מַתָּנוֹת, מִשּׁוּם שֶׁהִיא בַּבַּיִת וְהַבַּיִת בְּיָדֶיהָ. וְאוֹתָם הַמַּתָּנוֹת שֶׁנָּתַן לָהּ, כְּדֵי לְהַרְבּוֹת אַהֲבָה אֶל בַּעְלָהּ. מִכָּאן לָמַדְנוּ דֶּרֶךְ אֶרֶץ לְאוֹרֵחַ (לתת ביד בעלה, כשיוצא נותן מתנות לאשתו, ולא בידה, ולכן, כיון שנתן לו מתנות). וְעַל זֶה, לְאַחַר שֶׁנָּתַן לָהּ מַתָּנוֹת לְהַרְבּוֹת לָהּ אַהֲבָה עִם בַּעְלָהּ. (נ\"א: כיון שיצא, נתן מתנות ואוצרות ביד בעלה לתת לאשתו ולשמח עמה ולהרבות לה אהבה עם בעלה, זהו שכתוב ויקח מכל וגו' ויעל עלת במזבח, אלו מתנות שנתן ביד של בעלה כדי להרבות לה אהבה בעולם, ומכאן למדנו דרך ארץ לאורח שיתן מתנות ביד של בעלה לאשתו ולא בידיה, ועל זה ויעל עלת במזבח, קרבן לזכר, להרבות אהבה עם בעלה ברך אותו) בֵּרַךְ אוֹתוֹ, שֶׁכָּתוּב וַיְבָרֶךְ אֱלֹהִים אֶת נֹחַ וְאֶת בָּנָיו וַיֹּאמֶר לָהֶם פְּרוּ וּרְבוּ וְגוֹ'. וְלָכֵן כָּתוּב (משלי י) בִּרְכַּת ה' הִיא תַעֲשִׁיר. וַדַּאי כְּמוֹ שֶׁנִּתְבָּאֵר.</p>\n<p>וְלֹא יוֹסִף עֶצֶב עִמָּהּ - סוֹד הַכָּתוּב בְּעִצָּבוֹן תֹּאכֲלֶנָּה. עִצָּבוֹן - עַצְבוּת וְרֹגֶז בְּלִי הֶאָרַת פָּנִים. כְּשֶׁנֶּחְשֶׁכֶת הַלְּבָנָה (מלכות) וּבְרָכוֹת לֹא נִמְצָאוֹת. בְּעִצָּבוֹן - צַד שֶׁל רוּחַ אַחֵר שֶׁמּוֹנֵעַ בְּרָכוֹת מֵהָעוֹלָם, וְלָכֵן לֹא יוֹסִף עֶצֶב עִמָּהּ. וְזֶהוּ סוֹד הַכָּתוּב (בראשית ח) לֹא אֹסִף עוֹד לְקַלֵּל אֶת הָאֲדָמָה.</p>"],[9522011169,"<p>וּמוֹרַאֲכֶם וְחִתְּכֶם יִהְיֶה. מִכָּאן וּלְהָלְאָה יִהְיֶה לָכֶם דְּמֻיּוֹת בְּנֵי אָדָם, שֶׁהֲרֵי בַּתְּחִלָּה לֹא הָיוּ דְמֻיּוֹת שֶׁל בְּנֵי אָדָם. בּא רְאֵה, בַּתְּחִלָּה כָּתוּב (שם ט) בְּצֶלֶם אֱלֹהִים עָשָׂה אֶת הָאָדָם, וְכָתוּב (שם ה) בִּדְמוּת אֱלֹהִים עָשָׂה אֹתוֹ. כֵּיוָן שֶׁחָטְאוּ, הִשְׁתַּנְּתָה דְמוּתָם מֵאוֹתָהּ דְּמוּת עֶלְיוֹנָה, וְהֵם הִתְהַפְּכוּ לִפְחֹד מִלִּפְנֵי חַיּוֹת הַשָּׂדֶה.</p>\n<p>בַּהַתְחָלָה כָּל בְּרִיּוֹת הָעוֹלָם זָקְפוּ עֵינַיִם, וְרָאוּ דְמוּת קְדוֹשָׁה עֶלְיוֹנָה וְזָעוּ וּפָחֲדוּ מִלְּפָנָיו. כֵּיוָן שֶׁחָטְאוּ, הִתְהַפְּכָה דְמוּתָם בְּעֵינֵיהֶם לִדְמוּת אַחֶרֶת, וְהִתְהַפֵּךְ שֶׁבְּנֵי אָדָם זָעִים וּפוֹחֲדִים לִפְנֵי שְׁאָר הַבְּרִיּוֹת.</p>\n<p>בֹּא רְאֵה, כָּל אוֹתָם בְּנֵי אָדָם שֶׁלֹּא חוֹטְאִים לִפְנֵי רִבּוֹנָם וְלֹא עוֹבְרִים עַל מִצְווֹת הַתּוֹרָה, זִיו דְּמוּתָם לֹא מִשְׁתַּנֶּה מִמַּרְאֵה הַדְּמוּת הָעֶלְיוֹנָה, וְכָל בְּרִיּוֹת הָעוֹלָם זָעִים וּפוֹחֲדִים לְפָנָיו. וּבְשָׁעָה שֶׁבְּנֵי אָדָם עוֹבְרִים עַל דִּבְרֵי הַתּוֹרָה, מִתְחַלֶּפֶת דְּמוּתָם, וְכֻלָּם מִזְדַּעְזְעִים וּפוֹחֲדִים מִלִּפְנֵי הַבְּרִיּוֹת הָאֲחֵרוֹת, מִשּׁוּם שֶׁהִתְחַלְּפָה הַדְּמוּת הָעֶלְיוֹנָה וְהָעָבְרָה מֵהֶם, וְאָז שׁוֹלְטִים בָּהֶם חַיּוֹת הַשָּׂדֶה, שֶׁהֲרֵי לֹא רוֹאִים בָּהֶם אוֹתָהּ דְּמוּת עֶלְיוֹנָה כָּרָאוּי.</p>\n<p>וְעַל כָּךְ עַכְשָׁו, כֵּיוָן שֶׁהָעוֹלָם הִתְחַדֵּשׁ כְּמוֹ מִקֹּדֶם, בֵּרְכָם אֶת הַבְּרָכָה הַזּוֹ וְהִשְׁלִיט אוֹתָם עַל הַכֹּל, כְּמוֹ שֶׁנֶּאֱמַר וְכָל דְּגֵי הַיָּם בְּיֶדְכֶם נִתָּנוּ. וַאֲפִלּוּ דְּגֵי הַיָּם. רַבִּי חִיָּיא אָמַר, בְּיֶדְכֶם נִתָּנוּ - מִקֹּדֶם לָכֵן. כְּשֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא בָּרָא אֶת הָעוֹלָם, מָסַר בִּידֵיהֶם אֶת הַכֹּל, שֶׁכָּתוּב וּרְדוּ בִּדְגַת הַיָּם וּבְעוֹף הַשָּׁמַיִם וְגוֹ'.</p>\n<p>וַיְבָרֶךְ אֱלֹהִים אֶת נֹחַ. רַבִּי חִזְקִיָּה פָּתַח, (תהלים לב) לְדָוִד מַשְׂכִּיל אַשְׁרֵי נְשׂוּי פֶּשַׁע כְּסוּי חֲטָאָה. פָּסוּק זֶה בֵּאֲרוּהוּ, אֲבָל פָּסוּק זֶה נִתְבָּאֵר בְּסוֹד הַחָכְמָה. שֶׁהֲרֵי שָׁנִינוּ, בַּעֲשָׂרָה מִינֵי שֶׁבַח שִׁבַּח דָּוִד אֶת הַקָּדוֹשׁ בָּרוּךְ הוּא, וְאֶחָד מֵהֶם הוּא מַשְׂכִּיל, וְהוּא דַּרְגָּה אַחַת מֵאוֹתָן עֶשֶׂר. וְדָוִד הִתְקִין עַצְמוֹ בְּטֶרֶם שֶׁתִּשְׁרֶה עָלָיו הַדַּרְגָּה הַזּוֹ.</p>\n<p>אַשְׁרֵי נְשׂוּי פֶּשַׁע, שֶׁהֲרֵי בְּשָׁעָה שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא שׁוֹקֵל חֲטָאִים וּזְכֻיּוֹת שֶׁל בְּנֵי אָדָם שֶׁל אוֹתוֹ (ד\"א כשאותו) מִשְׁקָל שֶׁבְּצַד הַחֲטָאִים עוֹלִים, וְאוֹתָם הָאֲחֵרִים, הַזְּכֻיּוֹת שֶׁהֵן בְּמִשְׁקָל אַחֵר, מַכְרִיעוֹת לְמַטָּה - זֶהוּ נְשׂוּי פֶּשַׁע.</p>\n<p>כְּסוּי חֲטָאָה - בְּשָׁעָה שֶׁהַדִּין שׁוֹרֶה בָּעוֹלָם, שֶׁיִּהְיֶה מְכַסֶּה שֶׁלֹּא יִשְׁלֹט עָלָיו הַמַּשְׁחִית, כְּמוֹ שֶׁהָיָה לְנֹחַ שֶׁכִּסָּה אוֹתוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא מֵאוֹתוֹ חֵטְא שֶׁהִמְשִׁיךְ עָלָיו אָדָם עַל הָעוֹלָם. שֶׁכֵּיוָן שֶׁחֵטְא זֶה הִשְׁפִּיעַ אָדָם עַל הָעוֹלָם, שְׁאָר הַבְּרִיּוֹת שׁוֹלְטוֹת, וּבֶן אָדָם פּוֹחֵד מֵהֶם, וְהָעוֹלָם לֹא הֻתְקַן בְּתִקּוּנוֹ. וְלָכֵן כְּשֶׁיָּצָא נֹחַ מֵהַתֵּבָה, בֵּרְכוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא, שֶׁכָּתוּב וַיְבָרֶךְ אֱלֹהִים אֶת נֹחַ וְאֶת בָּנָיו וְגוֹ'.</p>\n<p>וְאַתֶּם פְּרוּ וּרְבוּ. בַּבְּרָכוֹת הַלָּלוּ לֹא נִמְצְאוּ נְקֵבוֹת, אֶלָּא אֶת נֹחַ וְאֶת בָּנָיו, אֲבָל נְקֵבוֹת הַפָּסוּק לֹא אָמַר. אָמַר רַבִּי שִׁמְעוֹן, וְאַתֶּם - כְּלָל שֶׁל הַזְּכָרִים וְהַנְּקֵבוֹת כְּאֶחָד. וְעוֹד, אֶת נֹחַ - לְרַבּוֹת אֶת אִשְׁתּוֹ. וְאֶת בָּנָיו - לְרַבּוֹת אֶת נְקֵבוֹתֵיהֶ ם.</p>\n<p>וְלָכֵן כָּתוּב וְאַתֶּם פְּרוּ וּרְבוּ, לַעֲשׂוֹת תּוֹלָדוֹת מִכָּאן וָהָלְאָה, שִׁרְצוּ בָאָרֶץ. וְכָאן נָתַן לָהֶם הַקָּדוֹשׁ בָּרוּךְ הוּא שֶׁבַע מִצְווֹת הַתּוֹרָה וּלְכָל הַבָּאִים אַחֲרֵיהֶם, עַד שֶׁעָמְדוּ יִשְׂרָאֵל בְּהַר סִינַי וְנִתְּנוּ לָהֶם כָּל מִצְווֹת הַתּוֹרָה כְּאֶחָד.</p>"],[9522011170,"<p>וַיֹּאמֶר אֱלֹהִים לְנֹחַ וְגוֹ', זאת אוֹת הַבְּרִית אֲשֶׁר אֲנִי נֹתֵן בֵּינִי וּבֵינֵיכֶם וְגוֹ', אֶת קַשְׁתִּי נָתַתִּי בֶּעָנָן. נָתַתִּי - מִקֹּדֶם לָכֵן. רַבִּי שִׁמְעוֹן פָּתַח, (יחזקאל א) וּמִמַּעַל לָרָקִיעַ אֲשֶׁר עַל רֹאשָׁם כְּמַרְאֵה אֶבֶן סַפִּיר דְּמוּת כִּסֵּא. מַה כָּתוּב לְמַעְלָה? וָאֶשְׁמַע אֶת קוֹל כַּנְפֵיהֶם כְּקוֹל מַיִם רַבִּים כְּקוֹל שַׁדַּי בְּלֶכְתָּן. אֵלּוּ אַרְבַּע חַיּוֹת גְּדוֹלוֹת עֶלְיוֹנוֹת קְדוֹשׁוֹת שֶׁאוֹתוֹ הָרָקִיעַ מְתֻקָּן עֲלֵיהֶם. וְכָל הַכְּנָפַיִם (נפרדות) מִתְחַבְּרוֹת זוֹ בָּזוֹ לְכַסּוֹת אֶת גּוּפָם.</p>\n<p>וּבְשָׁעָה שֶׁהֵם פּוֹרְשִׂים כַּנְפֵיהֶם, נִשְׁמָע קוֹל הַכְּנָפַיִם שֶׁלְּכֻלָּם שֶׁאוֹמְרִים שִׁירָה. זֶהוּ שֶׁכָּתוּב כְּקוֹל שַׁדַּי, שֶׁלֹּא שׁוֹכֵךְ לְעוֹלָמִים, כְּמוֹ שֶׁנֶּאֱמַר (תהלים ל) לְמַעַן יְזַמֶּרְךְ כָבוֹד וְלֹא יִדּוֹם. וּמָה אוֹמְרִים? (שם צח) הוֹדִיעַ ה' יְשׁוּעָתוֹ לְעֵינֵי הַגּוֹיִם גִּלָּה צִדְקָתוֹ.</p>\n<p>קוֹל הֲמֻלָּה כְּקוֹל מַחֲנֶה, כְּקוֹל מַחֲנֶה קָדוֹשׁ כְּשֶׁמִּתְחַבְּרִים כָּל הַצְּבָאוֹת הָעֶלְיוֹנִים לְמַעְלָה. וּמָה אוֹמְרִים? קָדוֹשׁ קָדוֹשׁ קָדוֹשׁ ה' צְבָאוֹת מְלֹא כָל הָאָרֶץ כְּבוֹדוֹ. חוֹזְרִים לַדָּרוֹם, אוֹמְרִים קָדוֹשׁ. חוֹזְרִים לַצָּפוֹן, אוֹמְרִים קָדוֹשׁ. חוֹזְרִים לַמִּזְרָח, אוֹמְרִים קָדוֹשׁ. חוֹזְרִים לַמַּעֲרָב, אוֹמְרִים בָּרוּךְ.</p>\n<p>וְהָרָקִיעַ הַזֶּה עוֹמֵד עַל רָאשֵׁיהֶם. וּבְכָל מָקוֹם שֶׁהִיא הוֹלֶכֶת, מְסוֹבְבִים פָּנִים לְאוֹתוֹ צַד שֶׁנִּכְלָלִים הַפָּנִים בּוֹ. מְסוֹבֵב פָּנָיו לְאַרְבָּעָה רוּחוֹת, וְכֻלָּם מִסְתּוֹבְבִים לְמַטָּה.</p>\n<p>בָּרִבּוּעַ שֶׁלּוֹ נֶחְקֶקֶת בְּאַרְבַּע פָּנִים: פְּנֵי אַרְיֵה, פְּנֵי נֶשֶׁר, פְּנֵי שׁוֹר, פְּנֵי אָדָם. חָקוּק בְּכֻלָּם אָדָם. פְּנֵי אַרְיֵ\"ה אָדָם. פְּנֵי נֶשֶׁ\"ר אָדָם. פְּנֵי שׁוֹ\"ר (אדם). כֻּלָּם כְּלוּלִים בּוֹ. וְלָכֵן כָּתוּב וּדְמוּת פְּנֵיהֶם פְּנֵי אָדָם.</p>\n<p>וְהָרָקִיעַ הַזֶּה שֶׁהִתְרַבַּע, כָּל הַגְּוָנִים כְּלוּלִים בּוֹ. אַרְבָּעָה גְוָנִים נִרְאִים בּוֹ חֲקוּקִים בְּאַרְבַּע אַרְבַּע. בְּאַרְבָּעָה חִקּוּקִים רְשׁוּמִים אוֹרוֹת עֶלְיוֹנִים וְתַחְתּוֹנִים. כְּשֶׁנִּפְרָדִים הַגְּוָנִים שֶׁל אוֹתָם אַרְבַּע, עוֹלִים שְׁנֵים עָשָׂר. גָּוֶן יָרֹק. גָּוֶן אָדם. גָּוֶן לָבָן. גָּוֶן סַפִּיר שֶׁנִּכְלְלוּ מִכָּל הַגְּוָנִים. זֶהוּ שֶׁכָּתוּב (יחזקאל א) כְּמַרְאֵה הַקֶּשֶׁת אֲשֶׁר יִהְיֶה בֶעָנָן בְּיוֹם הַגֶּשֶׁם כֵּן מַרְאֵה הַנֹּגַהּ סָבִיב הוּא מַרְאֵה דְּמוּת כְּבוֹד ה'. הַמַּרְאֶה שֶׁל כָּל הַגְּוָנִים, וְלָכֵן אֶת קַשְׁתִּי נָתַתִּי בֶּעָנָן.</p>\n<p>מַה זֶּה קַשְׁתִּי? כְּמוֹ שֶׁנֶּאֱמַר בְּיוֹסֵף, שֶׁכָּתוּב (בראשית מט) וַתֵּשֶׁב בְּאֵיתָן קַשְׁתּוֹ, מִשּׁוּם שֶׁיּוֹסֵף נִקְרָא צַדִּיק. וְלָכֵן קַשְׁתּוֹ, זוֹ בְּרִית שֶׁל הַקֶּשֶׁת שֶׁנִּכְלֶלֶת בְּצַדִּיק, שֶׁהַבְּרִית זֶה עִם זֶה נֶאֱחָז. וּמִשּׁוּם שֶׁנֹּחַ הָיָה צַדִּיק, הַבְּרִית שֶׁלּוֹ קֶשֶׁת.</p>\n<p>וַיָּפֹזּוּ, מַה זֶּה וַיָּפֹזּוּ? הֵאִירוּ בְּחֶמְדַּת הַכֹּל, כְּמוֹ שֶׁנֶּאֱמַר (תהלים יט) הַנֶּחֱמָדִים מִזָּהָב וּמִפַּז רָב וּמְתוּקִים. הוּאֲרוּ בְּאוֹר עֶלְיוֹן כְּשֶׁשָּׁמַר הַבְּרִית. וְלָכֵן נִקְרָא יוֹסֵף הַצַּדִּיק. וְעַל זֶה הַקֶּשֶׁת נִקְרֵאת בְּרִית, כּוֹלֵל זֶה בָּזֶה.</p>\n<p>זֹהַר נִכְבָּד עֶלְיוֹן הַמַּרְאֶה שֶׁל כָּל הַמַּרְאוֹת, מַרְאֶה כְּמַרְאֶה טְמוּנִים (נ\"א: טמון) הַגְּוָנִים הַטְּמוּנִים. הַגְּוָנִים שֶׁלֹּא הִתְגַּלּוּ. וְאֵין רְשׁוּת לְהִסְתַּכֵּל בָּעַיִן בַּקֶּשֶׁת כְּשֶׁנִּרְאֵית בָּעוֹלָם, שֶׁלֹּא יִתְרָאֶה קָלוֹן בַּשְּׁכִינָה. וְכֵן גּוֹנֵי הַקֶּשֶׁת הוּא מַרְאֶה מוּצָק קָשׁוּר כְּמַרְאֵה כָּבוֹד הָעֶלְיוֹן שֶׁלֹּא לְהִסְתַּכֵּל.</p>\n<p>וְכֵיוָן שֶׁהָאָרֶץ רָאֲתָה אֶת הַקֶּשֶׁת הַזּוֹ, בְּרִית קְדוֹשָׁה, הִתְקַיְּמָה בְּקִיּוּם. וְעַל זֶה וְהָיְתָה לְאוֹת בְּרִית בֵּין אֱלֹהִים וְגוֹ'. זֶה שֶׁאָמַרְנוּ שֶׁאֵלּוּ שְׁלֹשֶׁת הַגְּוָנִים וְאֶחָד שֶׁנִּכְלָל בֵּינֵיהֶם כֻּלָּם סוֹד אֶחָד, וּבְתוֹךְ הֶעָנָן עוֹלֶה לְהֵרָאוֹת.</p>\n<p>(יחזקאל א) וּמִמַּעַל לָרָקִיעַ אֲשֶׁר עַל רֹאשָׁם כְּמַרְאֵה אֶבֶן סַפִּיר - זוֹהִי אֶבֶן הַשְּׁתִיָּה שֶׁהִיא נְקֻדָּה אַחַת שֶׁל כָּל הָעוֹלָם וְעוֹמֵד עָלֶיהָ קֹדֶשׁ הַקְּדָשִׁים, וּמַהִי? הַכִּסֵּא הַקָּדוֹשׁ הָעֶלְיוֹן שֶׁמְּמֻנֶּה עַל אַרְבָּעָה אֵלֶּה דְּמוּת כִּסֵּא בְּאַרְבָּעָה עַמּוּדִים, וְזוֹהִי תוֹרָה שֶׁבְּעַל פֶּה.</p>\n<p>וְעַל דְּמוּת הַכִּסֵּא דְּמוּת כְּמַרְאֵה אָדָם עָלָיו מִלְמָעְלָה - זוֹהִי תוֹרָה שֶׁבִּכְתָב. מִכָּאן שֶׁתּוֹרָה שֶׁבִּכְתָב יָשִׂימוּ אוֹתָהּ עַל תּוֹרָה שֶׁבְּעַל פֶּה, מִשּׁוּם שֶׁזֶּה כִּסֵּא לָזֶה. כְּמַרְאֵה אָדָם, שֶׁהוּא הַדְּמוּת שֶׁל יַעֲקֹב שֶׁהוּא יוֹשֵׁב עָלֶיהָ.</p>"],[9522011171,"<p>רַבִּי יְהוּדָה קָם לַיְלָה אֶחָד לַעֲסֹק בַּתּוֹרָה בַּחֲצוֹת הַלַּיְלָה בְּאַכְסַנְיָה בְּעִיר מַחְסֵיָא, וְהָיָה שָׁם בַּבַּיִת יְהוּדִי אֶחָד שֶׁבָּא בִּשְׁתֵּי אַמְתָּחוֹת שֶׁל מַלְבּוּשִׁים. פָּתַח רַבִּי יְהוּדָה וְאָמַר, (בראשית כח) וְהָאֶבֶן הַזֹּאת אֲשֶׁר שַׂמְתִּי מַצֵּבָה יִהְיֶה בֵּית אֱלֹהִים - זוֹהִי אֶבֶן הַשְּׁתִיָּה שֶׁמִּשָּׁם נִשְׁתַּל הָעוֹלָם וְעָלֶיהָ נִבְנָה בֵּית הַמִּקְדָּשׁ.</p>\n<p>הֵרִים רֹאשׁוֹ אוֹתוֹ יְהוּדִי וְאָמַר לוֹ, דָּבָר זֶה אֵיךְ אֶפְשָׁר? וַהֲרֵי אֶבֶן הַשְּׁתִיָּה טֶרֶם שֶׁנִּבְרָא הָעוֹלָם הָיְתָה, וּמִמֶּנָּה נִשְׁתַּל הָעוֹלָם, וְאַתָּה אָמַרְתָּ וְהָאֶבֶן הַ את אֲשֶׁר שַׂמְתִּי מַצֵּבָה, שֶׁמַּשְׁמָע שֶׁיַּעֲקֹב שָׂם אוֹתָהּ עַכְשָׁו, שֶׁכָּתוּב (שם) וַיִּקַּח אֶת הָאֶבֶן אֲשֶׁר שָׂם מְרַאֲשּתָיו? וְעוֹד, שֶׁיַּעֲקֹב בְּבֵית אֵל הָיָה, וְהָאֶבֶן הַ את הָיְתָה בִּירוּשָׁלַיִם.</p>\n<p>רַבִּי יְהוּדָה לֹא סוֹבֵב רֹאשׁוֹ אֵלָיו, פָּתַח וְאָמַר, (עמוס ד) הִכּוֹן לִקְרַאת אֱלֹהֶיךְ יִשְׂרָאֵל, וְכָתוּב (דברים כז) הַסְכֵּת וּשְׁמַע יִשְׂרָאֵל. דִּבְרֵי תוֹרָה צְרִיכִים כַּוָּנָה, וְדִבְרֵי תוֹרָה צְרִיכִים לְהִתְתַּקֵּן בְּגוּף וְרָצוֹן כְּאֶחָד. קָם אוֹתוֹ יְהוּדִי וְהִתְלַבֵּשׁ, וְיָשַׁב אֵצֶל רַבִּי יְהוּדָה וְאָמַר, אַשְׁרֵיכֶם הַצַּדִּיקִים שֶׁעוֹסְקִים בַּתּוֹרָה יוֹמָם וָלַיְלָה.</p>\n<p>אָמַר לוֹ רַבִּי יְהוּדָה, עַכְשָׁו שֶׁכִּוַּנְתָּ עַצְמְךְ, אֱמֹר דְּבָרְךְ שֶׁנִּתְחַבֵּר כְּאֶחָד, שֶׁהֲרֵי דִּבְרֵי תוֹרָה צְרִיכִים תִּקּוּן הַגּוּף וְתִקּוּן הַלֵּב, וְאִם לֹא - בְּמִטָּתִי הָיִיתִי שׁוֹכֵב, וּבְלִבִּי הָיִיתִי אוֹמֵר דְּבָרִים. אֶלָּא הֲרֵי שָׁנִינוּ, שֶׁאֲפִלּוּ אֶחָד שֶׁיּוֹשֵׁב וְעוֹסֵק בַּתּוֹרָה, הַשְּׁכִינָה מִתְחַבֶּרֶת עִמּוֹ, וּמַה שְּׁכִינָה כָּאן וַאֲנִי שׁוֹכֵב בְּמִטָּתִי!? וְלֹא עוֹד, אֶלָּא שֶׁצְּרִיכִים צַחוּת.</p>\n<p>וְעוֹד, שֶׁכָּל בֶּן אָדָם שֶׁקָּם לַעֲסֹק בַּתּוֹרָה מֵחֲצוֹת הַלַּיְלָה, כְּשֶׁמִּתְעוֹרֶרֶת רוּחַ צָפוֹן (בחצות הלילה), הַקָּדוֹשׁ בָּרוּךְ הוּא בָּא לְהִשְׁתַּעֲשֵׁעַ עִם הַצַּדִּיקִים בְּגַן עֵדֶן. וְהוּא וְכָל הַצַּדִּיקִים שֶׁבַּגַּן, כֻּלָּם מַקְשִׁיבִים (לו, ומקשיבים) לְאוֹתָם דְּבָרִים שֶׁיּוֹצְאִים מִפִּיו. וּמָה הַקָּדוֹשׁ בָּרוּךְ הוּא וְכָל הַצַּדִּיקִים שֶׁמִּתְעַדְּנִים לִשְׁמֹעַ דִּבְרֵי תוֹרָה בַּשָּׁעָה הַזּוֹ, וַאֲנִי אֶהְיֶה שׁוֹכֵב בְּמִטָּתִי!? אָמַר לוֹ, כָּעֵת אֱמֹר דְּבָרְךְ.</p>\n<p>אָמַר לוֹ, שָׁאַלְתִּי עַל מַה שֶּׁאָמַרְתָּ בַּפָּסוּק הַזֶּה (סוד של אבן השתיה שאמרת), וְהָאֶבֶן הַ את אֲשֶׁר שַׂמְתִּי מַצֵּבָה יִהְיֶה בֵּית אֱלֹהִים, שֶׁזּוֹ אֶבֶן הַשְּׁתִיָּה, (עכשו שמקשיב לדברי) אֵיךְ אֶפְשָׁר? שֶׁהֲרֵי אֶבֶן הַשְּׁתִיָּה טֶרֶם שֶׁנִּבְרָא הָעוֹלָם הָיְתָה, וּמִמֶּנָּה נִשְׁתַּל הָעוֹלָם, וְאַתָּה אָמַרְתָּ אֲשֶׁר שַׂמְתִּי, שֶׁמַּשְׁמָע שֶׁיַּעֲקֹב שָׂם אוֹתָהּ כָּעֵת, וְכָתוּב וַיִּקַּח אֶת הָאֶבֶן אֲשֶׁר שָׂם מְרַאֲשּתָיו?</p>\n<p>וְעוֹד, שֶׁיַּעֲקֹב בְּבֵית אֵל הָיָה, וְהָאֶבֶן הַזּוֹ הָיְתָה בִּירוּשָׁלַיִם. אָמַר לוֹ, כָּל אֶרֶץ יִשְׂרָאֵל הִתְקַפְּלָה תַּחְתָּיו, וְאוֹתָהּ אֶבֶן תַּחְתָּיו הָיְתָה. אָמַר לוֹ, אֲשֶׁר שָׂם כָּתוּב, וְכָתוּב וְהָאֶבֶן הַ את אֲשֶׁר שַׂמְתִּי מַצֵּבָה. אָמַר לוֹ, אִם יָדַעְתָּ הַדָּבָר - אֱמֹר אוֹתוֹ.</p>\n<p>פָּתַח וְאָמַר, (תהלים יז) אֲנִי בְּצֶדֶק אֶחֱזֶה פָנֶיךְ אֶשְׂבְּעָה בְהָקִיץ תְּמוּנָתֶךְ. דָּוִד הַמֶּלֶךְ, הַחֲבִיבוּת וְהַדְּבֵקוּת שֶׁלּוֹ הָיְתָה בָּאֶבֶן הַזֹּאת, וְעָלֶיהָ אָמַר (שם קיח) אֶבֶן מָאֲסוּ הַבּוֹנִים הָיְתָה לְרֹאשׁ פִּנָּה. וּכְשֶׁרָצָה לְהִסְתַּכֵּל בְּמַרְאֵה כְּבוֹד רִבּוֹנוֹ, נָטַל אֶבֶן זוֹ בְּיָדוֹ בַּתְּחִלָּה, וְאַחַר כָּךְ נִכְנַס.</p>\n<p>מִשּׁוּם שֶׁכָּל מִי שֶׁרוֹצֶה לְהֵרָאוֹת לִפְנֵי רִבּוֹנוֹ, לֹא נִכְנָס אֶלָּא עִם אֶבֶן זאת, שֶׁכָּתוּב (ויקרא יג) בְּזאת יָבא אַהֲרֹן אֶל הַקֹּדֶשׁ. וְדָוִד מְשַׁבֵּחַ עַצְמוֹ וְאוֹמֵר, אֲנִי בְּצֶדֶק אֶחֱזֶה פָנֶיךְ. וְכָל הִשְׁתַּדְּלוּתוֹ שֶׁל דָּוִד לְהֵרָאוֹת בְּאֶבֶן זֹאת כָּרָאוּי כְּלַפֵּי מַעְלָה.</p>\n<p>בֹּא וְתִרְאֶה, אַבְרָהָם תִּקֵּן תְּפִלַּת הַבֹּקֶר וְהוֹדִיעַ טוּב רִבּוֹנוֹ בָּעוֹלָם, וְתִקֵּן אוֹתָהּ הַשָּׁעָה בְּתִקּוּנֶיהָ כָּרָאוּי, שֶׁכָּתוּב (בראשית כב) וַיַּשְׁכֵּם אַבְרָהָם בַּבֹּקֶר. יִצְחָק תִּקֵּן תְּפִלַּת מִנְחָה, וְהוֹדִיעַ בָּעוֹלָם שֶׁיֵּשׁ דִּין וְיֵשׁ דַּיָּן שֶׁיָּכוֹל לְהַצִּיל וְלָדוּן אֶת הָעוֹלָם.</p>\n<p>יַעָקֹב תִּקֵּן תְּפִלַּת עַרְבִית, וּבִשְׁבִיל הַתְּפִלָּה הַזּוֹ שֶׁתִּקֵּן מַה שֶּׁלֹּא תִקֵּן בֶּן אָדָם מִקֹּדֶם לָזֶה כָּרָאוּי, לָכֵן שִׁבַּח אֶת עַצְמוֹ וְאָמַר וְהָאֶבֶן הַ את אֲשֶׁר שַׂמְתִּי מַצֵּבָה. שֶׁעַד אוֹתָהּ שָׁעָה לֹא תִקֵּן אוֹתָהּ אַחֵר כְּמוֹתוֹ.</p>\n<p>וְלָכֵן וַיִּקַּח אֶת הָאֶבֶן אֲשֶׁר שָׂם מְרַאֲשּתָיו וַיָּשֶׂם אֹתָהּ מַצֵּבָה. מַה זֶּה מַצֵּבָה? שֶׁהָיְתָה נְפוּלָה, וְהֵקִים אוֹתָהּ. וַיִּצֹק שֶׁמֶן עַל רֹאשָׁהּ. שֶׁהֲרֵי בְּיַעֲקֹב תָּלוּי הַדָּבָר לַעֲשׂוֹת יוֹתֵר מִכָּל בְּנֵי הָעוֹלָם.</p>\n<p>בָּא רַבִּי יְהוּדָה וּנְשָׁקוֹ. אָמַר לוֹ, וְכָל זֶה יָדַעְתָּ, וְאֵיךְ אַתָּה עוֹסֵק בִּסְחוֹרָה וּמַנִּיחַ חַיֵּי עוֹלָם!? אָמַר לוֹ, שֶׁדְּחוּקָה הָיְתָה לִי הַשָּׁעָה, וְיֵשׁ לִי שְׁנֵי בָנִים, וְעוֹמְדִים כָּל הַיּוֹם בְּבֵית הָרַב, וַאֲנִי מִשְׁתַּדֵּל בִּמְזוֹנָם וְלָתֵת לָהֶם שָׂכָר לְמוֹרָם כְּדֵי שֶׁיַּעַסְקוּ בַתּוֹרָה.</p>\n<p>פָּתַח וְאָמַר, (מלכים א ב) וּשְׁלֹמֹה יָשַׁב עַל כִּסֵּא דָּוִד אָבִיו וַתִּכֹּן מַלְכֻתוֹ מְאֹד. מַה הוּא הַשֶּׁבַח הַזֶּה? אֶלָּא שֶׁהִתְקִין אֶבֶן שְׁתִיָּה וְשָׂם עָלֶיהָ קֹדֶשׁ הַקְּדָשִׁים, וְאָז וַתִּכֹּן מַלְכֻתוֹ מְאֹד.</p>\n<p>וְכָתוּב (בראשית ט) וּרְאִיתִיהָ לִזְכֹּר בְּרִית עוֹלָם. שֶׁהֲרֵי הַקָּדוֹשׁ בָּרוּךְ הוּא חִשְׁקוֹ בָהּ תָּמִיד, וּמִי שֶׁלֹּא נִרְאֶה עִמָּהּ, לֹא נִכְנָס לִפְנֵי רִבּוֹנוֹ. וְעַל זֶה כָּתוּב וּרְאִיתִיהָ לִזְכֹּר בְּרִית עוֹלָם.</p>\n<p>וּרְאִיתִיהָ, מַה זֶּה וּרְאִיתִיהָ? סוֹד הוּא, כְּמוֹ שֶׁנֶּאֱמַר (יחזקאל ט) וְהִתְוִיתָ תָּו עַל מִצְחוֹת וְגוֹ', לְהֵרָאוֹת עֲלֵיהֶם. וְיֵשׁ אוֹמְרִים, זֶה רֹשֶׁם הָאוֹת הַקָּדוֹשׁ שֶׁבַּבָּשָׂר.</p>\n<p>אָמַר רַבִּי יְהוּדָה, וַדַּאי הַכֹּל הוּא. (כך) אֲבָל קֶשֶׁת זוֹ שֶׁנִּרְאֵית בָּעוֹלָם עוֹמֶדֶת בְּסוֹד עֶלְיוֹן, וּכְשֶׁיֵּצְאוּ יִשְׂרָאֵל מֵהַגָּלוּת, עֲתִידָה קֶשֶׁת זוֹ לְהִתְקַשֵּׁט בִּגְוָנִים כַּכַּלָּה הַזּוֹ שֶׁמִּתְקַשֶּׁטֶת לְבַעְלָהּ.</p>\n<p>אָמַר לוֹ אוֹתוֹ יְהוּדִי, כָּךְ אָמַר לִי אַבָּא, כְּשֶׁהָיָה מִסְתַּלֵּק מֵהָעוֹלָם, (אמר לי) אַל תְּצַפֶּה לְרַגְלֵי מָשִׁיחַ עַד שֶׁתֵּרָאֶה קֶשֶׁת זוֹ בָּעוֹלָם (בענן) מְקֻשֶּׁטֶת בִּגְוָנִים מְאִירִים וְיוֹאַר לָעוֹלָם, וְאָז צַפֵּה לַמָּשִׁיחַ.</p>\n<p>מִנַּיִן לָנוּ? שֶׁכָּתוּב וּרְאִיתִיהָ לִזְכֹּר בְּרִית עוֹלָם. וְכָעֵת שֶׁנִּרְאֵית בִּגְוָנִים חֲשׁוּכִים, נִרְאֵית לְזִכָּרוֹן (והיא לזכר) שֶׁלֹּא יָבֹא מַבּוּל. אֲבָל בְּאוֹתוֹ זְמַן נִרְאֵית בִּגְוָנִים מְאִירִים וּמְקֻשֶּׁטֶת בְּתִקּוּן כְּמוֹ כַּלָּה שֶׁמִּתְקַשֶּׁטֶת לְבַעְלָהּ, וְאָז לִזְכֹּר בְּרִית עוֹלָם, וְיִזְכֹּר הַקָּדוֹשׁ בָּרוּךְ הוּא אֶת הַבְּרִית הַזּוֹ שֶׁהִיא בַּגָּלוּת וִיקִימָהּ מֵהֶעָפָר. זֶהוּ שֶׁכָּתוּב (הושע ג) וּבִקְשׁוּ אֶת ה' אֱלֹהֵיהֶם וְאֵת דָּוִיד מַלְכָּם. וְכָתוּב (ירמיה ל) וְעָבְדוּ אֵת ה' אֱלֹהֵיהֶם וְאֵת דָּוִד מַלְכָּם אֲשֶׁר אָקִים לָהֶם. אֲשֶׁר אָקִים מֵעָפָר. כְּמוֹ שֶׁנֶּאֱמַר (עמוס ט) אָקִים אֶת סֻכַּת דָּוִיד הַנֹּפֶלֶת. וְעַל זֶה וּרְאִיתִיהָ לִזְכֹר בְּרִית עוֹלָם וְלַהֲקִימָהּ מֵהֶעָפָר.</p>\n<p>וְאָמַר כָּךְ אַבָּא, שֶׁמִּשּׁוּם כָּךְ נִזְכְּרָה בַּתּוֹרָה גְּאֻלַּת יִשְׂרָאֵל וְזִכְרוֹנָהּ. וְזֶהוּ שֶׁכָּתוּב (ישעיה נד) אֲשֶׁר נִשְׁבַּעְתִּי מֵעֲבֹר מֵי נֹחַ עוֹד עַל הָאָרֶץ כֵּן נִשְׁבַּעְתִּי מִקְּצֹף עָלַיִךְ וּמִגְּעָר בָּךְ.</p>"],[9522011172,"<p>וַיִּהְיוּ בְנֵי נֹחַ הַיּצְאִים מִן הַתֵּבָה. רַבִּי אֶלְעָזָר אָמַר, כֵּיוָן שֶׁכָּתוּב וַיִּהְיוּ בְנֵי נֹחַ, לָמָּה אָמַר הַיֹּצְאִים מִן הַתֵּבָה? וְכִי בָנִים אֲחֵרִים הָיוּ לוֹ שֶׁלֹּא יָצְאוּ מֵהַתֵּבָה?</p>\n<p>אָמַר לוֹ רַבִּי אַבָּא, כֵּן, שֶׁהֲרֵי אַחַר כָּךְ הוֹלִידוּ בָנָיו בָּנִים, שֶׁכָּתוּב אֵלֶּה תּוֹלְדת שֵׁם וְגוֹ', וְהֵם לֹא יָצְאוּ מֵהַתֵּבָה. וְלָכֵן כָּתוּב הַיֹּצְאִים מִן הַתֵּבָה שֵׁם וְחָם וָיָפֶת.</p>\n<p>רַבִּי שִׁמְעוֹן אָמַר, אִלּוּ הָיִיתִי מָצוּי בָּעוֹלָם כְּשֶׁנָּתַן הַקָּדוֹשׁ בָּרוּךְ הוּא סִפְרוֹ שֶׁל חֲנוֹךְ בָּעוֹלָם וְסִפְרוֹ שֶׁל אָדָם, הָיִיתִי מִתְחַזֵּק שֶׁלֹּא יִמָּצְאוּ בֵּין הָאֲנָשִׁים, כִּי לֹא חָשְׁשׁוּ כָּל הַחֲכָמִים לְהִסְתַּכֵּל בָּהֶם וְטָעוּ בִּדְבָרִים אֲחֵרִים לְהוֹצִיא מֵרָשׁוּת עֶלְיוֹנָה לְרָשׁוּת אַחֶרֶת, וְכָעֵת הִנֵּה חַכְמֵי הָעוֹלָם יוֹדְעִים דְּבָרִים וּמַסְתִּירִים אוֹתָם וּמִתְחַזְּקִים בַּעֲבוֹדַת רִבּוֹנָם.</p>\n<p>וּפָסוּק זֶה מָצָאתִי בְּסוֹד הַסּוֹדוֹת (תוספתא), שֶׁכְּשֶׁמְּעוֹרֵר חֶדְוַת כָּל הַחֶדְווֹת הַטָּמִיר הַנִּסְתָּר, זְקַן הַזְּקֵנִים מֵאִיר מִמֶּנּוּ אוֹר דַּקִּיק. חֶדְוַת כָּל הַחֶדְווֹת מֵאִיר לְיָמִין בְּשֶׁמֶן מִשְׁחָה עֶלְיוֹן, וּמֵאִיר לַשְּׂמֹאל בְּחֶדְוַת הַיַּיִן הַטּוֹב, מֵאִיר לָאֶמְצַע בְּחֶדְוָה (של הארגמן) שֶׁל שְׁנֵי צְדָדִים. רוּחַ מִתְעוֹרֶרֶת וְרוּחַ עוֹלָה וְנִתָּן בָּרוּחַ.</p>\n<p>דְּבֵקִים זֶה בָּזֶה. שָׁלֹשׁ נִכְנָסִים לְשָׁלֹשׁ. מִתּוֹךְ שָׁלֹשׁ יוֹצֵאת בְּרִית אַחַת שֶׁדָּבְקָה בַּבְּרִית. עוֹבֶרֶת הָרוּחַ הָעוֹלָה וּמִתְעַבֶּרֶת מִמֶּנּוּ. כְּשֶׁנִּתֶּנֶת בִּשְׁנֵי צְדָדִים, נִדְבָּקִים רוּחַ בְּרוּחַ, וּמִתְעַבְּרוֹת מִשְּׁלֹשָׁה בָנִים. וְנֹחַ וְתֵבָה יָצְאוּ מֵהֶם שְׁלֹשָׁה, כְּמוֹ שְׁלֹשֶׁת הָעֶלְיוֹנִים, וְאֵלֶּה הֵם שֶׁיָּצְאוּ מִתּוֹךְ הַתֵּבָה - שֵׁם וְחָם וָיָפֶת. שֵׁם שֶׁבְּצַד יָמִין, חָם שֶׁבְּצַד שְׂמֹאל, יֶפֶת אַרְגָּמָן שֶׁכּוֹלֵל אוֹתָם.</p>\n<p>וְחָם הוּא אֲבִי כְנָעַן, זֻהֲמַת הַזָּהָב תַּחַת סִיגִים. הִתְעוֹרְרוּת רוּחַ הַטֻּמְאָה שֶׁל נָחָשׁ הַקַּדְמוֹנִי. וְלָכֵן רָשַׁם וְאָמַר, וְחָם הוּא אֲבִי כְנָעַן. שֶׁהֵבִיא קְלָלוֹת עַל הָעוֹלָם. אוֹתוֹ כְּנַעַן שֶׁהִתְקַלֵּל, אוֹתוֹ כְנַעַן שֶׁהֶחְשִׁיךְ פְּנֵי הַבְּרִיּוֹת.</p>\n<p>וְלָכֵן (כלם) לֹא יָצָא מִכְּלַל כֻּלָּם, אֶלָּא זֶה שֶׁכָּתוּב וְחָם הוּא אֲבִי כְנָעַן, אוֹתוֹ שֶׁהֶחְשִׁיךְ אֶת הָעוֹלָם, וְלֹא כָתוּב בִּכְלַל זֶה וְשֵׁם הוּא אֲבִי כָּךְ אוֹ יֶפֶת הוּא אֲבִי כָּךְ, אֶלָּא מִיָּד קָפַץ וְאָמַר וְחָם הוּא אֲבִי כְנָעַן. וַדַּאי.</p>\n<p>וְעַל זֶה, כְּשֶׁבָּא אַבְרָהָם, מַה כָּתוּב? (בראשית יב) וַיַּעֲבֹר אַבְרָם בָּאָרֶץ. שֶׁעֲדַיִן לֹא הָיָה קִיּוּם שֶׁל הָאָבוֹת וְלֹא בָאוּ זֶרַע שֶׁל יִשְׂרָאֵל לָעוֹלָם שֶׁיֵּצֵא הַשֵּׁם הַזֶּה וְיִכָּנֵס שֵׁם עֶלְיוֹן קָדוֹשׁ. כְּשֶׁהָיוּ יִשְׂרָאֵל צַדִּיקִים, נִקְרְאָה הָאָרֶץ עַל הַשֵּׁם הַזֶּה - אֶרֶץ יִשְׂרָאֵל. כְּשֶׁלֹּא זָכוּ, נִקְרְאָה הָאָרֶץ עַל שֵׁם אַחֵר - אֶרֶץ כְּנַעַן.</p>\n<p>וְעַל זֶה כָּתוּב (שם ט) וַיֹּאמֶר אָרוּר כְּנָעַן עֶבֶד עֲבָדִים יִהְיֶה לְאֶחָיו. שֶׁהוּא הֵבִיא קְלָלוֹת עַל הָעוֹלָם. וּבַנָּחָשׁ מַה כָּתוּב? (שם ג) אָרוּר אַתָּה מִכָּל הַבְּהֵמָה, הַיְנוּ מַה שֶּׁכָּתוּב עֶבֶד עֲבָדִים. וְעַל זֶה כָּתוּב שֵׁם וְחָם וָיָפֶת. שְׁלֹשֶׁת אֵלֶּה בְּנֵי נֹחַ הַיּוֹצְאִים מִן הַתֵּבָה, כְּמוֹ שֶׁאָמַרְנוּ.</p>"],[9522011173,"<p>שְׁלשָה אֵלֶּה בְּנֵי נֹחַ, הַקִּיּוּם שֶׁל כָּל הָעוֹלָם, הַקִּיּוּם שֶׁל סוֹד עֶלְיוֹן. וּמֵאֵלֶּה נָפְצָה כָל הָאָרֶץ, הַיְנוּ סוֹד (זה) שֶׁל שְׁלֹשֶׁת הַגְּוָנִים הָעֶלְיוֹנִים. שֶׁכְּשֶׁאוֹתוֹ נָהָר שֶׁשּׁוֹפֵעַ וְיוֹצֵא, מַשְׁקֶה אֶת הַגָּן בַּכֹּחַ שֶׁל שְׁלֹשֶׁת הָעֶלְיוֹנִים הַלָּלוּ. וּמִשָּׁם נִפְרָדִים הַגְּוָנִים שֶׁלְּמַטָּה כָּל אֶחָד וְאֶחָד כָּלוּל בַּחֲבֵרוֹ, לְהַרְאוֹת שֶׁכְּבוֹד הַקָּדוֹשׁ בָּרוּךְ הוּא הִתְפַּשֵּׁט לְמַעְלָה וּלְמַטָּה, וְהוּא אֶחָד בָּעֶלְיוֹנִים וּבַתַּחְתּוֹנִים.</p>\n<p>אָמַר רַבִּי אֶלְעָזָר, שְׁלֹשֶׁת הַגְּוָנִים הַלָּלוּ בְּכָל אוֹתָם שֶׁבָּאִים מִצַּד הַקְּדֻשָּׁה, וּמִמַּרְאֶה שֶׁל שְׁלֹשֶׁת גְּוָנִים אֵלּוּ נִפְרָדִים לְכָל אוֹתָם שֶׁבָּאִים מִצַּד הָרוּחַ הָאַחֶרֶת, וּכְשֶׁתִּסְתַּכֵּל בְּסוֹד הַדְּרָגוֹת תִּמְצָא אֵיךְ נִפְרָדִים הַגְּוָנִים לְכָל אוֹתָם הַצְּדָדִים, עַד שֶׁנִּכְנָסִים לְמַטָּה בַּסּוֹד שֶׁל אוֹתָם עֶשְׂרִים וְשִׁבְעָה הַצִּנּוֹרוֹת, (הצדדים) שֶׁל הַדְּלָתוֹת שֵׁמְּכַסִּים אֶת הַתְּהוֹמוֹת.</p>\n<p>וְהַסֹלֹ יָדוּעַ לַחֲכָמִים עֶלְיוֹנִים. אַשְׁרֵי חֶלְקָם שֶׁל הַצַּדִּיקִים שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא רוֹצֶה בִּכְבוֹדָם וְגִלָּה לָהֶם סִתְרֵי חָכְמָה עֶלְיוֹנִים, עֲלֵיהֶם כָּתוּב (תהלים כה) סוֹד ה' לִירֵאָיו וּבְרִיתוֹ לְהוֹדִיעָם.</p>\n<p>פָּתַח רַבִּי אֶלְעָזָר וְאָמַר, (ישעיה כה) ה' אֱלֹהַי אַתָּה אֲרוֹמִמְךְ אוֹדֶה שִׁמְךְ כִּי עָשִׂיתָ פֶּלֶא עֵצוֹת מֵרָחֹק אֱמוּנָה אֹמֶן. כַּמָּה יֵשׁ לִבְנֵי אָדָם לְהִסְתַּכֵּל בִּכְבוֹד הַקָּדוֹשׁ בָּרוּךְ הוּא וּלְשַׁבֵּחַ לִכְבוֹדוֹ, מִשּׁוּם שֶׁכָּל מִי שֶׁיּוֹדֵעַ לְשַׁבֵּחַ אֶת רִבּוֹנוֹ כָּרָאוּי, הַקָּדוֹשׁ בָּרוּךְ הוּא עוֹשֶׂה אֶת רְצוֹנוֹ, וְלֹא עוֹד - אֶלָּא שֶׁמַּרְבֶּה בְרָכוֹת לְמַעְלָה וּלְמַטָּה.</p>\n<p>וְעַל כֵּן, מִי שֶׁיּוֹדֵעַ לְשַׁבֵּחַ אֶת רִבּוֹנוֹ וּלְיַחֵד אֶת שְׁמוֹ, חָבִיב הוּא לְמַעְלָה וְנֶחְמָד לְמַטָּה, וְהַקָּדוֹשׁ בָּרוּךְ הוּא מִשְׁתַּבֵּחַ בּוֹ (בכבודו), וְעָלָיו כָּתוּב (שם מט) וַיֹּאמֶר לִי עַבְדִּי אַתָּה יִשְׂרָאֵל אֲשֶׁר בְּךְ אֶתְפָּאָר.</p>"],[9522011174,"<p>וַיָּחֶל נֹחַ אִישׁ הָאֲדָמָה וַיִּטַּע כֶּרֶם. רַבִּי יְהוּדָה וְרַבִּי יוֹסֵי. אֶחָד אָמַר מִגַּן עֵדֶן (נתרכבה) גֹּרְשָׁה וְנָטַע אוֹתָהּ כָּאן. וְאֶחָד אָמַר בָּאָרֶץ הָיְתָה, וְעָקַר אוֹתָהּ וְשָׁתַל אוֹתָהּ, וּבְאוֹתוֹ יוֹם עָשְׂתָה פֵרוֹת וְנִצְנְצוּ לִבְלוּבִים וַעֲנָבִים, וְהָיָה סוֹחֵט אוֹתָהּ וְשׁוֹתֶה מֵהַיַּיִן וּמִשְׁתַּכֵּר.</p>\n<p>רַבִּי שִׁמְעוֹן אָמַר, סוֹד הַחָכְמָה הוּא כָּאן בַּפָּסוּק הַזֶּה. כְּשֶׁרָצָה נֹחַ לִבְדֹּק בְּאוֹתוֹ חֵטְא שֶׁבָּדַק אָדָם הָרִאשׁוֹן - לֹא כְּדֵי לְהִתְדַּבֵּק בּוֹ, אֶלָּא לָדַעַת וּלְתַקֵּן הָעוֹלָם, וְלֹא יָכֹל. סָחַט עֲנָבִים לִבְדֹּק בְּאוֹתוֹ כֶּרֶם. כֵּיוָן שֶׁהִגִּיעַ לָזֶה, (אז) וַיִּשְׁכָּר וַיִּתְגַּל, וְלֹא הָיָה לוֹ כֹּחַ לַעֲמֹד. וְלָכֵן וַיִּתְגַּל, גִּלָּה פִּרְצָה שֶׁל הָעוֹלָם שֶׁהָיְתָה נִסְתֶּרֶת. בְּתוֹךְ אָהֳלֹה, כָּתוּב בְּהֵ\"א. וְעַל זֶה כָּתוּב וְאַל תִּקְרַב אֶל פֶּתַח בֵּיתָהּ. בְּתוֹךְ אָהֳלָהּ שֶׁל אוֹתָהּ כֶּרֶם.</p>\n<p>כְּמוֹ זֶה בְּנֵי אַהֲרֹן שֶׁשָּׁנִינוּ שֶׁהָיוּ שְׁתוּיֵי יַיִן, וְכִי מִי נָתַן לָהֶם יַיִן בְּאוֹתוֹ מָקוֹם לִשְׁתּוֹת? אִם תַּעֲלֶה בְדַעְתְּךְ שֶׁהָיוּ חֲצוּפִים שֶׁשָּׁתוּ יַיִן - לֹא כָּךְ! אֶלָּא וַדַּאי מֵאוֹתוֹ יַיִן שָׁתוּ, שֶׁכָּתוּב (ויקרא י) וַיַּקְרִיבוּ לִפְנֵי ה' אֵשׁ זָרָה. כָּתוּב כָּאן אֵשׁ זָרָה, וְכָתוּב שָׁם (משלי ז) לִשְׁמָרְךְ מֵאִשָּׁה זָרָה. וְהַכֹּל דָּבָר אֶחָד.</p>\n<p>וְכָךָ כְּמוֹ זֶה וַיֵּשְׁתְּ מִן הַיַּיִן וַיִּשְׁכָּר וַיִּתְגַּל. וְעַל זֶה הִתְעוֹרֵר חָם אֲבִי כְנַעַן, כְּמוֹ שֶׁנִּתְבָּאֵר, וְנִתַּן מָקוֹם לִכְנַעַן לִשְׁלֹט. וּמַה שֶּׁהָיָה זֶה צַדִּיק בְּסוֹד הַבְּרִית, סֵרַס אוֹתוֹ. וְשָׁנִינוּ, שֶׁהֶעֱבִיר מִמֶּנּוּ אוֹתוֹ קִיּוּם.</p>\n<p>וְלָכֵן אָמַר אָרוּר, שֶׁהֲרֵי הַקְּלָלוֹת הִתְעוֹרְרוּ בַּתְּחִלָּה עַל יָדוֹ בָּעוֹלָם. (ועל זה ויאמר ארור כנען, שהרי קללות יבאו על העולם כבתחלה). עֶבֶד עֲבָדִים יִהְיֶה, כְּמוֹ שֶׁנֶּאֱמַר אָרוּר אַתָּה מִכָּל הַבְּהֵמָה וְגוֹ'. הַכֹּל יְתֻקַּן לֶעָתִיד לָבֹא, וְהוּא לֹא יְתֻקַּן. וְכֻלָּם יֵצְאוּ לְחֵרוּת, וְהוּא לֹא יֵצֵא. וְסוֹד הוּא לְאוֹתָם שֶׁיּוֹדְעִים דַּרְכֵי וּשְׁבִילֵי הַתּוֹרָה.</p>"],[9522011175,"<p>פָּתַח וְאָמַר, (תהלים נא) כִּי פְשָׁעַי אֲנִי אֵדָע וְחַטָּאתִי נֶגְדִּי תָמִיד. כַּמָּה יֵשׁ לִבְנֵי אָדָם לְהִשָּׁמֵר מֵחֲטָאֵיהֶם לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא, שֶׁהֲרֵי אַחַר שֶׁחָטָא אָדָם, רָשׁוּם חֶטְאוֹ לְמַעְלָה וְלֹא נִמְחָק, רַק בְּכֹחַ שֶׁל תְּשׁוּבָה רַבָּה, כְּמוֹ שֶׁנֶּאֱמַר (ירמיה ב) כִּי אִם תְּכַבְּסִי בַּנֶּתֶר וְתַרְבִּי לָךְ בֹּרִית נִכְתָּם עֲונֵךְ לְפָנַי.</p>\n<p>בֹּא רְאֵה, כֵּיוָן שֶׁחָטָא אָדָם לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא פַּעַם אַחַת - עוֹשֶׂה רֹשֶׁם. וּכְשֶׁחָטָא בּוֹ פַּעַם שְׁנִיָּה - מִתְחַזֵּק יוֹתֵר אוֹתוֹ הָרֹשֶׁם. חָטָא בּוֹ פַּעַם שְׁלִישִׁית - מִתְפַּשֵּׁט אוֹתוֹ הַכֶּתֶם מִצַּד זֶה לְצַד זֶה, וְאָז כָּתוּב נִכְתָּם עֲוֹנֵךְ לְפָנַי.</p>\n<p>בֹּא רְאֵה, כֵּיוָן שֶׁחָטָא דָוִד הַמֶּלֶךְ לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא עַל הָעֵסֶק שֶׁל בַּת שֶׁבַע, חָשַׁב שֶׁאוֹתוֹ חֵטְא נִרְשָׁם עָלָיו לְעוֹלָמִים. מַה כָּתוּב? (שמואל ב יב) גַּם ה' הֶעֱבִיר חַטָּאתְךְ לֹא תָמוּת. הָעֳבַר אוֹתוֹ הָרֹשֶׁם מִלְּפָנָיו.</p>\n<p>אָמַר לוֹ רַבִּי אַבָּא, וַהֲרֵי שָׁנִינוּ שֶׁבַּת שֶׁבַע הָיְתָה שֶׁל דָּוִד הַמֶּלֶךְ מִיּוֹם שֶׁנִּבְרָא הָעוֹלָם, לָמָּה נָתַן אוֹתָהּ הַקָּדוֹשׁ בָּרוּךְ הוּא לְאוּרִיָּה הַחִתִּי מִקֹּדֶם לָזֶה?</p>\n<p>אָמַר לוֹ, כָּךְ דַּרְכּוֹ שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא - אַף עַל גַּב שֶׁמְּזֻמֶּנֶת לְבֶן אָדָם לִהְיוֹת שֶׁלּוֹ, מַקְדִּים אַחֵר וְנוֹשֵׂא אוֹתָהּ עַד שֶׁמַּגִּיעַ זְמַנּוֹ שֶׁל זֶה. כֵּיוָן שֶׁהִגִּיעַ זְמַנּוֹ, נִדְחֶה זֶה שֶׁנָּשָׂא אוֹתָהּ מִלִּפְנֵי הָאַחֵר הַזֶּה שֶׁבָּא אַחַר כָּךְ וּמִסְתַּלֵּק מֵהָעוֹלָם, וְקָשֶׁה לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא לְהַעֲבִירוֹ מֵהָעוֹלָם כְּשֶׁעֲדַיִן לֹא הִגִּיעַ זְמַנּוֹ מִלִּפְנֵי הָאַחֵר הַזֶּה.</p>\n<p>וְסוֹד שֶׁבַּת שֶׁבַע שֶׁנִּתְּנָה לְאוּרִיָּה הַחִתִּי (כפי שאמרנו) בַּתְּחִלָּה, צֵא וְדַיֵּק וְתִמְצָא לָמָּה נִתְּנָה הָאָרֶץ הַקְּדוֹשָׁה לִכְנַעַן בְּטֶרֶם שֶׁבָּאוּ יִשְׂרָאֵל, וְתִמְצָא דָבָר זֶה. וְהַכֹּל סוֹד אֶחָד הוּא וְדָבָר אֶחָד.</p>\n<p>בֹּא רְאֵה, דָּוִד, אַף עַל גַּב שֶׁהוֹדָה עַל חֶטְאוֹ וְשָׁב בִּתְשׁוּבָה, לֹא הֵסִיר מִלִּבּוֹ וּרְצוֹנוֹ מֵאוֹתָם חֲטָאִים שֶׁחָטָא וּמֵאוֹתוֹ חֵטְא שֶׁל בַּת שֶׁבַע, כִּי פָחַד עֲלֵיהֶם תָּמִיד שֶׁמָּא יִגְרֹם אֶחָד מֵהֶם וִיקַטְרֵג עָלָיו בִּשְׁעַת הַסַּכָּנָה, וְלָכֵן לֹא שָׁכַח אוֹתָם מִמֶּנּוּ וּמֵרְצוֹנוֹ.</p>\n<p>דָּבָר אַחֵר, כִּי פְשָׁעַי אֲנִי אֵדָע - כָּל הַדְּרָגוֹת שֶׁתְּלוּיוֹת בָּהֶם חֲטָאֵי בְּנֵי אָדָם אֲנִי אֵדַע. וְחַטָּאתִי נֶגְדִּי תָמִיד - זוֹ פְגִימַת הַלְּבָנָה שֶׁלֹּא יָצְאָה מִטֻּמְאָתָהּ עַד שֶׁבָּא שְׁלֹמֹה וְהֵאִירָה בִשְׁלֵמוּת, וְאָז הִתְבַּסֵּם הָעוֹלָם וְיָשְׁבוּ יִשְׂרָאֵל לָבֶטַח, שֶׁכָּתוּב (מלכים א ה) וַיֵּשֶׁב יְהוּדָה וְיִשְׂרָאֵל לָבֶטַח אִישׁ תַּחַת גַּפְנוֹ וְתַחַת תְּאֵנָתוֹ. וְעִם כָּל זֶה - וְחַטָּאתִי נֶגְדִּי תָמִיד, וְלֹא נִפְסָק מֵהָעוֹלָם עַד שֶׁיָּבֹא מֶלֶךְ הַמָּשִׁיחַ לֶעָתִיד לָבא, כְּמוֹ שֶׁנֶּאֱמַר (זכריה יג) וְאֶת רוּחַ הַטֻּמְאָה אַעֲבִיר מִן הָאָרֶץ.</p>"],[9522011176,"<p>הוּא הָיָה גִבֹּר צַיִד לִפְנֵי ה' עַל כֵּן יֵאָמַר כְּנִמְרֹד גִּבּוֹר צַיִד לִפְנֵי ה'. בֹּא רְאֵה, הוּא הָיָה אִישׁ חָזָק. לְבוּשֵׁי אָדָם הָרִאשׁוֹן הָיָה לוֹבֵשׁ, וְיָדַע לָצוּד צִידָה שֶׁל הַבְּרִיּוֹת בָּהֶם.</p>\n<p>אָמַר רַבִּי אֶלְעָזָר, נִמְרוֹד הָיָה מְפַתֶּה אֶת הַבְּרִיּוֹת לָלֶכֶת אַחַר עֲבוֹדַת הָעֲבוֹדָה זָרָה, וְהָיָה שׁוֹלֵט בְּאוֹתָם לְבוּשִׁים וּמְנַצֵּחַ אֶת בְּנֵי הָעוֹלָם, וְהָיָה אוֹמֵר שֶׁהוּא שַׁלִּיט שֶׁל הָעוֹלָם, וְעוֹבְדִים אוֹתוֹ בְּנֵי אָדָם. וְלָמָּה נִקְרָא שְׁמוֹ נִמְרוֹד? שֶׁמָּרַד בַּמֶּלֶךְ הָעֶלְיוֹן שֶׁלְּמַעְלָה, שֶׁמָּרַד בָּעֶלְיוֹנִים וּמָרַד בַּתַּחְתּוֹנִים.</p>\n<p>בְּאוֹתָם לְבוּשִׁים הוּא שָׁלַט עַל כָּל (שאר) בְּנֵי הָעוֹלָם וּמָלַךְ בָּהֶם, וּמָרַד בְּרִבּוֹנוֹ וְאָמַר שֶׁהוּא הַשַּׁלִּיט שֶׁל הָעוֹלָם, וְהָיָה מְפַתֶּה אֶת הַבְּרִיּוֹת אַחֲרָיו, עַד שֶׁמָּשַׁךְ בְּנֵי אָדָם לָצֵאת מֵאַחַר עֲבוֹדַת רִבּוֹן הָעוֹלָם. אָמַר רַבִּי שִׁמְעוֹן, בַּלְּבוּשִׁים הַלָּלוּ יוֹדְעִים בָּהֶם הַחֲבֵרִים סוֹד עֶלְיוֹן.</p>"],[9522011177,"<p>מִשְׁנָה, וַיְהִי כָל הָאָרֶץ שָׂפָה אֶחָת וּדְבָרִים אֲחָדִים. רַבִּי שִׁמְעוֹן פָּתַח, (מלכים א ו) וְהַבַּיִת בְּהִבָּנֹתוֹ אֶבֶן שְׁלֵמָה מַסָּע נִבְנָה וּמַקָּבוֹת וְהַגַּרְזֶן כָּל כְּלִי בַרְזֶל לֹא נִשְׁמַע בַּבַּיִת בְּהִבָּנֹתוֹ. וְהַבַּיִת בְּהִבָּנֹתוֹ - וְכִי לֹא הָיָה בּוֹנֶה אוֹתוֹ שְׁלֹמֹה וְכָל הָאָמָּנִים שֶׁהָיוּ שָׁם? מַה זֶּה בְּהִבָּנֹתוֹ?</p>\n<p>אֶלָּא כָּךְ הוּא, כְּמוֹ שֶׁכָּתוּב (שמות כה) מִקְשָׁה תֵּיעָשֶׂה הַמְּנוֹרָה. אִם הִיא מִקְשָׁה, מַהוּ תֵּיעָשֶׂה? אֶלָּא וַדַּאי הַכֹּל בְּאוֹת וְנֵס נַעֲשָׂה הוּא מֵעַצְמוֹ. כֵּיוָן שֶׁהִתְחִילוּ לַעֲשׂוֹת הַמַּעֲשֶׂה, לִמֵּד אֶת הָאָמָּנִים לַעֲשׂוֹת אוֹתָהּ מַה שֶּׁלֹּא הָיוּ יוֹדְעִים מִקֹּדֶם לָכֵן.</p>\n<p>מָה הַטַּעַם? מִשּׁוּם שֶׁבִּרְכַּת הַקָּדוֹשׁ בָּרוּךְ הוּא שָׁרְתָה עַל יָדָם, וְעַל כֵּן כָּתוּב בְּהִבָּנֹתוֹ, הוּא נִבְנָה מֵעַצְמוֹ, שֶׁהוּא לִמֵּד אֶת הַלִּמּוּד לָאָמָּנִים אֵיךְ לְהַתְחִיל לַעֲשׂוֹת, וְלֹא הִסְתַּלֵּק מֵעֵינֵיהֶם הָרֹשֶׁם שֶׁל אוֹתוֹ הַמַּעֲשֶׂה מַמָּשׁ, וּמִסְתַּכְּלִים בּוֹ וְעוֹשִׂים, עַד שֶׁנִּבְנָה כָּל הַבַּיִת.</p>\n<p>אֶבֶן שְׁלֵמָה מַסָּע נִבְנָה, שְׁלֵמָה כָּתוּב חָסֵד יוֹ\"ד, אֶבֶן שְׁלֵמָה וַדַּאי. מַסָּע, שֶׁנָּסְעָה וּבָאָה וְשָׁרְתָה עֲלֵיהֶם וְנֶעֶשְׂתָה הָעֲבוֹדָה (מסע, שנסעה ידם ונעשתה העבודה). מַסָּע, שֶׁהִסִּיעַ יָדָם לַעֲשׂוֹת שֶׁלֹּא מִדַּעְתָּם. כָּתוּב כָּאן מַסָּע, וְכָתוּב שָׁם (במדבר י) וּלְמַסַּע אֶת הַמַּחֲנוֹת.</p>\n<p>וּמַקָּבוֹת וְהַגַּרְזֶן כָּל כְּלִי בַרְזֶל לֹא נִשְׁמַע, מִשּׁוּם שֶׁהַשָּׁמִיר בָּקַע הַכֹּל וְלֹא נִשְׁמַע דָּבָר, שֶׁלֹּא הִצְטָרְכוּ לִשְׁאָר הַכֵּלִים לַעֲשׂוֹת, וְהַכֹּל הָיָה עִם אוֹת וְנֵס.</p>\n<p>אָמַר רַבִּי שִׁמְעוֹן, כַּמָּה חֲבִיבִים הֵם דִּבְרֵי הַתּוֹרָה. אַשְׁרֵי חֶלְקוֹ שֶׁל מִי שֶׁמִּתְעַסֵּק בָּהֶם וְיוֹדֵעַ לָלֶכֶת (בו) בְּדֶרֶךְ אֱמֶת. וְהַבַּיִת בְּהִבָּנֹתוֹ. כַּאֲשֶׁר עָלָה בִּרְצוֹן הַקָּדוֹשׁ בָּרוּךְ הוּא לַעֲשׂוֹת כָּבוֹד לִכְבוֹדוֹ, עָלָה מִתּוֹךְ הַמַּחֲשָׁבָה רָצוֹן לְהִתְפַּשֵּׁט, וְהִתְפַּשֵּׁט מֵהַמָּקוֹם שֶׁל אוֹתָהּ הַמַּחֲשָׁבָה הַנִּסְתֶּרֶת שֶׁאֵינָהּ יְדוּעָה.</p>\n<p>עֵד שֶׁמִּתְפַּשֶּׁטֶת וְשׁוֹרָה בְּבֵית הַגָּרוֹן, הַמָּקוֹם שֶׁתָּמִיד נוֹבֵעַ בְּסוֹד שֶׁהוּא רוּחַ חַיִּים. וְאָז, כְּשֶׁמִּתְפַּשֶּׁטֶת הַמַּחֲשָׁבָה הַהִיא וְשׁוֹרָה בַּמָּקוֹם הַזֶּה, נִקְרֵאת הַמַּחֲשָׁבָה הַהִיא אֱלֹהִים חַיִּים, שֶׁכָּתוּב (ירמיה י) הוּא אֱלֹהִים חַיִּים.</p>\n<p>עוֹד רָצָה לְהִתְפַּשֵּׁט וּלְהִתְגַּלּוֹת, מִשָּׁם יָצְאוּ אֵשׁ רוּחַ וּמַיִם כְּלוּלִים יַחַד, וְיוֹצֵא יַעֲקֹב אִישׁ שָׁלֵם, וְהוּא קוֹל אֶחָד שֶׁיּוֹצֵא וְנִשְׁמָע. מִכָּאן הַמַּחֲשָׁבָה שֶׁהָיְתָה נִסְתֶּרֶת בַּחֲשַׁאי נִשְׁמַעַת בְּגִלּוּי.</p>\n<p>עוֹד מִתְפַּשֶּׁטֶת הַמַּחֲשָׁבָה הַזּוֹ לְהִתְגַּלּוֹת, וּמַכֶּה הַקּוֹל הַזֶּה וּמַקִּישׁ בַּשְּׂפָתַיִם, וְאָז יוֹצֵא הַדִּבּוּר שֶׁמַּשְׁלִים הַכֹּל וּמְגַלֶּה הַכֹּל. נִשְׁמָע שֶׁהַכֹּל הוּא אוֹתָהּ מַחֲשָׁבָה נִסְתֶּרֶת שֶׁהָיְתָה בִּפְנִים, וְהַכֹּל אֶחָד.</p>\n<p>כֵּיוָן שֶׁמַּגִּיעָה הִתְפַּשְּׁטוּת זוֹ וְנַעֲשֶׂה דִבּוּר בְּכֹחַ אוֹתוֹ הַקּוֹל, אָז - וְהַבַּיִת בְּהִבָּנֹתוֹ. לֹא כָּתוּב כַּאֲשֶׁר נִבְנָה, אֶלָּא בְּהִבָּנֹתוֹ, בְּכָל פַּעַם וּפַעַם. אֶבֶן שְׁלֵמָה, כְּמוֹ שֶׁנִּתְבָּאֵר. וְכָתוּב (שיר ג) בָּעֲטָרָה שֶׁעִטְּרָה לּוֹ אִמּוֹ.</p>\n<p>מַסָּע, שֶׁיּוֹצֵא מִבִּפְנִים וְשׁוֹרֶה וְנוֹסֵעַ הַחוּצָה. יוֹצֵא מִלְמַעְלָה וְשׁוֹרֶה וְנוֹסֵעַ לְמַטָּה. וּמַקָּבוֹת וְהַגַּרְזֶן כָּל כְּלִי בַרְזֶל - אֵלּוּ שְׁאָר הַדְּרָגוֹת הַתַּחְתּוֹנוֹת שֶׁכֻּלָּם תְּלוּיִים בּוֹ, וְלֹא נִשְׁמְעוּ וְלֹא הִתְקַבְּלוּ פְּנִימָה כְּשֶׁהִיא עוֹלָה לְהֵאָחֵז לְמַעְלָה וְלִינוֹק מִשָּׁם, וְזֶהוּ בְּהִבָּנֹתוֹ.</p>\n<p>וְאָז, כְּשֶׁהִיא יוֹנֶקֶת, כֻּלָּם עוֹמְדִים בְּחֶדְוָה וְיוֹנְקִים וּמִתְמַלְּאִים בִּבְרָכוֹת, וְאָז כָּל הָעוֹלָמוֹת עוֹמְדִים בְּסוֹד אֶחָד, בְּיִחוּד אֶחָד, וְאֵין בָּהֶם בְּכָל הָעוֹלָמוֹת פֵּרוּד. אַחַר שֶׁכָּל אֶחָד וְאֶחָד נוֹטְלִים חֶלְקָם, כֻּלָּם מִתְפַּשְּׁטִים וְנִפְרָדִים לְצִדֵּיהֶם לְמַה שֶּׁהִתְמַנּוּ.</p>"],[9522011178,"<p>בֹּא רְאֵה, וַיְהִי כָל הָאָרֶץ שָׂפָה אֶחָת וְגוֹ'. מַה כָּתוּב אַחַר כָּךְ? וַיְהִי בְּנָסְעָם מִקֶּדֶם - מֵאוֹתוֹ קַדְמוֹנוֹ שֶׁל הָעוֹלָם - וַיִּמְצְאוּ בִקְעָה בְּאֶרֶץ שִׁנְעָר. שֶׁהֲרֵי מִשָּׁם נִפְרָדִים לְכָל אוֹתָם הַצְּדָדִים, וְהוּא רֹאשׁ הַמַּלְכוּת לְהִתְפַּזֵּר.</p>\n<p>וְאִם תֹּאמַר, הִנֵּה כָּתוּב (בראשית ב) וְנָהָר יֹצֵא מֵעֵדֶן לְהַשְׁקוֹת אֶת הַגָּן וּמִשָּׁם יִפָּרֵד? וַדַּאי שֶׁכָּכָה זֶה. שֶׁכֵּיוָן שֶׁנּוֹסְעִים מִשָּׁם יֵשׁ פֵּרוּד, וְכַאֲשֶׁר הֵם מְכֻנָּסִים שָׁם לִינוֹק אֵין פֵּרוּד. וּכְשֶׁנּוֹסְעִים יֵשׁ פֵּרוּד, שֶׁכָּתוּב וַיְהִי בְּנָסְעָם מִקֶּדֶם וַיִּמְצְאוּ בִקְעָה, כְּמוֹ שֶׁנִּתְבָּאֵר.</p>\n<p>וַיְהִי כָל הָאָרֶץ שָׂפָה אֶחָת וּדְבָרִים אֲחָדִים, שֶׁאָז הֲרֵי הָעוֹלָם בִּיסוֹד וְעִקָּר וְשֹׁרֶשׁ אֶחָד וֶאֱמוּנָה אַחַת בַּקָּדוֹשׁ-בָּרוּךְ-הוּא. מַה כָּתוּב? וַיְהִי בְּנָסְעָם מִקֶּדֶם, מֵהָרִאשׁוֹן עִקַּר הָעוֹלָם אֱמוּנַת הַכֹּל. וַיִּמְצְאוּ בִקְעָה, מְצִיאָה מָצְאוּ וְיָצְאוּ בָהּ מִתַּחַת הָאֱמוּנָה הָעֶלְיוֹנָה (וימצאו).</p>\n<p>בֹּא רְאֵה מַה כָּתוּב בְּנִמְרוֹד, וַתְּהִי רֵאשִׁית מַמְלַכְתּוֹ בָּבֶל. שֶׁהֲרֵי מִשָּׁם נָסַע לְהֵאָחֵז בְּרָשׁוּת אַחֶרֶת. וְכָאן, וַיִּמְצְאוּ בִקְעָה בְּאֶרֶץ שִׁנְעָר. מִשָּׁם נָסְעוּ בְּלִבָּם לָצֵאת מֵרָשׁוּת הָעֶלְיוֹנָה לְרָשׁוּת אַחֶרֶת.</p>\n<p>וַיֹּאמְרוּ הָבָה נִבְנֶה לָּנוּ עִיר וּמִגְדָּל וְרֹאשׁוֹ בַשָּׁמַיִם וְנַעֲשֶׂה לָּנוּ שֵׁם. רַבִּי חִיָּיא פָּתַח, (ישעיה נז) וְהָרְשָׁעִים כַּיָּם נִגְרָשׁ וְגוֹ'. וְכִי יֵשׁ יָם נִגְרָשׁ? כֵּן. שֶׁכַּאֲשֶׁר הַיָּם יוֹצֵא מִתִּקּוּנוֹ וְהוֹלֵךְ (בלי הבל) בְּלִי רַב חוֹבֵל, אָז נִגְרָשׁ וּמִתְגָּרֵשׁ מִמְּקוֹמוֹ, כְּמִי שֶׁשּׁוֹתֶה יַיִן וְלֹא יוֹשֵׁב עַל בֻּרְיוֹ וְעוֹלֶה וְיוֹרֵד. מָה הַטַּעַם? מִשּׁוּם כִּי הַשְׁקֵט לֹא יוּכָל וַיִּגְרְשׁוּ מֵימָיו רֶפֶשׁ וָטִיט. שֶׁמּוֹצִיאִים מֵימָיו כָּל אוֹתוֹ הַטִּיט שֶׁל הַיָּם וְכָל הַטִּנֹּפֶת לִשְׂפָתוֹ.</p>\n<p>כְּמוֹ זֶה אוֹתָם הָרְשָׁעִים שֶׁיּוֹצְאִים מִדֶּרֶךְ תְּקִינָה וְהוֹלְכִים כִּשְׁתוּיֵי יַיִן בְּלִי תִקּוּן, שֶׁיּוֹצְאִים מִדֶּרֶךְ יְשָׁרָה לְדֶרֶךְ עֲקֻמָּה. מָה הַטַּעַם? מִשּׁוּם כִּי הַשְׁקֵט לֹא יוּכָל, שֶׁהֲרֵי עִקּוּם דַּרְכֵיהֶם גָּרַם לָהֶם לָלֶכֶת בְּלִי תִקּוּן וּבְלִי שֶׁקֶט.</p>\n<p>וְלֹא עוֹד, אֶלָּא שֶׁכָּל רֻגְזָם בְּשָׁעָה שֶׁאוֹמְרִים דִּבּוּר מִפִּיהֶם, אוֹתוֹ הַדִּבּוּר רֶפֶשׁ וָטִיט, כֻּלָּם מוֹצִיאִים טִנֹּפֶת וְגֹעַל מִפִּיהֶם הַחוּצָה עַד שֶׁנִּטְמָאִים וּמְטַמְּאִים אוֹתָם.</p>\n<p>בֹּא רְאֵה, וַיֹּאמְרוּ הָבָה נִבְנֶה לָּנוּ עִיר וּמִגְדָּל וְרֹאשׁוֹ בַשָּׁמַיִם. אֵין הָבָה אֶלָּא לְשׁוֹן הַזְמָנָה בְּעָלְמָא. נִבְנֶה לָּנוּ עִיר וּמִגְדָּל וְרֹאשׁוֹ בַשָּׁמַיִם, כֻּלָּם בָּאוּ בְּעֵצָה רָעָה לְסָרֵב לַקָּדוֹשׁ-בָּרוּךְ-הוּא. בִּשְׁטוּת בָּאוּ, הוּא בְּטִפְּשׁוּת הַלֵּב.</p>\n<p>אָמַר רַבִּי אַבָּא, שְׁטוּת לָקְחוּ בְּלִבָּם, אֲבָל בְּחָכְמָה שֶׁל רִשְׁעוּת בָּאוּ כְּדֵי לָצֵאת מֵרָשׁוּת עֶלְיוֹנָה לְרָשׁוּת אַחֶרֶת, וּלְהַחֲלִיף כְּבוֹדוֹ לְכָבוֹד זָר. וּבַכֹּל יֵשׁ סוֹד שֶׁל חָכְמָה עֶלְיוֹנָה.</p>\n<p>הָבָה נִבְנֶה לָּנוּ עִיר וּמִגְדָּל. בֹּא רְאֵה, כְּשֶׁהִגִּיעוּ לַבִּקְעָה הַ את שֶׁהִיא רָשׁוּת זָרָה, וְהִתְגַּלָּה לָהֶם מָקוֹם שֶׁשִּׁלְטוֹן זֶה תָּקוּעַ בְּתוֹךְ דְּגֵי הַיָּם, אָמְרוּ, הִנֵּה מָקוֹם לָשֶׁבֶת וּלְחַזֵּק אֶת הַלֵּב לֵהָנוֹת בּוֹ הַתַּחְתּוֹנִים. מִיָּד הָבָה נִבְנֶה לָּנוּ עִיר, נַתְקִין בַּמָּקוֹם הַזֶּה עִיר וּמִגְדָּל.</p>\n<p>וְנַעָשֶׂה לָּנוּ שֵׁם. מָקוֹם זֶה (נתן להם) יִהְיֶה לָנוּ לְיִרְאָה, וְלֹא אַחֵר, וְנִבְנֶה לְמָקוֹם זֶה עִיר וּמִגְדָּל. לָמָּה לָנוּ לַעֲלוֹת לְמַעְלָה שֶׁלֹּא נוּכַל לֵהָנוֹת מִמֶּנּוּ? הֲרֵי כָּאן מָקוֹם מְתֻקָּן. וְנַעֲשֶׂה לָּנוּ שֵׁם, יִרְאָה לַעֲבֹד שָׁם. פֶּן נָפוּץ לִדְרָגוֹת אֲחֵרוֹת וְנִתְפַּזֵּר לִצִדְדֵי הָעוֹלָם.</p>\n<p>מְקִימֵי הָעִיר וְהַמִּגְדָּל מְדַבְּרִים בִּלְשׁוֹן הַקֹּדֶשׁ שֶׁמַּלְאֲכֵי הַשָּׁרֵת מַכִּירִים אוֹתָהּ, וְלֹא הָיוּ מְדַבְּרִים בְּלָשׁוֹן אַחֶרֶת, מִשּׁוּם כָּךְ כָּתוּב וְעַתָּה לֹא יִבָּצֵר מֵהֶם וְגוֹ'. שֶׁאִלְמָלֵא מְדַבְּרִים בְּלָשׁוֹן אַחֶרֶת שֶׁמַּלְאָכִים עֶלְיוֹנִים לֹא הָיוּ מַכִּירִים אוֹתָהּ, נֶחְסְרָה הַחֲשִׁיבוּת שֶׁהֵם חָשְׁבוּ לַעֲשׂוֹת, כֵּיוָן שֶׁמַּעֲשֵׂה הַשֵּׁדִים אֵינוֹ אֶלָּא בְּרֶגַע אֶחָד לְמַרְאֵה בְּנֵי אָדָם וְלֹא יוֹתֵר.</p>\n<p>וּדְבָרִים אֲחָדִים, שֶׁהָיוּ יוֹדְעִים דְּרָגוֹת עֶלְיוֹנוֹת כָּל אַחַת וְאַחַת עַל בֻּרְיָהּ, וְלֹא הִתְחַלְּפָה לָהֶם דַּרְגָּה, וְלָכֵן כָּתוּב וּדְבָרִים אֲחָדִים. וּמִשּׁוּם כָּךְ הִתְיָעֲצוּ בְּעֵצָה רָעָה, עֵצָה שֶׁל חָכְמָה, שֶׁכָּתוּב הָבָה נִבְנֶה לָּנוּ עִיר וּמִגְדָּל.</p>\n<p>הַכֹּל הוּא בְּסוֹד הַחָכְמָה. וְרָצוּ לְחַזֵּק בָּאָרֶץ אֶת הַצַּד הָאַחֵר וְלַעֲבֹד אֶת עֲבוֹדָתוֹ, מִשּׁוּם שֶׁהָיוּ יוֹדְעִים שֶׁכָּל הַדִּינִים הָרָעִים מִשָּׁם יוֹרְדִים לָעוֹלָמוֹת, וְרָצוּ לִדְחוֹת אֶת דַּרְגַּת הַקֹּדֶשׁ.</p>\n<p>עִי\"ר וּמִגְדָּ\"ל - זוֹ הַחָכְמָה הָעֶלְיוֹנָה, (שהרי) הָיוּ יוֹדְעִים שֶׁשֵּׁם הַקָּדוֹשׁ לֹא מִתְחַזֵּק בָּאָרֶץ אֶלָּא בְּעִיר וּמִגְדָּל. עִי\"ר - שֶׁכָּתוּב (שמואל ב ה) עִיר דָּוִד הִיא צִיּוֹן וְגוֹ'. מִגְדָּ\"ל - שֶׁכָּתוּב (שיר ד) כְּמִגְדַּל דָּוִיד צַוָּארֵךְ. וּבְחָכְמָה עָשׂוּ לִהְיוֹת שִׁלְטוֹן הַצַד הָאַחֵר בָּאָרֶץ שֶׁדּוֹחֶה (לדחות) אֶת אֲדוֹן כָּל הָאָרֶץ מִמְּקוֹמוֹ, וְלִהְיוֹת דִּיּוּר לַסִּטְרָא אַחֲרָא בָּאָרֶץ.</p>\n<p>וְנַעָשֶׂה לָּנוּ שֵׁם - כְּמוֹ שֶׁאָחוּז (שאחר) הוּא הַשֵּׁם לְמַעְלָה, נְחַזֵּק אוֹתָהּ בֵּינֵינוּ שֶׁיִּהְיֶה שֵׁם בָּאָרֶץ. פֶּן נָפוּץ - יְדִיעָה הָיוּ יוֹדְעִים שֶׁיִּתְפַּזְּרוּ מֵעַל פְּנֵי הָאָרֶץ, וְלָכֵן הָיוּ מִתְיַחֲדִים לַעֲשׂוֹת מַעֲשֶׂה זֶה בְּחָכְמָה.</p>\n<p>הַצַד הָאַחֵר הוּא זָכָר וּנְקֵבָה, תֹּקֶף זֻהֲמַת הַדִּין הַקָּשֶׁה. וּכְמוֹ שֶׁאָדָם חָטָא (בו) בָהֶם וְהִתְחַזְּקוּ בִּגְלָלוֹ עַל הָעוֹלָם, גַּם כָּאן הֵם עָשׂוּ שֶׁיִּתְחַזֵּק יוֹתֵר, שֶׁכָּתוּב אֲשֶׁר בָּנוּ בְּנֵי הָאָדָם. בְּנֵי אָדָם הָרִאשׁוֹן שֶׁהֵבִיא וְהִשְׁלִיט צַד הָאַחֵר עַל הָעוֹלָם, הַצַּד הָרָע. כְּמוֹ שֶׁצַּד הַקְּדֻשָּׁה אֵין שִׁלְטוֹנוֹ בָּעוֹלָם הַזֶּה אֶלָּא בְּעִיר וּמִגְדָּל, גַּם כָּאן חָשְׁבוּ הֵם לִבְנוֹת עִיר וּמִגְדָּל לְהַשְׁלִיט אֶת הַצַּד הָרָע הַזֶּה בָּעוֹלָם.</p>\n<p>וַיֵּרֶד ה' לִרְאוֹת. נָחַת הַשֵּׁם הַקָּדוֹשׁ הַזֶּה לִרְאוֹת (על) אֶת מַעֲשֵׂיהֶם שֶׁל הַבִּנְיָן שֶׁבָּנוּ, וְהֵם הָיוּ מְדַבְּרִים בִּלְשׁוֹן הַקֹּדֶשׁ לְכָל אוֹתָם דְּרָגוֹת קְדוֹשׁוֹת וְהָיוּ מַצְלִיחִים. כֵּיוָן שֶׁיָּרְדָה הַקְּדֻשָּׁה, הִתְבַּלְבְּלוּ כָּל הַדְּרָגוֹת הַלָּלוּ. עֶלְיוֹנִים יָרְדוּ וְתַחְתּוֹנִים עָלוּ, וְלֹא הָיוּ עוֹמְדִים בְּדֶרֶךְ יָשָׁר כְּמוֹ שֶׁהָיוּ. וְאַחַר כָּךְ בִּלְבֵּל לְשׁוֹנָם בְּשִׁבְעִים לָשׁוֹן וְהִתְפַּזְּרוּ לְכָל צִדְדֵי הָעוֹלָם.</p>\n<p>מְמֻנֶּה אֶחָד יֵשׁ בָּרָקִיעַ, וּבוֹ קַיָּמִים כָּל (ד\"א אותם) מַפְתְּחוֹת שֶׁל מַעֲשֵׂי הָעוֹלָם, וְהוּא קַיָּם וְזָמִין בְּכָל הַשָּׁעוֹת וְרִגְעֵי הַיּוֹם. וְהֵם הָיוּ יוֹדְעִים בְּסוֹד הַחָכְמָה, הַגְּנוּזָה שֶׁל הַמְמֻנֶּה הַזֶּה, וְהָיוּ פוֹתְחִים וְסוֹגְרִים וּמַצְלִיחִים בְּמַעֲשֵׂיהֶם בְּמַאֲמַר פִּיהֶם. כֵּיוָן (שהסתכלו) שֶׁהִתְבַּלְבֵּל הַמַּאֲמָר שֶׁלָּהֶם, הַכֹּל נִמְנַע מֵהֶם,</p>\n<p>וּמָקוֹם מְתֻקָּן מָצְאוּ בְּאוֹתָהּ בִּקְעָה. צַד הַצְּדָדִים. וַיִּמְצְאוּ בִקְעָה, מָקוֹם מְתֻקָּן לְזֶה (אותו) הַצַּד הָרָע, שֶׁרָצוּ הֵם לְחַזֵּק וְנִמְנְעוּ. תֹּקֶף (שלו) שֶׁל אוֹתוֹ הַצַּד הָיָה תָלוּי לְהִפָּרַע בְּאוֹתָהּ בִּקְעָה, עַד שֶׁנָּטְלָה מִשָּׁם צְבָאוֹת וּמַחֲנוֹת, כְּמוֹ שֶׁהֵם בָּנוּ עִיר וּמִגְדָּל וְנִתְּנוּ (הכל) כֻלָּם בְּיָדֶיהָ. וְנֶהֶרְגוּ שָׁם</p>\n<p>אוֹתָם שֶׁלֹּא רָצוּ לָצֵאת בְּקֵ\"ץ הַיָּמִי\"ן. נִבְהֲלוּ וְנָפְלוּ בְּקֵ\"ץ הַיָּמִי\"ם, בְּאוֹתוֹ מָקוֹם שֶׁנֶּחֱלַשׁ הַכֹּחַ בַּתְּחִלָּה בַּבִּקְעָה הַזּוֹ. וְעַל זֶה כָּתוּב (יחזקאל לו) וְהִיא מְלֵאָה עֲצָמוֹת. וְהִתְחַזְּקָה בְּאוֹתוֹ הַצֶּלֶם שֶׁהֵקִים נְבוּכַדְנֶצַּר.</p>\n<p>וְנִשְׁבַּר הַתֹּקֶף אַחַר כָּךְ בְּאוֹתָם עֲצָמוֹת וּבְאוֹתוֹ צֶלֶם. שֶׁאוֹתָם רִאשׁוֹנִים הִתְקַיְּמוּ וְקָמוּ עַל רַגְלֵיהֶם, וְאוֹתוֹ צֶלֶם נִשְׁבַּר,</p>\n<p>וְאָז יָדְעוּ כָּל עַמֵּי הָעוֹלָם שֶׁאֵין אֱלוֹהַּ מִבַּלְעֲדֵי הַקָּדוֹשׁ בָּרוּךְ הוּא בִּלְבַדּוֹ. וְעוֹד, שֶׁהִתְקַדֵּשׁ שְׁמוֹ עַל יְדֵי חֲנַנְיָה מִישָׁאֵל וַעֲזַרְיָה, וְהַכֹּל בְּיוֹם אֶחָד. וְעַל זֶה כָּתוּב (ישעיה כט) וְהִקְדִּישׁוּ אֶת קְדוֹשׁ יַעֲקֹב וְגוֹ'. ע\"כ סתרי תורה.</p>\n<p>וַיֵּרֶד ה' לִרְאוֹת אֶת הָעִיר וְאֶת הַמִּגְדָּל. זוֹ אַחַת מֵעֶשֶׂר פְּעָמִים שֶׁיָּרְדָה הַשְּׁכִינָה לָאָרֶץ. וְכִי מַה הוּא לִרְאוֹת, וְלֹא הָיָה יוֹדֵעַ מִקֹּדֶם לָזֶה? אֶלָּא לִרְאוֹת לְהַשְׁגִּיחַ בַּדִּין, כְּמוֹ שֶׁנֶּאֱמַר (שמות ה) יֵרֶא ה' עֲלֵיכֶם וְיִשְׁפֹּט.</p>\n<p>אֶת הָעִיר וְאֶת הַמִּגְדָּל - כָּאן יֵשׁ לְהִסְתַּכֵּל, שֶׁהֲרֵי לֹא כָתוּב לִרְאוֹת אֶת בְּנֵי הָאָדָם, אֶלָּא לִרְאוֹת אֶת הָעִיר וְאֶת הַמִּגְדָּל. לָמָּה? אֶלָּא בְּשָׁעָה שֶׁמַּשְׁגִּיחַ הַקָּדוֹשׁ בָּרוּךְ הוּא בְּדִין, בַּהַתְחָלָה מַשְׁגִּיחַ בַּדַּרְגָּה שֶׁלְּמַעְלָה, וְאַחַר כָּךְ בַּדַּרְגָּה שֶׁלְּמַטָּה. בַּהַתְחָלָה בָּעֶלְיוֹנִים, וְאַחַר כָּךְ בַּתַּחְתּוֹנִים. וּמִשּׁוּם שֶׁדָּבָר זֶה מַגִּיעַ לְמַעְלָה, הַהַשְׁגָּחָה שֶׁל מַעְלָה הָיְתָה בּוֹ בַּהַתְחָלָה, שֶׁכָּתוּב לִרְאוֹת אֶת הָעִיר וְאֶת הַמִּגְדָּל.</p>\n<p>אֲשֶׁר בָּנוּ בְּנֵי הָאָדָם. מַה זֶּה בְּנֵי הָאָדָם? בְּנֵי אָדָם הָרִאשׁוֹן שֶׁמָּרַד בְּרִבּוֹנוֹ וְגָרַם מָוֶת לָעוֹלָם. אֲשֶׁר בָּנוּ בְּנֵי הָאָדָם - בִּנְיָן וַדַּאי אָמְרוּ (גרמו) וְרָצוּ לִבְנוֹת לְמַעְלָה.</p>"],[9522011179,"<p>רַבִּי שִׁמְעוֹן פָּתַח (ואמר), (יחזקאל מו) כֹּה אָמַר ה' אֱלֹהִים שַׁעַר הֶחָצֵר הַפְּנִימִית הַפֹּנֶה קָדִים יִהְיֶה סָגוּר שֵׁשֶׁת יְמֵי הַמַּעֲשֶׂה וּבְיוֹם הַשַּׁבָּת יִפָּתֵחַ וּבְיוֹם הַחֹדֶשׁ יִפָּתֵחַ. בְּפָסוּק זֶה יֵשׁ לְהִסְתַּכֵּל בּוֹ, וְהוּא סוֹד כְּמוֹ שֶׁנֶּאֱמַר. יִהְיֶה סָגוּר שֵׁשֶׁת יְמֵי הַמַּעֲשֶׂה, לָמָּה? (וביום השבת יפתח וביום החדש יפתח וגו', למה יהיה סגור כל אותם ימים של ששת ימי המעשה?)</p>\n<p>אֶלָּא אֵלּוּ יְמֵי הַחֹל שֶׁשַּׁעַר זֶה יִהְיֶה סָגוּר שֶׁלֹּא לְהִשְׁתַּמֵּשׁ הַחֹל עִם הַקֹּדֶשׁ. וּבְיוֹם הַשַּׁבָּת יִפָּתֵחַ וּבְיוֹם הַחֹדֶשׁ יִפָּתֵחַ, שֶׁהֲרֵי אָז שִׁמּוּשׁ (של הקדוש ברוך הוא) שֶׁל קֹדֶשׁ בְּקֹדֶשׁ, וְאָז מְאִירָה הַלְּבָנָה לְהִתְחַבֵּר עִם הַשֶּׁמֶשׁ.</p>\n<p>בֹּא רְאֵה, שַׁעַר זֶה לֹא נִפְתָּח בְּאוֹתָם שֵׁשֶׁת יְמֵי הַחֹל, מִשּׁוּם שֶׁהֲרֵי בְּאוֹתָם יְמֵי הַחֹל הָעוֹלָם הַתַּחְתּוֹן נִזּוֹן, וְשׁוֹלְטִים כָּל אוֹתָם שֵׁשֶׁת יְמֵי הַחֹל עַל הָעוֹלָם חוּץ מֵאֲשֶׁר בְּאֶרֶץ יִשְׂרָאֵל.</p>\n<p>וְאוֹתָם שֶׁשּׁוֹלְטִים, לֹא שׁוֹלְטִים בָּאָרֶץ הַקְּדוֹשָׁה, מִשּׁוּם שֶׁהַשַּׁעַר הַזֶּה סָגוּר. אֲבָל בְּיוֹם הַשַּׁבָּת וּבְיוֹם הַחֹדֶשׁ, כֻּלָּם עוֹבְרִים וְלֹא שׁוֹלְטִים, מִשּׁוּם שֶׁהַשַּׁעַר הַזֶּה הוּא פָתוּחַ, וְהָעוֹלָם הוּא בְּחֶדְוָה וְנִזּוֹן מִשָּׁם, וְלֹא נִתָּן הָעוֹלָם לְרָשׁוּת אַחֶרֶת.</p>\n<p>וְאִם תֹּאמַר שֶׁכָּל אוֹתָם שִׁשָּׁה יָמִים הֵם שׁוֹלְטִים לְבַדָּם - בֹּא תִרְאֶה, הַפּוֹנֶה קָדִים, עַד שֶׁלֹּא יָקוּמוּ לִשְׁלֹט, הוּא מִסְתַּכֵּל תָּמִיד בָּעוֹלָם. אֲבָל לֹא נִפְתָּח לָזוּן הָעוֹלָם מִן הַקֹּדֶשׁ פְּרָט לְיוֹם הַשַּׁבָּת וְיוֹם הַחֹדֶשׁ. וְכָל הַיָּמִים כֻּלָּם נִדְבָּקִים בְּיוֹם הַשַּׁבָּת וְנִזּוֹנִים מִשָּׁם. שֶׁהֲרֵי (אז) בְּיוֹם הַשַּׁבָּת כָּל הַשְּׁעָרִים פְּתוּחִים, וּמְנוּחָה נִמְצֵאת לַכֹּל - לָעֶלְיוֹנִים וְלַתַּחְתּוֹנִים. בּא רְאֵה, וַיֵּרֶד ה' לִרְאוֹת, יָרַד מִקֹּדֶשׁ לְחֹל (וצעיף פרוש) לְהַשְׁגִּיחַ בְּמַה שֶּׁבָּנוּ וְקִיְּמוּ קִיּוּם לְעוֹרֵר עַל הָעוֹלָם לְיִרְאָה אוֹתָם.</p>\n<p>רַבִּי יִצְחָק הָיָה יוֹשֵׁב לִפְנֵי רַבִּי שִׁמְעוֹן. אָמַר לוֹ, מָה רָאוּ אֵלֶּה שֶׁעָשׂוּ שְׁטוּת זוֹ לִמְרֹד בַּקָּדוֹשׁ- בָּרוּךְ-הוּא וְכֻלָּם בְּעֵצָה אַחַת הִתְקַיְּמוּ בָזֶה? אָמַר לוֹ, הֲרֵי נִתְבָּאֵר, שֶׁכָּתוּב וַיְהִי בְּנָסְעָם מִקֶּדֶם. הֻסְּעוּ מִלְמַעְלָה לְמַטָּה. נָסְעוּ מֵאֶרֶץ יִשְׂרָאֵל וְיָרְדוּ לְבָּבֶל. אָמִרוּ, הֲרֵי כָּאן מָקוֹם לְהִדָּבֵק.</p>\n<p>וְנַעָֹשֶׂה לָּנוּ שֵׁם וְגוֹ', וְיִתְדַּבֵּק הַסִּיּוּעַ שֶׁלְּמַטָּה בַּמָּקוֹם הַזֶּה. מִשּׁוּם שֶׁכְּשֶׁהַדִּין בָּא לִשְׁרוֹת בָּעוֹלָם, הֲרֵי מָקוֹם זֶה כְּנֶגְדּוֹ, וּמִכָּאן יֵהָנֶה הָעוֹלָם וְיִזּוֹן. שֶׁהֲרֵי לְמַעְלָה יֵשׁ דּחַק לְהָזִין אֶת הָעוֹלָם מִמֶּנּוּ. וְלֹא עוֹד, אֶלָּא אָנוּ נַעֲלֶה לָרָקִיעַ וְנַעֲרֹךְ בּוֹ קְרָב שֶׁלֹּא יֵרֵד (בו) מַבּוּל בָּעוֹלָם כְּמִקֹּדֶם.</p>"],[9522011180,"<p>וַיֹּאמֶר ה' הֵן עַם אֶחָד וְשָׂפָה אַחַת לְכֻלָּם. מִשּׁוּם שֶׁכֻּלָּם כְּאֶחָד, בְּיִחוּד, שֶׁכֻּלָּם יַעֲשׂוּ וְיַצְלִיחוּ בְּמַעֲשֵׂיהֶם, יִתְפַּזְּרוּ הַדְּרָגוֹת כָּל אֶחָד לַצַּד שֶׁלּוֹ, וּבִגְלַל זֶה יִתְפַּזְּרוּ כָּל אֵלֶּה שֶׁלְּמַטָּה. מַה כָּתוּב? וַיָּפֶץ ה' אֹתָם מִשָּׁם.</p>\n<p>וְאִם תֹּאמַר, לָמָּה הִתְבַּלְבְּלָה לְשׁוֹנָם (פזר ובלבל אותם הקדוש ברוך הוא)? אֶלָּא מִשּׁוּם שֶׁכֻּלָּם מְדַבְּרִים בִּלְשׁוֹן הַקֹּדֶשׁ, אוֹתָהּ לָשׁוֹן עָשְׂתָה לָהֶם סִיּוּעַ. מִשּׁוּם שֶׁבְּמַעֲשֶׂה וּבְדִבּוּר הַפֶּה דְּבָרִים הַלָּלוּ תְּלוּיִים לְהַשִּׂיג כַּוָּנַת הַלֵּב, וּבָזֶה עוֹשִׂים סִיּוּעַ לְאוֹתוֹ מָקוֹם שֶׁרָצוּ לְהָקִים.</p>\n<p>וְעַל זֶה הִתְבַּלְבְּלָה לְשׁוֹנָם שֶׁלֹּא יָכְלוּ לְחַזֵּק רְצוֹנָם בִּלְשׁוֹן הַקֹּדֶשׁ. כֵּיוָן שֶׁהִתְחַלְּפָה לְשׁוֹנָם, לֹא הִצְלִיחוּ בַּמַּעֲשֶׂה, מִשּׁוּם שֶׁהַצָּבָא שֶׁל מַעְלָה לֹא יוֹדְעִים וְלֹא מַכִּירִים - רַק אֶת לְשׁוֹן הַקֹּדֶשׁ. וּכְשֶׁהִתְבַּלְבְּלָה לְשׁוֹנָם, נֶחֱלַשׁ כֹּחָם וְנִשְׁבַּר תָּקְפָּם.</p>\n<p>בֹּא רְאֵה, שֶׁהֲרֵי דִּבּוּר (זה) שֶׁאוֹמְרִים הַתַּחְתּוֹנִים בִּלְשׁוֹן הַקֹּדֶשׁ, כָּל צִבְאוֹת הַשָּׁמַיִם יוֹדְעִים בּוֹ וּמַחֲזִיקִים בּוֹ, וְלָשׁוֹן אַחֶרֶת אֵינָם יוֹדְעִים וְלֹא מַכִּירִים בָּהּ. וְעַל זֶה, כֵּיוָן שֶׁהִתְבַּלְבְּלָה לְשׁוֹנָם שֶׁל אֵלֶּה, מִיָּד - וַיַּחְדְּלוּ לִבְנֹת הָעִיר, שֶׁהֲרֵי נִשְׁבַּר כֹּחָם וְלֹא יָכְלוּ לַעֲשׂוֹת דָּבָר בָּרָצוֹן שֶׁלָּהֶם.</p>\n<p>(דניאל ב) שֶׁיִּהְיֶה שְׁמוֹ (שם האלוה) (של הקב\"ה) מְבֹרָךְ מֵהָעוֹלָם וְעַד הָעוֹלָם, שֶׁהַחָכְמָה וְהַגְּבוּרָה שֶׁלּוֹ הִיא. שֶׁהֲרֵי מִשּׁוּם (זה) שֶׁהוֹרִיד הַקָּדוֹשׁ בָּרוּךְ הוּא סוֹדוֹת הַחָכְמָה לָעוֹלָם, הִתְקַלְקְלוּ בָהּ בְּנֵי אָדָם וְרָצוּ לְהִתְגָּרוֹת בּוֹ.</p>\n<p>נָתַן חָכְמָה עֶלְיוֹנָה לְאָדָם הָרִאשׁוֹן. וּבְאוֹתָהּ חָכְמָה שֶׁהִתְגַּלְּתָה לוֹ, יָדַע דְּרָגוֹת וְנִדְבַּק בַּיֵּצֶר הָרָע, עַד שֶׁהִסְתַּלְּקוּ מִמֶּנּוּ מַעְיְנוֹת הַחָכְמָה, וְאַחַר כָּךְ שָׁב לִפְנֵי רִבּוֹנוֹ וְהִתְגַּלּוּ לוֹ מֵהֶם, וְלֹא כְּמוֹ מִקֹּדֶם. אַחַר כָּךְ בְּאוֹתוֹ הַסֵּפֶר שֶׁלּוֹ יָדַע חָכְמוֹת. אַחַר כָּךְ בָּאוּ בְּנֵי אָדָם וְהִרְגִּיזוּ לְפָנָיו.</p>\n<p>נָתַן חָכְמָה לְנֹחַ וְעָבַד בָּהּ אֶת הַקָּדוֹשׁ בָּרוּךְ הוּא, וְאַחַר כָּךְ מַה כָּתוּב? וַיֵּשְׁתְּ מִן הַיַּיִן וַיִּשְׁכָּר וַיִּתְגַּל, כְּמוֹ שֶׁנִּתְבָּאֵר. נָתַן חָכְמָה לְאַבְרָהָם וְעָבַד בָּהּ אֶת הַקָּדוֹשׁ בָּרוּךְ הוּא, אַחַר כָּךְ יָצָא מִמֶּנּוּ יִשְׁמָעֵאל שֶׁהִרְגִּיז לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא. וְכֵן יִצְחָק יָצָא מִמֶּנּוּ עֵשָׂו. יַעֲקֹב לָקַח שְׁתֵּי אֲחָיוֹת.</p>\n<p>נָתַן חָכְמָה לְמֹשֶׁה, מַה כָּתוּב בּוֹ? (במדבר יב) בְּכָל בֵּיתִי נֶאֱמָן הוּא. וְלֹא הָיָה כְּמֹשֶׁה שַׁמָּשׁ נֶאֱמָן בְּכָל הַדְּרָגוֹת, וְלֹא סָטָה לִבּוֹ בִּתְשׁוּקַת אֶחָד מֵהֶם, אֶלָּא עָמַד בֶּאֱמוּנָה עֶלְיוֹנָה כָּרָאוּי.</p>\n<p>נָתַן חָכְמָה עֶלְיוֹנָה לִשְׁלֹמֹה הַמֶּלֶךְ, אַחַר כָּךְ מַה כָּתוּב בּוֹ? (משלי א) מִשְׁלֵי שְׁלֹמֹה, (שם ל) הַמַּשָּׂא נְאֻם הַגֶּבֶר לְאִיתִיאֵל לְאִיתִיאֵל וְאֻכָל. אָמַר שְׁלֹמֹה, אִתִּי אֵל, וְהַחָכְמָה שֶׁלּוֹ הִיא. וְאֻכָל - וַאֲנִי יָכוֹל לַעֲשׂוֹת רְצוֹנִי. אַחַר כָּךְ (מלכים א יח) וַיָּקֶם ה' שָׂטָן לִשְׁלֹמֹה וְגוֹ'.</p>\n<p>בֹּא רְאֵה, מִשּׁוּם קְצָת חָכְמָה שֶׁמָּצְאוּ אֵלֶּה מֵאוֹתָהּ חָכְמַת הָרִאשׁוֹנִים, הִתְגָּרוּ בַּקָּדוֹשׁ- בָּרוּךְ-הוּא, וּבָנוּ מִגְדָּל וְעָשׂוּ כָּל מַה שֶּׁעָשׂוּ, עַד שֶׁהִתְפַּזְּרוּ מֵעַל פְּנֵי הָאָרֶץ, וְלֹא נִשְׁאֲרָה בָהֶם חָכְמָה לַעֲשׂוֹת דָּבָר.</p>\n<p>אֲבָל לֶעָתִיד לָבא הַקָּדוֹשׁ בָּרוּךְ הוּא יְעוֹרֵר חָכְמָה בָּעוֹלָם וְיַעַבְדוּ אוֹתוֹ בָּהּ. זֶהוּ שֶׁכָּתוּב (יחזקאל לו) וְאֶת רוּחִי אֶתֵּן בְּקִרְבְּכֶם וְעָשִׂיתִי. לֹא כָּרִאשׁוֹנִים שֶׁהִשְׁחִיתוּ בָהּ אֶת הָעוֹלָם, אֶלָּא - וְעָשִׂיתִי אֵת אֲשֶׁר בְּחֻקַּי תֵּלֵכוּ וּמִשְׁפָּטַי תִּשְׁמְרוּ וַעֲשִׂיתֶם.</p>\n<p>רַבִּי יוֹסֵי וְרַבִּי חִיָּיא הָיוּ הוֹלְכִים בַּדֶּרֶךְ. אָמַר לוֹ רַבִּי יוֹסֵי לְרַבִּי חִיָּיא, נִפְתַּח בַּתּוֹרָה וְנֹאמַר דָּבָר. פָּתַח רַבִּי יוֹסֵי וְאָמַר, (דברים כג) כִּי ה' אֱלֹהֶיךְ מִתְהַלֵּךְ בְּקֶרֶב מַחֲנֶךְ לְהַצִּילְךְ וְלָתֵת אֹיְבֶיךְ לְפָנֶיךְ וְהָיָה מַחֲנֶיךְ קָדוֹשׁ וְלֹא יִרְאֶה בְךְ עֶרְוַת דָּבָר וְשָׁב מֵאַחֲרֶיךְ. כִּי ה' אֱלֹהֶיךְ מִתְהַלֵּךְ? מְהַלֵּךְ הָיָה צָרִיךְ לִהְיוֹת! אֶלָּא כְּמוֹ שֶׁנֶּאֱמַר (בראשית ג) מִתְהַלֵּךְ בַּגָּן לְרוּחַ הַיּוֹם. וְזֶהוּ אִילָן שֶׁאָכַל מִמֶּנּוּ אָדָם הָרִאשׁוֹן. מִתְהַלֵּךְ - נְקֵבָה. מְהַלֵּךְ - זָכָר.</p>\n<p>וְזְהִוּ שֶׁהָלַךְ לִפְנֵי יִשְׂרָאֵל כְּשֶׁהָיוּ הוֹלְכִים בַּמִּדְבָּר, שֶׁכָּתוּב (שמות יג) וַה' הֹלֵךְ לִפְנֵיהֶם יוֹמָם וְגוֹ'. וְהוּא שֶׁהוֹלֵךְ לִפְנֵי הָאָדָם כְּשֶׁהוֹלֵךְ בַּדֶּרֶךְ, שֶׁכָּתוּב (תהלים פה) צֶדֶק לְפָנָיו יְהַלֵּךְ וְיָשֵׂם לְדֶרֶךְ פְּעָמָיו. וְזֶהוּ שֶׁהוֹלֵךְ לִפְנֵי הָאָדָם בְּשָׁעָה שֶׁהוּא זוֹכֶה. וְלָמָּה? לְהַצִּילְךְ וְלָתֵת אֹיְבֶיךְ לְפָנֶיךְ, לְהַצִּיל אָדָם בַּדֶּרֶךְ וְלֹא יִשְׁלֹט בּוֹ אַחֵר.</p>\n<p>וְלָכֵן צָרִיךְ אָדָם לְהִשָּׁמֵר מֵחֲטָאָיו וּלְטַהֵר אֶת עַצְמוֹ. מַה טָּהֳרָה זוֹ? שֶׁכָּתוּב (דברים כג) וְהָיָה מַחֲנֶיךְ קָדוֹשׁ. מַה זֶּה קָדוֹשׁ? קְדוֹשִׁים הָיָה צָרִיךְ לִהְיוֹת! אֶלָּא מַחֲנֶיךְ קָדוֹשׁ - אֵלּוּ אֵיבְרֵי הַגּוּף שֶׁהַגּוּף מִתְחַבֵּר וְנִתְקָן בָּהֶם. וְלָכֵן וְהָיָה מַחֲנֶיךְ קָדוֹשׁ. וְלֹא יִרְאֶה בְךְ עֶרְוַת דָּבָר.</p>\n<p>מַה זֶּה עֶרְוַת דָּבָר? זֶה דְּבַר (ערוה) עֲרָיוֹת, שֶׁזֶּה הוּא דָבָר שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא מוֹאֵס בּוֹ יוֹתֵר מֵהַכֹּל. כֵּיוָן שֶׁאָמַר וְלֹא יִרְאֶה בְךְ עֶרְוַת, לָמָּה דָּבָר? אֶלָּא רִשְׁעֵי הָעוֹלָם הַלָּלוּ שֶׁגּוֹעֲלִים וּמְטַמְּאִים אֶת עַצְמָם בְּדִבּוּרָם שֶׁיּוֹצֵא מִפִּיהֶם, וְזֶהוּ עֶרְוַת דָּבָר.</p>\n<p>וְכָל כָּךְ לָמָּה? מִשּׁוּם שֶׁהוּא הוֹלֵךְ לְפָנֶיךְ. וְאִם אַתָּה עוֹשֶׂה כָּךְ, מִיָּד - וְשָׁב מֵאַחֲרֶיךְ. שֶׁלֹּא יֵלֵךְ עִמְּךְ וְיָשׁוּב מֵאַחֲרֶיךְ. וְאָנוּ הֲרֵינוּ הוֹלְכִים לְפָנָיו בַּדֶּרֶךְ, נִתְעַסֵּק בְּדִבְרֵי תוֹרָה, שֶׁהֲרֵי הַתּוֹרָה מִתְעַטֶּרֶת עַל רֹאשׁוֹ שֶׁל אָדָם וְהַשְּׁכִינָה לֹא זָזָה מִמֶּנּוּ.</p>\n<p>פָּתַח רַבִּי חִיָּיא וְאָמַר, וַיֹּאמֶר ה' הֵן עַם אֶחָד וְשָׂפָה אַחַת לְכֻלָּם וְגוֹ' בֹּא רְאֵה מַה כָּתוּב, וַיְהִי בְּנָסְעָם מִקֶּדֶם. מַה זֶּה מִקֶּדֶם? מִקַּדְמוֹנוֹ שֶׁל עוֹלָם. וַיִּמְצְאוּ? וַיִּרְאוּ צָרִיךְ הָיָה לִהְיוֹת! מַה זֶּה וַיִּמְצְאוּ? אֶלָּא מְצִיאָה מָצְאוּ שָׁם מִסּוֹדֵי הַחָכְמָה מֵהַקַּדְמוֹנִים שֶׁהִתְנַעֲרָה שָׁם מִבְּנֵי הַמַּבּוּל, וּבָהּ הִתְעַסְּקוּ לַעֲשׂוֹת בְּאוֹתוֹ מַעֲשֶׂה שֶׁעָשׂוּ לְסָרֵב לַקָּדוֹשׁ-בָּרוּךְ-הוּא, וְהָיוּ אוֹמְרִים בַּפֶּה וְעוֹשִׂים מַעֲשֶׂה.</p>\n<p>רְאֵה מַה כָּתוּב, הֵן עַם אֶחָד וְשָׂפָה אַחַת לְכֻלָּם. מִשּׁוּם שֶׁהֵם בְּלֵב אֶחָד וּבְרָצוֹן אֶחָד וּמְדַבְּרִים בִּלְשׁוֹן הַקֹּדֶשׁ. וְעַתָּה לֹא יִבָּצֵר מֵהֶם כֹּל אֲשֶׁר יָזְמוּ לַעֲשׂוֹת, וְאֵין מִי שֶׁיִּמְנַע מַעֲשֵׂיהֶם. אֲבָל מָה אֶעֱשֶׂה? אֲבַלְבֵּל לָהֶם הַדְּרָגוֹת שֶׁל מַעְלָה וּלְשׁוֹנָם שֶׁלְּמַטָּה, וְאָז נִמְנַע מַעֲשֶׂה שֶׁלָּהֶם.</p>\n<p>וּמַה מִשּׁוּם שֶׁהָיוּ בְּרָצוֹן וְלֵב אֶחָד וּמְדַבְּרִים בִּלְשׁוֹן הַקֹּדֶשׁ כָּתוּב לֹא יִבָּצֵר מֵהֶם כֹּל אֲשֶׁר יָזְמוּ לַעֲשׂוֹת, וְדִין שֶׁלְּמַעְלָה לֹא יָכֹל לִשְׁלֹט בָּהֶם - אָנוּ אוֹ הַחֲבֵרִים שֶׁמִּתְעַסְּקִים בַּתּוֹרָה, וְאָנוּ בְּלֵב אֶחָד וְרָצוֹן אֶחָד, עַל אַחַת כַּמָּה וְכַמָּה.</p>\n<p>אָמַר רַבִּי יוֹסֵי, מִכָּאן שֶׁלְּאוֹתָם בַּעֲלֵי הַמַּחֲלֹקֶת אֵין לָהֶם קִיּוּם. שֶׁהֲרֵי בְּכָל פַּעַם שֶׁהַלָּלוּ בְּנֵי הָעוֹלָם אֵלֶּה עִם אֵלֶּה בְּרָצוֹן אֶחָד וְלֵב אֶחָד - אַף עַל גַּב שֶׁמּוֹרְדִים בַּקָּדוֹשׁ-בָּרוּךְ-הוּא, לֹא שׁוֹלֵט בָּהֶם הַדִּין שֶׁלְּמַעְלָה. כֵּיוָן שֶׁנֶּחְלְקוּ, מִיָּד - וַיָּפֶץ אֹתָם ה' מִשָּׁם וְגוֹ'.</p>\n<p>אָמַר רַבִּי חִיָּיא, נִשְׁמָע שֶׁהַכֹּל בְּדִבּוּר הַפֶּה תָּלוּי, שֶׁהֲרֵי כֵּיוָן שֶׁהִתְבַּלְבְּלוּ, מִיָּד וַיָּפֶץ ה' אֹתָם מִשָּׁם. אֲבָל לֶעָתִיד לָבֹא מַה כָּתוּב? (צפניה ג) כִּי אָז אֶהְפֹּךְ אֶל עַמִּים שָׂפָה בְרוּרָה לִקְרֹא כֻלָּם בְּשֵׁם ה' לְעָבְדוֹ שְׁכֶם אֶחָד, וְכָתוּב (זכריה יד) וְהָיָה ה' לְמֶלֶךְ עַל כָּל הָאָרֶץ בַּיּוֹם הַהוּא יִהְיֶה ה' אֶחָד וּשְׁמוֹ אֶחָד. בָּרוּךְ ה' לְעוֹלָם אָמֵן וְאָמֵן:</p>"],[9522011181,"<p>רַבִּי אַבָּא פָּתַח וְאָמַר (ישעיה מו) שִׁמְעוּ אֵלַי אַבִּירֵי לֵב הָרְחוֹקִים מִצְּדָקָה. שִׁמְעוּ אֵלַי אַבִּירֵי לֵב - כַּמָּה חֲזָקִים לִבּוֹתֵיהֶם שֶׁל הָרְשָׁעִים, שֶׁרוֹאִים אֶת שְׁבִילֵי וְדַרְכֵי הַתּוֹרָה וְלֹא מִסְתַּכְּלִים בָּהֶם, וְלִבּוֹתֵיהֶם חֲזָקִים שֶׁאֵינָם חוֹזְרִם בִּתְשׁוּבָה לְרִבּוֹנָם, וְנִקְרָאִים אַבִּירֵי לֵב. הָרְחוֹקִים מִצְּדָקָה - שֶׁמִּתְרַחֲקִים מִן הַתּוֹרָה.</p>\n<p>רַבִּי חִזְקִיָּה אָמַר, שֶׁמִּתְרַחֲקִים מִן הַקָּדוֹשׁ בָּרוּךְ הוּא, וְהֵם רְחוֹקִים מִמֶּנּוּ, וּמִשּׁוּם כָּךְ נִקְרְאוּ אַבִּירֵי לֵב. הָרְחוֹקִים מִצְּדָקָה - שֶׁאֵינָם רוֹצִים לִקְרַב אֶל הַקָּדוֹשׁ בָּרוּךְ הוּא, מִשּׁוּם כָּךְ הֵם רְחוֹקִים מִצְּדָקָה. כֵּיוָן שֶׁהֵם רְחוֹקִים מִצְּדָקָה, רְחוֹקִים הֵם מִשָּׁלוֹם, שֶׁאֵין לָהֶם שָׁלוֹם, שֶׁכָּתוּב (ישעיה מח) אֵין שָׁלוֹם אָמַר ה' לָרְשָׁעִים. מָה הַטַּעַם? מִשּׁוּם שֶׁהֵם רְחוֹקִים מִצְּדָקָה.</p>\n<p>בֹּא רְאֵה, אַבְרָהָם רָצָה לִקְרַב אֶל הַקָּדוֹשׁ בָּרוּךְ הוּא וְהִתְקָרֵב. זֶהוּ שֶׁכָּתוּב (תהלים מה) אָהַבְתָּ צֶּדֶק וַתִּשְׂנָא רֶשַׁע. מִשּׁוּם שֶׁאָהַב צֶדֶק וְשָׂנָא רֶשַׁע, הִתְקָרֵב לִצְדָקָה, וְעַל זֶה כָּתוּב (ישעיה מא) אַבְרָהָם אֹהֲבִי. מָה הַטַּעַם אֹהֲבִי? מִשּׁוּם שֶׁכָּתוּב אָהַבְתָּ צֶּדֶק. הָאַהֲבָה שֶׁאָהַב אַבְרָהָם אֶת הַקָּדוֹשׁ בָּרוּךְ הוּא מִכָּל בְּנֵי דוֹרוֹ, שֶׁהָיוּ אַבִּירֵי לֵב, וְהֵם רְחוֹקִים מִצְּדָקָה, כְּמוֹ שֶׁנִּתְבָּאֵר.</p>"],[9522011182,"<p>רַבִּי יוֹסֵי פָּתַח, (תהלים פד) מַה יְּדִידוֹת מִשְׁכְּנוֹתֶיךְ ה' צְבָאוֹת. כַּמָּה יֵשׁ לִבְנֵי אָדָם לְהִסְתַּכֵּל בַּעֲבוֹדַת הַקָּדוֹשׁ בָּרוּךְ הוּא, שֶׁהֲרֵי כָּל בְּנֵי הָאָדָם לֹא יוֹדְעִים וְלֹא מִסְתַּכְּלִים עַל מָה עוֹמֵד הָעוֹלָם וְעַל מָה הֵם קַיָּמִים. שֶׁכַּאֲשֶׁר בָּרָא הַקָּדוֹשׁ בָּרוּךְ הוּא אֶת הָעוֹלָם, עָשָׂה שָׁמַיִם מֵאֵשׁ וּמִמַּיִם מְעֹרָבִים יַחַד, וְלֹא הָיוּ קוֹפְאִים, וְאַחַר כָּךְ קָפְאוּ וְעָמְדוּ בְּרוּחַ עֶלְיוֹנָה, מִשָּׁם שָׁתַל אֶת הָעוֹלָם לַעֲמֹד עַל עמּוּדִים, וְאוֹתָם הַתּוֹמְכִים לֹא עוֹמְדִים אֶלָּא בָּרוּחַ הַהִיא. וּבְשָׁעָה שְׁאוֹתָהּ הָרוּחַ עוֹלָה, כֻּלָּם מתְרוֹפְפִים וְזָעִים וְהָעוֹלָם רוֹתֵת. הוּ שֶׁכָּתוּב (איוב ט) הַמַּרְגִּיז אֶרֶץ ממְּקוֹמָהּ וְעַמּוּדֶיהָ יִתְפַּלָּצוּן. וְהַכֹּל עוֹמֵד עַל הַתּוֹרָה. שֶׁכַּאֲשֶׁר יִשְׂרָאֵל משְׁתַּדְּלִים בַּתּוֹרָה, מִתְקַיֵּם הָעוֹלָם, אוֹתָם הָעַמּוּדִים הַתּוֹמְכִים קַיָּמִים בִּמְקוֹמָם בְּקִיּוּם שָׁלֵם.</p>\n<p>בֹּא רְאֵה, בְּשָׁעָה שֶׁמִּתְעוֹרֵר חֲצוֹת הַלַּיְלָה וְהַקָּדוֹשׁ בָּרוּךְ הוּא נִכְנָס לְגַן העֵדֶן לְהִשְׁתַּעֲשֵׁעַ עִם הַצַּדִּיקִים, כָּל האִילָנוֹת שֶׁל גַּן הָעֵדֶן מְזַמְּרִים מְשַׁבְּחִים לְפָנָיו, שֶׁכָּתוּב (דברי הימים א טז) אָז יְרַנְּנוּ עֲצֵי הַיַּעַר מִלִּפְנֵי ה' וְגוֹ'.</p>\n<p>הַכָּרוֹז קוֹרֵא בְחַיִל וְאוֹמֵר: לָכֶם אוֹמְרִים קְדוֹשִׁים עֶלְיוֹנִים, מִי מִכֶּם שְׁנִּכְנְסָה רוּחַ לְאָזְנָיו לִשְׁמֹעַ, וְעֵינָיו פּקוּחוֹת לִרְאוֹת, וְלִבּוֹ פָּתוּחַ לָדַעַת, בּשָׁעָה שֶׁהָרוּחַ שֶׁל כָּל הָרוּחוֹת מרִימָה אֶת הִתְבַּשְּׂמוּת הַנְּשָׁמָה, מִשָּׁם יוֹצֵא הַקּוֹל שֶׁל הַקּוֹלוֹת, הַצְּבָאוֹת הִתְפַּזְּרוּ לְאַרְבָּעָה רוּחוֹת הָעוֹלָם.</p>\n<p>א, אֶחָד עוֹלֶה לְצַד אֶחָד. ב. אֶחָד וֹרֵד לְאוֹתוֹ הַצַּד. ג. אֶחָד נִכְנָס בֵּין שְׁנַיִם. ד. שְׁנַיִם מִתְעוֹרְרִים (מתעטרים) בּשְׁלֹשָׁה. ה. שְׁלֹשָׁה נִכְנָסִים בְּאֶחָד: אֶחָד מוֹצִיא גְוָנִים. ז. שִׁשָּׁה מֵהֶם לצַד אֶחָד, וְשִׁשָּׁה מֵהֶם יוֹרְדִים לאוֹתוֹ הַצַּד. ח. שִׁשָּׁה נִכְנָסִים בּשְׁנֵים עָשָׂר. ט. שְׁנֵים עָשָׂר מתְעוֹרְרִים בְּעֶשְׂרִים וּשְׁנַיִם. י. שִׁשָּׁה כּלוּלִים בַּעֲשָׂרָה. יא. עֲשָׂרָה עוֹמְדִים בְּאֶחָד.</p>\n<p>אוֹי לְאוֹתָם שֶׁיְּשֵׁנִים וְשֵׁנָה בִּנְחִירֵיהֶם, לֹא יוֹדְעִים וְלֹא מִסְתַּכְּלִים אֵיךְ יָקוּמוּ בַּדִּין כְּשֶׁהַחֶשְׁבּוֹן נִמְנֶה, כְּשֶׁנִּטְמָא הַגּוּף, וְהַנְּשָׁמָה מְשׁוֹטֶטֶת עַל פְּנֵי הָאֲוִיר שֶׁמֵּאִיר וְעוֹלָה וְיוֹרֶדֶת, וְהַשְּׁעָרִים לֹא נִפְתָּחִים, וּמִתְגַּלְגְּלִים כַּאֲבָנִים בְּתוֹךְ הַקֶּלַע. אוֹי לָהֶם! מִי יְבַקֵּשׁ אוֹתָם שֶׁלֹּא יָקוּמוּ בַתַּעֲנוּג הַזֶּה? בְּתוֹךְ הַמְּקוֹמוֹת שֶׁל עִנּוּגֵי הַצַּדִּיקִים וְנִפְקָד מְקוֹמָם. וְנִמְסָרִים בִּידֵי דוּמָה, יוֹרְדִים וְלֹא עוֹלִים. עֲלֵיהֶם כָּתוּב (איוב ז) כָּלָה עָנָן וַיֵּלַךְ כֵּן יוֹרֵד שְׁאוֹל לֹא יַעֲלֶה.</p>\n<p>בְּאוֹתָהּ הַשָּׁעָה מִתְעוֹרֶרֶת שַׁלְהֶבֶת אַחַת מִצַּד הַצָּפוֹן, וּמַכָּה בְּאַרְבָּעָה רוּחוֹת הָעוֹלָם, וְיוֹרֶדֶת וּמַגִּיעָה לְבֵין כַּנְפֵי הַתַּרְנְגוֹל, וּמִתְעוֹרֶרֶת בּוֹ אוֹתָהּ הַשַּׁלְהֶבֶת וְקוֹרֵא. וְאֵין מִי שֶׁמִּתְעוֹרֵר, פְּרָט לְאוֹתָם צַדִּיקֵי הָאֱמֶת שֶׁעוֹמְדִים וּמִתְעוֹרְרִים בַּתּוֹרָה. וְאָז הַקָּדוֹשׁ בָּרוּךְ הוּא וְכָל אוֹתָם הַצַּדִּיקִים שֶׁבְּתוֹךְ גַּן הָעֵדֶן מַקְשִׁיבִים לְקוֹלָם, כְּמוֹ שֶׁנֶּאֱמַר (שיר ח) הַיּוֹשֶׁבֶת בַּגַּנִּים חֲבֵרִים מַקְשִׁיבִים לְקוֹלֵךְ הַשְׁמִיעִנִי.</p>"],[9522011183,"<p>לָמַדְנוּ בְּתֹקֶף רְצוֹן הַמֶּלֶךְ נָטַע אִילָן אֶחָד גָּדוֹל וְחָזָק בְּתוֹךְ הַנְּטִיעוֹת הָעֶלְיוֹנוֹת, הַנְּטִיעָה שֶׁל הָאִילָן הַזֶּה בִּתְרֵיסַר תְּחוּמִים מְסֻבֶּבֶת. בְּאַרְבָּעָה צְדָדִים שֶׁל הָעוֹלָם פְּרוּשָׂה רַגְלוֹ.</p>\n<p>ת\"ק פַּרְסָאוֹת מַסְעוֹתָיו. כָּל הָרְצוֹנוֹת שֶׁל אוֹתָם פַּרְסוֹת בּוֹ תְּלוּיִים. כְּשֶׁזֶּה מִתְעוֹרֵר, כֻּלָּם מִתְעוֹרְרִים עִמּוֹ. אֵין מִי שֶׁיּוֹצֵא מֵרְצוֹנוֹ. אַחַר כָּךְ כֻּלָּם בְּרָצוֹן אֶחָד עִמּוֹ.</p>\n<p>קָם מִלְמַעְלָה, (יורד) יוֹרֵד בְּמַסְעוֹתָיו לְתוֹךְ הַיָּם. מִמֶּנּוּ הַיָּם (מתגלה) מִתְמַלֵּא. הוּא הַמָּקוֹר (של כל) הַמַּיִם הַנּוֹבְעִים, תַּחְתָּיו נֶחֱלָקִים כָּל מֵימֵי בְרֵאשִׁית. הַשְׁקָאוֹת הַגָּן תְּלוּיִים בּוֹ.</p>\n<p>כָּל הַנְּשָׁמוֹת שֶׁל הָעוֹלָמִים פּוֹרְחוֹת מִמֶּנּוּ. הַנְּשָׁמוֹת הַלָּלוּ נִכְנָסוֹת לַגָּן לָרֶדֶת לָעוֹלָם הַזֶּה. כְּשֶׁיּוֹצֵאת נְשָׁמָה, הִיא מִתְבָּרֶכֶת בְּשֶׁבַע בְּרָכוֹת לִהְיוֹת אָב (לרוח ורם) לַגּוּף (ולהיות) בַּעֲלִיָּה (של הדמות העליונה, זהו שכתוב ויאמר ה' אל אברם, הרי נשמה עליונה אבא (לרוח ורם) לגוף בעליה) שֶׁל דְּמוּת עֶלְיוֹנָה.</p>\n<p>כְּשֶׁרוֹצָה (הנפש) לָרֶדֶת לָעוֹלָם הַזֶּה, מַשְׁבִּיעַ אוֹתָהּ הַקָּדוֹשׁ בָּרוּךְ הוּא לִשְׁמֹר אֶת מִצְווֹת הַתּוֹרָה וְלַעֲשׂוֹת רְצוֹנוֹ, וּמוֹסֵר לָהּ מֵאָה מַפְתְּחוֹת שֶׁל בְּרָכוֹת שֶׁל כָּל יוֹם לְהַשְׁלִים אֶת הַדְּרָגוֹת הָעֶלְיוֹנוֹת כְּחֶשְׁבּוֹן לֶ\"ךְ לְ\"ךְ. שֶׁהֲרֵי כֻּלָּם נִמְסְרוּ לָהּ כְּדֵי לְתַקֵּן בָּהֶם אֶת הַגָּן וּלְעָבְדָהּ וּלְשָׁמְרָהּ. מֵאַרְצְךְ - זֶה גַּן הָעֵדֶן.</p>\n<p>(ומולדתך זה הגוף, שנקרא עץ החיים, שהוא תריסר שבטים עליונים, ומבית אביך זו השכינה, אביך זה הקדוש ברוך הוא, שנאמר (משלי כח) גוזל אביו ואמו ואמר אין פשע וגו', ואין אביו אלא הקדוש ברוך הוא, ואין אמו אלא כנסת ישראל, אל הארץ אשר אראך זה הוא העולם הזה,) (ס\"א וממולדתך זה עץ החיים, ומבית אביך תריסר תחומים, שבטים עליונים, אל הארץ אשר אראך זהו העולם הזה). עד כָּאן סתרי תורָה.</p>"],[9522011184,"<p>וַיֹּאמֶר ה' אֶל אַבְרָם. מַה כָּתוּב לְמַעְלָה? (בראשית יא) וַיָּמָת הָרָן עַל פְּנֵי תֶּרַח אָבִיו וְגוֹ'. מָה אוֹמֵר כָּאן? אֶלָּא עַד אוֹתוֹ הַיּוֹם לֹא הָיָה אָדָם שֶׁמֵּת בְּחַיֵּי אָבִיו פְּרָט לָזֶה, וּכְשֶׁנִּזְרַק אַבְרָהָם לָאֵשׁ, נֶהֱרַג חָרָן, וּמִשּׁוּם זֶה יָצְאוּ מִשָּׁם. (מי הרג את הרן? אלא כיון שהשליכו את אברהם לאור כשדים, התגלה עליו הקדוש ברוך הוא והצילו, והיה הרן אחיו עומד שם.) אמרו הכשדים, בשביל זכותו של הרן נצול, מיד יצאה שלהבת של אש ושרפה את הרן, זהו שכתוב וימת הרן על פני תרח אביו, ויש שאומרים שאין שולטת אש בזרעו של תרח, אבל נשליך את הרן לאש, ואם לא יבער, נדע ודאי שאין שולטת האש בזרעו, מיד השליכו את הרן לאש ונשרף, והיה תרח אביו עומד שם, זהו שכתוב וימת הרן על פני תרח אביו. באותו היום ידעו כל אמה ולשון שלא הציל את אברהם אלא הקדוש ברוך הוא שהוא יחידו של עולם, והיו מביאים את בניהם למשכנו של אברהם, ואומרים לו', ראינו אותך שאתה בוטח בקדוש ברוך הוא שהוא רבון העולם, למד את בנינו מדרכך שאתה יודע, ועליהם אמר הכתוב (תהלים מז) נדיבי עמים נאספו עם אלהי אברהם,</p>\n<p>בֹּא רְאֵה מַה כָּתוּב, וַיִּקַּח תֶּרַח אֶת אַבְרָם בְּנוֹ וְאֶת לוֹט בֶּן הָרָן וְגוֹ', וַיֵּצְאוּ אִתָּם מֵאוּר כַּשְׂדִּים. וַיֵּצְאוּ אִתָּם? אִתּוֹ הָיָה צָרִיךְ לִהְיוֹת, שֶׁהֲרֵי כָּתוּב וַיִּקַּח תֶּרַח וְגוֹ'. מַה זֶּה וַיֵּצְאוּ אִתָּם? אֶלָּא תֶרַח וְלוֹט עִם אַבְרָהָם וְשָׂרָה יָצְאוּ, שֶׁהֵם הָיוּ הָעִקָּר לָצֵאת מִתּוֹךְ אוֹתָם הָרְשָׁעִים. שֶׁכֵּיוָן שֶׁרָאָה תֶרַח שֶׁאַבְרָהָם בְּנוֹ נִצַּל מִתּוֹךְ הָאֵשׁ, חָזַר לַעֲשׂוֹת אֶת רְצוֹנוֹ שֶׁל אַבְרָהָם, וּמִשּׁוּם כָּךְ וַיֵּצְאוּ אִתָּם תֶּרַח וְלוֹט.</p>\n<p>וּבְשָׁעָה שֶׁיָּצְאוּ מַה כָּתוּב? לָלֶכֶת אַרְצָה כְּנַעַן. שֶׁרְצוֹנָם הָיָה לָלֶכֶת לְשָׁם. מִכָּאן לָמַדְנוּ, כָּל מִי שֶׁמִּתְעוֹרֵר לְהִטַּהֵר, מְסַיְּעִים אוֹתוֹ. בֹּא רְאֵה שֶׁכָּךְ הוּא, שֶׁכֵּיוָן שֶׁכָּתוּב לָלֶכֶת אַרְצָה כְּנַעַן, מִיָּד - וַיֹּאמֶר ה' אֶל אַבְרָם לֶךְ לְךְ. וְעַד שֶׁהוּא הִתְעוֹרֵר בַּתְּחִלָּה, לֹא כָתוּב לֶךְ לְךְ.</p>\n<p>בֹּא רְאֵה, הַדָּבָר שֶׁלְּמַעְלָה לֹא מִתְעוֹרֵר עַד שֶׁמִּתְעוֹרֵר לְמַטָּה בָּרִאשׁוֹנָה עַל מַה שֶּׁיִּשְׁרֶה עָלָיו אוֹתוֹ שֶׁלְּמַעְלָה. וְסוֹד הַדָּבָר - הָאוֹר הַשָּׁחֹר אֵינוֹ נֶאֱחָז בָּאוֹר הַלָּבָן עַד שֶׁהִיא מִתְעוֹרֶרֶת בָּרִאשׁוֹנָה. כֵּיוָן שֶׁהִיא מִתְעוֹרֶרֶת בָּרִאשׁוֹנָה, מִיָּד שׁוֹרֶה עָלֶיהָ הָאוֹר הַלָּבָן.</p>\n<p>וְעַל זֶה כָּתוּב (שם פג) אֱלֹהִים אַל דֳּמִי לָךְ אַל תֶּחֱרַשׁ וְאַל תִּשְׁקֹט אֵל, כְּדֵי שֶׁלֹּא יִפָּסֵק הָאוֹר הַלָּבָן מִן הָעוֹלָם לְעוֹלָמִים. וְכֵן (ישעיה סב) הַמַּזְכִּירִים אֶת ה' אַל דֳּמִי לָכֶם, כְּדֵי לְעוֹרֵר לְמַטָּה בְּמַה שֶּׁתִּשְׁרֶה הַהִתְעוֹרְרוּת שֶׁלְּמַעְלָה. וְכֵן כֵּיוָן שֶׁמֵּעִיר אָדָם הִתְעוֹרְרוּת (טובה) בָּרִאשׁוֹנָה, אָז מִתְעוֹרֶרֶת הִתְעוֹרְרוּת שֶׁלְּמַעְלָה. בֹּא רְאֵה, כֵּיוָן שֶׁכָּתוּב וַיֵּצְאוּ אִתָּם מֵאוּר כַּשְׂדִּים וְגוֹ', מִיָּד - וַיֹּאמֶר ה' אֶל אַבְרָם וְגוֹ'.</p>"],[9522011185,"<p>וַיֹּאמֶר ה' אֶל אַבְרָם לֶךְ לְךְ. אָמַר רַבִּי אֶלְעָזָר, לֶךְ לְךְ - לְעַצְמְךְ, לְתַקֵּן אֶת עַצְמְךְ, (להתחזק) לְתַקֵּן אֶת דַּרְגָּתְךְ. לֶךְ לְךְ - אֵינְךְ (ס\"א כדאי) לַעֲמֹד כָּאן בֵּין הָרְשָׁעִים הַלָּלוּ.</p>\n<p>וְסוֹד הַדָּבָר - לֶךְ לְךְ, שֶׁהֲרֵי הַקָּדוֹשׁ בָּרוּךְ הוּא נָתַן לְאַבְרָהָם רוּחַ שֶׁל חָכְמָה, וְהָיָה יוֹדֵעַ וּמְצָרֵף (צנורות) צִדְדֵי יִשּׁוּב הָעוֹלָם, וְהִסְתַּכֵּל בָּהֶם וְשָׁקַל בְּמִשְׁקָל וְיָדַע אֶת הַכֹּחוֹת הַמְמֻנִּים עַל צִדְדֵי הַיִּשּׁוּב.</p>\n<p>כְּשֶׁהִגִּיעַ לְתוֹךְ נְקֻדַּת אֶמְצַע הַיִּשּׁוּב, שָׁקַל בְּמִשְׁקָל וְלֹא הָיָה עוֹלֶה בְיָדוֹ. הִתְבּוֹנֵן לָדַעַת אֶת הַכֹּחַ שֶׁמְּמֻנֶּה עָלֶיהָ, וְלֹא יָכֹל לְהִתְדַּבֵּק בִּרְצוֹנוֹ.</p>\n<p>שָׁקַל כַּמָּה פְעָמִים, וְרָאָה שֶׁהִנֵּה מִשָּׁם נִשְׁתַּל כָּל הָעוֹלָם. הִתְבּוֹנֵן וְצֵרַף וְשָׁקַל לָדַעַת, וְרָאָה שֶׁהִנֵּה הַכֹּחַ הָעֶלְיוֹן שֶׁעָלֶיהָ אֵין לוֹ שִׁעוּר, עָמֹק וְנִסְתָּר, וְאֵינוֹ כְּמוֹ הַצְּדָדִים שֶׁל דַּרְגוֹת הַיִּשּׁוּב.</p>\n<p>הִתְבּוֹנֵן וְשָׁקַל וְיָדַע שֶׁהֲרֵי כְּמוֹ שֶׁמֵּהַנְּקֻדָּה הַהִיא אֶמְצָעִיתוֹ שֶׁל הַיִּשּׁוּב, מִמֶּנָּה נִשְׁתַּל כָּל הָעוֹלָם לְכָל צְדָדָיו. כָּךְ גַּם יָדַע שֶׁהֲרֵי הַכֹּחַ שֶׁשּׁוֹרֶה עָלֶיהָ, מִשָּׁם יָצְאוּ כָּל שְׁאָר הַכֹּחוֹת הַמְמֻנִּים עַל כָּל צִדְדֵי הָעוֹלָם, וְכֻלָּם אֲחוּזִים בּוֹ. אָז (בראשית יא) וַיֵּצְאוּ אִתָּם מֵאוּר כַּשְׂדִּים לָלֶכֶת אַרְצָה כְּנַעַן.</p>\n<p>עוֹד, הִשְׁגִּיחַ וְשָׁקַל וְצֵרַף לַעֲמֹד עַל בֵּרוּר הַדָּבָר שֶׁל אוֹתוֹ הַמָּקוֹם וְלֹא הָיָה יוֹדֵעַ, וְלֹא יָכֹל לַעֲמֹד עָלֶיהָ לְהַשִּׂיג. כֵּיוָן שֶׁרָאָה אֶת כֹּחוֹ שֶׁל הַמָּקוֹם הַזֶּה וְלֹא יָכֹל לַעֲמֹד עָלָיו, מִיָּד וַיָּבאוּ עַד חָרָן וַיֵּשְׁבוּ שָׁם.</p>\n<p>מָה הַטַּעַם שֶׁל אַבְרָהָם? אֶלָּא שֶׁהוּא הָיָה יוֹדֵעַ וּמְצָרֵף אֶת כָּל אוֹתָם הַשַּׁלִּיטִים מַנְהִיגֵי הָעוֹלָם בְּכָל צִדְדֵי הַיִּשּׁוּב, וְהָיָה שׁוֹקֵל וּמְצָרֵף אוֹתָם הַשּׁוֹלְטִים בִּצִדְדֵי הַיִּשּׁוּב מַנְהִיגֵי הַכּוֹכָבִים וְהַמַּזָּלוֹת שֶׁלָּהֶם מִי הֵם הַחֲזָקִים אֵלּוּ עַל אֵלּוּ. וְהָיָה שׁוֹקֵל אֶת כָּל יִשּׁוּבֵי הָעוֹלָם (ולא) וְהָיָה עוֹלֶה בְיָדוֹ. כְּשֶׁהִגִּיעַ לַמָּקוֹם הַזֶּה רָאָה אֶת חֹזֶק הָעֳמָקִים וְלֹא יָכֹל לַעֲמֹד בּוֹ.</p>\n<p>כֵּיוָן שֶׁרָאָה הַקָּדוֹשׁ בָּרוּךְ הוּא אֶת הִתְעוֹרְרוּתוֹ וּתְשׁוּקָתוֹ, מִיָּד הִתְגַּלָּה עָלָיו וְאָמַר לוֹ לֶךְ לְךְ, לָדַעַת אוֹתְךְ וּלְתַקֵּן עַצְמְךְ.</p>\n<p>מֵאַרְצְךָ - מֵאוֹתוֹ הַצַּד שֶׁל הַיִּשּׁוּב שֶׁהָיִיתָ נִדְבָּק בּוֹ. וּמִמּוֹלַדְתְּךְ - מֵאוֹתָהּ הַחָכְמָה שֶׁאַתָּה מִתְבּוֹנֵן וְשׁוֹקֵל אֶת תּוֹלַדְתְּךְ וְהָרֶגַע וְהַשָּׁעָה וְהַזְּמַן שֶׁנּוֹלַדְתָּ בּוֹ, וּבְאוֹתוֹ הַכּוֹכָב וּבְאוֹתוֹ הַמַּזָּל.</p>\n<p>וּמִבֵּית אָבִיךְ - שֶׁלֹּא תַשְׁגִּיחַ בְּבֵית אָבִיךְ. וְאִם יֵשׁ לְךְ שֹׁרֶשׁ לְהַצְלִיחַ בָּעוֹלָם מִבֵּית אָבִיךְ, מִשּׁוּם כָּךְ לֶךְ לְךְ מֵהַחָכְמָה הַזּוֹ וּמֵהַהַשְׁגָּחָה הַזּוֹ</p>\n<p>בֹּא רְאֵה שֶׁכָּךְ הוּא, שֶׁהֲרֵי יָצְאוּ מֵאוּר כַּשְׂדִּים וְהָיוּ בְחָרָן, לָמָּה יֹאמַר לוֹ לֶךְ לְךְ מֵאַרְצְךְ וּמִמּוֹלַדְתְּךְ? אֶלָּא עִקַּר הַדָּבָר כְּמוֹ שֶׁנֶּאֱמַר. אֶל הָאָרֶץ אֲשֶׁר אַרְאֶךָּ. אַרְאֶךָּ - מַה שֶּׁלֹּא יָכֹלְתָּ לַעֲמֹד עָלָיו, וְלֹא יָכֹלְתָּ לָדַעַת אֶת כֹּחַ הָאָרֶץ הַהִיא שֶׁהוּא עָמֹק וְנִסְתָּר.</p>"],[9522011186,"<p>וְאֶעָשְׂךָ לְגוֹי גָּדוֹל וְגוֹ'. וְאֶעֶשְׂךְ - מִשּׁוּם שֶׁכָּתוּב לֶךְ לְךְ. וַאֲבָרֶכְךְ - מִשּׁוּם שֶׁכָּתוּב מֵאַרְצְךְ. וַאֲגַדְּלָה שְׁמֶךְ - מִשּׁוּם שֶׁכָּתוּב מִמּוֹלַדְתְּךְ. וֶהְיֵה בְּרָכָה - מִשּׁוּם שֶׁכָּתוּב וּמִבֵּית אָבִיךְ.</p>\n<p>רַבִּי שִׁמְעוֹן אָמַר, וְאֶעֶשְׂךְ לְגוֹי גָּדוֹל - מִצַּד הַיָּמִין. וַאֲבָרֶכְךְ - מִצַּד הַשְּׂמֹאל. וַאֲגַדְּלָה שְׁמֶךְ - מִצַּד הָאֶמְצַע. וֶהְיֵה בְּרָכָה - מִצַּד שֶׁל אֶרֶץ יִשְׂרָאֵל. הִנֵּה כָּאן כִּסֵּא שֶׁל אַרְבָּעָה עַמּוּדִים שֶׁכֻּלָּם כְּלוּלִים בְּאַבְרָהָם. מִכָּאן וָהָלְאָה בְּרָכוֹת לָאֲחֵרִים שֶׁנִּזּוֹנִים מִכָּאן, שֶׁכָּתוּב וַאֲבָרְכָה מְבָרֲכֶיךְ. וּמְקַלֶּלְךְ אָאֹר וְנִבְרְכוּ בְךְ כֹּל מִשְׁפְּחֹת הָאֲדָמָה.</p>"],[9522011187,"<p>רַבִּי אֶלְעָזָר הָיָה יוֹשֵׁב לִפְנֵי רַבִּי שִׁמְעוֹן אָבִיו, וְהָיָה עִמּוֹ רַבִּי יְהוּדָה וְרַבִּי יִצְחָק וְרַבִּי חִזְקִיָּה. אָמַר לוֹ רַבִּי אֶלְעָזָר לְרַבִּי שִׁמְעוֹן אָבִיו, זֶה שֶׁכָּתוּב לֶךְ לְךְ מֵאַרְצְךְ וּמִמּוֹלַדְתְּךְ, כֵּיוָן שֶׁכֻּלָּם יָצְאוּ לָלֶכֶת, לָמָּה לֹא נֶאֱמַר לוֹ שֶׁכֻּלָּם יֵצְאוּ?</p>\n<p>שֶׁהֲרֵי אַף עַל גַּב שֶׁתֶּרַח הָיָה עוֹבֵד לַעֲבוֹדָה זָרָה, כֵּיוָן שֶׁהִתְעוֹרֵר בְּהִתְעוֹרְרוּת טוֹבָה לָצֵאת עִם אַבְרָהָם, וְרָאִינוּ שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא מְרֻצֶּה מִתְּשׁוּבַת הָרְשָׁעִים, וְהִתְחִיל לָצֵאת, לָמָּה לֹא כָתוּב לְכוּ לָכֶם? לָמָּה לְאַבְרָהָם לְבַדּוֹ לֶךְ לְךְ?</p>\n<p>אָמַר לוֹ רַבִּי שִׁמְעוֹן, אִם תֹּאמַר שֶׁתֶּרַח, כְּשֶׁיָּצָא מֵאוּר כַּשְׂדִּים, זֶה הָיָה כְּדֵי לַחֲזֹר בִּתְשׁוּבָה - לֹא כָּךְ! אֶלָּא כְּשֶׁיָּצָא, יָצָא לְהִנָּצֵל, שֶׁכָּל בְּנֵי אַרְצוֹ רָצוּ לַהֲרֹג אוֹתוֹ. כֵּיוָן שֶׁרָאוּ שֶׁנִּצַּל אַבְרָהָם, הָיוּ אוֹמְרִים לְתֶרַח: אַתָּה הוּא שֶׁהָיִיתָ מַטְעֶה אוֹתוֹ בַּפְּסִילִים הַלָּלוּ. וּמִתּוֹךְ הַהַפְחָדָה שֶׁלָּהֶם יָצָא תֶרַח. כֵּיוָן שֶׁהִגִּיעַ לְחָרָן, לֹא יָצָא מִשָּׁם אַחַר כָּךְ, שֶׁכָּתוּב וַיֵּלֶךְ אַבְרָם כַּאֲשֶׁר דִּבֶּר אֵלָיו ה' וַיֵּלֶךְ אִתּוֹ לוֹט. וְאִלּוּ תֶרַח לֹא כָתוּב (בו וילך, אלא ויצא).</p>\n<p>פָּתַח וְאָמַר, (איוב לח) וְיִמָּנַע מֵרְשָׁעִים אוֹרָם וּזְרוֹעַ רָמָה תִּשָּׁבֵר. הַפָּסוּק הַזֶּה הֱקִימוּהוּ, אֲבָל וְיִמָּנַע מֵרְשָׁעִים אוֹרָם - זֶה נִמְרוֹד וּבְנֵי דוֹרוֹ שֶׁיָּצָא אַבְרָהָם מֵהֶם, שֶׁהָיָה אוֹרָם. וּזְרוֹעַ רָמָה תִּשָּׁבֵר - זֶה נִמְרוֹד.</p>\n<p>דָּבָר אַחֵר וְיִמָּנַע מֵרְשָׁעִים אוֹרָם - זֶה תֶרַח וּבְנֵי בֵיתוֹ. אוֹרָם - זֶה אַבְרָהָם. לֹא כָתוּב הָאוֹר אֶלָּא אוֹרָם, שֶׁהָיָה עִמָּהֶם. וּזְרוֹעַ רָמָה תִּשָּׁבֵר - זֶה נִמְרוֹד, שֶׁהָיָה מַטְעֶה אַחֲרָיו אֶת כָּל בְּנֵי הָעוֹלָם, וּמִשּׁוּם כָּךְ כָּתוּב לֶךְ לְךְ, כְּדֵי לְהָאִיר לְךְ וּלְכָל אוֹתָם שֶׁיֵּצְאוּ מִמְּךְ מִכָּאן וָהָלְאָה.</p>\n<p>עוֹד פָּתַח וְאָמַר, (שם לז) וְעַתָּה לֹא רָאוּ אוֹר בָּהִיר הוּא בַּשְּׁחָקִים וְרוּחַ עָבְרָה וַתְּטַהֲרֵם. וְעַתָּה לֹא רָאוּ אוֹר - מָתַי? בְּשָׁעָה שֶׁאָמַר הַקָּדוֹשׁ בָּרוּךְ הוּא לְאַבְרָהָם לֶךְ לְךְ מֵאַרְצְךְ וּמִמּוֹלַדְתְּךְ וּמִבֵּית אָבִיךְ. בָּהִיר הוּא בַּשְּׁחָקִים - שֶׁרָצָה הַקָּדוֹשׁ בָּרוּךְ הוּא לְהַדְבִּיק אֶת אַבְרָהָם בָּאוֹר הַהוּא שֶׁלְּמַעְלָה וּלְהָאִיר שָׁם.</p>\n<p>וְרוּחַ עָבְרָה וַתְּטַהֲרֵם - שֶׁהֲרֵי אַחַר כָּךְ שָׁבוּ בִּתְשׁוּבָה תֶּרַח וְכָל בְּנֵי בֵיתוֹ (נ\"א: וכל בני עירו). בְּנֵי בֵיתוֹ (נ\"א: בני עירו), שֶׁכָּתוּב וְאֶת הַנֶּפֶשׁ אֲשֶׁר עָשׂוּ בְחָרָן. תֶּרַח, שֶׁכָּתוּב וְאַתָּה תָבוֹא אֶל אֲבֹתֶיךְ בְּשָׁלוֹם וְגוֹ'.</p>\n<p>וְאֶעָשְׂךָ לְגוֹי גָּדוֹל. זּוֹ בְרָכָה אַחַת. וַאֲבָרֶכְךְ - שְׁתַּיִם. וַאֲגַדְּלָה שְׁמֶךְ - שָׁלֹשׁ. וֶהְיֵה בְּרָכָה - אַרְבַּע. וַאֲבָרְכָה מְבָרֲכֶיךְ - חָמֵשׁ. וּמְקַלֶּלְךְ אָאֹר - שֵׁשׁ. וְנִבְרְכוּ בְךְ כֹּל מִשְׁפְּחֹת הָאֲדָמָה - הִנֵּה שֶׁבַע. כֵּיוָן שֶׁהִתְבָּרֵךְ בְּשֶׁבַע הַבְּרָכוֹת הַלָּלוּ, מַה כָּתוּב? וַיֵּלֶךְ אַבְרָם כַּאֲשֶׁר דִּבֶּר אֵלָיו ה', לָרֶדֶת לָעוֹלָם הַזֶּה כְּפִי שֶׁהִצְטַוָּה.</p>\n<p>מִיָּד וַיֵּלֶךְ אִתּוֹ לוֹט. זֶה הַנָּחָשׁ שֶׁהִתְקַלֵּל וְהִתְקַלֵּל הָעוֹלָם בִּגְלָלוֹ, שֶׁהוּא עוֹמֵד לַפֶּתַח לְהַסְטִין לַגּוּף, וְלֹא תִפְעַל הַנְּשָׁמָה עֲבוֹדָה שֶׁהִצְטַוְּתָה עַד שֶׁיַּעַבְרוּ עָלֶיהָ בָּעוֹלָם הַזֶּה שְׁלֹשׁ עֶשְׂרֵה שָׁנִים. שֶׁהֲרֵי מִשְּׁנֵים עָשָׂר שָׁנִים וָמַעְלָה מִתְעוֹרֶרֶת הַנְּשָׁמָה לַעֲבֹד אֶת הָעֲבוֹדָה שֶׁהִצְטַוְּתָה. זֶהוּ שִּכָּתוּב, ואַברָם בִּן חָמשּ שָׁנִים וְשִׁבְעִים שָׁנָה. שֶׁבַע וְחָמֵשׁ הֵם שְׁנֵים עָשָׂר (ושני עליונים עליהם ארבעה עשר הם).</p>\n<p>וְאָז נִרְאֵית הַנְּשָׁמָה בָּעוֹלָם הַזֶּה, שֶׁהִיא בָּאָה מֵחָמֵשׁ שָׁנִים שֶׁהֵם ת\"ק פַּרְסוֹת שֶׁל עֵץ הַחַיִּים. וְשִׁבְעִים שָׁנָה - זֶהוּ אוֹתוֹ אִילָן מַמָּשׁ, שֶׁהוּא שְׁבִיעִי לַדְּרָגוֹת וְנִקְרָא שִׁבְעִים שָׁנָה.</p>\n<p>אָז יוֹצֵאת מֵאוֹתָהּ זֻהֲמַת הַנָּחָשׁ, וְנִכְנֶסֶת לָעֲבוֹדָה הַקְּדוֹשָׁה. זֶהוּ שֶׁכָּתוּב בְּצֵאתוֹ מֵחָרָן (ימי שבעים שנה לא ספורות חיים מאותם ארבע עשרה) מֵאוֹתוֹ הָרֹגֶז וְהַתֹּקֶף שֶׁל (השטן) הַהוּא הַנָּחָשׁ שֶׁהָיָה מֵסִית אוֹתוֹ עַד עַכְשָׁו אֶת הַגּוּף וְשׁוֹלֵט עָלָיו.</p>\n<p>בָּאִילָן שׁוֹלֶטֶת עָרְלָה שָׁלֹשׁ שָׁנִים. בָּאָדָם שְׁלֹשׁ עֶשְׂרֵה שָׁנִים שֶׁנִּקְרָאִים שְׁנֵי עָרְלָה. כֵּיוָן שֶׁעָבְרוּ עַל הַגּוּף אוֹתָן הַשָּׁנִים וְהִתְעַבְּרָה (ד\"א והתעוררה) הַנְּשָׁמָה לַעֲבֹד אֶת עֲבוֹדַת הַקֹּדֶשׁ, הִיא מְצַוָּה אֶת הַגּוּף לְרָצוֹן טוֹב, לְהַכְנִיעַ אֶת אוֹתוֹ הַנָּחָשׁ שֶׁהִנֵּה לֹא יָכוֹל לִשְׁלֹט כְּמוֹ שֶׁהָיָה,</p>\n<p>שֶׁכָּתוּב וַיִּקַּח אַבְרָם אֶת שָׂרַי אִשְׁתּוֹ וְגוֹ' (אברם זו י', את שרי זו ה', י' זו הנשמה לנשמה, והוא זכר, ה' זו הנשמה של הנקבה). זֶה הַגּוּף, שֶׁהוּא אֵצֶל הַנְּשָׁמָה כְּמוֹ נְקֵבָה אֵצֶל הַזָּכָר. וְאֶת לוֹט בֶּן אָחִיו - זֶה (יצר הרע) הַנָּחָשׁ שֶׁלֹּא זָז כָּל כָּךְ מִן הַגּוּף, מִשּׁוּם הַדְּבֵקוּת שֶׁל הַגּוּף לֹא כָּל כָּךְ זָזִים (הזמן ההוא) מִמֶּנּוּ. אֲבָל הִתְעוֹרְרוּת הַנְּשָׁמָה תָּמִיד מַלְקָה אוֹתוֹ וּמַתְרָה בּוֹ וּמוֹכִיחָה אוֹתוֹ וּמַכְנִיעָה אוֹתוֹ בְּעַל כָּרְחוֹ, וְלֹא יָכוֹל לִשְׁלֹט.</p>\n<p>וְאֶת כָּל רְכוּשָׁם אֲשֶׁר רָכָשׁוּ - אֵלּוּ הַמַּעֲשִׂים הַטּוֹבִים שֶׁעוֹשֶׂה אָדָם בָּעוֹלָם הַזֶּה בַּהִתְעוֹרְרוּת שֶׁל הַנְּשָׁמָה. וְאֶת הַנֶּפֶשׁ אֲשֶׁר עָשׂוּ בְחָרָן - אוֹתָהּ הַנֶּפֶשׁ שֶׁהָיְתָה בָּרִאשׁוֹנָה בַּדְּבֵקוּת בַּחֲבֵרוּת שֶׁל הָעָרְלָה הַהִיא עִם הַגּוּף וְתִקֵּן אוֹתָהּ לְאַחַר מִכֵּן, שֶׁהֲרֵי אַחַר שְׁלֹשׁ עֶשְׂרֵה שָׁנִים וָמַעְלָה, כְּשֶׁהַנְּשָׁמָה מִתְעוֹרֶרֶת לְתַקֵּן אֶת הַגּוּף, שְׁנֵיהֶם מְתַקְּנִים אֶת אוֹתָהּ הַנֶּפֶשׁ שֶׁמִּשְׁתַּתֶּפֶת עִם חֹזֶק הַנָּחָשׁ וּתְשׁוּקָתוֹ הָרָעָה. זֶהוּ שֶׁכָּתוּב וְאֶת הַנֶּפֶשׁ אֲשֶׁר עָשׂוּ בְחָרָן.</p>\n<p>וְעִם כָּל זֶה הַנְּשָׁמָה מִתְגַּבֶּרֶת בְּאוֹתוֹ הַנָּחָשׁ לִשְׁבֹּר אוֹתוֹ בְּחֹזֶק בְּשִׁעְבּוּד שֶׁל תְּשׁוּבָה (נ\"א: בשעבוד של תורה, ומושך אותו לבתי כנסיות ובתי מדרשות כדי שלא יתגבר על הרוח כבראשונה). זֶהוּ שֶׁכָּתוּב וַיַּעֲבֹר. (ע\"כ סתרי תורה).</p>"],[9522011188,"<p>וַיֵּלֶךָ אַבְרָם כַּאֲשֶׁר דִּבֶּר אֵלָיו ה'. אָמַר רַבִּי אֶלְעָזָר, בֹּא רְאֵה, שֶׁהֲרֵי לֹא כָתוּב וַיֵּצֵא אַבְרָם כַּאֲשֶׁר דִּבֶּר אֵלָיו ה', אֶלָּא וַיֵּלֶךְ, כְּמוֹ שֶׁנֶּאֱמַר לֶךְ לְךְ, שֶׁהֲרֵי בָּרִאשׁוֹנָה עָשׂוּ יְצִיאָה, שֶׁכָּתוּב וַיֵּצְאוּ אִתָּם מֵאוּר כַּשְׂדִּים לָלֶכֶת אַרְצָה כְּנַעַן. וְעַכְשָׁו כָּתוּב וַיֵּלֶךְ, וְלֹא כָתוּב וַיֵּצֵא.</p>\n<p>כַּאֲשֶׁר דִּבֶּר אֵלָיו ה' - שֶׁהִבְטִיחַ לוֹ אֶת כָּל הַהַבְטָחוֹת. וַיֵּלֶךְ אִתּוֹ לוֹט - שֶׁהִתְחַבֵּר עִמּוֹ כְּדֵי לִלְמֹד מִמַּעֲשָׂיו, וְעִם כָּל זֶה לֹא לָמַד כָּל זֶה. אָמַר רַבִּי אֶלְעָזָר, אַשְׁרֵי הַצַּדִּיקִים שֶׁלּוֹמְדִים דַּרְכֵי הַקָּדוֹשׁ בָּרוּךְ הוּא כְּדֵי לָלֶכֶת בָּהֶם וְלִירָא מִמֶּנּוּ מֵאוֹתוֹ יוֹם הַדִּין שֶׁעָתִיד אָדָם לָתֵת דִּין וְחֶשְׁבּוֹן לַקָּדוֹשׁ- בָּרוּךְ-הוּא.</p>\n<p>פָּתַח וְאָמַר, (איוב לז) בְּיַד כָּל אָדָם יַחְתּוֹם לָדַעַת כָּל אַנְשֵׁי מַעֲשֵׂהוּ. הַפָּסוּק הַזֶּה בֵּאֲרוּהוּ. אֲבָל בֹּא רְאֵה, בַּיּוֹם הַהוּא שֶׁנִּשְׁלָמִים יְמֵי הָאִישׁ לָצֵאת מִן הָעוֹלָם, הַיּוֹם הַהוּא שֶׁהַגּוּף נִשְׁבָּר וְהַנֶּפֶשׁ רוֹצָה לְהִפָּרֵד מִמֶּנּוּ, אָז נִתֶּנֶת רְשׁוּת לָאָדָם לִרְאוֹת מַה שֶּׁלֹּא הָיְתָה לוֹ רְשׁוּת לִרְאוֹת בִּזְמַן שֶׁהַגּוּף שָׁלַט וְעָמַד עַל בֻּרְיוֹ.</p>\n<p>וְאָז עוֹמְדִים עָלָיו שְׁלֹשָׁה שְׁלִיחִים וּמְחַשְּׁבִים יָמָיו וַחֲטָאָיו וְכָל מַה שֶּׁעָשָׂה בָּעוֹלָם הַזֶּה, וְהוּא מוֹדֶה עַל הַכֹּל בְּפִיו, וְאַחַר כָּךְ הוּא חוֹתֵם עָלָיו בְּיָדוֹ. זֶהוּ שֶׁכָּתוּב בְּיַד כָּל אָדָם יַחְתּוֹם.</p>\n<p>וּבְיָדוֹ כֻּלָּם חֲתוּמִים לָדוּן אוֹתוֹ (באותו ד\"א בזה) הָעוֹלָם עַל הָרִאשׁוֹנִים וְעַל הָאַחֲרוֹנִים, עַל חֲדָשִׁים וְעַל יְשָׁנִים, לֹא נִשְׁכָּח אֶחָד מֵהֶם. זֶהוּ שֶׁכָּתוּב לָדַעַת כָּל אַנְשֵׁי מַעֲשֵׂהוּ. וְכָל אוֹתָם הַמַּעֲשִׂים שֶׁעָשָׂה בָּעוֹלָם הַזֶּה בְּגוּף וְרוּחַ, כָּךְ גַּם נוֹתֵן חֶשְׁבּוֹן בְּגוּף וְרוּחַ בְּטֶרֶם יָצָא מִן הָעוֹלָם</p>\n<p>בֹּא רְאֵה כַּמָּה הָרְשָׁעִים קְשֵׁי עֹרֶף בָּעוֹלָם הַזֶּה, כָּךְ גַּם אֲפִלּוּ בְּשָׁעָה שֶׁרוֹצִים לָצֵאת מִן הָעוֹלָם הַזֶּה הֵם קְשֵׁי עֹרֶף. מִשּׁוּם כָּךְ אַשְׁרֵי הָאִישׁ שֶׁלּוֹמֵד בָּעוֹלָם הַזֶּה אֶת דַּרְכֵי הַקָּדוֹשׁ בָּרוּךְ הוּא כְּדֵי לָלֶכֶת בָּהֶם. וְהָרָשָׁע, אַף עַל פִּי שֶׁמִּסְתַּכֵּל בְּאֵלּוּ (נ\"א: שמשתדל עם) הַצַּדִּיקִים, מַקְשֶׁה עֹרֶף וְלֹא רוֹצֶה לִלְמֹד.</p>\n<p>וּמִשּׁוּם כָּךְ יֵשׁ לַצַּדִּיק לְהַחֲזִיק בּוֹ. וְאַף עַל גַּב שֶׁהָרָשָׁע מַקְשֶׁה עֹרֶף הוּא, לֹא יַעֲזֹב אוֹתוֹ, וְיֵשׁ לוֹ לְהַחֲזִיק בְּיָדוֹ וְלֹא יַעֲזב אוֹתוֹ. כִּי אִם יַעֲזב אוֹתוֹ, יֵלֶךְ וְיַחֲרִיב אֶת הָעוֹלָם.</p>\n<p>בֹּא רְאֵה מֵאֱלִישָׁע שֶׁדָּחָה אֶת גֵיחֲזִי. וְכֵן בְּאַבְרָהָם - כָּל פַּעַם שֶׁלּוֹט הָיָה עִמּוֹ, לֹא הִתְחַבֵּר עִם הָרְשָׁעִים. כֵּיוָן שֶׁנִּפְרַד מִמֶּנּוּ, מַה כָּתוּב? וַיִּבְחַר לוֹ לוֹט אֵת כָּל כִּכַּר הַיַּרְדֵּן. וְכָתוּב וַיֶּאֱהַל עַד סְדוֹם. מַה כָּתוּב אַחַר כָּךְ? וְאַנְשֵׁי סְדֹם רָעִים וְחַטָּאִים לַה' מְאֹד.</p>\n<p>אָמַר רַבִּי אַבָּא, זֶה שֶׁאָמַרְתָּ וַיֵּלֶךְ אַבְרָם וְלֹא כָתוּב וַיֵּצֵא אַבְרָם - זֶה יָפֶה. אֲבָל בְּסוֹף הַפָּסוּק מַה כָּתוּב? בְּצֵאתוֹ מֵחָרָן. אָמַר רַבִּי אֶלְעָזָר, כָּתוּב מֵחָרָן, וְהַיְצִיאָה הַהִיא מֵאֶרֶץ מוֹלַדְתּוֹ הָיְתָה בָּרִאשׁוֹנָה.</p>"],[9522011189,"<p>וַיִּקַּח אַבְרָם אֶת שָׂרַי אִשְׁתּוֹ. מַה זֶּה וַיִּקַּח? אֶלָּא מָשַׁךְ אוֹתָהּ בִּדְבָרִים נְעִימִים, מִשּׁוּם שֶׁאֵין רְשׁוּת לְאָדָם לְהוֹצִיא אֶת אִשְׁתּוֹ לָלֶכֶת לְאֶרֶץ אַחֶרֶת לְלֹא רְצוֹנָהּ. וְכֵן הוּא אוֹמֵר (במדבר כ) קַח אֶת אַהֲרֹן, (שם ג) קַח אֶת הַלְוִיִּם. וּמִשּׁוּם כָּךְ וַיִּקַּח אַבְרָם. מָשַׁךְ אוֹתָהּ בִּדְבָרִים וְהוֹדִיעַ לָהּ אֶת דַּרְכֵי בְּנֵי הַדּוֹר כַּמָּה הֵם רָעִים. וּמִשּׁוּם כָּךְ וַיִּקַּח אַבְרָם אֶת שָׂרַי אִשְׁתּוֹ.</p>\n<p>וְאֶת לוֹט בֶּן אָחִיו. מָה רָאָה אַבְרָם לְהַדְבִּיק עִמּוֹ אֶת לוֹט? אֶלָּא מִשּׁוּם שֶׁצָּפָה בְּרוּחַ הַקֹּדֶשׁ שֶׁעָתִיד לָצֵאת מִמֶּנּוּ דָּוִד. וְאֶת הַנֶּפֶשׁ אֲשֶׁר עָשׂוּ בְחָרָן - אֵלּוּ הַגֵּרִים וְהַגֵּרוֹת שֶׁתִּקְּנוּ אֶת נַפְשׁוֹתָם. אַבְרָהָם מְגַיֵּר אֲנָשִׁים, וְשָׂרָה מְגַיֶּרֶת נָשִׁים, וּמַעֲלֶה עֲלֵיהֶם כְּאִלּוּ עָשׂוּ אוֹתָם.</p>\n<p>אָמַר רַבִּי אַבָּא, אִם כָּךְ, כַּמָּה בְּנֵי אָדָם הָיוּ, אִם תֹּאמַר שֶׁכֻּלָּם הָלְכוּ עִמּוֹ? אָמַר רַבִּי אֶלְעָזָר, כֵּן, (ומשום שכלם ד\"א ומשום כך כלם) הָאֲנָשִׁים שֶׁהָיוּ הוֹלְכִים עִמּוֹ, כֻּלָּם נִקְרְאוּ עַם אֱלֹהֵי אַבְרָהָם. וְהָיָה עוֹבֵר בָּאָרֶץ וְלֹא הָיָה פוֹחֵד, שֶׁכָּתוּב וַיַּעֲבֹר אַבְרָם בָּאָרֶץ.</p>\n<p>אָמַר לוֹ רַבִּי אַבָּא, אִם הָיָה כָּתוּב וְהַנֶּפֶשׁ אֲשֶׁר עָשׂוּ בְחָרָן - הָיִיתִי אוֹמֵר כָּךְ. אֶלָּא כָתוּב וְאֶת הַנֶּפֶשׁ. אֶת - לְרַבּוֹת אֶת הַזְּכוּת שֶׁל כָּל הַנְּפָשׁוֹת שֶׁהָיוּ הוֹלְכוֹת עִמּוֹ. שֶׁכָּל מִי שֶׁמְּזַכֶּה אֶת הָאַחֵר, אוֹתָהּ הַזְּכוּת תְּלוּיָה בּוֹ וְלֹא זָזָה מִמֶּנּוּ. מִנַּיִן לָנוּ? שֶׁכָּתוּב וְאֶת הַנֶּפֶשׁ אֲשֶׁר עָשׂוּ בְחָרָן. הַזְּכוּת שֶׁל אוֹתָן הַנְּפָשׁוֹת הָיְתָה הוֹלֶכֶת עִם אַבְרָהָם. לֶךָ לְךְ.</p>\n<p>אָמַר רַבִּי שִׁמְעוֹן, מָה הַטַּעַם שֶׁהַהִתְגַּלּוּת הָרִאשׁוֹנָה שֶׁהִתְגַּלָּה הַקָּדוֹשׁ בָּרוּךְ הוּא עַל אַבְרָהָם פּוֹתַחַת בְּלֶךְ לְךְ, שֶׁהֲרֵי עַד כָּאן לֹא דִבֵּר עִמּוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא. מָה הַטַּעַם פָּתַח בְּלֶךְ לְךְ? אֶלָּא זֶה אָמְרוּ שֶׁרָמַז בְּחֶשְׁבּוֹנוֹ מֵאָה, שֶׁהֲרֵי לְמֵאָה שָׁנִים נוֹלַד לוֹ בֵּן.</p>\n<p>אֲבָל בֹּא תִרְאֶה, כָּל מַה שֶּׁעָשָׂה הַקָּדוֹשׁ בָּרוּךְ הוּא בָּאָרֶץ, הַכֹּל הוּא סוֹד שֶׁל חָכְמָה. מִשּׁוּם שֶׁאַבְרָהָם לֹא הָיָה דָבוּק בַּקָּדוֹשׁ- בָּרוּךְ-הוּא אָז כָּרָאוּי, אָמַר לוֹ לֶךְ לְךְ. וְזֶה רֶמֶז לַמָּקוֹם הַהוּא שֶׁצָּרִיךְ לְהִתְקָרֵב עִם הַקָּדוֹשׁ בָּרוּךְ הוּא, וְהִיא הַדַּרְגָּה הָרִאשׁוֹנָה לְהִכָּנֵס לַקָּדוֹשׁ-בָּרוּךְ- הוּא, מִשּׁוּם כָּךְ לֶךְ לְךְ.</p>\n<p>וּבַדַּרְגָּה הַזּוֹ לֹא יָכוֹל אַבְרָהָם לְהֵאָחֵז בָּהּ עַד שֶׁיִּכָּנֵס לָאָרֶץ, שֶׁשָּׁם יְקַבֵּל אֶת הַדַּרְגָּה הַהִיא. כְּמוֹ כֵן כָּתוּב (שמואל ב ב) וַיִּשְׁאַל דָּוִד בַּה' לֵאמֹר הַאֶעֱלֶה בְּאַחַת מֵעָרֵי יְהוּדָה וַיֹּאמֶר ה' עֲלֵה וַיֹּאמֶר דָּוִד אָנָה אֶעֱלֶה וַיֹּאמֶר חֶבְרוֹנָה. וְכִי כֵּיוָן שֶׁמֵּת שָׁאוּל וְהַמַּלְכוּת רְאוּיָה לְדָוִד, לָמָּה לֹא קִבֵּל אֶת הַמַּלְכוּת מִיָּד עַל כָּל יִשְׂרָאֵל?</p>\n<p>אֶלָּא הַכֹּל הוּא סוֹד שֶׁל חָכְמָה, מִשּׁוּם שֶׁדָּוִד אֵין לוֹ לְקַבֵּל מַלְכוּת אֶלָּא עַד שֶׁיִּתְחַבֵּר עִם הָאָבוֹת שֶׁהֵם בְּחֶבְרוֹן, וְאָז יְקַבֵּל בָּהֶם מַלְכוּת. וְעַל כֵּן הִתְעַכֵּב שָׁם שֶׁבַע שָׁנִים, כְּדֵי שֶׁיְּקַבֵּל מַלְכוּת כָּרָאוּי, וְהַכֹּל בְּסוֹד הַחָכְמָה וּכְדֵי שֶׁיְּתַקֵּן אֶת מַלְכוּתוֹ. כְּמוֹ כֵן אַבְרָהָם לֹא נִכְנַס לִבְרִיתוֹ שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא עַד שֶׁנִּכְנַס לָאָרֶץ.</p>\n<p>רְאֵה מַה כָּתוּב, וַיַּעֲבֹר אַבְרָם בָּאָרֶץ. וַיַּעֲבר? וַיֵּלֶךְ הָיָה צָרִיךְ לִהְיוֹת! אֶלָּא כָּאן הוּא רֶמֶז הַשֵּׁם הַקָּדוֹשׁ שֶׁנֶּחְתָּם בּוֹ הָעוֹלָם בְּשִׁבְעִים וּשְׁתַּיִם אוֹתִיּוֹת חֲקוּקוֹת שֶׁכֻּלָּן בַּשֵּׁם הַזֶּה. כָּתוּב כָּאן וַיַּעֲבֹר, וְכָתוּב שָׁם (שמות לד) וַיַּעֲבֹר ה' עַל פָּנָיו וַיִּקְרָא.</p>"],[9522011190,"<p>בְּסִפְרוֹ שֶׁל רַבִּי יֵיסָא הַזָּקֵן כָּתוּב, וַיַּעֲבֹר אַבְרָם בָּאָרֶץ, וְכָתוּב שָׁם (שם לג) אֲנִי אַעֲבִיר כָּל טוּבִי. וְהוּא רֶמֶז לִקְדֻשַּׁת הָאָרֶץ שֶׁבָּאָה מִמָּקוֹם עֶלְיוֹן כָּרָאוּי.</p>\n<p>עַד מְקוֹם שְׁכֶם עַד אֵלוֹן מוֹרֶה, מִצַּד זֶה (ד\"א ל\"ג שלמטה) לְצַד זֶה כָּרָאוּי. וְהַכְּנַעֲנִי אָז בָּאָרֶץ, הֲרֵי נִתְבָּאֵר שֶׁעַד כָּעֵת שׁוֹלֵט הַנָּחָשׁ הָרָע שֶׁהִתְקַלֵּל וְהֵבִיא קְלָלוֹת עַל הָעוֹלָם, שֶׁכָּתוּב (בראשית ט) אָרוּר כְּנָעַן עֶבֶד עֲבָדִים יִהְיֶה לְאֶחָיו, וְכָתוּב (שם ג) אָרוּר אַתָּה מִכָּל הַבְּהֵמָה וְגוֹ'. וְשָׁם הִתְקָרֵב אַבְרָהָם לַקָּדוֹשׁ- בָּרוּךְ-הוּא. מַה כָּתוּב? וַיֵּרָא ה' אֶל אַבְרָם. כָּאן הִתְגַּלָּה לוֹ מַה שֶּׁלֹּא הָיָה יוֹדֵעַ אוֹתוֹ הַכֹּחַ הֶעָמֹק שֶׁשּׁוֹלֵט עַל הָאָרֶץ. וּמִשּׁוּם כָּךְ וַיֵּרָא, מַה שֶּׁהָיָה מְכֻסֶּה מִמֶּנּוּ.</p>\n<p>וְאָז וַיִּבֶן שָׁם מִזְבֵּחַ לַה' הַנִּרְאֶה אֵלָיו. כֵּיוָן שֶׁאָמַר לַה', מַה זֶּה הַנִּרְאֶה אֵלָיו? אֶלָּא כָּאן הִתְגַּלְּתָה לוֹ אוֹתָהּ הַדַּרְגָּה שֶׁשּׁוֹלֶטֶת עַל הָאָרֶץ, וְנִכְנַס בָּהּ וְהִתְקַיֵּם בָּהּ.</p>\n<p>וַיַּעִִתֵּק מִשָּׁם הָהָרָה. מִשָּׁם יָדַע הַר ה' וְכָל הַדְּרָגוֹת הַנְּטוּעוֹת בַּמָּקוֹם הַזֶּה. וַיֵּט אָהֳלֹה, כָּתוּב בְּהֵ\"א. פָּרַשׂ פְּרִישָׂה וְקִבֵּל מַלְכוּת שָׁמַיִם בְּכָל הַדְּרָגוֹת שֶׁאֲחוּזוֹת בּוֹ, וְאָז יָדַע שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא שׁוֹלֵט עַל הַכֹּל, וְאָז בָּנָה מִזְבֵּחַ.</p>\n<p>וּשְׁנֵי מִזְבְּחוֹת הָיוּ, מִשּׁוּם שֶׁכָּאן הִתְגַּלָּה לוֹ שֶׁהֲרֵי הַקָּדוֹשׁ בָּרוּךְ הוּא שׁוֹלֵט עַל הַכֹּל, וְיָדַע הַחָכְמָה הָעֶלְיוֹנָה מַה שֶּׁלֹּא הָיָה יוֹדֵעַ מִלִּפְנֵי כֵן. וּבָנָה שְׁנֵי מִזְבְּחוֹת - אֶחָד לַדַּרְגָּה הַגְּלוּיָה, וְאֶחָד לַדַּרְגָּה הַנִּסְתֶּרֶת. בֹּא רְאֵה שֶׁכָּךְ הָיָה בָּרִאשׁוֹנָה. כָּתוּב וַיִּבֶן שָׁם מִזְבֵּחַ לַה' הַנִּרְאֶה אֵלָיו וְגוֹ', וְאַחַר כָּךְ כָּתוּב וַיִּבֶן שָׁם מִזְבֵּחַ לַה' סְתָם, וְלֹא כָתוּב הַנִּרְאֶה אֵלָיו, וְהַכֹּל הוּא סוֹד שֶׁל חָכְמָה.</p>\n<p>וְאָז הִתְעַטֵּר אַבְרָהָם מִדַּרְגָּה לְדַרְגָּה עַד שֶׁעָלָה לְדַרְגָּתוֹ. זֶהוּ שֶׁכָּתוּב וַיִּסַּע אַבְרָם הָלוֹךְ וְנָסוֹעַ הַנֶּגְבָּה. זֶה הַדָּרוֹם, שֶׁהוּא חֶלְקוֹ שֶׁל אַבְרָהָם, הָלוֹךְ וְנָסוֹעַ דַּרְגָּה אַחַר דַּרְגָּה עַד שֶׁעָלָה לַדָּרוֹם וְשָׁם נִקְשַׁר כָּרָאוּי, וְעָלָה לְדַרְגָּתוֹ שֶׁל הַדָּרוֹם.</p>\n<p>כֵּיוָן שֶׁאַבְרָהָם הִתְעַטֵּר בְּדַרְגָּתוֹ בָּאָרֶץ הַקְּדוֹשָׁה וְנִכְנַס (בארץ) לַדַּרְגָּה הַקְּדוֹשָׁה, אָז מַה כָּתוּב? וַיְהִי רָעָב בָּאָרֶץ, שֶׁלֹּא הָיוּ יוֹדְעִים יְדִיעָה לְהִתְקָרֵב אֶל הַקָּדוֹשׁ בָּרוּךְ הוּא.</p>\n<p>וַיְהִי רָעָב בָּאָרֶץ, שֶׁעַד כָּעֵת לֹא הָיָה הַכֹּחַ שֶׁעַל הָאָרֶץ נוֹתֵן חֹזֶק וּמָזוֹן עַל הָאָרֶץ, מִשּׁוּם שֶׁטֶּרֶם הִתְקַדְּשָׁה (נ\"א: נתקנה) וְלֹא עָמְדָה בְקִיּוּם. כֵּיוָן שֶׁאַבְרָהָם רָאָה אֶת אוֹתוֹ הַכֹּחַ הַמְמֻנֶּה עַל הָאָרֶץ, לֹא נָתַן חֹזֶק וְכֹחַ קָדוֹשׁ כָּרָאוּי, אָז וַיֵּרֶד אַבְרָם מִצְרַיִם לָגוּר שָׁם.</p>\n<p>מִנַּיִן יָדַע אַבְרָהָם? שֶׁכָּתוּב לְזַרְעֲךְ נָתַתִּי אֶת הָאָרֶץ הַ את. אָז יָדַע אַבְרָהָם שֶׁהִנֵּה הָאָרֶץ לֹא נִתְקְנָה בְּתִקּוּן קָדוֹשׁ, אֶלָּא בִּדְרָגוֹת (ידועות) קְדוֹשׁוֹת שֶׁיֵּצְאוּ מִמֶּנּוּ. וְאָז יָדַע אַבְרָהָם אֶת סוֹד הַחָכְמָה, שֶׁהָאָרֶץ לֹא תִתַּקֵּן בִּקְדֻשָּׁה, אֶלָּא כְּפִי שֶׁאָמַרְנוּ.</p>\n<p>הַקָּדוֹשׁ בָּרוּךָ הוּא רוֹמֵז חָכְמָה עֶלְיוֹנָה בְּאַבְרָהָם וּבְיִצְחָק. אַבְרָהָם זוֹ הַנְּשָׁמָה לִנְשָׁמָה וְהִיא (ס\"א אב ורם), וְהַנְּשָׁמָה הַזּוֹ הִיא שָׂרָה. לוֹט זֶה הוּא הַנָּחָ\"שׁ וּבַת זוּגוֹ שֶׁל הַסמא\"ל הַהוּא. רוּ\"חַ הַקְּדוֹשָׁה זֶה יִצְחָק. נֶפֶ\"שׁ הַקְּדוֹשָׁה זוֹ רִבְקָה. יֵצֶ\"ר הָרָע זוֹ רוּחַ הַבְּהֵמָה, וְעַל זֶה אָמַר שְׁלֹמֹה בְּחָכְמָתוֹ (קהלת ג) מִי יוֹדֵעַ רוּחַ בְּנֵי הָאָדָם הָעֹלָה הִיא וְגוֹ'. נֶפֶשׁ הַבַּהֲמִית זוֹ הַנֶּפֶשׁ מִצַּד הַיֵּצֶר הָרָע.</p>\n<p>וְעַל זֶה אָמְרוּ (שההוא) שֶׁהַנְּשָׁמָה לִנְשָׁמָה הַזּוֹ מְעוֹרֶרֶת אֶת הָאִישׁ בְּיִרְאָ\"ה וּבְחָכְמָ\"ה. הַנְּשָׁמָה מְעוֹרֶרֶת אֶת הָאִישׁ בְּבִינָה. זֶהוּ שֶׁכָּתוּב (איוב כח) וַיֹּאמֶר לָאָדָם הֵן יִרְאַת ה' הִיא חָכְמָה וְגוֹ'. הַנְּשָׁמָ\"ה מְעוֹרֶרֶת בִּתְשׁוּבָ\"ה שֶׁנִּקְרֵאת בִּינָה וְנִקְרֵאת שָׂרָ\"ה. וְרוּ\"חַ הוּא הַקּוֹ\"ל, וְנִקְרָא דַעַת, וּמְעוֹרְרִים אֶת הָאִישׁ שֶׁקּוֹלוֹ עוֹלֶה בַתּוֹרָה, וְנִקְרָא תוֹרָה שֶׁבִּכְתָב, וְהַנֶּפֶשׁ הַשִּׂכְלִית מִתְעוֹרְרִים מִמֶּנָּהּ מַעֲשִׂים טוֹבִים.</p>\n<p>וּבַדֻּגְמָה הַזּוֹ בָּרָא אֶת הַגּוּף מֵאַרְבָּעָה יְסוֹדוֹת - אֵשׁ וְרוּחַ וְעָפָר וּמַיִם, כְּמוֹ שֶׁהוּא נְשָׁמָה לִנְשָׁמָה, נְשָׁמָה וְרוּחַ וְנֶפֶשׁ. מַיִם זֶה זָכָר, וְזֶהוּ הַמַּיִם הַמְּתוּקִים שֶׁל קְדֻשָּׁה. וְיֵשׁ מַיִם הַמְאָרְרִים שֶׁהֵם יֵצֶר הָרָע. יֵשׁ אֵשׁ קְדוֹשָׁה נְקֵבָה, וְיֵשׁ אֵשׁ נָכְרִיָּה, אֵשׁ זָרָה. וְעַל זֶה כָּתוּב וְאַל יָבא בְכָל עֵת אֶל הַקֹּדֶשׁ, שֶׁהִיא נְקֵבָה מִיֵּצֶר הָרָע. רוּחַ קְדוֹשָׁה הִיא זָכָר. יֵשׁ רוּחַ טֻמְאָה, זֶה יֵצֶר הָרָע, שֶׁנֶּאֱמַר (ישעיה יד) כִּי מִשֹּׁרֶשׁ נָחָשׁ יֵצֵא צֶפַע. יֵשׁ עָפָר קָדוֹשׁ וְיֵשׁ עָפָר טָמֵא.</p>\n<p>וְעַל זֶה, הַנְּשָׁמָה שֶׁהִיא תְשׁוּבָ\"ה, מִתְגַּבֶּרֶת בְּאוֹתוֹ הַנָּחָשׁ לִשְׁבֹּר אוֹתוֹ בְּשִׁעְבּוּד שֶׁל תְּשׁוּבָה, וּמוֹשֵׁךְ אוֹתוֹ לְבָתֵּי כְּנֵסִיּוֹת וּבָתֵּי מִדְרָשׁוֹת, וְאוֹתָם אַרְבַּעַת הַיְסוֹדוֹת מִתְפַּשְּׁטִים לְכ\"ב אוֹתִיּוֹת, אחה\"ע בומ\"ף גיכ\"ק דטלנ\"ת זסשר\"ץ.</p>\n<p>וַיַּעָבֹר אַבְרָם בָּאָרֶץ עַד מְקוֹם שְׁכֶם - זֶה בֵּית הַכְּנֶסֶת, מְקוֹם דִּיּוּר הַשְּׁכִינָה שָׁם, כְּמוֹ שֶׁנֶּאֱמַר (בראשית מח) וַאֲנִ\"י נָתַתִּי לְךְ שְׁ'כֶ'ם אַחַד. זוֹ שְׁכִינָה שֶׁרְאוּיָה לוֹ, הוֹאִיל וְנִקְרָא צַדִּיק, שֶׁהֲרֵי הַצֶּדֶק אֵין דִּיּוּרָהּ אֶלָּא עִם צַדִּיק, וְזֶהוּ עַד מְקוֹם שְׁכֶם. עַד אֵלוֹן מוֹרֶה - אֵלּוּ בָּתֵּי מִדְרָשׁוֹת שֶׁלּוֹמְדִים וּמוֹרִים שָׁם תּוֹרָה בָּרַבִּים.</p>\n<p>וְהַכְּנַעָנִי אָז בָּאָרֶץ - אָז נִמְתַּק וְנִתְקַן יֵצֶר הָרָע בַּגּוּף בְּעַל כָּרְחוֹ. שֶׁשֵּׁמוֹת רַבִּים יֵשׁ לוֹ, וּמִשּׁוּם כָּךְ (חזר) נִזְכָּר בְּשֵׁמוֹת רַבִּים. אָז בָּאָרֶץ, וַדַּאי, וְנִכְנָע בָּזֶה, מִשּׁוּם שֶׁאָז הַגּוּף בִּזְמַן שֶׁלֹּא בָּטַל מִמֶּנּוּ אוֹתוֹ הַנָּחָשׁ כָּל כָּךְ, מִשּׁוּם דְּבֵקוּת הַגּוּף אָז הַכְּנַעֲנִי אָז בָּאָרֶץ. לָמָּה נִקְרָא כְּנַעֲנִי? שֶׁמְּסוֹבֵב אֶת הַגּוּף לְדִינִים רָעִים.</p>\n<p>וְהַנְּשָׁמָה עוֹמֶדֶת בָּעוֹלָם הַזֶּה כָּרָאוּי כְּדֵי לִזְכּוֹת בָּהּ, אַחַר כָּךְ יוֹצֵאת מִן הָעוֹלָם הַזֶּה. אִם זוֹכָה - עוֹלָה לִמְקוֹמָהּ שֶׁמִּשָּׁם יָצְאָה, שֶׁכָּתוּב אֶל מְקוֹם הַמִּזְבֵּחַ אֲשֶׁר עָשָׂה שָׁם בָּרִאשּנָה. וְכָתוּב עַד הַמָּקוֹם אֲשֶׁר הָיָה שָׁם אָהֳלֹה בַּתְּחִלָּה. אָהֳלֹ\"ה בְּהֵ\"א.</p>\n<p>וְכָעֵת הִיא עוֹמֶדֶת בֵּין לַעֲלוֹת לְמַעְלָה וּבֵין לָרֶדֶת לְמַטָּה, (שכתוב) בֵּין בֵּית אֵל וּבֵין הָעָי. אִם זוֹכָה - עוֹלָה אֶל מְקוֹם הַמִּזְבֵּחַ אֲשֶׁר עָשָׂה שָׁם וְגוֹ'. מִי עָשָׂה וְאֵיזֶה מִזְבֵּחַ? אֶלָּא אֲשֶׁר עָשָׂה שָׁם זֶה הַקָּדוֹשׁ בָּרוּךְ הוּא, שֶׁעָשָׂה שָׁם אֶת הַמִּזְבֵּחַ הַזֶּה וְתִקֵּן אוֹתוֹ עַל שְׁתֵּים עֶשְׂרֵה אֲבָנִים לְמִסְפַּר שִׁבְטֵי בְּנֵי יַעֲקֹב אֲשֶׁר הָיָה דְּבַר ה' אֵלָיו לֵאמֹר יִשְׂרָאֵל יִהְיֶה שְׁמֶךְ וַדַּאי.</p>\n<p>וְהַמִּזְבֵּחַ הַזֶּה עָשָׂה שָׁם בָּרִאשׁוֹנָה כַּאֲשֶׁר נִבְרָא הָעוֹלָם הָעֶלְיוֹן, (עליון) הַטָּמִיר שֶׁל כָּל הָעוֹלָמוֹת, וּמִיכָאֵל הַכֹּהֵן הַגָּדוֹל עוֹמֵד וּמַקְרִיב עָלָיו קָרְבָּנוֹת שֶׁל נְשָׁמוֹת. כֵּיוָן שֶׁעוֹלָה לְשָׁם נְשָׁמָה מַה כָּתוּב? וַיִּקְרָא שָׁם אַבְרָם בְּשֵׁם ה'. הַנְּשָׁמָה קוֹרֵאת שָׁם וְנִצְרֶרֶת בִּצְרוֹר הַחַיִּים.</p>\n<p>וְכָל זֶה אִם צַדִּיק בָּעוֹלָם הַזֶּה לְתַקֵּן הַגּוּף כָּרָאוּי וּלְהַכְנִיעַ (ולאסף) הַחֹזֶק שֶׁל אוֹתוֹ הַמְקֻלָּל. עַד שֶׁנִּפְרַד מִמֶּנּוּ מַה כָּתוּב? וַיְהִי רִיב בֵּין רֹעֵי מִקְנֵה אַבְרָם וּבֵין רֹעֵי מִקְנֵה לוֹט (זה יצר הרע), שֶׁבְּכָל יוֹם וָיוֹם בָּעוֹלָם הַזֶּה הֵם מְסַיְּעִים וּמַנְהִיגִים אֶת הַנְּשָׁמָה, וְהֵם מְסַיְּעִים וּמַנְהִיגִים אֶת הַיֵּצֶר הָרָע, הֵם מְקַטְרְגִים בְּקִטְרוּג אֵלּוּ עִם אֵלּוּ, וְכָל הָאֵיבָרִים שֶׁל הַגּוּף בְּצַעַר בֵּינֵיהֶם, בֵּין הַנְּשָׁמָה לְאוֹתוֹ הַנָּחָשׁ שֶׁנִּלְחָמִים בִּקְרָב בְּכָל יוֹם.</p>\n<p>מַה כָּתוּב? וַיֹּאמֶר אַבְרָם אֶל לוֹט. הַנְּשָׁמָה חוֹזֶרֶת לַיֵּצֶר הָרָע וְאוֹמֶרֶת לוֹ, אַל נָא תְהִי מְרִיבָה בֵּינִי וּבֵינֶךְ וּבֵין רֹעַי וּבֵין רוֹעֶיךְ, הַצְּדָדִים שֶׁלִּי וְהַצְּדָדִים שֶׁלְּךְ, כִּי אֲנָשִׁים אַחִים אֲנָחְנוּ. יֵצֶר הַטּוֹב וְיֵצֶר הָרָע קְרוֹבִים זֶה עִם זֶה. זֶה לְיָמִין וְזֶה לִשְׂמֹאל.</p>\n<p>הֲלֹא כָל הָאָרֶץ לְפָנֶיךְ הִפָּרֶד נָא מֵעָלָי. רַבִּים הָרְשָׁעִים בָּעוֹלָם, לֵךְ וְשׁוֹטֵט אַחֲרֵיהֶם וְהִפָּרֵד מֵעִמִּי. אִם הַשְּׂמֹאל וְאֵימִנָה וְגוֹ'. וּמוֹכִיחַ אוֹתוֹ וּמֵצִיק לוֹ בְּכַמָּה קְרָבוֹת שֶׁעוֹשֶׂה עִמּוֹ בְּכָל יוֹם, עַד שֶׁכָּתוּב וַיִּפָּרְדוּ אִישׁ מֵעַל אָחִיו.</p>\n<p>כֵּיוָן שֶׁנִּפְרָדִים זֶה מִזֶּה מַה כָּתוּב? אַבְרָם יָשַׁב בְּאֶרֶץ כְּנָעַן. מִתְיַשֶּׁבֶת הַנְּשָׁמָה עִם אוֹתָם הַצַּדִּיקִים בְּיִשּׁוּב טוֹב בְּשָׁלוֹם. וְלוֹט יָשַׁב בְּעָרֵי הַכִּכָּר. אוֹתוֹ הַמְקֻלָּל הַמְקַטְרֵג הוֹלֵךְ לְקַטְרֵג וּלְהִתְחַבֵּר בְּמָקוֹם שֶׁהָרְשָׁעִים שָׁם, שֶׁכָּתוּב וַיֶּאֱהַל עַד סְדם. מַה כָּתוּב אַחֲרָיו? וְאַנְשֵׁי סְדם רָעִים וְחַטָּאִים לַה' מְאֹד. שָׁם שָׁרוּי וְשָׂם דִּיּוּרוֹ בֵּינֵיהֶם לְהִתְחַבֵּר עִמָּהֶם לְהָסִיט אוֹתָם וּלְאַבֵּד אוֹתָם. (ואברהם במעשים טובים, בתשובה, ובתורה) (חסר) (במעשים רעים).</p>\n<p>(כיון שנשארת הנשמה בלי מקטרג ונטהר הגוף מאותה הזהמה, מיד הקדוש ברוך הוא משרה את דיורו עמו ויורש נחלה עליונה ותחתונה, ויש לו נחת בין הצדיקים, והמקלל ההוא בין אותם הרשעים חוטאים עמו, עד שאין פדות לחטאיהם,)</p>\n<p>(מה כתוב? וישמע אברם, זו הנשמה שנשארה בטהר הגוף, כי נשבה אחיו זה יצר הרע שנשבה בין אותם הרשעים בחטאים רבים, וירק את חניכיו ילידי ביתו אלו הם הצדיקים שעוסקים בתורה, שהם האיברים של הגוף הזריזים ללכת עמו, שמנה עשר ושלש מאות אלו רמ\"ח איברי הגוף, ושבעים של סוד הנשמה שיוצאת משם,) בַּכֹּל מִזְדָּרֵז לָלֶכֶת לְשָׁם לְאוֹתָם הָרְשָׁעִים לְהָשִׁיב אוֹתָם (מחטאם) מֵחֲטָאֵיהֶם.</p>\n<p>מַה כָּתוּב? וַיִּרְדֹּף עַד דָּן. רוֹדֵף אַחֲרֵיהֶם וּמוֹדִיעַ לָהֶם אֶת דִּין הָעוֹלָם הַהוּא וְעֹנֶשׁ הַגֵּיהִנֹּם, וְלֹא נוֹתֵן שֵׁנָה לְעֵינוֹ בַּיּוֹם וּבַלַּיְלָה עַד שֶׁמּוֹכִיחַ אוֹתָם אֶת אוֹתָם הָרְשָׁעִים, וּמֵשִׁיב אוֹתָם בִּתְשׁוּבָה לַקָּדוֹשׁ-בָּרוּךְ-הוּא. מַה כָּתוּב? וַיָּשֶׁב אֵת כָּל הָרְכֻשׁ. הֵשִׁיב אוֹתָם בִּתְשׁוּבָה שְׁלֵמָה כָּרָאוּי.</p>\n<p>וְגַם אֶת לוֹט אָחִיו וְגוֹ' - אֲפִלּוּ אֶת אוֹתוֹ יֵצֶר הָרָע מַחֲזִיק עִמּוֹ, עַד שֶׁמַּכְנִיעוֹ בְּעַל כָּרְחוֹ (ולא) וּמַמְתִּיק אוֹתוֹ כָּרָאוּי. וְהַכֹּל מֵשִׁיב בִּתְשׁוּבָה שְׁלֵמָה כָּרָאוּי, מִכֵּיוָן שֶׁלֹּא יִשְׁקֹט יוֹמָם וָלַיְלָה, עַד שֶׁמּוֹכִיחַ אוֹתָם וְרוֹדֵף אוֹתָם עַל אוֹתוֹ הַחֵטְא שֶׁחָטְאוּ עַד שֶׁשָּׁבִים בִּתְשׁוּבָה שְׁלֵמָה כָּרָאוּי.</p>\n<p>חָזַרְנוּ לַדְּבָרִים הָרִאשׁוֹנִים שֶׁל הַפָּרָשָׁה. כָּתוּב (שיר ג) מְצָאוּנִי הַשּּׁמְרִים הַ בְבִים בָּעִיר וְגוֹ'. (שנינו, כדגמה שרמוז באברהם ויצחק ושרה ורבקה יהו\"ה, כדגמה הזו רמוז בפסוק הזה (רות א) ושם האיש אלימלך ושם אשתו נעמי ושם שני בניו מחלון וכליון אפרתים, אלימל\"ך זו הנשמה לנשמה, נעמ\"י זו הנשמה, ולמה נקראת נעמי? משום (תהלים צ) ויהי נעם ה' אלהינו, מחלון זו רוח הקדש, ולמה נקרא מחלון? שמחל לו הקדוש ברוך הוא, רו\"ת זו הנפש הקדושה, ולמה נקראת רו\"ת? על שם תו\"ר, כליו\"ן זו רוח הבהמ\"ה, ועל זה אמר שלמה עליו השלום (קהלת ג) רוח הבהמה, זה יצ\"ר הר\"ע, ערפ\"ה זו נפש השמאל, בת זוגו של היצר הרע, ולמה נקראת ערפה? משום כי עם קשה ערף הוא. אם זכה אדם עולה הנשמה העליונה, ואם לא מסתלקים אותם דוברי הנשמה והרוח, ונשארת הנשמה העליונה והנפש השכלית, מה כתוב? (רות א) ותצא מן המקום אשר היתה שמה ושתי כלתיה עמה, ותאמר נעמי לכלתיה שבנה בנתי וגו', ותאמר רות אל תפגעי בי וגו', וערפה שבה לעמה ולאלהיה). שנינו, עשה הקדוש ברוך הוא ירושלים של מעלה כמו ירושלים של מטה, בחומות ומגדלים ופתחים פתוחים, ואותן החומות ששם יש עליהם שומרים ששומרים את השערים של אותן החומות, שכתוב, (ישעיה סב) עַל חוֹמֹתַיִךְ יְרוּשָׁלַיִם הִפְקַדְתִּי שֹׁמְרִים וְגוֹ'. וּמִיכָאֵל כֹּהֵן גָּדוֹל עֶלְיוֹן מִכֻּלָּם, שׁוֹמֵר פְּתָחִים שֶׁל אֵלּוּ הַחוֹמוֹת.</p>\n<p>הַנְּשָׁמָ\"ה (שנקראת נעמ\"י), כְּשֶׁיּוֹצֵאת מִן הָעוֹלָם הַזֶּה, אִם זוֹכָה - נִכְנֶסֶת לְגַן הָעֵדֶן שֶׁל הָאָרֶץ שֶׁנָּטַע הַקָּדוֹשׁ בָּרוּךְ הוּא לְרוּחוֹת הַצַּדִּיקִים כְּמוֹ אוֹתוֹ גַּן עֵדֶן שֶׁלְּמַעְלָה, וְשָׁם כָּל הַצַּדִּיקִים שֶׁל הָעוֹלָם.</p>\n<p>וּכְשֶׁהַנְּשָׁמָה יוֹצֵאת מִן הָעוֹלָם הַזֶּה, נִכְנֶסֶת לִמְעָרַת הַמַּכְפֵּלָה שֶׁשָּׁם הוּא פֶּתַח גַּן הָעֵדֶן. פּוֹגֶשֶׁת בְּאָדָם הָרִאשׁוֹן וּבְאוֹתָם הָאָבוֹת שֶׁשָּׁם. אִם הִיא זוֹכָה - שְׂמֵחִים בָּהּ וּפוֹתְחִים לָהּ פְּתָחִים וְנִכְנֶסֶת, וְאִם לֹא - דּוֹחִים אוֹתָהּ הַחוּצָה (ומה היא אומרת כשדוחים אותה החוצה? (שיר ג) מצאוני השומרים וגו', והולכת, אחר שהולכת שם מלפני שבאה לעולם הזה ונתון נר על ראשו, שנאמר (איוב כט) בהלו נרו עלי ראשי, כל מי שרואים אותה מזדעזעים ואומרים הזאת נעמי?) (היא משיבה ואומרת, (רות א) אל תקראנה לי נעמי קראן לי מרא וגו', אני מלאה הלכתי באותו מקום, וריקם השיבני ה' בלי תורה ובלי מעשים טובים, שהכניס אותי לגוף רע, למה תקראנה לי נעמי וה' ענה בי). ואם זוכה, נכנסת לגן עדן. כיון שנכנסת, יושבת שם בגן (מזדוגת עם אלימלך, זה מחלון, שזה הרוח מזדוג עם רות, שזו הנפש השכלית) והתלבשו (ד\"א ומתלבשת) שם בלבוש של הדמות של העולם הזה ושם מתעדנת.</p>"],[9522011191,"<p>סֵתֶר הַסְּתָרִים נִמְסָר לְחַכְמֵי הַלֵּב. (ארבע) שָׁלֹשׁ דְּרָגוֹת הֵן שֶׁאֲחוּזוֹת זוֹ בְּזוֹ, וְאֵלּוּ הֵן נֶפֶשׁ (נשמה לנשמה, הנשמה העליונה שנקראת יו\"ד) רוּ\"חַ וּנְשָׁמָה. (נפ\"ש) הַנֶּפֶשׁ הִיא הַכֹּחַ שֶׁהַגּוּף נִבְנֶה מִמֶּנּוּ. שֶׁכַּאֲשֶׁר הָאָדָם מִתְעוֹרֵר בָּעוֹלָם הַזֶּה לְהִזְדַּוֵּג עִם נְקֵבָתוֹ, כָּל אֵיבָרָיו מַסְכִּימִים (נ\"א: מתכנסים) וְנִתְקָנִים לֵהָנוֹת (לנשמה) שָׁם, וְאוֹתָהּ הַנֶּפֶשׁ וְהָרָצוֹן שֶׁלּוֹ מַסְכִּים עִם אוֹתוֹ הַמַּעֲשֶׂה (ממש), וּמוֹשֵׁךְ אֶת אוֹתָהּ הַנֶּפֶשׁ וּמַכְנִיס אוֹתָהּ שָׁם בְּאוֹתוֹ הַזֶּרַע שֶׁשּׁוֹפֵךְ.</p>\n<p>וּמִתּוֹךָ רָצוֹן וְהַמְשָׁכַת הַנֶּפֶשׁ שֶׁמּוֹשֵׁךְ לְשָׁם, נִמְשָׁךְ כֹּחַ אַחֵר לְשָׁם מֵאוֹתָן הַדְּרָגוֹת שֶׁנִּקְרָאוֹת אִישִׁי\"ם, וְהַכֹּל נִכְנָס בִּמְשִׁיכַת הַזֶּרַע הַהוּא וְנִבְנֶה מִמֶּנּוּ הַגּוּף. וְזֶהוּ הַכֹּחַ הָרִאשׁוֹן הַתַּחְתּוֹן שֶׁל אוֹתָם (ארבע) שָׁלֹשׁ.</p>\n<p>וּמִשּׁוּם שֶׁ את (נשמה לנשמה) הַנֶּפֶשׁ נִקְרֶבֶת בִּדְבֵקוּת וְהַיְסוֹד שֶׁל הַגּוּף, הַקָּרְבָּן שֶׁנִּקְרָב לְכַפֵּר עַל הַנְּשָׁמָה נִתָּן חֵלֶק לְאוֹתָם הַדְּרָגוֹת שֶׁל אִישִׁי\"ם (שנקראו רוח ונפש השכלית), מִשּׁוּם שֶׁמְּשִׁיכַת הַחֵלֶק שֶׁל אוֹתָהּ (נשמה) הַנֶּפֶשׁ בָּאָה מֵהֶם. וְהַיְנוּ שֶׁכָּתוּב אֶת קָרְבָּנִי לַחְמִי לְאִשַּׁי (מהו לחמי לאשי? שנותן מזון לאשי, וזהו שפע מאור שהם נהנים מזיו השכינה), מִשּׁוּם שֶׁהוּאא כַּפָּרַת הַנֶּפֶשׁ נוֹטְלִים חֶלְקָם. וּכְשֶׁמֵּת אָדָם בָּעוֹלָם הַזֶּה, אוֹתָהּ הַנֶּפֶשׁ לֹא זָזָה מִן הַקֶּבֶר לְעוֹלָמִים, וּבַכֹּחַ הַזֶּה יוֹדְעִים הַמֵּתִים וּמְסַפְּרִים זֶה עִם זֶה.</p>\n<p>הָרוּחַ הִיא שֶׁמְּקַיֶּמֶת אֶת הַנֶּפֶשׁ בָּעוֹלָם הַזֶּה, וְהִיא מְשִׁיכַת הִתְעוֹרְרוּת הַנְּקֵבָה לַזָּכָר כְּשֶׁהֵם בִּתְשׁוּקָה אַחַת. וְאָז מִתְעוֹרֶרֶת לַזָּכָר בִּתְשׁוּקָתָהּ לָרוּחַ הַזּוֹ כְּמוֹ שֶׁהַנְּקֵבָה כְּלַפֵּי מַטָּה שׁוֹפֶכֶת זֶרַע בִּתְשׁוּקָה אֶל הַזָּכָר. וְהַסֵּתֶר הַזֶּה (כשנשפך שפע בתשוקה לנקבה, וכאן סוד) (קהלת יב) וְהָרוּחַ תָּשׁוּב אֶל הָאֱלֹהִים אֲשֶׁר נְתָנָהּ.</p>\n<p>וְהָרוּ\"חַ הַזּוֹ (ונפ\"ש ונשמ\"ה ונשמ\"ה לנשמה כאשר), כְּשֶׁיּוֹצֵאת מִן הָעוֹלָם הַזֶּה וְנִפְרֶדֶת מִן הַנֶּפֶשׁ (נפרדים י\"ה מסתלק לגן עדן בשמים העליונים, ומתלבש בדמות עליונה מרקמת מכל הגונים) נִכְנָס לְגַן הָעֵדֶן שֶׁבָּעוֹלָם הַזֶּה (התחתון), וּמִתְלַבֵּשׁ שָׁם בְּתוֹךְ הָאֲוִיר שֶׁל הַגָּן כְּמוֹ שֶׁמִּתְלַבְּשִׁים הַמַּלְאָכִים הָעֶלְיוֹנִים כְּשֶׁיּוֹרְדִים לָעוֹלָם הַזֶּה, מִשּׁוּם שֶׁהֵם מֵאוֹתָהּ הָרוּחַ הָיוּ, שֶׁכָּתוּב (תהלים קד) עֹשֶׂה מַלְאָכָיו רוּחוֹת וְגוֹ'.</p>\n<p>אַף כָּךְ הָרוּחַ מִתְלַבֶּשֶׁת בְּגַן הָעֵדֶן שֶׁל הָאָרֶץ בִּדְמוּת הָעוֹלָם הַזֶּה, וְשָׁם מִתְעַדֶּנֶת בְּכָל הָעִדּוּנִים. בְּגַן הָעֵדֶן הַזֶּה יֵשׁ צִיּוּרִים וּדְמֻיּוֹת שֶׁל הָעוֹלָם הַזֶּה, וְיֵשׁ צִיּוּרִים וּדְמֻיּוֹת שֶׁל הָעוֹלָם הָעֶלְיוֹן, וְשָׁם כָּל אוֹתָם הַצַּדִּיקִים הוֹלְכִים וּמִתְעַדְּנִים שָׁם. וּבְרָאשֵׁי חֳדָשִׁים וְשַׁבָּתוֹת הֵם רוֹצִים לַעֲלוֹת לְמַעְלָה (הדמות הזו מרו\"ח וא\"ש של העולם הזה, ובדמות הזו מתעדנים בכל העדונים, ובכל המועדי\"ם והחדשי\"ם והשבתו\"ת מסתלקים הרו\"ח והנפ\"ש ומתפשטים מהגוף הזה ומתלבשים בדמות עליונה בגן העדן שלמעלה מרקם בכל הגונים, באיזה מקום הוא י\"ה? בלבושו, ומזדוגים יחד יהו\"ה, והם נהנים מאור השכינה). וּבְאֶמְצַע הַגָּן יֵשׁ עַמּוּד אֶחָד מְרֻקָּם בְּכָל הַגְּוָנִים, וּכְשֶׁאוֹתָהּ הָרוּחַ כַּאֲשֶׁר רוֹצָה לַעֲלוֹת, מִתְפַּשֶּׁטֶת שָׁם מֵהַלְּבוּשׁ הַהוּא (והנפש נשארת שם בגוף) וְנִכְנֶסֶת לְתוֹךְ אוֹתוֹ הָעַמּוּד (ועולה) וְעוֹלֶה לְמַעְלָה לְתוֹךְ אוֹתוֹ הַמָּקוֹם שֶׁיָּצְאָה מִמֶּנּוּ, כַּכָּתוּב וְהָרוּחַ תָּשׁוּב וְגוֹ'.</p>\n<p>וְנוֹטֵל אוֹתָהּ מִיכָאֵל הַכֹּהֵן הַגָּדוֹל, וּמַקְרִיב אוֹתָהּ קָרְבַּן בְּשָׂמִים לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא, (ובאה) וְיוֹשֶׁבֶת שָׁם, וּמִתְעַדֶּנֶת בְּאוֹתוֹ צְרוֹר הַחַיִּים, (ישעיה סד) שֶׁעַיִן לֹא רָאָתָה אֱלֹהִים זוּלָתְךְ וְגוֹ'. אַחַר כָּךְ יוֹרֶדֶת לְתוֹךְ הַגָּן שֶׁל הָאָרֶץ וּמִתְעַדֶּנֶת בְּכָל הָעִדּוּנִים, וּמִתְלַבֶּשֶׁת בַּלְּבוּשׁ הַהוּא (ומזדוגת עם נפשו), וְיוֹשֶׁבֶת שָׁם בְּעִטּוּר שֶׁל אֶחָד פִּי שְׁנַיִם מִכַּמָּה שֶׁהָיְתָה בָּרִאשׁוֹנָה. (וזהו בחל, ועולה לישיבות של גן העדן ומתעסקת בתורה, ובכל ראשי חדשים ומועדים ושבתות יורדת להזדוג עם הנפש).</p>\n<p>הַנְּשָׁמָה הִיא כֹּחַ עֶלְיוֹן עַל כָּל אֵלּוּ, וְהִיא מִכֹּחַ הַזָּכָר, הַסּוֹד שֶׁל עֵץ הַחַיִּים. וְזוֹ עוֹלָה לְמַעְלָה מִיָּד, וְכָל אֵלּוּ (אותן) שְׁלֹשׁ הַדְּרָגוֹת נִקְשָׁרוֹת יַחַד זֶה עִם זֶה. וּכְשֶׁנִּפְרָדוֹת, כֻּלָּן עוֹלוֹת וְשָׁבוֹת לְאוֹתוֹ מָקוֹם שֶׁיָּצְאוּ מִמֶּנּוּ.</p>\n<p>כְּשֶׁהָרוּחַ הַזּוֹ יוֹצֵאת מִן הָעוֹלָם הַזֶּה וְנִכְנֶסֶת לַמְּעָרָה שֶׁשָּׁם אָדָם וְהָאָבוֹת, הֵם נוֹתְנִים לָהּ פִּנְקָס סִימָן, וְנִכְנֶסֶת לְגַן הָעֵדֶן. קְרֵבָה לְשָׁם, וּמוֹצֵאת הַכְּרוּבִים וְאוֹתָהּ לַהַט הַחֶרֶב הַמִּתְהַפֶּכֶת. אִם זוֹכָה - רוֹאִים פִּנְקָס הַסִּימָן, וּפוֹתְחִים לָהּ פֶּתַח וְנִכְנֶסֶת. וְאִם לֹא - דּוֹחִים אוֹתָהּ הַחוּצָה.</p>\n<p>וְיוֹשֶׁבֶת שָׁם. כָּל אוֹתוֹ הַזְּמַן שֶׁיּוֹשֶׁבֶת, מִתְלַבֶּשֶׁת שָׁם בִּדְמוּת שֶׁל הָעוֹלָם הַזֶּה. וּבְרָאשֵׁי חֳדָשִׁים וְשַׁבָּתוֹת כְּשֶׁרוֹצָה לַעֲלוֹת, הַצַּדִּיקִים שֶׁבְּגַן עֵדֶן נוֹתְנִים לָהּ פִּנְקָס סִימָן וְעוֹלָה בָּעַמּוּד הַהוּא, וּפוֹגֶשֶׁת אֶת אוֹתָם שׁוֹמְרֵי חוֹמוֹת יְרוּשָׁלַיִם. אִם זוֹכָה - פּוֹתְחִים לָהּ פֶּתַח וְנִכְנֶסֶת, וְאִם לֹא - נוֹטְלִים מִמֶּנָּה אוֹתוֹ הַפִּנְקָס וְדוֹחִים אוֹתָהּ הַחוּצָה. הִיא שָׁבָה לַגָּן וְאוֹמֶרֶת, (שיר ג) מְצָאוּנִי הַשֹּׁמְרִים הַסֹּבְבִים בָּעִיר וְגוֹ', נָשְׂאוּ אֶת רְדִידִי מֵעָלַי. זֶהוּ פִּנְקָס הַסִּימָן שֶׁנָּטְלוּ מִמֶּנּוּ (ממנה). שׁוֹמְרֵי הַחוֹמוֹת, אֵלּוּ אוֹתָם שׁוֹמְרֵי חוֹמוֹת יְרוּשָׁלַיִם. (כדגמה הזו, הנשמה לנשמה מתפשטת מאותו הלבוש שלמעלה ומסתלקת למעלה למעלה ונהנית מאור השכינה, והנשמה (והנפש) נשארת בגוף, ובכל ראשי החדשים והמועדים והשבתות יורדת נשמה לנשמה ומזדוגת עם הנשמה שנשארה בגוף ומזדוגת עם הנשמה, והדמות של גן העדן שלמעלה היתה מן הרוח והעפר שנכר לגבי מעלה, וסוד חשוב הוא, ובלבוש זה מתלבש י\"ה לבוש של גן עדן שלמטה, הוא אש ומים, שנאמר שמים, עד כאן הרוח של השמאל היורדת למטה, יורדת לדרגתה, ונפשה נשארת בגוף של הארץ, שכתוב (איוב יד) אך בשרו עליו יכאב וגו', ועל זה אמרו שהמתים יודעים בעולם הבא מכבוד הצדיקים ומהעולם התחתון ומספרים זה עם זה), עד כָּאן סתרי תורָה,</p>"],[9522011192,"<p>וַיֵּרֶד אַבְרָם מִצְרַיְמָה לָגוּר שָׁם. מָה הַטַּעַם לְמִצְרַיִם? אֶלָּא מִשּׁוּם שֶׁשָּׁקוּל לְגַן ה', שֶׁכָּתוּב כְּגַן ה' כְּאֶרֶץ מִצְרַיִם. שֶׁשָּׁם שָׁקַל וְיָרַד נָהָר אֶחָד שֶׁהוּא לְיָמִין, שֶׁכָּתוּב (בראשית ב) שֵׁם הָאֶחָד פִּישׁוֹן הוּא הַסֹּבֵב אֵת כָּל אֶרֶץ הַחֲוִילָה אֲשֶׁר שָׁם הַזָּהָב.</p>\n<p>וְאַבְרָהָם כֵּיוָן שֶׁיָּדַע וְנִכְנַס בָּאֱמוּנָה הַשְּׁלֵמָה, רָצָה לָדַעַת כָּל אוֹתָן הַדְּרָגוֹת שֶׁנֶּאֶחְזוּ לְמַטָּה. וּמִצְרַיִם הָיָה נוֹסֵעַ מִיָּמִין (ד\"א לימין), וּמִשּׁוּם כָּךְ יָרַד לְמִצְרַיִם. וּבֹא וּרְאֵה, הָרָעָב לֹא נִמְצָא בָאָרֶץ אֶלָּא כַּאֲשֶׁר מִסְתַּלְּקִים רַחֲמִים מִן הַדִּין.</p>\n<p>וַיְהִי כַּאֲשֶׁר הִקְרִיב לָבא מִצְרָיְמָה. אָמַר רַבִּי אֶלְעָזָר, כַּאֲשֶׁר הִקְרִיב? כַּאֲשֶׁר קָרַב הָיָה צָרִיךְ לִהְיוֹת! מַה זֶּה כַּאֲשֶׁר הִקְרִיב? אֶלָּא כַּכָּתוּב (שמות יד) וּפַרְעֹה הִקְרִיב, שֶׁהוּא קֵרַב אֶת יִשְׂרָאֵל לִתְשׁוּבָה. אַף כָּאן הִקְרִיב, שֶׁהִקְרִיב אֶת עַצְמוֹ לַקָּדוֹשׁ-בָּרוּךְ-הוּא כָּרָאוּי. לָבֹא מִצְרָיְמָה, לְהִתְבּוֹנֵן בְּאוֹתָן הַדְּרָגוֹת וּלְהִתְרַחֵק מֵהֶן וּלְהִתְרַחֵק מִמַּעֲשֵׂי מִצְרַיִם.</p>\n<p>אָמַר רַבִּי יְהוּדָה, בֹּא רְאֵה, כֵּיוָן (ס\"א משום) שֶׁיָּרַד אַבְרָהָם לְמִצְרַיִם בְּלִי רְשׁוּת, הִשְׁתַּעְבְּדוּ בָנָיו בְּמִצְרַיִם אַרְבַּע מֵאוֹת שָׁנָה, שֶׁהֲרֵי כָּתוּב וַיֵּרֶד אַבְרָהָם מִצְרָיְמָה, וְלֹא כָתוּב רֵד מִצְרַיִם, וְהִצְטַעֵר כָּל הַלַּיְלָה הַהוּא בִּשְׁבִיל שָׂרָה.</p>\n<p>וַיֹּאמֶר אֶל שָׂרַי אִשְׁתּוֹ הִנֵּה נָא יָדַעְתִּי כִּי אִשָּׁה יְפַת מַרְאֶה אָתְּ. וְכִי עַד הַשָּׁעָה הַהִיא לֹא הָיָה יוֹדֵעַ אַבְרָהָם שֶׁהָיְתָה אִשָּׁה יְפַת מַרְאֶה? אֶלָּא זֶה פֵּרְשׁוּהָ, שֶׁעַד הַשָּׁעָה הַהִיא לֹא הִסְתַּכֵּל בִּדְמוּת שָׂרָה מֵרֹב הַצְּנִיעוּת שֶׁהָיְתָה בֵינֵיהֶם. וּכְשֶׁקָּרַב לְמִצְרַיִם, הִיא הִתְגַּלְּתָה וְרָאָה אוֹתָהּ.</p>\n<p>דָּבָר אַחֵר, בַּמֶּה יָדַע? אֶלָּא עַל יְדֵי טֹרַח הַדֶּרֶךְ אָדָם מִתְבַּזֶּה, וְהִיא עָמְדָה בְּיָפְיָהּ וְלֹא הִשְׁתַּנְּתָה. דָּבָר אַחֵר הִנֵּה נָא יָדַעְתִּי, שֶׁרָאָה עִמָּהּ אֶת הַשְּׁכִינָה, וּמִשּׁוּם כָּךְ בָּטַח אַבְרָהָם וְאָמַר אֲחֹתִי אָתְּ.</p>\n<p>וְזֶה הַדָּבָר עוֹלֶה לִשְׁנֵי גְוָנִים - אֶחָד כְּמַשְׁמָעוֹ, וְאֶחָד כַּכָּתוּב (משלי ז) אֱמֹר לַחָכְמָה אֲחֹתִי אָתְּ, וְכָתוּב (דברים ה) וְאַתְּ תְּדַבֵּר אֵלֵינוּ. לְמַעַן יִיטַב לִי בַּעֲבוּרֵךְ - כְּלַפֵּי שְׁכִינָה אָמַר, בַּעֲבוּרֵךְ יֵיטִיב לִי הַקָּדוֹשׁ בָּרוּךְ הוּא. וְחָיְתָה נַפְשִׁי בִּגְלָלֵךְ, מִשּׁוּם שֶׁבָּזֶה יִתְעַלֶּה אָדָם וְיִזְכֶּה לְהִתְעַלּוֹת לְדֶרֶךְ הַחַיִּים.</p>\n<p>אִמְרִי נָא אֲחֹתִי וְגוֹ'. רַבִּי יֵיסָא אָמַר, יוֹדֵעַ הָיָה אַבְרָהָם שֶׁכָּל הַמִּצְרִים שְׁטוּפִים הֵם בְּזִמָּה, וְכֵיוָן שֶׁכָּל זֶה יָדַע, לָמָּה לֹא פָחַד עַל אִשְׁתּוֹ שֶׁלֹּא חָזַר מִן הַדֶּרֶךְ וְלֹא יִכָּנֵס לְשָׁם? אֶלָּא מִשּׁוּם שֶׁרָאָה עִמָּהּ שְׁכִינָה.</p>"],[9522011193,"<p>וַיְהִי כְּבוֹא אַבְרָם מִצְרָיְמָה וַיִּרְאוּ הַמִּצְרִים אֶת הָאִשָּׁה כִּי יָפָה הִוא מְאֹד. אָמַר רַבִּי יְהוּדָה, הִכְנִיס אוֹתָהּ בְּתֵבָה, וּפָתְחוּ אוֹתָהּ לָקַחַת מִמֶּנָּה מֶכֶס. כֵּיוָן שֶׁנִּפְתַּח, הָיָה אוֹר כְּאוֹר הַשֶּׁמֶשׁ. זֶהוּ שֶׁכָּתוּב כִּי יָפָה הִוא מְאֹד.</p>\n<p>מַה זֶּה מְאֹד? אֶלָּא שֶׁרָאוּ בַּתֵּבָה דְּמוּת (נ\"א: אור) אַחֶרֶת. הוֹצִיאוּ אוֹתָהּ וְרָאוּ אוֹתָהּ כְּבַתְּחִלָּה. זֶהוּ שֶׁכָּתוּב וַיִּרְאוּ אֹתָהּ שָׂרֵי פַרְעֹה. כֵּיוָן שֶׁכָּתוּב וַיִּרְאוּ הַמִּצְרִים אֶת הָאִשָּׁה, מַה זֶּה וַיִּרְאוּ אֹתָהּ שָׂרֵי פַרְעֹה? אֶלָּא שֶׁהוֹצִיאוּ אוֹתָהּ וְרָאוּ אוֹתָהּ כְּבַתְּחִלָּה, וְאָז וַיְהַלֲלוּ אֹתָהּ אֶל פַּרְעֹה וְגוֹ'.</p>\n<p>אָמַר רַבִּי יִצְחָק, אוֹי לְאוֹתָם רִשְׁעֵי הָעוֹלָם שֶׁלֹּא יוֹדְעִים וְלֹא מַשְׁגִּיחִים בְּמַעֲשֵׂי הַקָּדוֹשׁ בָּרוּךְ הוּא, וְהֵם לֹא מִסְתַּכְּלִים (בכל) שֶׁכָּל מַה שֶּׁיֵּשׁ בָּעוֹלָם הוּא מֵעִם הַקָּדוֹשׁ בָּרוּךְ הוּא, שֶׁהוּא יוֹדֵעַ בַּתְּחִלָּה מַה שֶּׁיִּהְיֶה בַּסּוֹף, שֶׁכָּתוּב (ישעיה מו) מַגִּיד מֵרֵאשִׁית אַחֲרִית. וְהוּא צוֹפֶה וְעוֹשֶׂה מַעֲשִׂים בָּרִאשׁוֹנָה כְּדֵי לְהַעֲלוֹתָם לְאַחַר יָמִים.</p>\n<p>בֹּא רְאֵה, אִלְמָלֵא שֶׁנִּטְּלָה שָׂרַי לְפַרְעֹה, הוּא לֹא הָיָה מֻלְקֶה. וְהַהַלְקָאָה הַזּוֹ גָּרְמָה הַלְקָאָה לְאַחַר מִכֵּן שֶׁיִּלְקוּ מִצְרַיִם בִּנְגָעִים גְּדוֹלִים. כָּתוּב כָּאן נְגָעִים גְּדלִים, וְכָתוּב שָׁם (דברים ו) וַיִּתֵּן ה' אוֹתֹת וּמֹפְתִים גְּדלִים וְרָעִים בְּמִצְרַיִם. מַה לְּהַלָּן עֶשֶׂר מַכּוֹת - אַף כָּאן עֶשֶׂר מַכּוֹת. כְּמוֹ שֶׁעָשָׂה הַקָּדוֹשׁ בָּרוּךְ הוּא נִסִּים וּגְבוּרוֹת לְיִשְׂרָאֵל בַּלַּיְלָה - אַף כָּאן עָשָׂה הַקָּדוֹשׁ בָּרוּךְ הוּא לְשָׂרָה נִסִּים וּגְבוּרוֹת בַּלַּיְלָה.</p>\n<p>רַבִּי יוֹסֵי פָּתַח וְאָמַר, (תהלים ג) וְאַתָּה ה' מָגֵן בַּעֲדִי כְּבוֹדִי וּמֵרִים רֹאשִׁי. אָמַר דָּוִד, אַף עַל גַּב שֶׁכָּל בְּנֵי הָעוֹלָם יָבוֹאוּ לַעֲרֹךְ עִמִּי קְרָב - וְאַתָּה ה' מָגֵן בַּעֲדִי. בּא רְאֵה, כָּתוּב מָגֵן בַּעֲדִי. אָמַר דָּוִד לַקָּדוֹשׁ-בָּרוּךְ-הוּא: רִבּוֹנוֹ שֶׁל עוֹלָם, מִפְּנֵי מָה לֹא עוֹשִׂים בִּי חֲתִימָה שֶׁל בְּרָכָה כְּמוֹ שֶׁחוֹתְמִים בְּרָכָה בְּאַבְרָהָם, שֶׁכָּתוּב אָנֹכִי מָגֵן לָךְ, וְאוֹמְרִים מָגֵן אַבְרָהָם?</p>\n<p>אָמַר הַקָּדוֹשׁ בָּרוּךְ הוּא לְדָוִד: אַבְרָהָם כְּבָר בְּחַנְתִּיו וּצְרַפְתִּיו, וְעוֹמֵד לְפָנַי בְּקִיּוּם שָׁלֵם. אָמַר לוֹ דָּוִד: אִם כָּךְ, (שם כו) בְּחָנֵנִי ה' וְנַסֵּנִי צָרְפָה כִלְיוֹתַי וְלִבִּי. כֵּיוָן שֶׁעָשָׂה אוֹתוֹ הַדָּבָר שֶׁל בַּת שֶׁבַע, נִזְכַּר דָּוִד לְפָנָיו עַל מַה שֶּׁאָמַר. אָמַר (שם יז) בָּחַנְתָּ לִבִּי פָּקַדְתָּ לַּיְלָה צְרַפְתַּנִי בַל תִּמְצָא זַמֹּתִי בַּל יַעֲבָר פִּי.</p>\n<p>אָמַר, אֲנִי אָמַרְתִּי בְּחָנֵנִי ה' וְנַסֵּנִי, וְאַתָּה בָּחַנְתָּ לִבִּי. אֲנִי אָמַרְתִּי צָרְפָה כִלְיוֹתַי, וְאַתָּה צְרַפְתַּנִי בַל תִּמְצָא, לֹא מָצָאתָ אוֹתִי כָּרָאוּי. זַמֹּתִי בַּל יַעֲבָר פִּי - מִי יִתֵּן וְהַדָּבָר הַזֶּה שֶׁחָשַׁבְתִּי, שֶׁלֹּא יַעֲבֹר אֶת פִּי.</p>\n<p>וְעִם כָּל זֶה חוֹתְמִים בּוֹ הַבְּרָכָה, שֶׁאָנוּ אוֹמְרִים מָגֵן דָּוִד. וּמִשּׁוּם כָּךְ אָמַר דָּוִד, וְאַתָּה ה' מָגֵן בַּעֲדִי כְּבוֹדִי וּמֵרִים רֹאשִׁי. (וזה) וַדַּאי דַּרְגָּה זוֹ הַכָּבוֹד שֶׁלִּי שֶׁאֲנִי מִתְעַטֵּר בּוֹ.</p>\n<p>וַיְצַו עָלָיו פַּרְעֹה אֲנָשִׁים וַיְשַׁלְּחוּ אֹתוֹ. בֹּא רְאֵה, הַקָּדוֹשׁ בָּרוּךְ הוּא מָגֵן לַצַּדִּיקִים שֶׁלֹּא יִשְׁלְטוּ בָהֶם בְּנֵי אָדָם, וְהַקָּדוֹשׁ בָּרוּךְ הוּא הֵגֵן עַל אַבְרָהָם שֶׁלֹּא יִשְׁלְטוּ בוֹ וּבְאִשְׁתּוֹ.</p>\n<p>בֹּא רְאֵה, הַשְּׁכִינָה לֹא זָזָה מִשָּׂרָה כָּל הַלַּיְלָה הַהוּא. בָּא פַּרְעֹה לִקְרַב אֵלֶיהָ - בָּא הַמַּלְאָךְ וְהִלְקָה אוֹתוֹ. כָּל פַּעַם שֶׁאָמְרָה שָׂרָה הַלְקֵה - הָיָה מַלְקֶה. וְאַבְרָהָם הָיָה מַחֲזִיק בְּרִבּוֹנוֹ, שֶׁהֲרֵי עַל שָׂרָה לֹא יָכְלוּ לִשְׁלֹט עָלֶיהָ. זֶהוּ שֶׁכָּתוּב (משלי כח) וְצַדִּיקִים כִּכְפִיר יִבְטָח. וְכָאן הַנִּסָּיוֹן שֶׁלֹּא הִרְהֵר אַחַר הַקָּדוֹשׁ בָּרוּךְ הוּא.</p>\n<p>אָמַר רַבִּי יִצְחָק, בֹּא רְאֵה שֶׁמִּשּׁוּם כָּךְ לֹא צִוָּה הַקָּדוֹשׁ בָּרוּךְ הוּא לָרֶדֶת לְמִצְרַיִם, אֶלָּא הוּא עַצְמוֹ מֵעַצְמוֹ יָרַד, כְּדֵי שֶׁלֹּא יִהְיֶה פִּתְחוֹן פֶּה לִבְנֵי הָעוֹלָם שֶׁאָמַר לוֹ כֵּן, וְאַחַר כָּךְ הִצְטַעֵר עַל אִשְׁתּוֹ.</p>\n<p>רַבִּי יִצְחָק פָּתַח וְאָמַר, (תהלים צב) צַדִּיק כַּתָּמָר יִפְרָח כְּאֶרֶז בַּלְּבָנוֹן יִשְׂגֶּה. צַדִּיק כַּתָּמָר יִפְרָח, מִפְּנֵי מָה הִקִּישׁ צַדִּיק לְתָמָר? מַה תָּמָר כֵּיוָן שֶׁגּוֹזְרִים אוֹתוֹ לֹא עוֹלֶה עַד זְמַן רַב - אַף כָּךְ צַדִּיק, כֵּיוָן שֶׁאָבַד מִן הָעוֹלָם, לֹא עוֹלֶה אַחֵר תַּחְתָּיו עַד זְמַן רַב. כְּאֶרֶז בַּלְּבָנוֹן יִשְׂגֶּה - אַף כָּךְ גַּם.</p>\n<p>כַּתָּמָר יִפְרָח - מַה תָּמָר לֹא עוֹלֶה אֶלָּא זָכָר וּנְקֵבָה, אַף כָּךְ הַצַּדִּיק לֹא עוֹלֶה אֶלָּא זָכָר וּנְקֵבָה. הַזָּכָר צַדִּיק וְהַנְּקֵבָה צַדֶּקֶת, כְּמוֹ שֶׁאַבְרָהָם וְשָׂרָה.</p>\n<p>כְּאֶרֶז בַּלְּבָנוֹן יִשְׂגֶּה - מָה הָאֶרֶז בַּלְּבָנוֹן עֶלְיוֹן עַל הַכֹּל וְהַכֹּל יוֹשְׁבִים תַּחְתָּיו - אַף כָּךְ הַצַּדִּיק הוּא עֶלְיוֹן עַל הַכֹּל וְהַכֹּל יוֹשְׁבִים תַּחְתָּיו. וְהָעוֹלָם אֵינוֹ עוֹמֵד אֶלָּא עַל צַדִּיק אֶחָד, שֶׁכָּתוּב (משלי י) וְצַדִּיק יְסוֹד עוֹלָם. וְעָלָיו הָעוֹלָם עוֹמֵד, וּבִגְלָלוֹ נִסְמָךְ, וְעָלָיו נִשְׁתָּל.</p>\n<p>רַבִּי יְהוּדָה אָמַר, וַהֲרֵי שָׁנִינוּ שֶׁעַל שִׁבְעָה עַמּוּדִים הָעוֹלָם עוֹמֵד, כַּכָּתוּב (שם ט) חָצְבָה עַמּוּדֶיהָ שִׁבְעָה. אָמַר לוֹ רַבִּי יוֹסֵי, כָּךְ הוּא וַדַּאי, אֲבָל (כאן) כָּל הָאֲחֵרִים בַּשְּׁבִיעִי הֵם עוֹמְדִים, שֶׁהוּא סֶמֶךְ שֶׁל הָעוֹלָם, וְהוּא צַדִּיק, וְזֶה מַשְׁקֶה (את העולם) וּמַרְוֶה אֶת הָעוֹלָם (מן הכל) וְזָן לַכֹּל, וְעָלָיו כָּתוּב (ישעיה ג) אִמְרוּ צַדִּיק כִּי טוֹב כִּי פְרִי מַעַלְלֵיהֶם יֹאכֵלוּ, וְכָתוּב (תהלים קמה) טוֹב ה' לַכֹּל וְרַחֲמָיו עַל כָּל מַעֲשָׂיו.</p>\n<p>אָמַר רַבִּי יִצְחָק, הֲרֵי כָּתוּב (בראשית ב) וְנָהָר יֹצֵא מֵעֵדֶן לְהַשְׁקוֹת אֶת הַגָּן. זֶה הוּא הָעַמּוּד שֶׁהָעוֹלָם עוֹמֵד עָלָיו וְהוּא מַשְׁקֶה לַגָּן (העדן), וְהַגָּן נִשְׁקֶה מִמֶּנּוּ, וּמִמֶּנּוּ עוֹשֶׂה פֵרוֹת. וְכָל הַפֵּרוֹת פּוֹרְחִים בָּעוֹלָם וְהֵם הַקִּיּוּם שֶׁל הָעוֹלָם, הַקִּיּוּם שֶׁל הַתּוֹרָה. וּמִי הֵם? נִשְׁמוֹת הַצַּדִּיקִים שֶׁהֵם פְּרִי מַעֲשָׂיו שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא. וּמִשּׁוּם כָּךְ בְּכָל לַיְלָה וְלַיְלָה נִשְׁמוֹת הַצַּדִּיקִים עוֹלוֹת.</p>"],[9522011194,"<p>וּכְשֶׁנֶּחֱלָק הַלַּיְלָה, הַקָּדוֹשׁ בָּרוּךְ הוּא בָּא לְגַן הָעֵדֶן לְהִשְׁתַּעֲשֵׁעַ בָּהֶם. בְּמִי? אָמַר רַבִּי יוֹסֵי, בְּכֻלָּם. בֵּין אוֹתָם שֶׁמְּדוֹרָם בָּעוֹלָם הַהוּא, וּבֵין אוֹתָם שֶׁיּוֹשְׁבִים בִּמְדוֹרָם בָּעוֹלָם הַזֶּה, בְּכֻלָּם מִשְׁתַּעֲשֵׁעַ הַקָּדוֹשׁ בָּרוּךְ הוּא בַּחֲצוֹת הַלַּיְלָה.</p>\n<p>בֹּא רְאֵה, הָעוֹלָם שֶׁלְּמַעְלָה צָרִיךְ אֶת הִתְעוֹרְרוּתוֹ שֶׁל הָעוֹלָם הַתַּחְתּוֹן. וּכְשֶׁנִּשְׁמוֹת הַצַּדִּיקִים יוֹצְאוֹת מִן הָעוֹלָם הַזֶּה וְעוֹלוֹת לְמַעְלָה, כֻּלָּן מִתְלַבְּשׁוֹת בָּאוֹר שֶׁלְּמַעְלָה בִּדְמוּת נִכְבָּדָה, וּבָהֶם הַקָּדוֹשׁ בָּרוּךְ הוּא מִשְׁתַּעֲשֵׁעַ וְתָאֵב לָהֶם, שֶׁהֵם פְּרִי מַעֲשָׂיו, וְעַל זֶה נִקְרְאוּ יִשְׂרָאֵל שֶׁיֵּשׁ לָהֶם נְשָׁמוֹת קְדוֹשׁוֹת בָּנִים לַקָּדוֹשׁ- בָּרוּךְ-הוּא, כְּמוֹ שֶׁנֶּאֱמַר (דברים יד) בָּנִים אַתֶּם לַה' אֱלֹהֵיכֶם. בָּנִים וַדַּאי, פְּרִי מַעֲשָׂיו.</p>\n<p>אָמַר רַבִּי יֵיסָא, אֲפִלּוּ אוֹתָם שֶׁבָּעוֹלָם הַזֶּה (של הארץ). אֵיךְ? אָמַר לוֹ, מִשּׁוּם שֶׁבַּחֲצוֹת הַלַּיְלָה כָּל אוֹתָם צַדִּיקֵי אֱמֶת, כֻּלָּם מִתְעוֹרְרִים לִקְרֹא בַתּוֹרָה וְלִשְׁמֹעַ אֶת תִּשְׁבְּחוֹת הַתּוֹרָה. וַהֲרֵי נִתְבָּאֵר שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא וְכָל אוֹתָם הַצַּדִּיקִים שֶׁבְּתוֹךְ גַּן הָעֵדֶן כֻּלָּם מַקְשִׁיבִים לְקוֹלָם, וְחוּט שֶׁל חֶסֶד נִמְשָׁךְ עֲלֵיהֶם בַּיּוֹם, שֶׁכָּתוּב (תהלים מב) יוֹמָם יְצַוֶּה ה' חַסְדּוֹ וּבַלַּיְלָה שִׁירֹה עִמִּי.</p>\n<p>וְעַל כֵּן הַתִּשְׁבָּחוֹת שֶׁעוֹלוֹת בַּלַּיְלָה לְפָנָיו, זוֹ תִשְׁבַּחַת שְׁלֵמָה. בּא רְאֵה, בְּשָׁעָה שֶׁיִּשְׂרָאֵל הָיוּ סְגוּרִים בְּבָתֵּיהֶם כְּשֶׁהָרַג הַקָּדוֹשׁ בָּרוּךְ הוּא בִּבְכוֹרֵי מִצְרַיִם, הָיוּ אוֹמְרִים הַלֵּל וְתִשְׁבָּחוֹת לְפָנָיו.</p>\n<p>בֹּא רְאֵה שֶׁדָּוִד הַמֶּלֶךְ הָיָה קָם בַּחֲצוֹת הַלַּיְלָה, שֶׁאִם תֹּאמַר שֶׁהָיָה יוֹשֵׁב אוֹ שׁוֹכֵב בְּמִטָּתוֹ וְהָיָה אוֹמֵר שִׁירוֹת וְתִשְׁבָּחוֹת - לֹא, אֶלָּא כְּמוֹ שֶׁכָּתוּב (שם קיט) חֲצוֹת לַיְלָה אָקוּם לְהוֹדוֹת לָךְ. אָקוּם וַדַּאי בַּעֲמִידָה לְהִתְעַסֵּק בְּשִׁירוֹת וְתִשְׁבָּחוֹת שֶׁל הַתּוֹרָה.</p>\n<p>וּמִשּׁוּם כָּךְ דָּוִד הַמֶּלֶךְ חַי לְעוֹלָמִים, וַאֲפִלּוּ בִּימֵי מֶלֶךְ הַמָּשִׁיחַ הוּא מֶלֶךְ. שֶׁהֲרֵי שָׁנִינוּ, מֶלֶךְ הַמָּשִׁיחַ, אִם מִן הַחַיִּים הוּא - דָּוִד שְׁמוֹ, וְאִם מִן הַמֵּתִים הוּא - דָּוִד שְׁמוֹ. וְהוּא הָיָה מִתְעוֹרֵר</p>"],[9522011195,"<p>בַּבֹּקֶר בְּטֶרֶם יָבא, שֶׁכָּתוּב (שם נז) עוּרָה כְבוֹדִי עוּרָה הַנֵּבֶל וְכִנּוֹר אָעִירָה שָּׁחַר. בֹּא רְאֵה, כָּל אוֹתוֹ הַלַּיְלָה שֶׁשָּׂרָה הָיְתָה אֵצֶל פַּרְעֹה, בָּאוּ הַמַּלְאָכִים הָעֶלְיוֹנִים לְזַמֵּר לַקָּדוֹשׁ-בָּרוּךְ- הוּא בְּשִׁירוֹת וְתִשְׁבָּחוֹת. אָמַר לָהֶם הַקָּדוֹשׁ בָּרוּךְ הוּא: כֻּלְּכֶם לְכוּ וַעֲשׂוּ מַכּוֹת גְּדוֹלוֹת בְּמִצְרַיִם, סִימָן לְמִי שֶׁאֲנִי עָתִיד לַעֲשׂוֹת אַחַר כָּךְ. זֶה מַה שֶּׁכָּתוּב וַיְנַגַּע ה' אֶת פַּרְעֹה נְגָעִים גְּדֹלִים וְגוֹ'</p>\n<p>בֹּא רְאֵה מַה כָּתוּב, וַיִּקְרָא פַרְעֹה לְאַבְרָם וְגוֹ'. מִנַּיִן הָיָה יוֹדֵעַ, שֶׁהֲרֵי לֹא כָתוּב כָּאן כְּמוֹ שֶׁנֶּאֱמַר בַּאֲבִימֶלֶךְ, שֶׁכָּתוּב וְעַתָּה הָשֵׁב אֵשֶׁת הָאִישׁ כִּי נָבִיא הוּא וְגוֹ', וְכָאן לֹא אָמַר לוֹ דָּבָר?</p>\n<p>אָמַר רַבִּי יִצְחָק, הֲרֵי כָּתוּב עַל דְּבַר שָׂרַי אֵשֶׁת אַבְרָם. שֶׁכָּךְ הָיוּ אוֹמְרִים לוֹ: עַל דְּבַר שָׂרַי אֵשֶׁת אַבְרָם. שֶׁהֲרֵי לֹא הָיָה מְדַבֵּר עִמּוֹ כְּמוֹ שֶׁמְּדַבֵּר עִם אֲבִימֶלֶךְ, אֶלָּא בְּדָבָר זֶה נִתְבָּאֵר וְלֹא יוֹתֵר: הַמַּכָּה הַזּוֹ הִיא עַל דְּבַר שָׂרַי אֵשֶׁת אַבְרָם. וְלֹא הָיָה מְדַבֵּר (זה) עִמּוֹ. אָז (הוא) יָדַע שֶׁזּוֹ אִשְׁתּוֹ שֶׁל אַבְרָהָם הִיא. מִיָּד - וַיִּקְרָא פַרְעֹה לְאַבְרָם וַיֹּאמֶר וְגוֹ'.</p>\n<p>וַיְצַו עָלָיו פַּרְעֹה אֲנָשִׁים, לָמָּה? כְּדֵי שֶׁלֹּא יִקְרַב אָדָם לָהֶם לְהָרַע לָהֶם. וַיְשַׁלְּחוּ אֹתוֹ, לְוָיָה עָשׂוּ לוֹ בְּכָל אֶרֶץ מִצְרַיִם. אָמַר לוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא: כָּךְ אַתָּה עָתִיד לַעֲשׂוֹת לְבָנָיו, אַתָּה תְלַוֶּה אוֹתָם מֵאַרְצְךְ, שֶׁכָּתוּב (שמות יג) וַיְהִי בְשַׁלַּח פַּרְעֹה אֶת הָעָם, שֶׁלִּוָּה אוֹתָם מִכָּל אַרְצוֹ.</p>\n<p>אָמַר רַבִּי אַבָּא, כָּל כָּךְ לָמָּה הִזְדַּמֵּן לְאַבְרָהָם וּלְמַה הִצְטָרֵךְ? אֶלָּא כְּדֵי לְגַדֵּל אֶת שְׁמָם שֶׁל אַבְרָהָם וְשָׂרָה בָּעוֹלָם, שֶׁאֲפִלּוּ בְּמִצְרַיִם שֶׁהֵם מְכַשְּׁפֵי הָעוֹלָם, וְלֹא יָכוֹל הָיָה אָדָם לְהִנָּצֵל מֵהֶם, הִתְגַּדֵּל אַבְרָהָם וְהִתְעַלָּה לְמַעְלָה. זֶהוּ שֶׁכָּתוּב וַיַּעַל אַבְרָם מִמִּצְרַיִם. לְאֵיזֶה מָקוֹם? הַנֶּגְבָּה (ומה זה הוא ואשתו וכל אשר לו? אלא להודיע שלא גזלו ממנו דבר מאותן מתנות שנתנו לו בשביל שרה שתהיה למלך).</p>\n<p>אָמַר רַבִּי שִׁמְעוֹן, בּא רְאֵה, הַכֹּל הוּא סוֹד שֶׁל חָכְמָה, וְרָמַז כָּאן בַּחָכְמָה וְהַדְּרָגוֹת שֶׁלְּמַטָּה שֶׁאַבְרָהָם יָרַד לְעָמְקָם וְיָדַע אוֹתָם, וְלֹא נִדְבַּק בָּהֶם, וְשָׁב לִפְנֵי רִבּוֹנוֹ,</p>\n<p>וְלֹא הִתְפַּתָּה בָהֶם כְּאָדָם שֶׁכַּאֲשֶׁר הִגִּיעַ לַדַּרְגָּה הַהִיא הִתְפַּתָּה בַּנָּחָשׁ וְגָרַם מָוֶת לָעוֹלָם. וְלֹא הִתְפַּתָּה כְּמוֹ נֹחַ, שֶׁכַּאֲשֶׁר יָרַד וְהִגִּיעַ לַדַּרְגָּה הַהִיא מַה כָּתוּב? (בראשית ט) וַיֵּשְׁתְּ מִן הַיַּיִן וַיִּשְׁכָּר וַיִּתְגַּל בְּתוֹךְ אָהֳלֹה. אָהֳלֹה כָּתוּב בְּהֵ\"א.</p>\n<p>אֲבָל בְּאַבְרָהָם מַה כָּתוּב? וַיַּעַל אַבְרָם מִמִּצְרַיִם. שֶׁעָלָה וְלֹא יָרַד, וְשָׁב לִמְקוֹמוֹ לְדַרְגָּה עֶלְיוֹנָה שֶׁנִּדְבַּק בָּהּ כְּבָרִאשׁוֹנָה. וְהַמַּעֲשֶׂה הַזֶּה הָיָה כְּדֵי לְהַרְאוֹת הַחָכְמָה שֶׁהִתְקַיֵּם בְּקִיּוּם שָׁלֵם כָּרָאוּי לוֹ וְלֹא הִתְפַּתָּה, וְעָמַד בְּקִיּוּם וְשָׁב לִמְקוֹמוֹ. הַנֶּגְבָּה - זֶה הַדָּרוֹם, הַדַּרְגָּה הָעֶלְיוֹנָה שֶׁנֶּאֱחַז בָּהּ כְּבָרִאשׁוֹנָה, שֶׁכָּתוּב הָלוֹךְ וְנָסוֹעַ הַנֶּגְבָּה. אַף כָּאן הַנֶּגְבָּה - מָקוֹם שֶׁנִּדְבַּק בּוֹ בָּרִאשׁוֹנָה.</p>\n<p>בֹּא רְאֵה סוֹד הַדָּבָר, אִם אַבְרָם לֹא יֵרֵד לְמִצְרַיִם וְלֹא יִצְטָרֵף שָׁם בָּרִאשׁוֹנָה, לֹא יִהְיֶה חֵלֶק גּוֹרָלוֹ בַּקָּדוֹשׁ-בָּרוּךְ-הוּא. כְּמוֹ זֶה לְבָנָיו, כְּשֶׁרָצָה הַקָּדוֹשׁ בָּרוּךְ הוּא לַעֲשׂוֹת לוֹ (ד\"א להם) עַם אֶחָד, עַם שָׁלֵם, וּלְקָרְבָם אֵלָיו, אִם לֹא יֵרְדוּ בָּרִאשׁוֹנָה לְמִצְרַיִם וְלֹא יִזְדַּכְּכוּ שָׁם, לֹא הָיוּ הָעָם הַיְחִידִי שֶׁלּוֹ.</p>\n<p>כְּמוֹ כֵן אִם לֹא נִתְּנָה הָאָרֶץ הַקְּדוֹשָׁה לִכְנַעַן בָּרִאשׁוֹנָה וְיִשְׁלֹט בָּהּ, לֹא הָיְתָה הָאָרֶץ חֶלְקוֹ וְגוֹרָלוֹ שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא, וְהַכֹּל סוֹד אֶחָד.</p>"],[9522011196,"<p>רַבִּי שִׁמְעוֹן הָיָה הוֹלֵךְ בַּדֶּרֶךְ, וְהָיָה עִמּוֹ רַבִּי אֶלְעָזָר בְּנוֹ, וְרַבִּי אַבָּא וְרַבִּי יְהוּדָה. בְּעוֹדָם הוֹלְכִים, אָמַר רַבִּי שִׁמְעוֹן, תְּמֵהַנִי אֵיךְ בְּנֵי הָעוֹלָם לֹא מַשְׁגִּיחִים לָדַעַת דִּבְרֵי תוֹרָה וְעַל מָה עוֹמְדִים. פָּתַח וְאָמַר, (ישעיה כו) נַפְשִׁי אִוִּיתִךְ בַּלַּיְלָה אַף רוּחִי בְקִרְבִּי אֲשַׁחֲרֶךָּ. הַפָּסוּק הַזֶּה בֵּאֲרוּהוּ וּבֵאַרְנוּ אוֹתוֹ. אֲבָל בּא רְאֵה, נֶפֶשׁ הָאָדָם, כְּשֶׁהוּא עוֹלֶה לְמִטָּתוֹ, יוֹצֵאת מִמֶּנּוּ וְעוֹלָה לְמַעְלָה. וְאִם תֹּאמַר שֶׁכֻּלָּן עוֹלוֹת - אֵין כָּל אֶחָד וְאֶחָד רוֹאֶה אֶת פְּנֵי הַמֶּלֶךְ, אֶלָּא הַנֶּפֶשׁ עוֹלָה וְלֹא נִשְׁאָר בָּהּ עִם הַגּוּף, רַק רֹשֶׁם (נשימה) שֶׁל הַמִּדָּה שֶׁל חַיּוּת הַלֵּב.</p>\n<p>וְהַנֶּפֶשׁ הוֹלֶכֶת וְרוֹצָה לַעֲלוֹת. וְכַמָּה דְרָגוֹת לִדְרָגוֹת לַעֲלוֹת, הִיא מְשׁוֹטֶטֶת וּפוֹגֶשֶׁת בַּקְּלִפּוֹת שֶׁל אוֹרוֹת הַטֻּמְאָה. אִם הִיא טְהוֹרָה, שֶׁלֹּא נִטְמְאָה בַיּוֹם, עוֹלָה לְמַעְלָה. וְאִם לֹא טְהוֹרָה, נִטְמֵאת בֵּינֵיהֶם וְנִדְבֶּקֶת בָּהֶם וְלֹא עוֹלָה יוֹתֵר.</p>\n<p>וְשָׁם מוֹדִיעִים לָהּ דְּבָרִים, וְנִדְבֶּקֶת מֵאוֹתָם דְּבָרִים שֶׁל זְמַן קָרוֹב. וְלִפְעָמִים שֶׁצּוֹחֲקִים עָלֶיהָ וּמוֹדִיעִים לָהּ דְּבָרִים כּוֹזְבִים. וְאָז הוֹלֶכֶת כְּמוֹ זֶה כָּל הַלַּיְלָה עַד שֶׁיִּתְעוֹרֵר הָאִישׁ, וְשָׁבָה לִמְקוֹמָהּ. אַשְׁרֵי הַצַּדִּיקִים שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא מְגַלֶּה לָהֶם סוֹדוֹתָיו בַּחֲלוֹם כְּדֵי שֶׁיִּשָּׁמְרוּ מִן הַדִּין. אוֹי לְאוֹתָם רִשְׁעֵי הָעוֹלָם שֶׁמְּטַמְּאִים עַצְמָם וְנַפְשָׁם.</p>\n<p>בֹּא רְאֵה, אוֹתָם שֶׁלֹּא נִטְמְאוּ, כְּשֶׁעוֹלִים לְמִטָּתָם, הַנֶּפֶשׁ עוֹלָה וְנִכְנֶסֶת בֵּין כָּל אוֹתָן הַדְּרָגוֹת בָּרִאשׁוֹנָה, וְעוֹלָה וְלֹא נִדְבֶּקֶת בָּהֶן. אַחַר כָּךְ הוֹלֶכֶת וּמְשׁוֹטֶטֶת וְעוֹלָה כְּפִי דַרְכָּהּ.</p>\n<p>אוֹתָהּ הַנֶּפֶשׁ שֶׁזּוֹכָה לַעֲלוֹת, נִרְאֵית לִפְנֵי סֵבֶר פְּנֵי הַיָּמִים, וְנִדְבֶּקֶת בְּרָצוֹן לְהֵרָאוֹת בִּתְשׁוּקָה עֶלְיוֹנָה לִרְאוֹת בְּנֹעַם הַמֶּלֶךְ וּלְבַקֵּר בְּהֵיכָלוֹ. וְזֶה הוּא הָאִישׁ שֶׁיֵּשׁ לוֹ חֵלֶק תָּמִיד בָּעוֹלָם הַבָּא.</p>\n<p>וְזוֹ הִיא הַנֶּפֶשׁ שֶׁהַכִּסּוּף שֶׁלָּהּ כְּשֶׁעוֹלָה בַּקָּדוֹשׁ-בָּרוּךְ-הוּא (תמיד) וְלֹא נִדְבֶּקֶת בַּמִּינִים הַלָּלוּ אוֹרוֹת הָאֲחֵרִים, וְהִיא הוֹלֶכֶת אַחַר מִין קָדוֹשׁ בְּמָקוֹם (אחר מקום) שֶׁיּוֹצֵאת מִשָּׁם. וּמִשּׁוּם כָּךְ כָּתוּב נַפְשִׁי אִוִּיתִךְ בַּלַּיְלָה, כְּדֵי לִרְדֹּף אַחֲרֶיךְ וְלֹא לְהִתְפַּתּוֹת אַחַר מִין אַחֵר נָכְרִי.</p>"],[9522011197,"<p>בֹּא רְאֵה, נַפְשִׁי - זוֹ הַנֶּפֶשׁ שֶׁשּׁוֹלֶטֶת בַּלַּיְלָה לִרְדֹּף אַחַר הַדַּרְגָּה שֶׁלָּהּ. הָרוּחַ בַּיּוֹם, שֶׁכָּתוּב נַפְשִׁי אִוִּיתִךְ בַּלַּיְלָה, זוֹ הַנֶּפֶשׁ שֶׁשּׁוֹלֶטֶת בַּלַּיְלָה. אַף רוּחִי בְקִרְבִּי אֲשַׁחֲרֶךָּ - זוֹ הָרוּחַ שֶׁשּׁוֹלֶטֶת בַּיּוֹם.</p>\n<p>וְאִם תֹּאמַר שֶׁשְּׁתֵּי דְרָגוֹת הֵן בְּפֵרוּד - לֹא כָּךְ, שֶׁהֲרֵי הֵן דַּרְגָּה אַחַת, וְהֵן שְׁתַּיִם בְּחִבּוּר אֶחָד, וְאַחַת עֶלְיוֹנָה שֶׁשּׁוֹלֶטֶת עֲלֵיהֶן וְנִדְבֶּקֶת בָּהֶן וְהֵן בָּהּ (ונקראים) וְנִקְרֵאת נְשָׁמָה.</p>\n<p>וְכָל הַדְּרָגוֹת עוֹלוֹת בְּסוֹד הַחָכְמָה. שֶׁכְּשֶׁמִּסְתַּכְּלִים עַל אֵלּוּ הַדְּרָגוֹת, יִסְתַּכֵּל הָאָדָם בַּחָכְמָה הָעֶלְיוֹנָה, וְהַנְּשָׁמָה הַזּוֹ נִכְנֶסֶת בָּהֶם וְנִדְבָּקִים בָּהּ. וּכְשֶׁזֶּה שׁוֹלֵט, אָז אוֹתוֹ הָאִישׁ נִקְרָא קָדוֹשׁ, שָׁלֵם מִן הַכֹּל. רָצוֹן אֶחָד לַקָּדוֹשׁ-בָּרוּךְ-הוּא.</p>\n<p>הַנֶּפֶ\"שׁ הִיא הִתְעוֹרְרוּת תַּחְתּוֹנָה, וְזוֹ סְמוּכָה בַּגּוּף וְזָנָה אוֹתוֹ, וְהַגּוּף אוֹחֵז בָּהּ וְהִיא אֲחוּזָה בַּגּוּף. אַחַר כָּךְ נִתְקֶנֶת וְנַעֲשֵׂית כִּסֵּא לְהַשְׁרוֹת עָלֶיהָ רוּחַ בְּהִתְעוֹרְרוּת הַנֶּפֶשׁ הַזֹּאת שֶׁנֶּאֱחֶזֶת בַּגּוּף, כַּכָּתוּב (ישעיה לב) עַד יֵעָרֶה עָלֵינוּ רוּחַ מִמָּרוֹם.</p>\n<p>לְאַחַר שֶׁמְּתַקְנִים אֶת שְׁנֵיהֶם, עֲתִידִים לְקַבֵּל נְשָׁמָה, שֶׁהֲרֵי הָרוּחַ נַעֲשֵׂית כִּסֵּא לַנְּשָׁמָה לְהַשְׁרוֹת עָלֶיהָ, וְהַנְּשָׁמָה הַזּוֹ הִיא נִסְתֶּרֶת עֶלְיוֹנָה עַל הַכֹּל טְמוּנַת כָּל הַטְּמוּנִים.</p>\n<p>נִמְצָא שֶׁיֵּשׁ (לה) כִּסֵּא לַכִּסֵּא, וְכִסֵּא לָעֶלְיוֹן עֲלֵיהֶם. וּכְשֶׁתִּסְתַּכֵּל בַּדְּרָגוֹת, תִּמְצָא סוֹד הַחָכְמָה בַּדָּבָר הַזֶּה, וְהַכֹּל הִיא חָכְמָה לְהַדְבִּיק בַּגָּוֶן הַזֶּה דְּבָרִים נִסְתָּרִים.</p>\n<p>בֹּא רְאֵה, הַנֶּפֶשׁ הִיא הִתְעוֹרְרוּת תַּחְתּוֹנָה שֶׁנִּדְבֶּקֶת בַּגּוּף, כְּמוֹ הָאוֹר שֶׁל הַמָּאוֹר, שֶׁהָאוֹר הַתַּחְתּוֹן שֶׁהוּא שָׁחֹר, נִדְבָּק בַּפְּתִילָה וְלֹא נִפְרָד מִמֶּנָּה וְלֹא נִתְקָן אֶלָּא בָּהּ. וּכְשֶׁנִּתְקָן בַּפְּתִילָה, נַעֲשֶׂה כִסֵּא לָאוֹר הָעֶלְיוֹן הַלָּבָן שֶׁשּׁוֹרֶה עַל אוֹתוֹ הָאוֹר הַשָּׁחֹר.</p>\n<p>אַחַר כָּךְ כְּשֶׁשְּׁנֵיהֶם נִתְקָנִים, נַעֲשֶׂה אוֹתוֹ אוֹר לָבָן כִּסֵּא לָאוֹר הַנִּסְתָּר שֶׁאֵינוֹ נִרְאֶה וְאֵינוֹ נוֹדָע מַה שֶּׁשָּׁרָה עַל אוֹתוֹ הָאוֹר הַלָּבָן, וְאָז הָאוֹר שָׁלֵם. וְכָךְ הָאָדָם שֶׁהוּא שָׁלֵם בַּכֹּל, וְאָז נִקְרָא קָדוֹשׁ, כְּמוֹ שֶׁנֶּאֱמַר (תהלים טז) לִקְדוֹשִׁים אֲשֶׁר בָּאָרֶץ הֵמָּה וְגוֹ'. כְּמוֹ כֵן בְּסוֹד עֶלְיוֹן.</p>\n<p>בֹּא רְאֵה, בְּשָׁעָה שֶׁאַבְרָהָם נִכְנַס לָאָרֶץ, נִרְאָה לוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא, כְּמוֹ שֶׁנֶּאֱמַר לַה' הַנִּרְאֶה אֵלָיו, וְקִבֵּל שָׁם נֶפֶשׁ וּבָנָה מִזְבֵּחַ לַדַּרְגָּה הַהִיא. אַחַר כָּךְ הָלוֹךְ וְנָסוֹעַ הַנֶּגְבָּה, שֶׁקִּבֵּל רוּחַ. אַחַר כָּךְ (עד) שֶׁעָלָה לְהִתְדַּבֵּק תּוֹךְ הַנְּשָׁמָה, אָז וַיִּבֶן שָׁם מִזְבֵּחַ לַה', סְתָם. זוֹ הִיא הַנְּשָׁמָה שֶׁהִיא נִסְתֶּרֶת כָּל הַנִּסְתָּרִים.</p>\n<p>אַחַר כָּךְ יָדַע שֶׁצָּרִיךְ לְהִצָּרֵף וּלְהִתְעַטֵּר בַּדְּרָגוֹת, מִיָּד - וַיֵּרֶד אַבְרָם מִצְרָיְמָה, וְנִצַּל מִשָּׁם, וְלֹא הִתְפַּתָּה תּוֹךְ אוֹתָם הָאוֹרוֹת, וְנִצְרַף וְשָׁב לִמְקוֹמוֹ. כֵּיוָן שֶׁיָּרַד וְנִצְרַף, מִיָּד - וַיַּעַל אַבְרָם מִמִּצְרַיִם. עָלָה וַדַּאי וְשָׁב לִמְקוֹמוֹ וְנִדְבַּק בָּאֱמוּנָה הָעֶלְיוֹנָה, שֶׁכָּתוּב הַנֶּגְבָּה.</p>\n<p>מִכָּאן וָהָלְאָה יָדַע אַבְרָהָם הַחָכְמָה הָעֶלְיוֹנָה וְנִדְבַּק בַּקָּדוֹשׁ- בָּרוּךְ-הוּא, וְנַעֲשָׂה הַיָּמִין שֶׁל הָעוֹלָם. אָז, וְאַבְרָם כָּבֵד מְאֹד בַּמִּקְנֶה בַּכֶּסֶף וּבַזָּהָב. כָּבֵד מְאֹד - בְּצַד הַמִּזְרָח. בַּמִּקְנֶה - בְּצַד הַמַּעֲרָב. בַּכֶּסֶף - מִצַּד הַדָּרוֹם. בַּזָּהָב - מִצַּד הַצָּפוֹן.</p>\n<p>בָּאוּ רַבִּי אֶלְעָזָר וְרַבִּי אַבָּא וְכָל הַחֲבֵרִים וְנִשְּׁקוּ אֶת יָדוֹ. בָּכָה רַבִּי אַבָּא וְאָמַר, וַי וַי, כְּשֶׁתִּסְתַּלֵּק מִן הָעוֹלָם, מִי יָאִיר אֶת אוֹר הַתּוֹרָה? אַשְׁרֵי חֶלְקָם שֶׁל הַחֲבֵרִים שֶׁשּׁוֹמְעִים דִּבְרֵי תוֹרָה הַלָּלוּ מִפִּיךְ.</p>"],[9522011198,"<p>אָמַר רַבִּי שִׁמְעוֹן, בֹּא רְאֵה מַה כָּתוּב. וַיֵּלֶךְ לְמַסָּעָיו, לִפְקֹד אֶת מְקוֹמוֹ וְדַרְגָּתוֹ. לְמַסָּעָיו - לְמַסָּעוֹ כָּתוּב, מִי הַמַּסָּעוֹ? זוֹ הַדַּרְגָּה הָרִאשׁוֹנָה שֶׁרְאוּיָה לוֹ בָּרִאשׁוֹנָה. כָּתוּב כָּאן מַסָּעוֹ, וְכָתוּב שָׁם (מלכים א ו) אֶבֶן שְׁלֵמָה מַסָּע נִבְנָה. וַהֲרֵי בֵּאַרְנוּ אֶבֶן שְׁלֵמָה וַדַּאי. מַסָּע, כְּמוֹ שֶׁנִּתְבָּאֵר.</p>\n<p>וַיֵּלֶךָ לְמַסָּעָיו, כָּל אוֹתָן הַדְּרָגוֹת, דַּרְגָּה אַחַר דַּרְגָּה, כְּמוֹ שֶׁנֶּאֱמַר. מִנֶּגֶב וְעַד בֵּית אֵל, לְתַקֵּן אֶת מְקוֹמוֹ וּלְחַבְּרָם בְּיִחוּד שָׁלֵם, שֶׁהֲרֵי מִנֶּגֶב וְעַד בֵּית אֵל נִמְצָא סוֹד הַחָכְמָה כָּרָאוּי.</p>\n<p>אֶל הַמָּקוֹם אֲשֶׁר הָיָה שָׁם אָהֳלֹה בַּתְּחִלָּה, אָהֳלֹה בְּהֵ\"א. מִי אָהֳלֹה? זֶה בֵּית אֵל. אֶבֶן שְׁלֵמָה, כְּמוֹ שֶׁאָמַרְנוּ. עוֹד רָשַׁם וְאָמַר, אֶל מְקוֹם הַמִּזְבֵּחַ אֲשֶׁר עָשָׂה שָׁם בָּרִאשֹׁנָה, שֶׁכָּתוּב לַה' הַנִּרְאֶה אֵלָיו. וְאָז וַיִּקְרָא שָׁם אַבְרָם בְּשֵׁם ה', אָז נִדְבַּק בָּאֱמוּנָה הַשְּׁלֵמָה.</p>\n<p>בֹּא רְאֵה, בָּרִאשׁוֹנָה עָלָה מִמַּטָּה לְמַעְלָה, שֶׁכָּתוּב וַיֵּרָא ה' אֶל אַבְרָם, וְכָתוּב לַה' הַנִּרְאֶה אֵלָיו, וְזוֹ הַדַּרְגָּה הָרִאשׁוֹנָה כְּמוֹ שֶׁאָמַרְנוּ אֶבֶן שְׁלֵמָה (מסע נבנה, וכתוב למסעו), וְאַחַר כָּךְ הָלוֹךְ וְנָסוֹעַ הַנֶּגְבָּה, דַּרְגָּה אַחַר דַּרְגָּה, עַד שֶׁהִתְעַטֵּר בַּדָּרוֹם, חֶלְקוֹ וְגוֹרָלוֹ. אַחַר כָּךְ סָתַם הַדָּבָר כְּשֶׁעָלָה וְאָמַר לַה' סְתָם, זֶה הָעוֹלָם הָעֶלְיוֹן, וּמִשָּׁם נָסַע בַּדְּרָגוֹת וְיָרַד מִמַּעְלָה לְמַטָּה, וְהַכֹּל נִדְבַּק בִּמְקוֹמוֹ כָּרָאוּי.</p>\n<p>וְכָאן כְּשֶׁתִּסְתַּכֵּל בַּדְּרָגוֹת, תִּמְצָא אֶת סוֹד הַחָכְמָה הָעֶלְיוֹנָה. מַה כָּתוּב? וַיֵּלֶךְ לְמַסָּעָיו מִנֶּגֶב. מִצַּד הַיָּמִין, רֵאשִׁית הָעוֹלָם הָעֶלְיוֹן הַנִּסְתָּר הֶעָמֹק לְמַעְלָה עַד אֵין סוֹף. וְיָרַד דַּרְגָּה אַחַר דַּרְגָּה (עד) מִנֶּגֶב וְעַד בֵּית אֵל, מִמַּעְלָה לְמַטָּה.</p>\n<p>וְכָתוּב וַיִּקְרָא שָׁם אַבְרָם בְּשֵׁם ה'. נִדְבַּק הַיִּחוּד בִּמְקוֹמוֹ כָּרָאוּי, שֶׁכָּתוּב אֶל מְקוֹם הַמִּזְבֵּחַ אֲשֶׁר עָשָׂה שָׁם בָּרִאשֹׁנָה. מַה זֶּה אֲשֶׁר עָשָׂה שָׁם? שֶׁהֶעֱלָה אוֹתָהּ מִמַּטָּה לְמַעְלָה, וְעַכְשָׁו יָרַד בַּדְּרָגוֹת מִמַּעְלָה לְמַטָּה כְּדֵי שֶׁלֹּא תָזוּז מֵאוֹתָן הַדְּרָגוֹת הָעֶלְיוֹנוֹת וְהֵם לֹא יָזוּזוּ מִמֶּנָּה, וְיִתְיַחֵד הַכֹּל בְּיִחוּד אֶחָד כָּרָאוּי.</p>\n<p>אָז הִתְעַטֵּר אַבְרָהָם וְהָיָה לְחֵלֶק גּוֹרָלוֹ שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא וַדַּאי. אַשְׁרֵיהֶם הַצַּדִּיקִים שֶׁמִּתְעַטְּרִים בַּקָּדוֹשׁ בָּרוּךְ הוּא וְהוּא מִתְעַטֵּר בָּהֶם. אַשְׁרֵיהֶם בָּעוֹלָם הַזֶּה וְאַשְׁרֵיהֶם בָּעוֹלָם הַבָּא. עֲלֵיהֶם כָּתוּב (ישעיה ס) וְעַמֵּךְ כֻּלָּם צַדִּיקִים לְעוֹלָם יִירְשׁוּ אָרֶץ, וְכָתוּב (משלי ד) וְאֹרַח צַדִּיקִים כְּאוֹר נֹגַהּ הוֹלֵךְ וָאוֹר עַד נְכוֹן הַיּוֹם.</p>\n<p>הָלְכוּ, כְּשֶׁהִגִּיעוּ לְשָׂדֶה אֶחָד יָשְׁבוּ. פָּתַח רַבִּי שִׁמְעוֹן וְאָמַר, (תהלים כה) פְּנֵה אֵלַי וְחָנֵּנִי. בַּפָּסוּק הַזֶּה יֵשׁ לְהִסְתַּכֵּל בּוֹ, וַהֲרֵי בֵּאַרְנוּ אוֹתוֹ בְּכַמָּה מְקוֹמוֹת. אֲבָל בַּפָּסוּק הַזֶּה דְּבָרִים נִסְתָּרִים יֵשׁ בּוֹ. פְּנֵה אֵלַי - וְכִי דָוִד אָמַר פְּנֵה אֵלַי וְחָנֵּנִי?</p>\n<p>אֶלָּא בַּעֲבוּר דַּרְגָּתוֹ שֶׁהוּא מִתְעַטֵּר בָּהּ הוּא אָמַר. (שם פו) תְּנָה עֻזְּךְ לְעַבְדֶּךְ - תְּנָה עֻזְּךְ זֶה הָעֹז הָעֶלְיוֹן, כַּכָּתוּב (שמואל א ב) וְיִתֵּן עֹז לְמַלְכּוֹ. מִי מַלְכּוֹ? זֶה מֶלֶךְ סְתָם, מֶלֶךְ הַמָּשִׁיחַ. אַף כָּאן לְעַבְדֶּךְ זֶה מֶלֶךְ הַמָּשִׁיחַ, כְּמוֹ שֵׁאָמַרְנוּ מֶלֶךְ סְתָם.</p>\n<p>וְהוֹשִׁיעָֹה לְבֶן אֲמָתֶךְ - וְכִי לֹא הָיָה בֶן יִשַׁי הוּא, עַד שֶׁאָמַר בַּשֵּׁם שֶׁל אִמּוֹ וְלֹא בַּשֵּׁם שֶׁל אָבִיו? אֶלָּא הִנֵּה הֵקַמְנוּ, שֶׁכַּאֲשֶׁר יָבֹא אָדָם לְקַבֵּל דָּבָר עֶלְיוֹן לְהַזְכִּיר, צָרִיךְ לָלֶכֶת בְּדָבָר שֶׁהוּא וַדַּאי, וְעַל כֵּן הִזְכִּיר אֶת אִמּוֹ וְלֹא אֶת אָבִיו. וְעוֹד, הִנֵּה שָׁנִינוּ (שהרי) שֶׁזֶּה מֶלֶךְ כְּפִי שֶׁאָמַרְנוּ.</p>"],[9522011199,"<p>אָמַר רַבִּי שִׁמְעוֹן, בּא רְאֵה מַה כָּתוּב. וַיְהִי רִיב בֵּין רֹעֵי מִקְנֵה אַבְרָם, רִב כָּתוּב חָסֵר יוֹ\"ד. שֶׁרָצָה לוֹט לַחֲזֹר לַעֲבוֹדָה הַזָּרָה שֶׁעוֹבְדִים יוֹשְׁבֵי הָאָרֶץ, וְסוֹף הַכָּתוּב מוֹכִיחַ, שֶׁכָּתוּב וְהַכְּנַעֲנִי וְהַפְּרִזִּי אָז יֹשֵׁב בָּאָרֶץ.</p>\n<p>וּמִנַּיִן לָנוּ שֶׁלּוֹט חָזַר לְסוּרוֹ הָרָע לַעֲבוֹדָה זָרָה? שֶׁכָּתוּב וַיִּסַּע לוֹט מִקֶּדֶם. מַהוּ מִקֶּדֶם? מִקַּדְמוֹנוֹ שֶׁל עוֹלָם. כָּתוּב כָּאן וַיִּסַּע לוֹט מִקֶּדֶם, וְכָתוּב וַיְהִי בְּנָסְעָם מִקֶּדֶם. מַה לְּהַלָּן נְסִיעָה מִקַּדְמוֹנוֹ שֶׁל עוֹלָם - אַף כָּאן כֵּן.</p>\n<p>כֵּיוָן שֶׁיָּדַע אַבְרָהָם שֶׁלְּכָךְ נָטָה לִבּוֹ שֶׁל לוֹט, מִיָּד - וַיֹּאמֶר אַבְרָם אֶל לוֹט וְגוֹ' הִפָּרֶד נָא מֵעָלָי. אֵינְךְ כְּדַאי לְהִתְחַבֵּר עִמִּי. אָז נִפְרַד מִמֶּנּוּ אַבְרָהָם וְלֹא רָצָה לָלֶכֶת וּלְהִתְחַבֵּר עִמּוֹ, שֶׁכָּל מִי שֶׁמִּתְחַבֵּר לָרָשָׁע, סוֹפוֹ לָלֶכֶת אַחֲרָיו וּלְהֵעָנֵשׁ בִּגְלָלוֹ.</p>\n<p>מִנַּיִן לָנוּ? מִיהוֹשָׁפָט שֶׁהִתְחַבֵּר עִם אַחְאָב, וְאִלְמָלֵא זְכוּת אָבוֹת נֶעֱנַשׁ שָׁם, שֶׁכָּתוּב (דברי הימים ב יח) וַיִּזְעַק יְהוֹשָׁפָט. וְאָז נִצַּל, שֶׁכָּתוּב וַיְסִיתֵם אֱלֹהִים מִמֶּנּוּ,</p>\n<p>וְעַל כֵּן לֹא רָצָה אַבְרָם לָלֶכֶת עִם לוֹט. וְעִם כָּל זֶה לֹא רָצָה לוֹט לַחֲזֹר מִסּוּרוֹ הָרָע, אֶלָּא וַיִּבְחַר לוֹ לוֹט אֵת כָּל כִּכַּר הַיַּרְדֵּן וַיִּסַּע לוֹט מִקֶּדֶם. נָסַע מִקַּדְמוֹנוֹ שֶׁל הָעוֹלָם, וְלֹא רָצָה לִדְבֹּק בָּאֱמוּנָה הַשְּׁלֵמָה כְּמוֹ אַבְרָהָם.</p>\n<p>אַבְרָם יָשַׁב בְּאֶרֶץ כְּנָעַן, לְהִדָּבֵק בִּמְקוֹם הָאֱמוּנָה וְלָדַעַת הַחָכְמָה לְהִדָּבֵק בְּרִבּוֹנוֹ. וְלוֹט יָשַׁב בְּעָרֵי הַכִּכָּר וַיֶּאֱהַל עַד סְדם, עִם אוֹתָם הָרְשָׁעִים שֶׁל הָעוֹלָם שֶׁיָּצְאוּ מִתּוֹךְ הָאֱמוּנָה, שֶׁכָּתוּב וְאַנְשֵׁי סְדם רָעִים וְחַטָּאִים לַה' מְאֹד. כָּל אֶחָד נִפְרַד לְדַרְכּוֹ כָּרָאוּי. מִשּׁוּם כָּךְ אַשְׁרֵיהֶם הַחֲבֵרִים שֶׁמִּשְׁתַּדְּלִים בַּתּוֹרָה יוֹמָם וָלַיְלָה, וְהַחֲבֵרוּת שֶׁלָּהֶם עִם הַקָּדוֹשׁ בָּרוּךְ הוּא, וַעֲלֵיהֶם כָּתוּב (דברים ד) וְאַתֶּם הַדְּבֵקִים בַּה' אֱלֹהֵיכֶם חַיִּים כֻּלְּכֶם הַיּוֹם.</p>"],[9522011200,"<p>וַה' אָמַר אֶל אַבְרָם אַחֲרֵי הִפָּרֶד לוֹט מֵעִמּוֹ וְגוֹ'. רַבִּי אַבָּא פָּתַח, (יונה א) וַיָּקָם יוֹנָה לִבְרֹחַ תַּרְשִׁישָׁה מִלִּפְנֵי ה' וְגוֹ'. אוֹי לְמִי שֶׁמִּסְתַּתֵּר מִלִּפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא, שֶׁכָּתוּב בּוֹ (ירמיה כג) הֲלוֹא אֶת הַשָּׁמַיִם וְאֶת הָאָרֶץ אֲנִי מָלֵא נְאֻם ה', וְהוּא בָּא לִבְרֹחַ מִלְּפָנָיו?!</p>\n<p>אֶלָּא כָּתוּב (שיר ג) יוֹנָתִי בְּחַגְוֵי הַסֶּלַע בְּסֵתֶר הַמַּדְרֵגָה. יוֹנָתִי - זוֹ כְּנֶסֶת יִשְׂרָאֵל. בְּחַגְוֵי הַסֶּלַע - זוֹ יְרוּשָׁלַיִם שֶׁהִיא עוֹלָה עַל כָּל הָעוֹלָם. מָה הַסֶּלַע הוּא עֶלְיוֹן וְחָזָק עַל הַכֹּל, אַף יְרוּשָׁלַיִם הִיא עֶלְיוֹנָה וַחֲזָקָה עַל הַכֹּל. בְּסֵתֶר הַמַּדְרֵגָה - זֶה (בית המקדש) הַמָּקוֹם שֶׁנִּקְרָא בֵּית קָדְשֵׁי הַקְּדָשִׁים, הַלֵּב שֶׁל כָּל הָעוֹלָם.</p>\n<p>וּמִשּׁוּם כָּךְ כָּתוּב בְּסֵתֶר הַמַּדְרֵגָה, מִשּׁוּם שֶׁשָּׁם הָיְתָה הַשְּׁכִינָה נִסְתֶּרֶת, כְּמוֹ אִשָּׁה שֶׁהִיא צְנוּעָה לְבַעְלָהּ וְאֵין יוֹצֵאת מִבֵּיתָהּ הַחוּצָה, כְּמוֹ שֶׁנֶּאֱמַר (תהלים קכח) אֶשְׁתְּךְ כְּגֶפֶן פּוֹרִיָּה בְּיַרְכְּתֵי בֵיתֶךְ וְגוֹ'. כָּךְ כְּנֶסֶת יִשְׂרָאֵל אֵינָהּ שׁוֹרָה מִחוּץ לִמְקוֹמָהּ בְּסֵתֶר הַמַּדְרֵגָה אֶלָּא בִּזְמַן שֶׁל הַגָּלוּת שֶׁהִיא בְּתוֹךְ הַגָּלוּת. וּמִשּׁוּם שֶׁהִיא בַּגָּלוּת, לִשְׁאָר הָעַמִּים יֵשׁ טוֹבָה וְשַׁלְוָה יוֹתֵר.</p>\n<p>בֹּא רְאֵה, בִּזְמַן שֶׁיִּשְׂרָאֵל שׁוֹרִים בָּאָרֶץ הַקְּדוֹשָׁה, הַכֹּל הָיָה מְתֻקָּן כָּרָאוּי, וְהַכִּסֵּא שָׁלֵם עֲלֵיהֶם, וְעוֹשִׂים אֶת הָעֲבוֹדָה, וּבוֹקֵעַ הָאֲוִירִים שֶׁל הָעוֹלָם. וְאוֹתָהּ הָעֲבוֹדָה עוֹלָה לְמַעְלָה בִּמְקוֹמָהּ, מִשּׁוּם שֶׁהָאָרֶץ לֹא הִתְתַּקְּנָה לָעֲבוֹדָה אֶלָּא לְיִשְׂרָאֵל לְבַדָּם. וּמִשּׁוּם כָּךְ שְׁאָר הָעַמִּים עוֹבְדֵי עַכּוּ\"ם הָיוּ מִתְרַחֲקִים, שֶׁלֹּא הָיוּ שׁוֹלְטִים בָּהּ כְּמוֹ עַכְשָׁו, מִשּׁוּם שֶׁלֹּא נִזּוֹנוּ אֶלָּא מֵהַתַּמְצִית.</p>\n<p>וְאִם תֹּאמַר, הֲרֵי רָאִינוּ כַּמָּה מְלָכִים הָיוּ שֶׁשָּׁלְטוּ בִּזְמַן שֶׁבֵּית הַמִּקְדָּשׁ קַיָּם עַל הָעוֹלָם - בֹּא רְאֵה, בְּבַיִת רִאשׁוֹן, כְּשֶׁטֶּרֶם טִמְּאוּ יִשְׂרָאֵל אֶת הָאָרֶץ, לֹא הָיוּ שׁוֹלְטִים שְׁאָר הָעַמִּים עוֹבְדֵי עַכּוּ\"ם, אֶלָּא נִזּוֹנוּ מִן הַתַּמְצִית, וּבָהּ הָיוּ שׁוֹלְטִים וְלֹא כָּל כָּךְ. כֵּיוָן שֶׁחָטְאוּ יִשְׂרָאֵל וְטִמְּאוּ אֶת הָאָרֶץ, אָז כִּבְיָכוֹל דָּחוּ אֶת הַשְּׁכִינָה מִמְּקוֹמָהּ, וְהִתְקָרְבָה לַמָּקוֹם הָאַחֵר, וְאָז שָׁלְטוּ שְׁאָר הָעַמִּים וְנִתְּנָה לָהֶם הָרְשׁוּת לִשְׁלֹט.</p>\n<p>בֹּא רְאֵה, עַל אֶרֶץ יִשְׂרָאֵל לֹא שׁוֹלֵט מְמֻנֶּה אַחֵר פְּרָט לַקָּדוֹשׁ- בָּרוּךְ-הוּא לְבַדּוֹ. וּבְשָׁעָה שֶׁחָטְאוּ יִשְׂרָאֵל וְהָיוּ מְקַטְּרִים לָעֲבוֹדָה הַזָּרָה שֶׁבְּתוֹךְ הָאָרֶץ, כִּבְיָכוֹל נִדְחֲתָה הַשְּׁכִינָה מִמְּקוֹמָהּ, וּמוֹשְׁכִים וּמְקַטְּרִים לִקְשֹׁר עֲבוֹדָה זָרָה לְתוֹךְ הַשְּׁכִינָה, וְאָז נִתְּנָה לָהֶם הַשְּׁלִיטָה, מִשּׁוּם שֶׁקְּטֹרֶת הִיא קֶשֶׁר לְהִתְקַשֵּׁר, וְאָז שָׁלְטוּ שְׁאָר הָעַמִּים וּבָטְלוּ נְבִיאִים, וְכָל אוֹתָן הַדְּרָגוֹת הָעֶלְיוֹנוֹת לֹא שָׁלְטוּ בָאָרֶץ.</p>\n<p>וְלֹא הֵסִירוּ אֶת שְׁלִיטַת שְׁאָר הָעַמִּים, מִשּׁוּם שֶׁהֵם מָשְׁכוּ אֶת הַשְּׁכִינָה אֲלֵיהֶם. וְעַל זֶה הִנֵּה בְּבַיִת שֵׁנִי לֹא סָרָה הַשְּׁלִיטָה מִשְּׁאָר הָעַמִּים, וְכָל שֶׁכֵּן בַּגָּלוּת שֶׁשְּׁכִינָה בִּשְׁאָר הָעַמִּים, הַמָּקוֹם שֶׁשָּׁם שׁוֹלְטִים שְׁאָר הַמְמֻנִּים. וּמִשּׁוּם כָּךְ כֻּלָּם יוֹנְקִים מִן הַשְּׁכִינָה שֶׁנִּקְרֶבֶת אֲלֵיהֶם.</p>\n<p>וְעַל זֶה, בִּזְמַן שֶׁיִּשְׂרָאֵל הָיוּ שְׁרוּיִים עַל הָאָרֶץ וְעוֹבְדִים אֶת עֲבוֹדַת הַקָּדוֹשׁ בָּרוּךְ הוּא, הַשְּׁכִינָה הָיְתָה צְנוּעָה בֵּינֵיהֶם, וְלֹא יָצְאָה מִתּוֹךְ בֵּיתָהּ הַחוּצָה בַּגָּלוּי. וּמִשּׁוּם כָּךְ, כָּל אוֹתָם הַנְּבִיאִים שֶׁהָיוּ בְּאוֹתוֹ הַזְּמַן, לֹא נָטְלוּ נְבוּאָה אֶלָּא בִּמְקוֹמָהּ, כְּפִי שֶׁאָמַרְנוּ. וּמִשּׁוּם כָּךְ יוֹנָה הָיָה בּוֹרֵחַ מִחוּץ לְאֶרֶץ הַקֹּדֶשׁ, כְּדֵי שֶׁלֹּא תִתְגַּלֶּה עָלָיו הַנְּבוּאָה, וְלֹא יֵלֵךְ בַּשְּׁלִיחוּת שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא.</p>\n<p>וְאִם תֹּאמַר, הֲרֵי רָאִינוּ שֶׁהִתְגַּלְּתָה הַשְּׁכִינָה בְּבָבֶל, שֶׁהִיא בַּחוּץ - הִנֵּה פֵּרַשְׁנוּ שֶׁכָּתוּב (יחזקאל א) הָיֹה הָיָה, שֶׁהָיָה מַה שֶּׁלֹּא הָיָה מִלִּפְנֵי כֵן מִיּוֹם שֶׁנִּבְנָה בֵּית הַמִּקְדָּשׁ, וְהַנְּבוּאָה הַהִיא הָיְתָה לְשַׁעְתָּהּ.</p>\n<p>וְכָתוּב עַל נְהַר כְּבָר, הַנָּהָר שֶׁכְּבָר הָיָה מִן הַיּוֹם שֶׁנִּבְרָא הָעוֹלָם, וְהַשְּׁכִינָה תָּמִיד הִתְגַּלְּתָה עָלָיו, שֶׁכָּתוּב (בראשית ב) וְנָהָר יֹצֵא מֵעֵדֶן לְהַשְׁקוֹת אֶת הַגָּן וּמִשָּׁם יִפָּרֵד וְגוֹ' (שם האחד וגו'), וְזֶה הוּא אֶחָד מֵהֶם.</p>\n<p>וְשָׁם נִגְלְתָה הַשְּׁכִינָה לְפִי שָׁעָה שֶׁהִצְטָרְכוּ אוֹתָהּ יִשְׂרָאֵל לְפִי צַעֲרָם, אֲבָל בִּזְמַן אַחֵר לֹא הִתְגַּלְּתָה. וּמִשּׁוּם כָּךְ יוֹנָה, כְּדֵי שֶׁלֹּא תִשְׁרֶה עָלָיו הַשְּׁכִינָה וְלֹא תִתְגַּלֶּה עָלָיו, הָלַךְ מֵאֶרֶץ הַקֹּדֶשׁ וּבָרַח. זֶהוּ שֶׁכָּתוּב (יונה א) מִלִּפְנֵי ה'. וְכָתוּב כִּי יָדְעוּ הָאֲנָשִׁים כִּי מִלִּפְנֵי ה' הוּא בֹרֵחַ</p>\n<p>בֹּא רְאֵה, כְּמוֹ שֶׁהַשְּׁכִינָה לֹא מִתְגַּלָּה אֶלָּא בְּמָקוֹם הָרָאוּי לָהּ, אַף כָּךְ לֹא רְאוּיָה וְלֹא מִתְגַּלָּה אֶלָּא בְּאָדָם שֶׁרָאוּי לָהּ. שֶׁהֲרֵי מִיּוֹם שֶׁעָלָה עַל רְצוֹנוֹ שֶׁל לוֹט לְהִתְהַפֵּךְ לְסוּרוֹ הָרָע, הִסְתַּלְּקָה רוּחַ הַקֹּדֶשׁ מֵאַבְרָהָם. וּכְשֶׁהִסְתַּלֵּק מִמֶּנּוּ לוֹט, מִיָּד שָׁרְתָה רוּחַ הַקֹּדֶשׁ בִּמְקוֹמָהּ. זֶהוּ שֶׁכָּתוּב וַה' אָמַר אֶל אַבְרָם אַחֲרֵי הִפָּרֶד לוֹט מֵעִמּוֹ וְגוֹ'.</p>\n<p>בֹּא רְאֵה, כֵּיוָן שֶׁרָאָה אַבְרָהָם שֶׁלּוֹט הָיָה שָׁב לְסוּרוֹ הָרָע, הָיָה פּוֹחֵד אַבְרָהָם. אָמַר, אוּלַי חַס וְשָׁלוֹם מִשּׁוּם הַחֲבֵרוּת עִם זֶה אִבַּדְתִּי בִּגְלָלוֹ אֶת הַחֵלֶק הַקָּדוֹשׁ שֶׁעִטֵּר אוֹתִי הַקָּדוֹשׁ בָּרוּךְ הוּא. כֵּיוָן שֶׁנִּפְרַד מִמֶּנּוּ, אָמַר לוֹ, שָׂא נָא עֵינֶיךְ וּרְאֵה מִן הַמָּקוֹם אֲשֶׁר אַתָּה שָׁם.</p>\n<p>כְּמוֹ מַה זֶּה מִן הַמָּקוֹם אֲשֶׁר אַתָּה שָׁם? שֶׁנִּדְבַּקְתָּ בּוֹ בַּתְּחִלָּה וְהִתְעַטַּרְתָּ בָּאֱמוּנָה הַשְּׁלֵמָה. צָפֹנָה וָנֶגְבָּה וָקֵדְמָה וָיָמָּה - אֵלּוּ הֵם מַסָּעָיו שֶׁהָיוּ בַתְּחִלָּה, שֶׁכָּתוּב וַיֵּלֶךְ לְמַסָּעָיו. וְכָתוּב הָלוֹךְ וְנָסוֹעַ הַנֶּגְבָּה - אֵלּוּ הַדְּרָגוֹת הָעֶלְיוֹנוֹת שֶׁהִתְעַטֵּר בָּאֱמוּנָה הַשְּׁלֵמָה בַּתְּחִלָּה.</p>\n<p>וְאָז הִתְבַּשֵּׂר שֶׁלֹּא תָזוּז מִמֶּנּוּ וּמִבָּנָיו לְעוֹלָמִים, שֶׁכָּתוּב כִּי אֶת כָּל הָאָרֶץ אֲשֶׁר אַתָּה רֹאֶה. מַה זֶּה אֲשֶׁר אַתָּה רֹאֶה? זוֹ הַדַּרְגָּה הָרִאשׁוֹנָה שֶׁהִתְגַּלְּתָה לוֹ, כְּמוֹ שֶׁנֶּאֱמַר לַה' הַנִּרְאֶה אֵלָיו. וּמִשּׁוּם כָּךְ אֲשֶׁר אַתָּה רֹאֶה, מִשּׁוּם שֶׁהַדַּרְגָּה הָרִאשׁוֹנָה הַזּוֹ נִכְלֶלֶת מִכָּל הַדְּרָגוֹת וְכֻלָּן נִרְאוֹת בָּהּ. וּמִשּׁוּם כָּךְ כִּי אֶת כָּל הָאָרֶץ אֲשֶׁר אַתָּה רֹאֶה וְגוֹ'.</p>"],[9522011201,"<p>רַבִּי אֶלְעָזָר נִקְלַע לְבֵית אַכְסַנְיָה בְּלוֹד, וְהָיָה עִמּוֹ רַבִּי חִזְקִיָּה. קָם בַּלַּיְלָה לַעֲסֹק בַּתּוֹרָה. קָם רַבִּי חִזְקִיָּה אֵלָיו. אָמַר לוֹ רַבִּי אֶלְעָזָר, הַחֲבֵרִים נִמְצָאִים בְּאַרְמוֹן צַר.</p>\n<p>פָּתַח רַבִּי אֶלְעָזָר וְאָמַר, (שיר ב) כְּתַפּוּחַ בַּעֲצֵי הַיַּעַר וְגוֹ'. כְּתַפּוּחַ - זֶה הַקָּדוֹשׁ בָּרוּךְ הוּא, שֶׁהוּא נֶחְמָד וּמִתְעַטֵּר בִּגְוָנָיו מִכָּל שְׁאָר הָאִילָנוֹת שֶׁאֵין מִי שֶׁדּוֹמֶה לוֹ. רָשׁוּם הוּא מִן הַכֹּל, רָשׁוּם הוּא שֶׁאֵין אַחֵר כְּמוֹתוֹ.</p>\n<p>מִשּׁוּם כָּךְ בְּצִלּוֹ חִמַּדְתִּי. בְּצִלּוֹ וְלֹא בְצֵל שֶׁל אַחֵר. בְּצִלּוֹ וְלֹא בְצֵל שֶׁל שְׁאָר הַמְמֻנִּים. חִמַּדְתִּי - מָתַי? מִן הַיּוֹם שֶׁהָיָה אַבְרָהָם בָּעוֹלָם, שֶׁהוּא נֶחְמָד וְאָהַב אֶת הַקָּדוֹשׁ בָּרוּךְ הוּא בְּאַהֲבָה, כְּמוֹ שֶׁנֶּאֱמַר (ישעיה מא) אַבְרָהָם אֹהֲבִי. וּפִרְיוֹ מָתוֹק לְחִכִּי - זֶה הוּא יִצְחָק, שֶׁהוּא פְּרִי קָדוֹשׁ.</p>\n<p>דָּבָר אַחֵר בְּצִלּוֹ חִמַּדְתִּי וְיָשַׁבְתִּי - זֶה יַעֲקֹב. וּפִרְיוֹ מָתוֹק לְחִכִּי - זֶה יוֹסֵף הַצַּדִּיק שֶׁעָשָׂה פֵרוֹת קְדוֹשִׁים בָּעוֹלָם, וְעַל זֶה כָּתוּב (בראשית לז) אֵלֶּה תֹּלְדוֹת יַעֲקֹב יוֹסֵף. שֶׁכָּל אוֹתָם הַתּוֹלָדוֹת שֶׁל יַעֲקֹב (יוסף שהוא שעושה תולדות) (נ\"א: ביוסף הצדיק הם עומדים, שעושה תולדות כעין כלם) (ד\"א שבטים), וּמִשּׁוּם כָּךְ נִקְרְאוּ יִשְׂרָאֵל עַל שֵׁם אֶפְרַיִם, שֶׁכָּתוּב (ירמיה לא) הֲבֵן יַקִּיר לִי אֶפְרַיִם וְגוֹ'.</p>\n<p>דָּבָר אַחֵר כְּתַפּוּחַ בַּעֲצֵי הַיַּעַר - זֶה אַבְרָהָם, שֶׁדּוֹמֶה לְתַפּוּחַ שֶׁמַּעֲלֶה רֵיחוֹת, וְנִצְטַיֵּן בֶּאֱמוּנָה שְׁלֵמָה עַל כָּל בְּנֵי דוֹרוֹ, וְנִרְשַׁם אֶחָד לְמַעְלָה וְנִרְשַׁם אֶחָד לְמַטָּה, שֶׁכָּתוּב אֶחָד הָיָה אַבְרָהָם.</p>\n<p>מָה הַטַּעַם הָיָה אֶחָד? שֶׁלֹּא הָיָה אַחֵר בָּעוֹלָם שֶׁעָלָה לֶאֱמוּנַת הַקָּדוֹשׁ בָּרוּךְ הוּא פְּרָט לוֹ. אָמַר לוֹ רַבִּי חִזְקִיָּה, וַהֲרֵי כָּתוּב וְאֶת הַנֶּפֶשׁ אֲשֶׁר עָשׂוּ בְחָרָן? אָמַר לוֹ, עַד כָּעֵת הֵם לֹא הָיוּ בִּדְרָגוֹת עֶלְיוֹנוֹת שֶׁהִתְעַטֵּר בָּהֶם אַבְרָהָם.</p>\n<p>אַחַר כָּךְ אָמַר לוֹ, עוֹד שָׁמַעְתִּי, שֶׁלֹּא נִקְרָא אַבְרָהָם אֶחָד עַד שֶׁהִתְעַלָּה בְּיִצְחָק וְיַעֲקֹב. כֵּיוָן שֶׁהִתְעַלָּה בְּיִצְחָק וְיַעֲקֹב וְהָיוּ שְׁלָשְׁתָּם אֲבוֹת הָעוֹלָם, אָז נִקְרָא אַבְרָהָם אֶחָד. וְאָז הוּא תַּפּוּחַ בָּעוֹלָם, מְצֻיָּן מִכָּל בְּנֵי הָעוֹלָם. אָמַר לוֹ, יָפֶה אָמַרְתָּ.</p>\n<p>דָּבָר אַחֵר, כְּתַפּוּחַ בַּעֲצֵי הַיַּעַר - זֶה הַקָּדוֹשׁ בָּרוּךְ הוּא. כֵּן דּוֹדִי - זֶה הַקָּדוֹשׁ בָּרוּךְ הוּא. בְּצִלּוֹ - זֶה הַקָּדוֹשׁ בָּרוּךְ הוּא. חִמַּדְתִּי וְיָשַׁבְתִּי - בַּיּוֹם שֶׁנִּגְלָה הַקָּדוֹשׁ בָּרוּךְ הוּא עַל הַר סִינַי וְקִבְּלוּ יִשְׂרָאֵל תּוֹרָה וְאָמְרוּ נַעֲשֶׂה וְנִשְׁמָע (שמות כד).</p>\n<p>וּפִרְיוֹ מָתוֹק לְחִכִּי - אֵלּוּ דִּבְרֵי הַתּוֹרָה שֶׁכָּתוּב בָּהֶם (תהלים יט) וּמְתוּקִים מִדְּבַשׁ וְנֹפֶת צוּפִים. דָּבָר אַחֵר וּפִרְיוֹ מָתוֹק לְחִכִּי - אֵלּוּ נִשְׁמוֹת הַצַּדִּיקִים שֶׁכֻּלָּן פְּרִי מַעֲשָׂיו שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא וְעוֹמְדוֹת עִמּוֹ לְמַעְלָה.</p>\n<p>בֹּא רְאֵה, כָּל נִשְׁמוֹת הָעוֹלָם שֶׁהֵן פְּרִי מַעֲשָׂיו שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא, כֻּלָּן אֶחָד בְּסוֹד אֶחָד. וּכְשֶׁיּוֹרְדוֹת לָעוֹלָם, כֻּלָּן נִפְרָדוֹת בִּגְוָנִים זָכָר וּנְקֵבָה, וְהֵן זָכָר וּנְקֵבָה מְחֻבָּרוֹת יַחַד.</p>\n<p>וּבֹא וּרְאֵה, תְּשׁוּקַת הַנְּקֵבָה לַזָּכָר עוֹשָׂה נֶפֶשׁ, וּתְשׁוּקַת הַזָּכָר לַנְּקֵבָה עוֹשָׂה נֶפֶשׁ. וְהָרָצוֹן שֶׁל תְּשׁוּקַת הַזָּכָר לַנְּקֵבָה וְהִתְדַּבְּקוּתוֹ בָּהּ מוֹצִיאָה נֶפֶשׁ, וְכוֹלֵל תְּשׁוּקַת (תשוקתו) הַנְּקֵבָה וְנוֹטֵל אוֹתָהּ. וְנִכְלֶלֶת הַתְּשׁוּקָה הַתַּחְתּוֹנָה בַּתְּשׁוּקָה שֶׁלְּמַעְלָה, וְנַעֲשֵׂית רָצוֹן אֶחָד בְּלִי פֵרוּד.</p>\n<p>וְאָז (נוטל) כּוֹלֵל הַכֹּל נְקֵבָה, וּמִתְעַבֶּרֶת מִן הַזָּכָר, וְהַתְּשׁוּקוֹת שֶׁל שְׁנֵיהֶם נִדְבָּקוֹת יַחַד, וְעַל כֵּן הַכֹּל כָּלוּל זֶה עִם זֶה. וּכְשֶׁהַנְּשָׁמוֹת יוֹצְאוֹת, הֵן יוֹצְאוֹת יַחַד זָכָר וּנְקֵבָה.</p>\n<p>אַחַר כָּךְ, כֵּיוָן שֶׁיּוֹרְדוֹת, נִפְרָדוֹת זוֹ לְצַד זֶה וְזוֹ לְצַד זֶה, וְהַקָּדוֹשׁ בָּרוּךְ הוּא מְזַוֵּג אוֹתָן אַחַר כָּךְ. וְהַזִּוּוּג לֹא נִתָּן לְאַחֵר, אֶלָּא לַקָּדוֹשׁ-בָּרוּךְ-הוּא לְבַדּוֹ, שֶׁהוּא יוֹדֵעַ אֶת זִוּוּגָם לְחַבֵּר אוֹתָם כָּרָאוּי.</p>\n<p>אַשְׁרֵי הָאִישׁ שֶׁזּוֹכֶה בְמַעֲשָׂיו וְהוֹלֵךְ בְּדֶרֶךְ הָאֱמֶת כְּדֵי שֶׁתִּתְחַבֵּר נֶפֶשׁ בְּנֶפֶשׁ כְּמוֹ שֶׁהָיָה בַּתְּחִלָּה. שֶׁהֲרֵי אִם הוּא זוֹכֶה בְמַעֲשָׂיו, זֶהוּ אָדָם שָׁלֵם כָּרָאוּי. וּמִשּׁוּם כָּךְ כָּתוּב וּפִרְיוֹ מָתוֹק לְחִכִּי, שֶׁהוּא בְּתִקּוּן מְבֹרָךְ שֶׁיִּתְבָּרֵךְ מִמֶּנּוּ הָעוֹלָם, מִשּׁוּם שֶׁהַכֹּל תָּלוּי בְּמַעֲשֵׂי הָאָדָם אִם זוֹכֶה וְאִם לֹא זוֹכֶה.</p>\n<p>אָמַר רַבִּי חִזְקִיָּה, כָּךְ שָׁמַעְתִּי, שֶׁכָּתוּב (הושע יד) מִמֶּנִּי פֶּרְיְךְ נִמְצָא. הַקָּדוֹשׁ בָּרוּךְ הוּא אָמַר לִכְנֶסֶת יִשְׂרָאֵל, וַדַּאי מִמֶּנִּי פֶּרְיְךְ נִמְצָא. לֹא כָתוּב פִּרְיִי נִמְצָא, אֶלָּא פֶּרְיְךְ. אוֹתָהּ תְּשׁוּקַת הַנְּקֵבָה שֶׁעוֹשָׂה נֶפֶשׁ וְנִכְלֶלֶת בְּכֹחַ הַזָּכָר, וְנִכְלֶלֶת נֶפֶשׁ בְּנֶפֶשׁ, וְנַעֲשׂוֹת אַחַת כּוֹלֶלֶת זוֹ בָּזֶה, כְּפי שֶׁאָמַרְנוּ. לְאַחַר מִכֵּן נִמְצָאִים שְׁנֵיהֶם בָּעוֹלָם, וַדַּאי בְּכֹחַ הַזָּכָר נִמְצָא פְּרִי הַנְּקֵבָה.</p>\n<p>דָּבָר אַחֵר, בִּתְשׁוּקַת הַנְּקֵבָה נִמְצָא פְּרִי הַזָּכָר, שֶׁאִם לֹא תְשׁוּקַת הַנְּקֵבָה לַזָּכָר, לֹא נַעֲשׂוּ פֵרוֹת לְעוֹלָמִים. זֶהוּ שֶׁכָּתוּב מִמֶּנִּי פֶּרְיְךְ נִמְצָא.</p>"],[9522011202,"<p>וַיְהִי בִּימֵי אַמְרָפֶל מֶלֶךְ שִׁנְעָר וְגוֹ'. רַבִּי יוֹסֵי פָּתַח, (ישעיה מא) מִי הֵעִיר מִמִּזְרָח צֶדֶק יִקְרָאֵהוּ לְרַגְלוֹ וְגוֹ'. אֶת הַפָּסוּק הַזֶּה בֵּאֲרוּ הַחֲבֵרִים. אֲבָל הַפָּסוּק הַזֶּה הוּא בַּסּוֹד שֶׁל הַחָכְמָה, שֶׁהֲרֵי שָׁנִינוּ, שִׁבְעָה רְקִיעִים עָשָׂה הַקָּדוֹשׁ בָּרוּךְ הוּא לְמַעְלָה, וְכֻלָּם לְהוֹדִיעַ אֶת כְּבוֹד הַקָּדוֹשׁ בָּרוּךְ הוּא, וְכֻלָּם עוֹמְדִים לְהוֹדִיעַ אֶת סוֹד הָאֱמוּנָה הָעֶלְיוֹנָה.</p>\n<p>בֹּא רְאֵה, יֵשׁ רָקִיעַ עֶלְיוֹן נִסְתָּר לְמַעְלָה מֵאוֹתָם הַשִּׁבְעָה, וְזֶה הוּא הָרָקִיעַ שֶׁמַּנְהִיגָם וּמֵאִיר לְכֻלָּם, וְזֶה אֵינוֹ נוֹדָע, וְעוֹמֵד בִּשְׁאֵלָה שֶׁלֹּא יְדוּעָה, מִשּׁוּם שֶׁהוּא נִסְתָּר וְעָמֹק, וְכֻלָּם תְּמֵהִים עָלָיו. וּמִשּׁוּם כָּךְ נִקְרָא מִ\"י, כְּמוֹ שֶׁפֵּרְשׁוּהָ שֶׁכָּתוּב (איוב לח) מִבֶּטֶן מִי יָצָא הַקָּרַח, וְנֶאֱמַר. וְזֶה הוּא הָרָקִיעַ הָעֶלְיוֹן שֶׁעוֹמֵד עַל כָּל אוֹתָם הַשִּׁבְעָה.</p>\n<p>וְיִשִׁ לְמַטָּה רָקִיעַ שֶׁהוּא תַּחְתּוֹן מִכֻּלָּם וְלֹא מֵאִיר. וּמִשּׁוּם שֶׁהוּא תַּחְתּוֹן שֶׁלֹּא מֵאִיר, אוֹתוֹ הָרָקִיעַ שֶׁעֲלֵיהֶם מִתְחַבֵּר עִמּוֹ, וּשְׁתֵּי הָאוֹתִיּוֹת הַלָּלוּ הוּא כּוֹלְלָם בְּתוֹכוֹ, וְנִקְרָא יָם, שֶׁאוֹתוֹ הָרָקִיעַ הָעֶלְיוֹן שֶׁנִּקְרָא מִ\"י.</p>\n<p>מִשּׁוּם שֶׁכָּל אוֹתָם הָרְקִיעִים הָאֲחֵרִים נַעֲשִׂים נְחָלִים וְנִכְנָסִים אֵלָיו, וְאָז הוּא הַיָּם הָעֶלְיוֹן, וְעוֹשֶׂה פֵרוֹת וְדָגִים לְמִינֵיהֶם. וְעַל זֶה אָמַר דָּוִד (תהלים קד) זֶה הַיָּם גָּדוֹל וּרְחַב יָדָיִם שָׁם רֶמֶשׂ וְאֵין מִסְפָּר חַיּוֹת קְטַנּוֹת עִם גְּדֹלוֹת.</p>\n<p>וְעַל זֶה כָּתוּב (ישעיה מא) מִי הֵעִיר מִמִּזְרָח צֶדֶק יִקְרָאֵהוּ לְרַגְלוֹ. מִי הֵעִיר מִמִּזְרָח - זֶה אַבְרָהָם. צֶדֶק יִקְרָאֵהוּ לְרַגְלוֹ - (נ\"א: זו שרה, ד\"א צדק יקראהו לרגלו וגו') זֶה הוּא הָרָקִיעַ הַתַּחְתּוֹן שֶׁל כָּל הָרְקִיעִים שֶׁנַּעֲשָׂה יָם. יִתֵּן לְפָנָיו גּוֹיִם, מִי זֶה? הוּא הָרָקִיעַ הַתַּחְתּוֹן שֶׁאָמַרְנוּ, שֶׁעוֹשֶׂה נְקָמוֹת וּמַפִּיל שׂוֹנְאִים. וּבָזֶה הִשְׁתַּבַּח דָּוִד וְאָמַר (תהלים יח) וְאֹיְבַי נָתַתָּה לִּי עֹרֶף וּמְשַׂנְאַי אַצְמִיתֵם.</p>\n<p>(ישעיה מא) יִתֵּן לְפָנָיו גּוֹיִם - אֵלּוּ הֵם הָעַמִּים שֶׁהָיָה אַבְרָהָם רוֹדֵף אַחֲרֵיהֶם, וְהַקָּדוֹשׁ בָּרוּךְ הוּא הָיָה הוֹרֵג אוֹתָם. (ומלכים ירד, (מה זה ירד, ' אלא) אלו המלכים שממנים למעלה עליהם, יתן לפניו גוים אלו העמים שלמטה) וּמְלָכִים יַרְדְּ - אֵלּוּ הַמְמֻנִּים הַגְּדוֹלִים שֶׁלְּמַעְלָה. שֶׁכַּאֲשֶׁר הַקָּדוֹשׁ בָּרוּךְ הוּא עוֹשֶׂה דִין בָּעוֹלָם (ד\"א בעם), הוּא עוֹשֶׂה דִין בַּכֹּל, בְּמַעְלָה וּבְמַטָּה.</p>\n<p>(ישעיה מא ג) יִרְדְּפֵם יַעֲבוֹר שָׁלוֹם אֹרַח בְּרַגְלָיו לֹא יָבוֹא, (ישעיה מא ג). יִרְדְּפֵם - זֶה אַבְרָהָם, שֶׁאַבְרָהָם הָיָה רוֹדֵף אוֹתָם, וְהַקָּדוֹשׁ בָּרוּךְ הוּא הָיָה עוֹבֵר לְפָנָיו וְהוֹרֵג אוֹתָם, שֶׁכָּתוּב יַעֲבוֹר שָׁלוֹם. זֶה הַקָּדוֹשׁ בָּרוּךְ הוּא שֶׁנִּקְרָא שָׁלוֹם.</p>\n<p>אֹרַח בְּרַגְלָיו לֹא יָבוֹא, וְכִי עוֹלֶה עַל דַּעְתְּךְ שֶׁאַבְרָהָם הָיָה הוֹלֵךְ בְּתוֹךְ הָעֲנָנִים אוֹ בְּתוֹךְ סוּסִים וּמֶרְכָּבוֹת? אֶלָּא אֹרַח בְּרַגְלָיו לֹא יָבוֹא, שֶׁלֹּא הָיָה הוֹלֵךְ לִפְנֵי אַבְרָהָם לֹא מַלְאָךְ וְלֹא שָׁלִיחַ, אֶלָּא הַקָּדוֹשׁ בָּרוּךְ הוּא לְבַדּוֹ, שֶׁכָּתוּב אֹרַח בְּרַגְלָיו. מִי זֶה רַגְלָיו? אֵלּוּ הַמַּלְאָכִים שֶׁתַּחְתָּיו שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא, כְּמוֹ שֶׁנֶּאֱמַר (זכריה יד) וְעָמְדוּ רַגְלָיו בַּיּוֹם הַהוּא וְגוֹ'.</p>\n<p>דָּבָר אַחֵר מִי הֵעִיר מִמִּזְרָח - בֹּא רְאֵה, בְּשָׁעָה שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא הֵעִיר אֶת הָעוֹלָם לְהָבִיא אֶת אַבְרָהָם וּלְקָרֵב אוֹתוֹ אֵלָיו, הַהִתְעוֹרְרוּת הַזּוֹ מִשּׁוּם שֶׁעָתִיד הָיָה לָצֵאת מִמֶּנּוּ יַעֲקֹב וּלְהַעֲמִיד שְׁנֵים עָשָׂר שְׁבָטִים כֻּלָּם צַדִּיקִים לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא.</p>\n<p>צֶדֶק יִקְרָאֵהוּ לְרַגְלוֹ, שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא הָיָה תָמִיד קוֹרֵא לוֹ מִיּוֹם שֶׁנִּבְרָא הָעוֹלָם, כְּמוֹ שֶׁנֶּאֱמַר (ישעיה מא) קֹרֵא הַדֹּרוֹת מֵרֹאשׁ. וּמִשּׁוּם כָּךְ, צֶדֶק יִקְרָאֵהוּ וַדַּאי. לְרַגְלוֹ - לְהִתְחַבֵּר בּוֹ בַּעֲבוֹדָתוֹ וּלְקָרֵב אוֹתוֹ אֵלָיו, כְּמוֹ שֶׁנֶּאֱמַר (שמות יא) הָעָם אֲשֶׁר בְּרַגְלֶיךְ.</p>\n<p>דָּבָר אַחֵר מִי הֵעִיר מִמִּזְרָח - שֶׁמִּשָּׁם רֵאשִׁית הָאוֹר לְהָאִיר. מִשּׁוּם שֶׁהַדָּרוֹם, אוֹתוֹ הַחֹזֶק שֶׁל הָאוֹר שֶׁלּוֹ הוּא מִן הַמִּזְרָח. וְעַל כֵּן, מִי הֵעִיר - אוֹתוֹ הָאוֹר שֶׁל הַדָּרוֹם. מִמִּזְרָח - מִשּׁוּם שֶׁהוּא נוֹסֵעַ וְנִזּוֹן בָּרִאשׁוֹנָה, וּתְשׁוּקָתוֹ שֶׁל אוֹתוֹ הָרָקִיעַ הָעֶלְיוֹן לָתֵת לַמִּזְרָח.</p>\n<p>צֶדֶק יִקְרָאֵהוּ לְרַגְלוֹ - זֶה הַמַּעֲרָב, שֶׁהוּא תָמִיד קוֹרֵא לוֹ וְלֹא שׁוֹקֵט, כְּמוֹ שֶׁנֶּאֱמַר (תהלים פג) אֱלֹהִים אַל דֳּמִי לָךְ אַל תֶּחֱרַשׁ וְאַל תִּשְׁקֹט אֵל, מִשּׁוּם שֶׁהַמַּעֲרָב תָּמִיד מִתְעוֹרֵר אֵלָיו. יִתֵּן לְפָנָיו גּוֹיִם וּמְלָכִים יַרְדְּ, שֶׁהֲרֵי מִמֶּנּוּ מְקַבֵּל אֶת הַחֹזֶק לְהַכְנִיעַ אֶת כָּל אוֹתָם הָעַמִּים שֶׁל הָעוֹלָם.</p>\n<p>רַבִּי יְהוּדָה אָמַר, (ישעיה מא) מִי הֵעִיר מִמִּזְרָח - זֶה אַבְרָהָם, שֶׁלֹּא נָטַל הִתְעוֹרְרוּת אֶל הַקָּדוֹשׁ בָּרוּךְ הוּא אֶלָּא מִמִּזְרָח. מִשּׁוּם שֶׁרָאָה אֶת הַשֶּׁמֶשׁ שֶׁיּוֹצֵאת בַּבֹּקֶר מִצַּד הַמִּזְרָח, נָטַל הִתְעוֹרְרוּת לְנַפְשׁוֹ שֶׁהוּא הַקָּדוֹשׁ בָּרוּךְ הוּא. אָמַר, זֶה הוּא הַמֶּלֶךְ שֶׁבָּרָא אוֹתִי. עָבַד לוֹ כָּל הַיּוֹם הַהוּא. לָעֶרֶב רָאָה הַשֶּׁמֶשׁ שֶׁנֶּאֱסַף (והלבנה יוצאת) וְהַלְּבָנָה מְאִירָה. אָמַר, זֶה הוּא וַדַּאי שֶׁשּׁוֹלֵט עַל אוֹתָהּ הָעֲבוֹדָה שֶׁעָבַדְתִּי כָּל הַיּוֹם הַזֶּה, שֶׁהִנֵּה נֶחְשַׁךְ לְפָנָיו וְלֹא מֵאִיר. עָבַד לוֹ כָּל הַלַּיְלָה הַהוּא.</p>\n<p>לַבֹּקֶר רָאָה שֶׁהָלְכָה הַחֲשֵׁכָה וְהֵאִיר צַד הַמִּזְרָח. אָמַר, וַדַּאי כָּל אֵלּוּ יֵשׁ עֲלֵיהֶם מֶלֶךְ וְשַׁלִּיט שֶׁמַּנְהִיג אוֹתָם. כֵּיוָן שֶׁרָאָה הַקָּדוֹשׁ בָּרוּךְ הוּא אֶת תְּשׁוּקָתוֹ שֶׁל אַבְרָהָם אֵלָיו, אֲזַי הִתְגַּלָּה אֵלָיו וְדִבֵּר עִמּוֹ, שֶׁכָּתוּב צֶדֶק יִקְרָאֵהוּ לְרַגְלוֹ, שֶׁדִּבֵּר עִמּוֹ וְהִתְגַּלָּה עָלָיו.</p>\n<p>רַבִּי יִצְחָק פָּתַח, (שם מה) דֹּבֵר צֶדֶק מַגִּיד מֵישָׁרִים. כָּל דִּבְרֵי הַקָּדוֹשׁ בָּרוּךְ הוּא הֵם אֱמֶת וְעוֹשֶׂה מֵישָׁרִים. בַּמָּה הוּא עוֹשֶׂה מֵישָׁרִים? מִשּׁוּם שֶׁכַּאֲשֶׁר בָּרָא הַקָּדוֹשׁ בָּרוּךְ הוּא אֶת הָעוֹלָם, לֹא הָיָה עוֹמֵד, וְהָיָה מִתְמוֹטֵט לְכָאן וּלְכָאן. אָמַר הַקָּדוֹשׁ בָּרוּךְ הוּא לָעוֹלָם: מַה לְּךְ שֶׁאַתָּה מִתְמוֹטֵט? אָמַר לוֹ: רִבּוֹנוֹ שֶׁל עוֹלָם, אֵינִי יָכוֹל לַעֲמֹד, שֶׁאֵין בִּי יְסוֹד עַל מַה שֶּׁאֶתְקַיֵּם.</p>\n<p>אָמַר לוֹ: הֲרֵי אֲנִי עָתִיד לְהַעֲמִיד בְּךְ צַדִּיק אֶחָד שֶׁהוּא אַבְרָהָם שֶׁיֹּאהַב אוֹתִי. מִיָּד עָמַד הָעוֹלָם בְּקִיּוּמוֹ. זֶהוּ שֶׁכָּתוּב (בראשית ב) אֵלֶּה תוֹלְדוֹת הַשָּׁמַיִם וְהָאָרֶץ בְּהִבָּרְאָם. אַל תִּקְרֵי בְּהִבָּרְאָם אֶלָּא בְּאַבְרָהָם. בְּאַבְרָהָם מִתְקַיֵּם הָעוֹלָם.</p>\n<p>אָמַר רַבִּי חִיָּיא, (ישעיה מה) מַגִּיד מֵישָׁרִים, שֶׁהִנֵּה הֵשִׁיב הָעוֹלָם לַקָּדוֹשׁ-בָּרוּךְ-הוּא: אוֹתוֹ אַבְרָהָם עָתִיד הוּא שֶׁיֵּצְאוּ מִמֶּנִּי בָּנִים שֶׁיַּחֲרִיבוּ אֶת הַמִּקְדָּשׁ וְיִשְׂרְפוּ אֶת הַתּוֹרָה. (נ\"א: לצאת ממנו ישמעאל, אמר לו', הנה יצחק, אמר לו, ' עתיד לצאת ממנו עשו הרשע שיחריב את בית המקדש וישרף התורה,) אָמַר לוֹ: עָתִיד אָדָם אֶחָד לָצֵאת מִמֶּנּוּ שֶׁהוּא יַעֲקֹב, וְיֵצְאוּ מִמֶּנּוּ שְׁנֵים עָשָׂר שְׁבָטִים כֻּלָּם צַדִּיקִים. מִיָּד הִתְקַיֵּם הָעוֹלָם בִּשְׁבִילוֹ. זֶהוּ שֶׁכָּתוּב מַגִּיד מֵישָׁרִים.</p>\n<p>רַבִּי אֶלְעָזָר אוֹמֵר, הֲרֵי הֵעַרְנוּ, וַיְדַבֵּר, וַיַּגֵּד, וַיֹּאמֶר - כֻּלָּם לְטַעֲמָם מִתְפָּרְשִׁים. וַיְדַבֵּר הוּא בְּגָלוּי, דַּרְגָּה חִיצוֹנָה, שֶׁאֵינָהּ דַּרְגָּה פְּנִימִית כְּמוֹ אוֹתָן הַדְּרָגוֹת הָעֶלְיוֹנוֹת. וְזֶהוּ דֹּבֵר צֶדֶק.</p>\n<p>וַיַּגֵּד, הוּא רֶמֶז לְדַרְגָּה פְּנִימִית עֶלְיוֹנָה שֶׁשּׁוֹלֶטֶת עַל הַדִּבּוּר, וְזֶהוּ מַגִּיד מֵישָׁרִים. מִי הַמֵּישָׁרִים? זוֹ הַדַּרְגָּה הָעֶלְיוֹנָה שֶׁיַּעֲקֹב שָׁרוּי בָּהּ. זֶהוּ שֶׁכָּתוּב (תהלים צט) אַתָּה כּוֹנַנְתָּ מֵישָׁרִים. וּמִשּׁוּם כָּךְ כָּתוּב מַגִּיד וְלֹא כָתוּב דּוֹבֵר.</p>\n<p>אָמַר רַבִּי יִצְחָק, וַהֲרֵי כָּתוּב (דברים ד) וַיַּגֵּד לָכֶם אֶת בְּרִיתוֹ? אָמַר לוֹ, כָּךְ הוּא וַדַּאי, הִיא הַדַּרְגָּה שֶׁשּׁוֹלֶטֶת עַל הַתַּחְתּוֹנָה שֶׁהִיא דּבֵר צֶדֶק, וְהַכֹּל (בה) הוּא (נ\"א: לשתל הפרי) לְהִתְבּוֹנֵן (יש) כָּאן. בּא רְאֵה, שֶׁאַף עַל גַּב שֶׁהַדִּבּוּר הוּא תַּחְתּוֹן, אַל תֹּאמַר שֶׁאֵינוֹ עֶלְיוֹן, אֶלָּא וַדַּאי הַדִּבּוּר הוּא מָלֵא מִן הַכֹּל וְהוּא דַּרְגָּה עֶלְיוֹנָה, וְסִימָן לַדָּבָר - (שם לב) כִּי לֹא דָבָר רֵק הוּא מִכֶּם.</p>\n<p>רַבִּי אֶלְעָזָר הָיָה הוֹלֵךְ לְבֵית חָמִיו, וְהָיוּ עִמּוֹ רַבִּי חִיָּיא וְרַבִּי יוֹסֵי וְרַבִּי חִזְקִיָּה. אָמַר רַבִּי אֶלְעָזָר, הִנֵּה רָאִיתִי שֶׁהִתְעוֹרְרוּת שֶׁל מַעְלָה אֵינָהּ אֶלָּא כְּשֶׁמִּתְעוֹרֵר לְמַטָּה, שֶׁהֲרֵי הַהִתְעוֹרְרוּת שֶׁל מַעְלָה תְּלוּיָה בַּתְּשׁוּקָה שֶׁל מַטָּה (הדבר).</p>"],[9522011203,"<p>פָּתַח וְאָמַר, (תהלים פג) אֱלֹהִים אַל דֳּמִי לָךְ אַל תֶּחֱרַשׁ וְאַל תִּשְׁקֹט אֵל. זוֹ הִיא הַהִתְעוֹרְרוּת שֶׁל מַטָּה כְּדֵי לִשְׁלֹט. אָמַר דָּוִד, אֱלֹהִים אַל דֳּמִי לָךְ, לְהָעִיר אֶל הָעֶלְיוֹן וּלְהִתְחַבֵּר אֶל הַיָּמִין.</p>\n<p>מָה הַטַּעַם? מִשּׁוּם (שם) כִּי הִנֵּה אוֹיְבֶיךְ יֶהֱמָיוּן וְגוֹ'. (וכתוב) כִּי נוֹעֲצוּ לֵב יַחְדָּו עָלֶיךְ בְּרִית יִכְרֹתוּ. וּמִשּׁוּם כָּךְ, אֱלֹהִים אַל דֳּמִי לָךְ לְהָעִיר כְּלַפֵּי מַעְלָה, שֶׁהֲרֵי אָז מִתְעוֹרֵר הַיָּמִין וְקוֹשֵׁר אוֹתָהּ עִמָּהּ. וְכַאֲשֶׁר נִקְשֶׁרֶת בַּיָּמִין, אָז נִשְׁבָּרִים הַשּׂוֹנְאִים, שֶׁכָּתוּב (שמות טו) יְמִינְךְ ה' נֶאְדָּרִי בַּכֹּחַ יְמִינְךְ ה' תִּרְעַץ אוֹיֵב.</p>\n<p>וּבֹא וּרְאֵה, בְּשָׁעָה שֶׁהִתְחַבְּרוּ כָּל אוֹתָם הַמְּלָכִים לְהִלָּחֵם בַּקְּרָב עַל אַבְרָהָם, הִתְיָעֲצוּ לְהַעֲבִירוֹ מִן הָעוֹלָם, וְכֵיוָן שֶׁשָּׁלְטוּ בְּלוֹט בֶּן אָחִיו שֶׁל אַבְרָהָם, מִיָּד הָלְכוּ, שֶׁכָּתוּב וַיִּקְחוּ אֶת לוֹט וְאֶת רְכֻשׁוֹ בֶּן אֲחִי אַבְרָם וַיֵּלֵכוּ. מָה הַטַּעַם? מִשּׁוּם שֶׁדְּמוּתוֹ שֶׁל לוֹט הָיְתָה דוֹמָה לְאַבְרָהָם, וּמִשּׁוּם כָּךְ וַיֵּלֵכוּ, שֶׁכָּל אוֹתוֹ הַקְּרָב הָיָה בִּשְׁבִילוֹ.</p>\n<p>מָה הַטַּעַם? מִשּׁוּם שֶׁאַבְרָהָם הָיָה מוֹצִיא אֶת בְּנֵי הָעוֹלָם מֵעֲבוֹדָה זָרָה וּמַכְנִיס אוֹתָם לַעֲבוֹדַת הַקָּדוֹשׁ בָּרוּךְ הוּא. וְעוֹד, הַקָּדוֹשׁ בָּרוּךְ הוּא הֵעִיר אוֹתָם בָּעוֹלָם כְּדֵי לְגַדֵּל אֶת שְׁמוֹ שֶׁל אַבְרָהָם בָּעוֹלָם וּלְקָרֵב אוֹתוֹ לַעֲבוֹדָתוֹ.</p>\n<p>וְסוֹד הַדָּבָר - כֵּיוָן שֶׁאַבְרָהָם הִתְעוֹרֵר לִרְדֹּף אַחֲרֵיהֶם, אָז אֱלֹהִים אַל דֳּמִי לָךְ, עַד שֶׁהַכֹּל נִקְשַׁר לְאַבְרָהָם. וּכְשֶׁהַכֹּל נִקְשַׁר לְאַבְרָהָם, אָז נִשְׁבְּרוּ כָּל הַמְּלָכִים מִלְּפָנָיו, כְּמוֹ שֶׁאָמַרְנוּ, שֶׁכָּתוּב יְמִינְךְ ה' תִּרְעַץ אוֹיֵב וְגוֹ'.</p>"]]});
